R:Segment({id="horde/02-the-barrens",title="The Barrens",faction="Horde",min=14,max=21,zone=1413,zoneName="The Barrens",next="horde/05-stonetalon-mountains"}, function() return {
  {t="The Barrens", lv=14, f={r={"Orc","Troll"}}, g={{"g",0,txt="Far Watch Post",m=1413,x=62.3,y=19.4}}},
  {t="Far Watch Post", lv=14, n="Leave Orgrimmar by the main gate and follow the road south through Durotar, then west over the Southfury River bridge: Far Watch Post sits just above it on the Barrens side. Kargal Battlescar and Uzzek stand together.", f={r={"Orc","Troll"}}, g={{"a",842,m=1413,x=62.3,y=19.4,ml=10},{"t",1498,m=1413,x=61.4,y=21.1,f={c={"WARRIOR"}}},{"a",1502,m=1413,x=61.4,y=21.1,f={c={"WARRIOR"}},ml=10}}},
  {t="The Crossroads", lv=14, n="You arrive from Far Watch Post. Zargh and Sergra stand by the inn, Helbrim and Gazrog by the north gate; Devrak, Thork and Darsok on the tower platform.", f={r={"Orc","Troll"}}, g={{"a",6365,m=1413,x=52.6,y=29.8,ml=10},{"t",842,m=1413,x=52.2,y=31},{"a",844,m=1413,x=52.2,y=31,ml=10},{"a",869,m=1413,x=51.9,y=30.3,ml=9},{"t",1358,n2="Apothecary Helbrim: Sample for Helbrim, from Zinge",m=1413,x=51.4,y=30.1},{"a",1492,m=1413,x=51.4,y=30.1,ml=9},{"a",848,m=1413,x=51.4,y=30.1,ml=10},{"t",6365,n2="Devrak, on the tower",m=1413,x=51.5,y=30.3},{"fp",25,txt="Get the Crossroads flight path (Devrak)",m=1413,x=51.5,y=30.3},{"a",5041,m=1413,x=51.5,y=30.9,ml=9},{"a",871,m=1413,x=51.5,y=30.9,ml=9},{"a",867,n2="Darsok Swiftdagger: the harpies come later, in the Dry Hills",m=1413,x=51.6,y=30.9,ml=12}}},
  {t="Thun'grim Firegaze", lv=14, n="Thun'grim camps beside the road east toward Ratchet.", f={c={"WARRIOR"},r={"Orc","Troll"}}, g={{"t",1502,m=1413,x=57.2,y=30.3},{"a",1503,m=1413,x=57.2,y=30.3,ml=10}}},
  {t="Razormane camp", lv=14, n="The Razormane camp lies east of the Crossroads. Warriors: the Stolen Iron Chest stands in the camp. Shamans: the quilboar drop the Fire Tar.\nCareful: The chest stands next to a broken wagon, guarded by a pair of Razormanes, including hunters that can pull more quilboar into the fight.", f={c={"WARRIOR","SHAMAN"},r={"Orc","Troll"}}, g={{"o",1503,i=1,txt="Forged Steel Bars",m=1413,x=55,y=26.6,f={c={"WARRIOR"}}},{"o",1525,i=1,txt="Fire Tar",m=1413,x=55.1,y=26.6,f={c={"SHAMAN"}}}}},
  {t="Razormane camp: Thork's quilboar", lv=14, n="While you are in the camp: Thork's Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time.", f={c={"WARRIOR","SHAMAN"},r={"Orc","Troll"}}, g={{"o",871,i=1,txt="Kill Razormane Water Seeker x8",m=1413,x=54.9,y=26.7},{"o",871,i=2,txt="Kill Razormane Thornweaver x8",m=1413,x=55.1,y=26.6},{"o",871,i=3,txt="Kill Razormane Hunter x3",m=1413,x=55.6,y=26.5},{"o",5041,i=1,txt="Crossroads' Supply Crates",m=1413,x=58.8,y=25.8}}},
  {t="Durotar", lv=14, w={{k="onquest",q={1525}}}, f={c={"SHAMAN"},r={"Orc","Troll"}}, g={{"g",0,txt="Telf Joolam",m=1411,x=38.5,y=59}}},
  {t="Telf Joolam", lv=14, n="Back east over the bridge and up the trail to Telf's shrine, as at 10. Telf makes Fire Sapta from the tar and pouch. Use it by the brazier next to him to reveal the Minor Manifestation of Fire, kill it for the Glowing Ember, then place the ember in the brazier.", f={c={"SHAMAN"},r={"Orc","Troll"}}, g={{"t",1525,m=1411,x=38.5,y=59},{"a",1526,m=1411,x=38.5,y=59,ml=10},{"o",1526,i=1,txt="Glowing Ember",m=1411,x=38.7,y=58.3},{"t",1526,m=1411,x=39,y=58.2},{"a",1527,m=1411,x=39,y=58.2,ml=10}}},
  {t="The Barrens", lv=14, f={c={"SHAMAN"},r={"Orc","Troll"}}, g={{"g",0,txt="Kranal Fiss",m=1413,x=61.4,y=21.1}}},
  {t="Kranal Fiss", lv=14, f={c={"SHAMAN"},r={"Orc","Troll"}}, g={{"t",1527,n2="Kranal Fiss: Searing Totem, your Fire Totem and the Totem of Charged Flames",m=1413,x=56,y=19.9}}},
  {t="Thun'grim Firegaze", lv=14, f={c={"WARRIOR"},r={"Orc","Troll"}}, g={{"t",1503,m=1413,x=57.2,y=30.3}}},
  {t="The Crossroads", lv=14, n="The Crossroads is your base for this guide. Everyone you need stands within a few steps of the inn: Sergra by the inn, Helbrim and Gazrog by the north gate, then up the tower to Devrak, the wind rider master, Thork and Darsok, and Tonga at the south gate on the way out.", lb="crossroads", g={{"a",844,m=1413,x=52.2,y=31,ml=10},{"b",0,txt="Set your hearthstone at The Crossroads",m=1413,x=52,y=29.9,at="The Crossroads"},{"t",1358,n2="Apothecary Helbrim: Sample for Helbrim, from Zinge",m=1413,x=51.4,y=30.1,f={r={"Tauren","Scourge","Skyborne"}}},{"a",1492,m=1413,x=51.4,y=30.1,ml=9},{"a",848,m=1413,x=51.4,y=30.1,ml=10},{"a",869,m=1413,x=51.9,y=30.3,ml=9},{"fp",25,txt="Get the Crossroads flight path (Devrak)",m=1413,x=51.5,y=30.3},{"t",98024,n2="Thork, at the top of the tower",m=1413,x=51.5,y=30.9,f={r={"Skyborne"}}},{"a",5041,m=1413,x=51.5,y=30.9,ml=9},{"a",871,m=1413,x=51.5,y=30.9,ml=9},{"a",867,n2="Darsok Swiftdagger: the harpies come later, in the Dry Hills",m=1413,x=51.6,y=30.9,ml=12},{"a",870,m=1413,x=52.3,y=31.9,ml=10}}},
  {t="Raptor Heads as you go", lv=14, n="Sunscale raptors roam the plains north and east of the Crossroads, and about three in four drop a head: kill the ones you pass on the way. Careful: Sunscale Screechers call nearby allies within 30 yd once below 30% health.", al=true, g={{"o",869,i=1,txt="Raptor Head x12",m=1413,x=52.9,y=33}}},
  {t="Plainstrider Beaks as you go", lv=14, n="Plainstriders roam the plains all over the Barrens, and about one in four drops a beak: kill the ones you pass on the way.", al=true, g={{"o",844,i=1,txt="Plainstrider Beak x7",m=1413,x=52.9,y=33.6}}},
  {t="Razormane camp", lv=14, n="In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time.", g={{"o",871,i=1,txt="Kill Razormane Water Seeker x8",m=1413,x=54.9,y=26.7},{"o",871,i=2,txt="Kill Razormane Thornweaver x8",m=1413,x=55.1,y=26.6},{"o",5041,i=1,txt="Crossroads' Supply Crates",m=1413,x=58.8,y=25.8},{"o",871,i=3,txt="Kill Razormane Hunter x3",m=1413,x=59.2,y=26.4}}},
  {t="Finish the Plainstrider Beaks", lv=14, n="Still short of seven? Plainstriders are thickest on the plains north of the Crossroads, along the road north.", w={{k="has",neg=true,n=7,item=5087}}, g={{"o",844,i=1,txt="Plainstrider Beak x7",m=1413,x=53,y=21}}},
  {t="The Crossroads", lv=14, lb="q844", g={{"t",844,m=1413,x=52.2,y=31},{"a",845,m=1413,x=52.2,y=31,ml=10},{"t",871,m=1413,x=51.5,y=30.9},{"t",5041,m=1413,x=51.5,y=30.9},{"a",872,m=1413,x=51.5,y=30.9,ml=9}}},
  {t="The Zhevra", lv=14, n="Zhevra Runners graze along the road east toward Ratchet: take their hooves on the way out.", g={{"o",845,i=1,txt="Zhevra Hooves x4",m=1413,x=56.3,y=32.6}}},
  {t="", lv=14, w={{k="onquest",q={1522}}}, f={c={"SHAMAN"},r={"Tauren"}}, g={{"t",1522,m=1413,x=56,y=19.9}}},
  {t="", lv=14, w={{k="onquest",q={2983}}}, f={c={"SHAMAN"},r={"Tauren"}}, g={{"t",2983,m=1413,x=56,y=19.9}}},
  {t="", lv=14, w={{k="onquest",q={2984}}}, f={c={"SHAMAN"},r={"Tauren"}}, g={{"t",2984,m=1413,x=56,y=19.9}}},
  {t="Kranal Fiss", lv=14, n="Kranal Fiss stands on the ridge north of the Razormane camp.", f={c={"SHAMAN"},r={"Tauren"}}, g={{"t",1523,m=1413,x=56,y=19.9},{"a",1524,m=1413,x=56,y=19.9,f={r={"Tauren"}},ml=10}}},
  {t="Far Watch Post", lv=14, n="Follow the road east to the outpost above the Southfury River.", f={c={"WARRIOR"},r={"Tauren"}}, g={{"t",1505,m=1413,x=61.4,y=21.1},{"a",1498,m=1413,x=61.4,y=21.1,f={r={"Tauren"}},ml=10}}},
  {t="Durotar", lv=14, f={c={"WARRIOR"},r={"Tauren"}}, g={{"g",0,txt="The thunder lizards across the river",m=1411,x=39.7,y=29.2}}},
  {t="Thunder lizards across the river", lv=14, n="Thunder Lizards and Lightning Hides graze just across the bridge below Far Watch Post.\nCareful: Halikor, a level 12 elite, roams Thunder Ridge among the lizards: watch for him before you pull.", f={c={"WARRIOR"},r={"Tauren"}}, g={{"o",1498,i=1,txt="Singed Scale x5",m=1411,x=39.1,y=29.3,f={r={"Tauren"}}}}},
  {t="Durotar", lv=14, f={c={"SHAMAN"},r={"Tauren"}}, g={{"g",0,txt="Telf Joolam",m=1411,x=38.5,y=59}}},
  {t="Telf Joolam", lv=14, n="Over the Southfury River bridge below Far Watch Post and south along the Durotar bank to where a narrow trail climbs the mountain: Telf keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail.", f={c={"SHAMAN"},r={"Tauren"}}, g={{"t",1524,m=1411,x=38.5,y=59,f={r={"Tauren"}}},{"a",1525,m=1411,x=38.5,y=59,f={r={"Tauren"}},ml=10}}},
  {t="Dustwind Gulch cultists", lv=14, n="Burning Blade Cultists hold Dustwind Gulch in northern Durotar; they drop the Reagent Pouch. The Fire Tar comes from the Razormane on your next visit to their camp.", f={c={"SHAMAN"},r={"Tauren"}}, g={{"o",1525,i=2,txt="Reagent Pouch",m=1411,x=52.4,y=26.8,f={r={"Tauren"}}}}},
  {t="The Barrens", lv=14, f={c={"WARRIOR"},r={"Tauren"}}, g={{"g",0,txt="Uzzek",m=1413,x=61.4,y=21.1}}},
  {t="Uzzek", lv=14, f={c={"WARRIOR"},r={"Tauren"}}, g={{"t",1498,m=1413,x=61.4,y=21.1,f={r={"Tauren"}}},{"a",1502,m=1413,x=61.4,y=21.1,f={r={"Tauren"}},ml=10}}},
  {t="Thun'grim Firegaze", lv=14, n="Thun'grim camps beside the road from the Crossroads to Ratchet. The Stolen Iron Chest sits in the south of the Razormane camp just north of him.", f={c={"WARRIOR"},r={"Tauren"}}, g={{"t",1502,m=1413,x=57.2,y=30.3,f={r={"Tauren"}}},{"a",1503,m=1413,x=57.2,y=30.3,f={r={"Tauren"}},ml=10},{"o",1503,i=1,txt="Forged Steel Bars",m=1413,x=55,y=26.6,f={r={"Tauren"}}},{"t",1503,m=1413,x=57.2,y=30.3,f={r={"Tauren"}}}}},
  {t="The Barrens", lv=14, f={c={"SHAMAN"},r={"Tauren"}}, g={{"g",0,txt="Ratchet",m=1413,x=62.7,y=36.2}}},
  {t="Ratchet", lv=14, n="Follow the road south-east to Ratchet on the coast.", g={{"a",887,n2="Gazlowe, upstairs",m=1413,x=62.7,y=36.2,ml=9},{"a",97253,m=1413,x=63.1,y=36.3,ml=9},{"a",894,n2="Sputtervalve: the console is in the Sludge Fen, later",m=1413,x=63,y=37.2,ml=10},{"fp",80,txt="Get the Ratchet flight path (Bragok)",n2="Bragok, beside Sputtervalve",m=1413,x=63.1,y=37.2,f={r={"Orc","Skyborne","Tauren","Troll","Scourge"}}},{"a",895,n2="WANTED poster",m=1413,x=62.6,y=37.5,ml=11},{"a",865,m=1413,x=62.4,y=37.6,ml=13},{"b",0,txt="Set your hearthstone at Ratchet",m=1413,x=62,y=39.4,at="Ratchet"},{"t",1492,n2="Wharfmaster Dizzywig, on the dock",m=1413,x=63.4,y=38.5},{"a",896,n2="Wharfmaster Dizzywig: the emerald comes from the Boulder Lode Mine, later",m=1413,x=63.4,y=38.5,ml=13}}},
  {t="The Barrens: kill these as you meet them", lv=14, n="The pirates camp on the beach south of Ratchet: the piles of complicated parts lie in the sand among them, and Baron Longshore stands at the camp's southern end.", g={{"o",887,i=1,txt="Kill Southsea Brigand x12",m=1413,x=63.6,y=43.4},{"o",887,i=2,txt="Kill Southsea Cannoneer x6",m=1413,x=63.9,y=43.8},{"o",97253,i=1,txt="Handful of Complicated Parts x5",m=1413,x=62.2,y=44},{"o",895,i=1,txt="Baron Longshore's Head",m=1413,x=64.2,y=47.1}}},
  {t="Ratchet", lv=14, g={{"t",887,n2="Gazlowe, upstairs",m=1413,x=62.7,y=36.2},{"t",895,m=1413,x=62.7,y=36.2},{"a",890,m=1413,x=62.7,y=36.2,ml=9},{"t",97253,m=1413,x=63.1,y=36.3},{"t",890,m=1413,x=63.4,y=38.5},{"a",892,m=1413,x=63.4,y=38.5,ml=9},{"t",892,m=1413,x=62.7,y=36.2},{"a",888,n2="Gazlowe: the crates lie at the south end of the beach camp, on the walk to Northwatch Hold at 18",m=1413,x=62.7,y=36.2,ml=9}}},
  {t="Fly to Crossroads", lv=14, g={{"g",0,txt="Ratchet flight master",m=1413,x=63.1,y=37.1},{"z",0,txt="Fly to Crossroads",at="Crossroads"}}},
  {t="The Crossroads", lv=14, g={{"t",845,m=1413,x=52.2,y=31},{"a",903,m=1413,x=52.2,y=31,ml=10}}},
  {t="Regthar Deathgate", lv=14, n="West to Regthar's watch post on the Kolkar border.", g={{"a",855,m=1413,x=45.3,y=28.4,ml=9},{"a",850,m=1413,x=45.3,y=28.4,ml=11}}},
  {t="The Barrens: kill these as you meet them", lv=14, n="The pools lie just north of Regthar. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. Barak Kodobane stands in the Kolkar camp west of the pools.", g={{"o",855,i=1,txt="Centaur Bracers x15",m=1413,x=45.9,y=25.4},{"c",870,txt="Explore the waters of the Forgotten Pools",m=1413,x=45.3,y=22.8},{"o",848,i=1,txt="Fungal Spores x4",m=1413,x=45.6,y=22.5},{"o",850,i=1,txt="Kodobane's Head",m=1413,x=42.8,y=23.5}}},
  {t="Regthar Deathgate", lv=14, g={{"t",855,m=1413,x=45.3,y=28.4},{"t",850,m=1413,x=45.3,y=28.4},{"a",851,n2="Regthar Deathgate: Verog walks with the Kolkar at the Stagnant Oasis, later",m=1413,x=45.3,y=28.4,ml=11}}},
  {t="The Dry Hills", lv=14, n="West to the Dry Hills. The Witchwing harpies nest all over them; any of them can drop a talon. Chen's Empty Keg lies in their hills. Savannah Prowlers hunt the plains between Regthar and the hills: take their claws on the way.\nCareful: There are 2 Witchwing Ambushers (level 17-18). They stay stealthed with Sneak while out of combat.", g={{"o",903,i=1,txt="Prowler Claws x7",m=1413,x=44.2,y=31.2},{"o",867,i=1,txt="Witchwing Talon x8",m=1413,x=41.9,y=19.3}}},
  {t="Samophlange", lv=14, n="The Control Console stands at the Venture Co. research site west of the Sludge Fen. Close the three valves around the drill, use the console again, then take the Console Key from Tinkerer Sniggles beside it.\nCareful: Several guards stand within aggro range of the valves, respawn in under about 3 minutes, and run at low health to bring back help; nearby mobs also join if you use a valve while they are close.", g={{"t",894,m=1413,x=52.4,y=11.7},{"a",900,m=1413,x=52.4,y=11.7,ml=10},{"o",900,i=1,txt="Main Control Valve",m=1413,x=52.3,y=11.6},{"o",900,i=2,txt="Fuel Control Valve",m=1413,x=52.4,y=11.4},{"o",900,i=3,txt="Regulator Valve",m=1413,x=52.3,y=11.4},{"t",900,m=1413,x=52.4,y=11.7},{"a",901,m=1413,x=52.4,y=11.7,ml=10},{"o",901,i=1,txt="Console Key",n2="Inside",m=1413,x=52.8,y=10.4},{"t",901,m=1413,x=52.4,y=11.7},{"a",902,n2="Sputtervalve in Ratchet: on the next Ratchet stop",m=1413,x=52.4,y=11.7,ml=10}}},
  {t="The Disruption Ends", lv=14, n="Back to the Razormane camp. Geomancers and Defenders hold its eastern half; Kreenig Snarlsnout walks among them.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near Kreenig: pull Kreenig and the quilboar away from them one at a time.", g={{"o",872,i=2,txt="Kill Razormane Defender x8",m=1413,x=56.7,y=24.6},{"o",872,i=1,txt="Kill Razormane Geomancer x8",m=1413,x=57,y=24.5},{"o",872,i=3,txt="Kreenig Snarlsnout's Tusk",m=1413,x=58.5,y=27},{"o",1525,i=1,txt="Fire Tar",m=1413,x=58.5,y=27.2,f={c={"SHAMAN"},r={"Tauren"}}}}},
  {t="Durotar", lv=14, f={c={"SHAMAN"},r={"Tauren"}}, g={{"g",0,txt="Telf Joolam",m=1411,x=38.5,y=59}}},
  {t="Telf Joolam", lv=14, n="Telf makes Fire Sapta from the tar and pouch. Use it by the brazier next to him to reveal the Minor Manifestation of Fire, kill it for the Glowing Ember, then place the ember in the brazier.", f={c={"SHAMAN"},r={"Tauren"}}, g={{"t",1525,m=1411,x=38.5,y=59,f={r={"Tauren"}}},{"a",1526,m=1411,x=38.5,y=59,f={r={"Tauren"}},ml=10},{"o",1526,i=1,txt="Glowing Ember",m=1411,x=38.7,y=58.3,f={r={"Tauren"}}},{"t",1526,m=1411,x=39,y=58.2,f={r={"Tauren"}}},{"a",1527,m=1411,x=39,y=58.2,f={r={"Tauren"}},ml=10}}},
  {t="The Barrens", lv=14, n="Sunscale raptors here count toward the heads.", f={c={"SHAMAN"},r={"Tauren"}}, g={{"g",0,txt="Kranal Fiss",m=1413,x=56,y=19.9}}},
  {t="Kranal Fiss", lv=14, f={c={"SHAMAN"},r={"Tauren"}}, g={{"t",1527,n2="Kranal Fiss: Searing Totem, your Fire Totem and the Totem of Charged Flames",m=1413,x=56,y=19.9,f={r={"Tauren"}}}}},
  {t="The Crossroads", lv=14, n="Sergra by the inn first, then the innkeeper, Helbrim by the north gate, Thork and Darsok on the tower platform, Mankrik by the inn, and Tonga at the south gate last. His seed test waits for the Verog pass at the Stagnant Oasis: go straight on north-west to the Dry Hills. After the spores Helbrim offers Apothecary Zamah, a delivery to Thunder Bluff within 45 minutes: this route doesn't go there, so leave it (Druids take it on the next Crossroads stop, right before their flight to Thunder Bluff).", g={{"t",903,m=1413,x=52.2,y=31},{"a",881,m=1413,x=52.2,y=31,ml=10},{"b",0,txt="Set your hearthstone at The Crossroads",m=1413,x=52,y=29.9,at="The Crossroads"},{"t",848,m=1413,x=51.4,y=30.1},{"t",872,m=1413,x=51.5,y=30.9},{"t",867,m=1413,x=51.6,y=30.9},{"a",875,m=1413,x=51.6,y=30.9,ml=12},{"a",4921,n2="Mankrik: his wife lies at the north edge of the Bristleback camps, later",m=1413,x=52,y=31.6,ml=14},{"a",899,m=1413,x=52,y=31.6,ml=14},{"t",870,m=1413,x=52.3,y=31.9},{"a",877,n2="Tonga Runetotem: the bubbling fissure at the Stagnant Oasis, on the Verog pass",m=1413,x=52.3,y=31.9,ml=10}}},
  {t="Harpy Lieutenants", lv=14, n="North-west to the Dry Hills: the Witchwing Slayers hold their western end; they wear the rings.\nCareful: Some stealthed harpy ambushers wait in the area and stay hidden until you get close. A level 19 elite harpy also patrols there.", g={{"o",875,i=1,txt="Harpy Lieutenant Ring x6",m=1413,x=40.2,y=16}}},
  {t="The Dry Hills", lv=14, g={{"h",4926,txt="Get Chen's Empty Keg",m=1413,x=37.9,y=16.2,n=1},{"a",819,ml=11}}},
  {t="Raptor Horns", lv=14, n="On the way east to Echeyakee: Sunscale Scytheclaws prowl the plains east of the Dry Hills; any of them can drop an Intact Raptor Horn for Mebok in Ratchet.", g={{"o",865,i=1,txt="Intact Raptor Horn x5",m=1413,x=44.1,y=14.4}}},
  {t="Echeyakee", lv=14, n="South-east on the way back to the Crossroads: Echeyakee, a white lion, prowls the plains north of the Razormane camp.\nCareful: Savannah Huntresses roam around the lair. They respawn quickly and often join the fight alongside Echeyakee, so clear them out before you blow the horn.\nSunscale raptors here count toward the heads.", g={{"o",881,i=1,txt="Use Horn of Echeyakee",m=1413,x=55.8,y=17.1},{"o",881,i=1,txt="Echeyakee's Hide",m=1413,x=55.9,y=17.2}}},
  {t="Finish the Raptor Heads", lv=14, n="Still short of twelve? Sunscale Lashtails and Screechers roam the plains north-east of the Crossroads, on the way back south from Echeyakee's lair.", w={{k="has",neg=true,n=12,item=5062}}, g={{"o",869,i=1,txt="Raptor Head x12",m=1413,x=55,y=23.5}}},
  {t="The Crossroads", lv=17, n="In from the north gate: Gazrog first, Sergra by the inn, then up to Darsok and Thork on the tower platform, where the flight master stands.", lb="q869", g={{"t",869,m=1413,x=51.9,y=30.3},{"a",3281,n2="Gazrog: the Stolen Silver, in a raptor nest north-west of Northwatch Hold",m=1413,x=51.9,y=30.3,ml=9},{"a",853,n2="Apothecary Helbrim: 45 minutes, for Zamah on the Thunder Bluff step next",m=1413,x=51.4,y=30.1,f={c={"DRUID"}},ml=10},{"t",881,m=1413,x=52.2,y=31},{"a",905,n2="Sergra Darkthorn: the raptor nests south of the Crossroads",m=1413,x=52.2,y=31,ml=10},{"t",875,m=1413,x=51.6,y=30.9},{"a",876,n2="Darsok Swiftdagger, on the tower: Serena Bloodfeather leads the harpies in the Dry Hills",m=1413,x=51.6,y=30.9,ml=12},{"a",6541,n2="Thork, on the tower, from level 17. Keep it: Kadrak at the Mor'shan Rampart, next guide",m=1413,x=51.5,y=30.9,ml=17}}},
  {t="Thunder Bluff", lv=17, n="Fly from the Crossroads to Thunder Bluff. Apothecary Zamah waits in the Pools of Vision, the cave under Spirit Rise: hand in the spores there first, while their time runs. Then Turak Runetotem trains you on Elder Rise.", f={c={"DRUID"}}, g={{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"},{"t",853,n2="Apothecary Zamah, in the Pools of Vision",m=1456,x=22.8,y=20.9},{"tr",0,txt="Visit your class trainer"},{"a",27,m=1456,x=76.5,y=27.2,f={r={"Tauren","Skyborne"}},ml=16},{"a",6126,n2="Turak Runetotem: Lessons Anew",m=1456,x=76.5,y=27.2,f={r={"Tauren","Skyborne"}},ml=14}}},
  {t="Moonglade", lv=17, f={c={"DRUID"},r={"Tauren","Skyborne"}}, g={{"g",0,txt="Cast Teleport: Moonglade",m=1450,x=56.3,y=32.5}}},
  {t="Trial of the Lake", lv=17, n="Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. The Shrine Baubles lie on the bed of Lake Elune'ara and fade within minutes: swim one straight to the Shrine of Remulos on the north-west shore, use it there and speak to Tajarri. Trial of the Lake runs on a timer: no teleport or Hearthstone until Tajarri has it.", f={c={"DRUID"},r={"Tauren","Skyborne"}}, g={{"t",27,m=1450,x=56.2,y=30.6,f={r={"Tauren","Skyborne"}}},{"t",6126,m=1450,x=56.2,y=30.6,f={r={"Tauren","Skyborne"}}},{"a",6127,n2="The Principal Source: Dreadmist Peak, next guide",m=1450,x=56.2,y=30.6,f={r={"Tauren","Skyborne"}},ml=14},{"a",28,m=1450,x=56.2,y=30.6,f={r={"Tauren","Skyborne"}},ml=16},{"h",15877,txt="Get Shrine Bauble",n2="Shrine Bauble, from a Bauble Container in the lake",m=1450,x=54.7,y=46.4,n=1},{"i",0,txt="Use Shrine Bauble",n2="At the Shrine of Remulos",m=1450,x=36,y=41.4},{"c",28,txt="Shrine Of Remulos",f={r={"Tauren","Skyborne"}}},{"t",28,n2="Tajarri, at the Shrine of Remulos",m=1450,x=36.5,y=40.1,f={r={"Tauren","Skyborne"}}},{"a",30,n2="Trial of the Sea Lion, carried: one half pendant in the Sludge Fen in this guide, the other underwater off Silverpine on the way to Hillsbrad at 21; the pendant is handed in after Hillsbrad",m=1450,x=36.5,y=40.1,f={r={"Tauren","Skyborne"}},ml=16},{"z",0,txt="Fly to Thunder Bluff",n2="Bunthen Plainswind in Nighthaven flies druids there",at="Thunder Bluff"}}},
  {t="Fly to Ratchet", lv=17, n="Fly from Thunder Bluff straight on to Ratchet.", f={c={"DRUID"}}, g={{"z",0,txt="Fly to Ratchet",at="Ratchet"}}},
  {t="Fly to Ratchet", lv=17, f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"g",0,txt="Crossroads flight master",m=1413,x=51.5,y=30.4},{"z",0,txt="Fly to Ratchet",at="Ratchet"}}},
  {t="Ratchet", lv=17, w={{k="group",q=92706}}, g={{"a",92706,n2="WANTED poster",m=1413,x=62.6,y=37.5,ml=15}}},
  {t="Ratchet", lv=17, g={{"a",865,n2="Mebok Mizzyrix, beside the WANTED poster: take it now if he did not offer it on the first Ratchet stop",m=1413,x=62.4,y=37.6,ml=13}}},
  {t="Ratchet", lv=17, w={{k="complete",q=865}}, g={{"t",865,n2="Mebok Mizzyrix, beside the WANTED poster",m=1413,x=62.4,y=37.6}}},
  {t="Ratchet", lv=17, w={{k="onquest",q={819}}}, g={{"t",819,m=1413,x=62.3,y=38.4}}},
  {t="Ratchet", lv=17, g={{"t",902,m=1413,x=63,y=37.2},{"a",1483,n2="Sputtervalve: keep it, Ziz Fizziks is on the Webwinder Path in Stonetalon, at the end of this guide",m=1413,x=63,y=37.2,ml=16},{"a",3921,n2="Sputtervalve: Wenikee stands on the road north of the Crossroads, on the way to the Sludge Fen",m=1413,x=63,y=37.2,ml=10},{"a",891,m=1413,x=62.3,y=39,ml=13},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Bruuz", lv=17, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Bruuz (level 20 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=92706}}, g={{"o",92706,i=1,txt="Bruuz's Dorsal Fin",m=1413,x=63.7,y=38.7,grp=true}}},
  {t="Ratchet", lv=17, n="Gazlowe stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", w={{k="group",q=92706}}, g={{"t",92706,m=1413,x=62.7,y=36.2}}},
  {t="Raptor nests", lv=17, n="South-west from Ratchet across the plains to the Raptor Grounds: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a Sunscale Feather: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest.", g={{"o",905,i=1,txt="Blue Raptor Nest",m=1413,x=52.6,y=46.1},{"o",905,i=2,txt="Yellow Raptor Nest",m=1413,x=52,y=46.5},{"o",905,i=3,txt="Red Raptor Nest",m=1413,x=52.5,y=46.6}}},
  {t="Raptor Grounds: kill these as you meet them", lv=17, n="Sunscale Scytheclaws hunt the plains around the Raptor Grounds; they drop the horns. Mebok takes them when the escort brings you back to Ratchet.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of Northwatch Hold.", g={{"o",865,i=1,txt="Intact Raptor Horn x5",m=1413,x=52.6,y=46},{"o",3281,i=1,txt="Stolen Silver",m=1413,x=58,y=53.9}}},
  {t="Stolen Booty", lv=17, n="East to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, a short walk north of Northwatch Hold.", g={{"o",888,i=1,txt="Shipment of Boots",m=1413,x=62.6,y=49.6},{"o",888,i=2,txt="Telescopic Lens",m=1413,x=63.6,y=49.3}}},
  {t="Northwatch Hold: kill these as you meet them", lv=17, n="Northwatch Hold, on the coast just south of the pirate camp. The Theramore Marines and Preservers (15-16) drop the medals; Captain Fairmount (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier.", g={{"o",891,i=4,txt="Theramore Medal x10",m=1413,x=62,y=51.7},{"o",891,i=1,txt="Kill Captain Fairmount",n2="On the top floor",m=1413,x=61.9,y=54.6},{"o",891,i=2,txt="Kill Cannoneer Whessan",n2="On the top floor",m=1413,x=60.4,y=54.8},{"o",891,i=3,txt="Kill Cannoneer Smythe",n2="Upstairs",m=1413,x=63.2,y=56.6}}},
  {t="Free From the Hold", lv=17, n="Gilthares Firebough is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to Ratchet.", g={{"a",898,n2="Inside",m=1413,x=62,y=55,ml=13}}},
  {t="Ratchet", lv=17, g={{"g",0,txt="Go here",m=1413,x=62.3,y=39.1},{"c",898,txt="Escort Gilthares Firebough back to Ratchet"}}},
  {t="Ratchet", lv=17, g={{"t",898,m=1413,x=62.3,y=39},{"t",891,m=1413,x=62.3,y=39}}},
  {t="Ratchet", lv=17, w={{k="complete",q=865}}, g={{"t",865,n2="Mebok Mizzyrix, beside the WANTED poster",m=1413,x=62.4,y=37.6}}},
  {t="Ratchet", lv=17, g={{"t",888,n2="Gazlowe, upstairs",m=1413,x=62.7,y=36.2}}},
  {t="Fly to Crossroads", lv=17, g={{"g",0,txt="Ratchet flight master",m=1413,x=63.1,y=37.1},{"z",0,txt="Fly to Crossroads",at="Crossroads"}}},
  {t="The Crossroads", lv=17, g={{"t",905,m=1413,x=52.2,y=31},{"a",3261,m=1413,x=52.2,y=31,ml=10},{"t",3281,m=1413,x=51.9,y=30.3}}},
  {t="Dreadmist Peak", lv=17, n="Head north from the Crossroads to Dreadmist Peak and fill the Empty Dreadmist Peak Sampler at the Dreadmist Peak Pool, then back to Tonga Runetotem in the Crossroads. No Herbalism? Hula'mahi beside him sells Earthroot, three at a time until he restocks.", f={c={"DRUID"},r={"Tauren","Skyborne"}}, g={{"o",6127,i=1,txt="Filled Dreadmist Peak Sampler",m=1413,x=48.4,y=18.9,f={r={"Tauren","Skyborne"}}},{"t",6127,m=1413,x=52.3,y=31.9,f={r={"Tauren","Skyborne"}}},{"a",6128,m=1413,x=52.3,y=31.9,f={r={"Tauren","Skyborne"}},ml=14},{"h",2449,txt="Buy Earthroot x5 (Hula'mahi)",n2="Earthroot from Hula'mahi; herbalists pick it on the plains",m=1413,x=51.4,y=30.2,n=5,opt=true}}},
  {t="Kolkar camp", lv=17, n="Lost Barrens Kodos roam the plains around the Kolkar camp north-west of Regthar; herbalists pick Earthroot there too.", f={c={"DRUID"},r={"Tauren","Skyborne"}}, g={{"o",6128,i=2,txt="Kodo Horn x5",m=1413,x=54.8,y=40.1},{"o",6128,i=1,txt="Earthroot x5",m=1413,x=60.9,y=41.3}}},
  {t="Vrang Wildgore", lv=17, n="North to the Dry Hills. Vrang Wildgore camps below the hills; Walton, the hermit on the ridge behind him, has work for you only once Vrang sends you up.", g={{"a",95494,m=1413,x=43.8,y=12.2,ml=14},{"a",95507,m=1413,x=43.8,y=12.2,ml=14}}},
  {t="The Barrens: kill these as you meet them", lv=17, n="Savannah Patriarchs roam the plains east of the hills, and the Sprung Traps lie among them. Serena Bloodfeather leads the Witchwing harpies in the hills to the west.\nCareful: The route in passes stealthed Harpy Ambushers and an elite harpy that patrols.", g={{"o",95507,i=1,txt="Trapped Game x8",m=1413,x=44.2,y=13.1},{"o",95494,i=1,txt="Savannah Lion Hide x6",m=1413,x=45,y=14.5},{"o",865,i=1,txt="Intact Raptor Horn x5",n2="Raptor Horns, if still open: Sunscale Scytheclaws prowl among the lions",m=1413,x=44.7,y=14.3},{"o",876,i=1,txt="Serena's Head",m=1413,x=39.2,y=12.2}}},
  {t="Vrang Wildgore", lv=17, g={{"t",95494,m=1413,x=43.8,y=12.2},{"t",95507,m=1413,x=43.8,y=12.2},{"a",95495,m=1413,x=43.8,y=12.2,ml=14}}},
  {t="Walton", lv=17, g={{"t",95495,m=1413,x=42,y=11.4},{"a",95621,m=1413,x=42,y=11.4,ml=14}}},
  {t="Trouble in the Valley", lv=17, n="Corporal Adamore and his marines hold the wrecked caravan south of Walton. The marines are linked: pulling one calls the rest. Pull from the edge and run; they leash short, so you can thin the camp one at a time before tackling the Corporal.", g={{"o",95621,i=1,txt="Benedict's Orders",m=1413,x=41.8,y=15.6}}},
  {t="Walton", lv=17, g={{"t",95621,m=1413,x=42,y=11.4},{"a",95508,m=1413,x=42,y=11.4,ml=14},{"c",95508,txt="Assist Walton",n2="Assist Walton: stay by him when Terry Longdrink and the Kul Tiras marines come up the ridge"},{"t",95508,m=1413,x=42,y=11.4}}},
  {t="Wenikee Boltbucket", lv=17, n="East from Walton toward the Sludge Fen: Wenikee stands at the camp on the road north of the Crossroads.", g={{"t",3921,m=1413,x=49,y=11.2},{"a",3922,m=1413,x=49,y=11.2,ml=10}}},
  {t="Ignition", lv=17, n="Wizzlecrank's Shredder stands inside the Venture Co. camp in the Sludge Fen; Supervisor Lugwizzle carries the key.", g={{"a",858,m=1413,x=56.5,y=7.5,ml=13},{"o",858,i=1,txt="Ignition Key",m=1413,x=56.3,y=8.6},{"t",858,m=1413,x=56.5,y=7.5},{"a",863,m=1413,x=56.5,y=7.5,ml=13}}},
  {t="Strange Lockbox", lv=17, n="The Strange Lockbox lies at the north edge of the Sludge Fen, by the Venture Co. tower. It holds the Half Pendant of Aquatic Agility for Trial of the Sea Lion.", w={{k="onquest",q={30}}}, f={c={"DRUID"},r={"Tauren","Skyborne"}}, g={{"h",15883,txt="Get Half Pendant of Aquatic Agility",m=1413,x=56.7,y=8.3,n=1}}},
  {t="The Escape", lv=17, n="Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. Sputtervalve takes it in Ratchet.\nCareful: The route leads west and climbs a ramp. Once you reach the top, two Venture Company mobs ambush you.", g={{"g",0,txt="Go here",m=1413,x=55.4,y=7.7},{"c",863,txt="Escort Wizzlecrank out of the Venture Co. drill site"}}},
  {t="Nugget Slugs", lv=17, n="The tool buckets with the slugs lie around the Venture Co. drill site in the Sludge Fen.", g={{"o",3922,i=1,txt="Nugget Slug x15",m=1413,x=55.5,y=8}}},
  {t="Boulder Lode Mine", lv=17, n="The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the Cats Eye Emerald.", g={{"o",896,i=1,txt="Cats Eye Emerald",m=1413,x=59.6,y=3.8}}},
  {t="Wenikee Boltbucket", lv=17, n="West from the mine to Wenikee's camp, then south down the road to the Crossroads.", g={{"t",3922,m=1413,x=49,y=11.2},{"a",3923,n2="Keep it: Rilli Greasygob is in Orgrimmar's Valley of Honor, on the Orgrimmar trip at 20",m=1413,x=49,y=11.2,ml=10}}},
  {t="the Crossroads", lv=17, n="South down the road to the Crossroads: Darsok stands on the tower platform, Tonga Runetotem at the south gate.", g={{"t",876,m=1413,x=51.6,y=30.9},{"a",1060,m=1413,x=51.6,y=30.9,ml=15},{"t",6128,m=1413,x=52.3,y=31.9,f={c={"DRUID"},r={"Tauren","Skyborne"}}},{"a",6129,n2="He gives you the Curative Animal Salve",m=1413,x=52.3,y=31.9,f={c={"DRUID"},r={"Tauren","Skyborne"}},ml=14}}},
  {t="Verog the Dervish", lv=17, n="Verog walks among the Kolkar at the Stagnant Oasis south-east of the Crossroads. Test Tonga's seeds at the bubbling fissure on the oasis' east bank while you are there.", g={{"o",851,i=1,txt="Verog's Head",m=1413,x=53.1,y=41.7},{"o",877,i=1,txt="Bubbling Fissure",n2="Underwater",m=1413,x=55.6,y=42.8},{"o",6129,i=1,txt="Cure Sickly Gazelle x10",n2="Sickly Gazelle: use the Curative Animal Salve on them; they roam the plains all around the Crossroads",m=1413,x=56.9,y=39,f={c={"DRUID"},r={"Tauren","Skyborne"}}}}},
  {t="Bristleback camps", lv=17, n="The Bristleback quilboar camps spread over the plains north of Camp Taurajo, either side of the Gold Road. Mankrik's wife lies at their north edge, on your way south. Leave the quilboar for now: Mangletooth in Camp Taurajo wants the same camps cleared. Lakota'mani, a grey kodo, sometimes wanders here: his hoof starts a quest.", g={{"o",4921,i=1,txt="Talk to Beaten Corpse",m=1413,x=49.3,y=50.3}}},
  {t="Camp Taurajo", lv=17, n="Follow the Gold Road south to Camp Taurajo.", g={{"a",878,n2="Mangletooth, in the cage",m=1413,x=44.5,y=59.3,ml=14},{"fp",77,txt="Get the Camp Taurajo flight path (Omusa Thunderhorn)",m=1413,x=44.5,y=59.1},{"t",3261,m=1413,x=44.9,y=59.1},{"a",882,m=1413,x=44.9,y=59.1,ml=10}}},
  {t="Bramblescar", lv=17, n="Back north into the Bristleback camps. Any Bristleback can drop a tusk for Mankrik, so collect them while you kill these for Mangletooth. Keep one Blood Shard.", g={{"o",878,i=1,txt="Kill Bristleback Water Seeker x6",m=1413,x=45.1,y=55.3},{"o",878,i=2,txt="Kill Bristleback Thornweaver x12",m=1413,x=45.5,y=51.6},{"o",878,i=3,txt="Kill Bristleback Geomancer x12",m=1413,x=43.8,y=48.2},{"o",899,i=1,txt="Bristleback Quilboar Tusk x60",m=1413,x=43.8,y=48.2}}},
