  {t="The Crossroads", lv=17, n="North up the Gold Road to the Crossroads: Tonga Runetotem at the south gate, Mankrik by the inn, Korran west of the north gate. Keep the Blood Shard: Mangletooth takes it on the next stop in Camp Taurajo.", g={{"t",877,m=1413,x=52.3,y=31.9},{"a",880,n2="Tonga Runetotem: the Oasis Snapjaws at Lushwater Oasis, with Hezrul after the Orgrimmar trip",m=1413,x=52.3,y=31.9,ml=10},{"t",899,m=1413,x=52,y=31.6},{"t",4921,m=1413,x=52,y=31.6},{"a",95774,n2="Mankrik offers Her Name Is Olgra once Lost in Battle is handed in",m=1413,x=52,y=31.6,ml=14},{"a",868,n2="Korran: the eggs are in the Field of Giants, south of Camp Taurajo, after the Orgrimmar trip",m=1413,x=51.1,y=29.6,ml=17}}},
