  {t="Ishamuhale", lv=20, n="Ishamuhale, a big Sunscale raptor, only comes to a fresh kill: loot a Fresh Zhevra Carcass from a zhevra, then use it at the Dead Tree north-west of Ratchet, north of the road to the Crossroads, and be ready when he arrives.", g={{"h",10338,txt="Get Fresh Zhevra Carcass",n2="Fresh Zhevra Carcass, from any zhevra; Zhevra Chargers graze around the tree",m=1413,x=61.3,y=50.1,n=1},{"o",882,i=1,txt="Use Fresh Zhevra Carcass",n2="At the Dead Tree: summons Ishamuhale",m=1413,x=60,y=30.2},{"o",882,i=1,txt="Ishamuhale's Fang",m=1413,x=59.8,y=30.6}}},
