  {t="Hezrul Bloodmark", lv=20, n="Hezrul leads the Kolkar on the west shore of Lushwater Oasis, south of Regthar. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to Regthar on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for Tonga.", g={{"o",852,i=1,txt="Hezrul's Head",m=1413,x=46,y=41.1},{"o",880,i=1,txt="Altered Snapjaw Shell x8",m=1413,x=45.9,y=40.4}}},
  {t="Olgra's Adornments", lv=20, n="On the way back down the Gold Road to Camp Taurajo: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry Olgra's Adornments. Hand them to Mankrik on your last Crossroads stop.", g={{"o",95774,i=1,txt="Olgra's Adornments x4",m=1413,x=49.8,y=45.8}}},
  {t="Camp Taurajo", lv=20, n="Down the Gold Road to Camp Taurajo again.", g={{"b",0,txt="Set your hearthstone at Camp Taurajo",m=1413,x=45.6,y=59,at="Camp Taurajo"},{"t",882,m=1413,x=44.9,y=59.1},{"a",907,m=1413,x=44.9,y=59.1,ml=10},{"a",6382,n2="Keep it: Senani Thunderheart in Ashenvale, next guide",m=1413,x=44.9,y=59.1,ml=20},{"t",1823,n2="Ruga Ragetotem, inside",m=1413,x=44.7,y=59.4,f={c={"WARRIOR"}}},{"t",1511,m=1413,x=44.6,y=59.3,f={c={"WARLOCK"}}},{"a",1515,m=1413,x=44.6,y=59.3,f={c={"WARLOCK"}},ml=20},{"t",5052,n2="Mangletooth, in the cage",m=1413,x=44.5,y=59.3},{"t",883,m=1413,x=44.9,y=59.1,opt=true}}},
