  {t="Enraged Thunder Lizards", lv=20, n="Thunderheads graze on the plains just south of Camp Taurajo. Owatanka, a blue thunder lizard, roams among them: his Tailspike starts a quest.", g={{"o",907,i=1,txt="Thunder Lizard Blood x3",m=1413,x=43.5,y=49.2},{"h",5102,txt="Get Owatanka's Tailspike",m=1413,x=44.2,y=62,n=1,opt=true},{"a",884,opt=true,ml=10}}},
  {t="Jorn Skyseer", lv=20, n="Warriors: take Trial at the Field of Giants from Ruga Ragetotem now: it runs for 30 minutes from the accept. The eggs and the antennae come first, at the same mounds, then straight back to Ruga; the thunderhawks after.", g={{"t",907,m=1413,x=44.9,y=59.1},{"a",913,m=1413,x=44.9,y=59.1,ml=10},{"t",884,m=1413,x=44.9,y=59.1,opt=true},{"a",1824,n2="Ruga Ragetotem, inside",m=1413,x=44.7,y=59.4,f={c={"WARRIOR"}},ml=20}}},
  {t="Field of Giants", lv=20, n="South of Camp Taurajo, the Silithid Mounds dot the Field of Giants; the eggs lie in them, and Silithid Swarmers come out to defend them.\nCareful: Silithid Swarmers in the area release many tiny adds that interrupt spells; damage shields such as Thorns kill them in one hit.", g={{"o",868,i=1,txt="Silithid Egg x12",m=1413,x=44.9,y=69.4}}},
  {t="Twitching Antennae", lv=20, n="The antennae vanish fifteen minutes after they drop: kill the Silithid Swarmers and Creepers at the same mounds until you have five, then take them straight to Ruga Ragetotem in Camp Taurajo, before the thunderhawks.\nCareful: Silithid Swarmers (level 21-22) cast Silithid Swarm both in and out of combat, which brings several small adds. Silithid Creepers (level 20-21) periodically cast Silithid Creeper Egg in combat, which spawns extra adds.", f={c={"WARRIOR"}}, g={{"o",1824,i=1,txt="Twitching Antenna x5",n2="Twitching Antennae from the silithid",m=1413,x=45.1,y=69.5}}},
  {t="Ruga Ragetotem", lv=20, n="Back north into Camp Taurajo before the antennae fade: Ruga Ragetotem is inside.", f={c={"WARRIOR"}}, g={{"t",1824,n2="Ruga Ragetotem, inside",m=1413,x=44.7,y=59.4,f={c={"WARRIOR"}}},{"a",1825,m=1413,x=44.7,y=59.4,f={c={"WARRIOR"}},ml=20}}},
  {t="Cry of the Thunderhawk", lv=20, n="Thunderhawk Cloudscrapers circle over the plains south of the camp.", g={{"o",913,i=1,txt="Thunderhawk Wings",m=1413,x=44.8,y=63}}},
  {t="Brine", lv=20, n="Brine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo: fill the Empty Brown Waterskin at the watering hole below it.", f={c={"SHAMAN"}}, g={{"t",1530,m=1413,x=43.4,y=77.4},{"a",1535,m=1413,x=43.4,y=77.4,ml=20},{"o",1535,i=1,txt="Filled Brown Waterskin",n2="Fill the Empty Brown Waterskin at the quilboar watering hole",m=1413,x=44.3,y=76.8},{"t",1535,m=1413,x=43.4,y=77.4},{"a",1536,n2="Keep it: the Spring Well is beside Tarren Mill, on the Hillsbrad guide",m=1413,x=43.4,y=77.4,ml=20}}},
  {t="Camp Taurajo", lv=20, n="Back north into Camp Taurajo on the way to the Crossroads: Jorn takes the thunderhawk wings.", g={{"t",913,m=1413,x=44.9,y=59.1}}},
  {t="The Crossroads", lv=20, n="North up the Gold Road to the Crossroads: Tonga Runetotem at the south gate, Mankrik by the inn, Korran west of the north gate.", g={{"t",880,m=1413,x=52.3,y=31.9},{"t",95774,m=1413,x=52,y=31.6},{"t",868,m=1413,x=51.1,y=29.6}}},
