  {t="The Stormrage Barrow Dens", lv=20, n="Tauren: the Great Cat Spirit waits on the southern hill above the bridge. Skyborne: the Avatar of Saeyleenan stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the Relic of the Silent Shadow lies at the foot of the white cat statue.", f={c={"DRUID"}}, g={{"t",98405,m=1450,x=54.5,y=75,f={r={"Tauren"}}},{"a",98342,m=1450,x=54.5,y=75,f={r={"Tauren"}},ml=20},{"t",98341,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}}},{"a",98404,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}},ml=20},{"o",98342,i=1,txt="Relic of the Fang",m=1450,x=72.4,y=66,f={r={"Tauren"}}},{"o",98342,i=2,txt="Relic of the Claw",m=1450,x=75.2,y=67.2,f={r={"Tauren"}}},{"o",98342,i=3,txt="Relic of the Silent Shadow",m=1450,x=74.4,y=65.4,f={r={"Tauren"}}},{"o",98404,i=1,txt="Relic of the Fang",m=1450,x=72.4,y=66,f={r={"Skyborne"}}},{"o",98404,i=2,txt="Relic of the Claw",m=1450,x=75.2,y=67.2,f={r={"Skyborne"}}},{"o",98404,i=3,txt="Relic of the Silent Shadow",m=1450,x=74.4,y=65.4,f={r={"Skyborne"}}},{"t",98342,m=1450,x=54.5,y=75,f={r={"Tauren"}}},{"a",98739,m=1450,x=54.5,y=75,f={r={"Tauren"}},ml=20},{"t",98404,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}}},{"a",98738,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}},ml=20}}},
