  {t="Grimtotem camp", lv=20, n="The Grimtotem camp is just north of Makaba, a short walk off the road: Ruffians and Mercenaries stand among the tents.", g={{"o",6548,i=1,txt="Kill Grimtotem Ruffian x8",m=1442,x=81.7,y=87.4},{"o",6548,i=2,txt="Kill Grimtotem Mercenary x6",m=1442,x=81.7,y=87.6}}},
