  {t="To Malaka'jin", lv=20, g={{"g",0,txt="Malaka'jin",m=1442,x=73.3,y=95.1}}},
  {t="Malaka'jin", lv=20, n="Follow the road on west from Seereth into Stonetalon. The troll village of Malaka'jin sits at the entrance of the canyon.", g={{"t",1060,m=1442,x=74.5,y=97.9,f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","DRUID"}}},{"a",6461,n2="Xen'Zilla: the spiders along the Webwinder Path",m=1442,x=71.2,y=95,ml=13}}},
  {t="Webwinder Path: kill these as you meet them", lv=20, n="North up the road from Malaka'jin: Grundig Darkcloud and his Grimtotem Brutes hold the bend in the road, and the Deepmoss Creepers and Venomspitters lurk in the webs on both sides of the path all the way up.", g={{"o",6629,i=1,txt="Kill Grundig Darkcloud",m=1442,x=73.7,y=86.1},{"o",6629,i=2,txt="Kill Grimtotem Brute x6",m=1442,x=73.8,y=85.8},{"o",6461,i=1,txt="Kill Deepmoss Creeper x10",m=1442,x=68.8,y=88.6},{"o",6461,i=2,txt="Kill Deepmoss Venomspitter x7",m=1442,x=61,y=66.4}}},
  {t="Ziz Fizziks", lv=20, n="The road climbs north as the Webwinder Path. Ziz Fizziks has a hut where the road forks east to Windshear Crag.", g={{"t",1483,n2="Ziz Fizziks, inside",m=1442,x=59,y=62.6},{"a",1093,m=1442,x=59,y=62.6,ml=16}}},
  {t="Windshear Crag", lv=20, n="East of Ziz, the Venture Company is clear-cutting Windshear Crag; one of the Operators carries the blueprints.", g={{"o",1093,i=1,txt="Super Reaper 6000 Blueprints",m=1442,x=62.5,y=53.8},{"o",1062,i=1,txt="Kill Venture Co. Logger x15",n2="Venture Co. Loggers, all over the clear-cut",m=1442,x=61.5,y=55.3}}},
  {t="Piznik", lv=20, n="Piznik's defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone.\nPiznik mines at the bottom of the Windshear Mine on the east side of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails.", w={{k="group",q=1090}}, g={{"a",1090,n2="Piznik, below ground",m=1442,x=71.9,y=60,ml=17},{"c",1090,txt="Piznik"},{"t",1090,m=1442,x=71.9,y=60},{"a",1092,m=1442,x=71.9,y=60,ml=17}}},
  {t="Ziz Fizziks: Gerenzo's Orders", lv=20, w={{k="group",q=1090}}, g={{"t",1092,n2="Ziz Fizziks, inside",m=1442,x=59,y=62.6}}},
  {t="Ziz Fizziks", lv=20, g={{"t",1093,n2="Ziz Fizziks, inside",m=1442,x=59,y=62.6},{"a",1094,n2="Ziz Fizziks: for Sputtervalve, beside Ratchet's flight master at the end of the Barrens & Stonetalon guide",m=1442,x=59,y=62.6,ml=16}}},
  {t="Kaya Flathoof", lv=20, n="On the way back down the Webwinder Path, Kaya Flathoof is held in Grundig Darkcloud's hut at the bend in the road. Once you take her quest she walks straight off south-east to Camp Aparaje, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly.", g={{"a",6523,n2="Kaya Flathoof, inside Grundig's hut",m=1442,x=73.5,y=85.6,ml=12},{"c",6523,txt="Kaya Escorted to Camp Aparaje",m=1442,x=77.1,y=90.8}}},
  {t="Malaka'jin", lv=20, n="West from the burned village to Malaka'jin: Xen'Zilla stands just outside it, before the village.", g={{"t",6461,m=1442,x=71.2,y=95}}},
  {t="Seereth's camp", lv=20, g={{"g",0,txt="Seereth's camp",m=1413,x=35.3,y=27.9}}},
  {t="Seereth Stonebreak", lv=20, n="East along the road to Seereth and Makaba's camp, on the way back out of Stonetalon.", g={{"t",1062,m=1413,x=35.3,y=27.9},{"t",6629,m=1413,x=35.2,y=27.8},{"t",6523,m=1413,x=35.2,y=27.8},{"a",6401,n2="Makaba Flathoof: keep it, Tammra Windfield at Sun Rock Retreat in the Barrens & Stonetalon guide",m=1413,x=35.2,y=27.8,ml=12},{"i",0,txt="The next guide goes north-east across the Barrens to the Mor'shan Rampart and Ashenvale."}}},
} end)

