  {t="Orgrimmar", lv=12, n="Walk in by the main gate. Doras, the wind rider master, stands on the tower in the Valley of Strength; Thatog by the bank below it.", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"fp",23,txt="Get the Orgrimmar flight path (Doras)",m=1454,x=45.1,y=63.9},{"a",97246,m=1454,x=55.7,y=72.2,ml=5}}},
