  {t="Neeru Fireblade", lv=12, n="The Cleft of Shadow is the canyon under the Valley of Strength; Neeru Fireblade stands at its far end.", w={{k="onquest",q={829}}}, f={r={"Orc","Troll"}}, g={{"t",829,m=1454,x=49.5,y=50.6},{"t",832,m=1454,x=49.5,y=50.6,opt=true}}},
