  {t="Karolek", lv=12, n="Karolek, the leatherworking trainer, works in the Valley of Honor.", w={{k="onquest",q={97906}}}, f={r={"Orc","Troll"}}, g={{"c",97906,txt="Karolek",m=1454,x=62.8,y=44.1},{"t",97906,n2="Karolek: Camping 101, from Brakk's campfire in Durotar",m=1454,x=62.8,y=44.1}}},
  {t="Snang", lv=12, n="Snang, the tailoring trainer, is in the Valley of Honor.", w={{k="onquest",q={96102}}}, f={r={"Orc","Troll"}}, g={{"c",96102,txt="Snang",m=1454,x=62.9,y=49.2},{"t",96102,n2="Snang: Camping 101, from Brakk's campfire in Durotar",m=1454,x=62.9,y=49.2}}},
  {t="Class trainer", lv=12, n="Train while you are in the city: Druids and Paladins have no trainer here.", f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","WARLOCK"},r={"Orc","Troll","Tauren","Skyborne"}}, g={{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","WARLOCK"}}}}},
