  {t="Hanashi", lv=12, n="While you're here: learn Staves from Hanashi (Valley of Honor, 10 silver); a staff carries more spell stats than a one-hander while you level.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Staves",skillLine=136}}, f={c={"PRIEST"},r={"Orc","Troll","Tauren","Skyborne"}}, g={{"tr",0,txt="Train with Hanashi",m=1454,x=81.5,y=19.6}}},
