  {t="Whuut", lv=12, n="Whuut, the alchemy trainer, stands next door to Kor'geld.", w={{k="onquest",q={97899}}}, f={r={"Orc","Troll"}}, g={{"c",97899,txt="Whuut",m=1454,x=55.8,y=32.9},{"t",97899,n2="Whuut: Camping 101, from Brakk's campfire in Durotar",m=1454,x=55.8,y=32.9}}},
  {t="Valley of Wisdom", lv=12, n="Thra and Migi sit behind Grommash Hold in the Valley of Wisdom; the Smooth Boulders lie around them.", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"a",97326,m=1454,x=36.8,y=29.1,ml=5},{"t",97249,m=1454,x=36.5,y=29.1},{"o",97326,i=1,txt="Smooth Boulder x8",m=1454,x=38.4,y=26.8},{"t",97326,m=1454,x=36.8,y=29.1}}},
