  {t="Zeppelin to Undercity", lv=12, f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"g",0,txt="Zeppelin to Undercity",m=1411,x=50.8,y=13.5}}},
  {t="Brill", lv=12, n="Brill is a short walk north up the road from the zeppelin towers: Deathguard Terrence stands by the road into town, Apothecary Johaan in the apothecary's house on the west side of the square.", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"a",96895,m=1420,x=61.4,y=53.4,ml=10},{"a",445,n2="Apothecary Johaan, inside",m=1420,x=59.5,y=52.4,ml=9}}},
  {t="Hadric Harlson", lv=12, n="Back down the road past the zeppelin towers and east to Deathguard Linnea's camp: Hadric stands beside her.", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"t",96895,m=1420,x=65.9,y=61.1},{"a",96897,m=1420,x=65.9,y=61.1,ml=10},{"a",96898,m=1420,x=65.9,y=61.1,ml=10}}},
  {t="The Cult of the Damned", lv=12, n="The cultists camp a short walk south-east of Hadric. Dark Neophytes and Dark Enforcers drop the Necrotic Crystal Fragments; more fragments, black crystals, lie on the ground among the tents.", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"o",96897,i=1,txt="Kill Dark Neophyte x8",m=1420,x=66.2,y=63.4},{"o",96897,i=2,txt="Kill Dark Enforcer x8",m=1420,x=66.3,y=63.3},{"o",96898,i=1,txt="Necrotic Crystal Fragment x12",m=1420,x=66.4,y=63.6}}},
