  {t="Brill", lv=12, n="Shari Stilwell trains Paladins in Brill, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine.", f={c={"PALADIN"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="The Sepulcher", lv=12, g={{"g",0,txt="The Sepulcher",m=1421,x=44,y=40.9}}},
  {t="The Sepulcher", lv=12, n="The Sepulcher is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; Karos Razok, the bat handler, is just east of it.", g={{"a",6321,m=1421,x=43.4,y=41.7,f={r={"Scourge"}},ml=10},{"fp",10,txt="Get the The Sepulcher flight path (Karos Razok)",m=1421,x=45.6,y=42.6},{"t",6321,m=1421,x=45.6,y=42.6,f={r={"Scourge"}}},{"a",6323,n2="Karos Razok: Gordon Wendham in the Undercity, at the end of this guide; no need to buy the flight",m=1421,x=45.6,y=42.6,f={r={"Scourge"}},ml=10},{"a",477,m=1421,x=44,y=40.9,ml=10},{"a",421,m=1421,x=44.2,y=39.8,ml=12},{"a",428,n2="High Executor Hadrec, below ground",m=1421,x=43.4,y=40.9,ml=10},{"a",437,m=1421,x=43.4,y=40.9,ml=10},{"t",445,n2="Apothecary Renferrel: Delivery to Silverpine Forest",m=1421,x=42.8,y=40.9}}},
  {t="The Sepulcher", lv=12, n="Until Death Do Us Part is handed in at Yuriv's Tombstone, a grave a few steps south of the crypt entrance, not to a person.", w={{k="onquest",q={264}}}, g={{"t",264,m=1421,x=44.2,y=42.7,f={r={"Skyborne","Tauren"}}}}},
  {t="Border Crossings", lv=12, n="Follow the road south. The Dalaran Crate sits beside it, north of Pyrewood.", g={{"t",477,m=1421,x=49.9,y=60.3},{"a",478,m=1421,x=49.9,y=60.3,ml=10}}},
  {t="The Dead Field", lv=12, n="North of the Sepulcher. Nightlash haunts the Dead Field: kill it, then walk across the field.", g={{"o",437,i=1,txt="Essence of Nightlash",m=1421,x=45,y=21},{"c",437,txt="Essence of Nightlash; Enter the Dead Fields",m=1421,x=45.1,y=21.7}}},
  {t="Malden's Orchard", lv=12, n="Follow the road north-east to the Yoricks' house at Malden's Orchard.", g={{"t",428,m=1421,x=53.5,y=13.4},{"a",429,m=1421,x=53.5,y=13.4,ml=10}}},
  {t="Mottled Worgs", lv=12, n="Mottled Worgs prowl the hills around the house.", g={{"o",429,i=1,txt="Discolored Worg Heart x3",m=1421,x=54.9,y=13.6}}},
  {t="Escorting Erland", lv=12, n="Deathstalker Erland waits north-east of the house. Escort him back to Rane; worgs attack on the way.", g={{"a",435,n2="Deathstalker Erland, inside",m=1421,x=56.2,y=9.2,ml=10},{"c",435,txt="Erland must reach Rane Yorick"}}},
  {t="Rane Yorick", lv=12, g={{"t",435,m=1421,x=53.5,y=13.4},{"a",449,m=1421,x=53.5,y=13.4,ml=10}}},
  {t="Prove Your Worth", lv=12, g={{"o",421,i=1,txt="Kill Moonrage Whitescalp x5",m=1421,x=53,y=26.7}}},
