  {t="Valgan's Field farmhouse", lv=12, n="On the road north, the farmhouse at Valgan's Field: go upstairs, the Dusty Spellbooks lie on the floor in the back room. Looting them brings a Moonrage Darkrunner.", g={{"o",422,i=1,txt="Remedy of Arugal",n2="Dusty Spellbooks; upstairs",m=1421,x=52.8,y=28.6}}},
