  {t="Vile Fin murlocs", lv=12, n="Follow the lake shore south-east from the Yoricks' house: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes.", g={{"o",91920,i=1,txt="Murloc Eye x3",m=1421,x=61.1,y=14.5}}},
  {t="The Decrepit Ferry", lv=12, n="Follow the lake shore south from the murlocs: the Corpse Laden Boat lies at the ferry landing, on the way to Ambermill.", g={{"t",438,m=1421,x=58.4,y=34.9},{"a",439,m=1421,x=58.4,y=34.9,ml=10}}},
  {t="Ambermill", lv=12, n="Keep south along the shore from the ferry to Ambermill. Protectors guard the outskirts and Mages the town; both drop pendants. Stay out of the middle, where Archmage Ataeric stands.", g={{"o",479,i=1,txt="Dalaran Pendant x8",m=1421,x=56.7,y=54.4}}},
  {t="The Sepulcher", lv=12, n="Back north-west up the road to the Sepulcher.", g={{"t",479,m=1421,x=44,y=40.9},{"t",91920,m=1421,x=42.8,y=40.9},{"a",91921,n2="Apothecary Renferrel: for Quinn, on the road north at the end",m=1421,x=42.8,y=40.9,ml=10},{"t",422,n2="Dalar Dawnweaver, just north of Allister",m=1421,x=44.2,y=39.8},{"t",439,n2="High Executor Hadrec, below ground",m=1421,x=43.4,y=40.9},{"a",440,n2="Magistrate Sevren in Brill, on the way to the zeppelin at the end",m=1421,x=43.4,y=40.9,ml=10}}},
  {t="The Ivar Patch", lv=12, n="Take the road north toward Tirisfal Glades: the Yoricks' house at Malden's Orchard is on the way. Ivar the Foul lurks a short walk west of it.", g={{"t",91921,n2="Quinn Yorick, inside",m=1421,x=53.4,y=12.6},{"a",425,m=1421,x=53.5,y=13.4,ml=10},{"o",425,i=1,txt="Ivar's Head",n2="Inside",m=1421,x=51.5,y=13.9},{"t",425,m=1421,x=53.5,y=13.4}}},
  {t="Brill", lv=12, g={{"g",0,txt="Brill",m=1420,x=61.3,y=50.8}}},
  {t="Magistrate Sevren", lv=12, n="Brill is a short walk north up the road from the zeppelin towers; Magistrate Sevren is in the town hall.", g={{"t",440,n2="Inside",m=1420,x=61.3,y=50.8},{"a",441,m=1420,x=61.3,y=50.8,ml=10}}},
  {t="Tirisfal Glades", lv=12, g={{"g",0,txt="Ruins of Lordaeron",m=1420,x=61.8,y=76.1}}},
  {t="The Undercity", lv=12, n="The Undercity lies under the Ruins of Lordaeron, beside the zeppelin towers. Raleigh Andrean stands at the inn by the way down; Alessandro Luca on the way down to the Apothecarium, where Doctor Martin Felben and Apothecary Zinge stand beside Master Apothecary Faranell.", g={{"t",6323,n2="Gordon Wendham, the weapon merchant beside the bat handler",m=1458,x=61.5,y=41.8,f={r={"Scourge"}}},{"a",6322,m=1458,x=61.5,y=41.8,f={r={"Scourge"}},ml=10},{"fp",11,txt="Get the Undercity flight path (Michael Garrett)",m=1458,x=63.2,y=48.6},{"t",6322,n2="Michael Garrett, the bat handler",m=1458,x=63.2,y=48.6,f={r={"Scourge"}}},{"a",6324,n2="Michael Garrett: keep Gordon's Crate, Podrig takes it on the next stop at the Sepulcher, at 22",m=1458,x=63.2,y=48.6,f={r={"Scourge"}},ml=10},{"t",441,m=1458,x=62,y=42.8},{"a",97891,m=1458,x=58.6,y=54.7,ml=9},{"t",97891,n2="Doctor Martin Felben, in the Apothecarium",m=1458,x=46.6,y=74.1},{"t",1359,n2="Apothecary Zinge, in the Apothecarium",m=1458,x=50.1,y=68},{"a",1358,n2="Apothecary Zinge: Helbrim at the Crossroads, in the next guide",m=1458,x=50.1,y=68,ml=10},{"tr",0,txt="Visit your class trainer",n2="Garen Largo, the Undercity's paladin trainer",f={c={"PALADIN"}}}}},
  {t="Brom Killian", lv=12, n="Brom Killian, the mining trainer, works in the Undercity.", w={{k="onquest",q={97959}}}, f={r={"Scourge"}}, g={{"c",97959,txt="Brom Killian",m=1458,x=56,y=37.5},{"t",97959,n2="Brom Killian: Camping 101, from Eleanor Shackleton's campfire in Tirisfal",m=1458,x=56,y=37.5}}},
  {t="Basil Frye", lv=12, n="Basil Frye, the blacksmithing trainer, works in the Undercity.", w={{k="onquest",q={97952}}}, f={r={"Scourge"}}, g={{"c",97952,txt="Basil Frye",m=1458,x=60.2,y=29.1},{"t",97952,n2="Basil Frye: Camping 101, from Eleanor Shackleton's campfire in Tirisfal",m=1458,x=60.2,y=29.1}}},
  {t="Graham Van Talen", lv=12, n="Graham Van Talen, the engineering trainer, works in the Undercity.", w={{k="onquest",q={97954}}}, f={r={"Scourge"}}, g={{"c",97954,txt="Graham Van Talen",m=1458,x=75.3,y=73.1},{"t",97954,n2="Graham Van Talen: Camping 101, from Eleanor Shackleton's campfire in Tirisfal",m=1458,x=75.3,y=73.1}}},
  {t="Lady Sylvanas Windrunner", lv=12, n="Lady Sylvanas Windrunner holds court in the Royal Quarter.", f={r={"Skyborne"}}, g={{"o",93739,i=4,txt="Talk to Lady Sylvanas Windrunner",n2="Speak with Lady Sylvanas Windrunner, in the Royal Quarter: Exploring the Horde",m=1458,x=58,y=91.8,opt=true,f={r={"Skyborne"}}}}},
  {t="Zeppelin to Orgrimmar", lv=12, g={{"g",0,txt="Zeppelin to Orgrimmar",m=1420,x=60.7,y=58.9}}},
  {t="Orgrimmar", lv=12, g={{"g",0,txt="Orgrimmar's Valley of Strength",m=1454,x=55.6,y=72.3}}},
  {t="Valley of Strength", lv=12, n="Walk in through the main gate. Thatog stands in the Valley of Strength.", g={{"a",97246,m=1454,x=55.7,y=72.2,ml=5}}},
  {t="Valley of Strength", lv=12, g={{"fp",23,txt="Get the Orgrimmar flight path (Doras)",m=1454,x=45.1,y=63.9}}},
  {t="Valley of Strength", lv=12, n="Borstan's Firepit is a few steps north.", g={{"t",97246,m=1454,x=57.2,y=53.3},{"a",97249,m=1454,x=57.2,y=53.3,ml=5}}},
  {t="Class trainer", lv=12, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}}}},
  {t="The Drag", lv=12, n="Kor'geld and Yelmak run the alchemy shop in the Drag; Whuut is next door.", g={{"a",97242,m=1454,x=56,y=34.1,ml=9}}},
  {t="Valley of Honor", lv=12, n="The cattails and speargrass grow along the water in the Valley of Honor, east of the Drag.", g={{"o",97242,i=1,txt="Handful of Cattails x2",m=1454,x=66.1,y=28.9},{"o",97242,i=2,txt="Speargrass Cuttings x4",m=1454,x=66.2,y=28.8}}},
  {t="Sayoc", lv=12, n="While you're here: learn Two-Handed Axes from Sayoc (Valley of Honor, 10 silver); two-handers level a Paladin fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Axes",skillLine=172}}, f={c={"PALADIN"}}, g={{"tr",0,txt="Train with Sayoc",m=1454,x=81.7,y=19.6}}},
  {t="Kor'geld", lv=12, g={{"t",97242,m=1454,x=56,y=34.1},{"a",97275,m=1454,x=56.8,y=33,ml=9},{"t",97275,m=1454,x=55.8,y=32.9}}},
  {t="Valley of Wisdom", lv=12, n="Thra and Migi sit behind Grommash Hold in the Valley of Wisdom; the Smooth Boulders lie around them. Train while you are in the city (Druids and Paladins have no trainer here). The next guide walks from here to Far Watch Post and the Crossroads.", g={{"a",97326,m=1454,x=36.8,y=29.1,ml=5},{"t",97249,m=1454,x=36.5,y=29.1},{"o",97326,i=1,txt="Smooth Boulder x8",m=1454,x=38.4,y=26.8},{"t",97326,m=1454,x=36.8,y=29.1},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}}}},
  {t="Zor Lonetree", lv=13, g={{"a",1061,n2="Zor Lonetree: Seereth Stonebreak, on the road into Stonetalon in the next guide",m=1454,x=38.9,y=38.4,ml=13}}},
} end)

R:Segment({id="horde/04-the-barrens",title="The Barrens & Stonetalon Mountains",faction="Horde",min=24,max=26,zone=1413,zoneName="The Barrens",next="horde/07-ashenvale"}, function() return {
  {t="Fly to Thunder Bluff", lv=24, n="Fly to Thunder Bluff first: two of its elders give quests worked on this guide's and the next guide's walks.", w={{k="onquest",neg=true,q={97538}}}, f={r={"Tauren","Skyborne"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Fly to Thunder Bluff", lv=24, n="Fly to Thunder Bluff first: two of its elders give quests worked on this guide's and the next guide's walks.", w={{k="onquest",neg=true,q={97538}}}, f={c={"PALADIN"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Fly to Camp Taurajo", lv=24, n="Thunder Bluff first: two of its elders give quests worked on this guide's and the next guide's walks. Fly to Camp Taurajo; from there it is a walk west into Mulgore and north to the bluffs.", w={{k="onquest",neg=true,q={97538}}}, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK","DRUID"},r={"Orc","Troll","Scourge"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Camp Taurajo",at="Camp Taurajo"}}},
  {t="To Thunder Bluff", lv=24, n="From Camp Taurajo follow the road west through the gate into Mulgore, then north past Bloodhoof Village to Thunder Bluff; a lift at the foot of the bluffs takes you up.", w={{k="onquest",neg=true,q={97538}}}, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK","DRUID"},r={"Orc","Troll","Scourge"}}, g={{"g",0,txt="Thunder Bluff's central rise",m=1456,x=47,y=49.8}}},
  {t="Thunder Bluff", lv=24, n="Tal, the wind rider master, stands on the central rise: take his flight path if you don't have it. Tah Winterhoof and Zangen Stonehoof stand a short walk east of him.", w={{k="onquest",neg=true,q={97538}}}, g={{"fp",22,txt="Get the Thunder Bluff flight path (Tal)",m=1456,x=47,y=49.8},{"a",97538,n2="Tah Winterhoof: the Mirkweed grows in Mirkfallon Lake, by Sun Rock",m=1456,x=54.1,y=47,ml=20},{"a",1195,n2="Zangen Stonehoof: the phial comes from Ashenvale, next guide",m=1456,x=55,y=51.4,opt=true,ml=20}}},
  {t="Fly to Crossroads", lv=24, n="Fly to the Crossroads from the wind rider master: Tal on Thunder Bluff's central rise.", g={{"z",0,txt="Fly to Crossroads",at="Crossroads"}}},
  {t="Seereth Stonebreak", lv=24, n="Follow the road west past Regthar's bunkers: Seereth Stonebreak camps beside it at the edge of Stonetalon.", w={{k="turnedin",q=1062}}, g={{"a",1068,n2="Seereth Stonebreak: XT:9 and XT:4 roam east of Ziz Fizziks, on the way up",m=1413,x=35.3,y=27.9,ml=13}}},
  {t="The road west", lv=24, g={{"g",0,txt="The road west past Seereth's camp",m=1413,x=35.3,y=27.9}}},
  {t="Malaka'jin", lv=24, n="Follow the road west past Regthar's bunkers and Seereth's camp into Stonetalon: Witch Doctor Jin'Zil waits below ground in Malaka'jin, at the foot of the Webwinder Path.", g={{"a",1058,n2="Witch Doctor Jin'Zil, below ground",m=1442,x=74.5,y=97.9,ml=20}}},
  {t="Shredding Machines", lv=24, n="Up the Webwinder Path to Ziz Fizziks' hut, then east along the road toward Windshear Crag: XT:9 patrols the road just east of the fork, XT:4 the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them.", w={{k="onquest",q={1068}}}, g={{"o",1068,i=2,txt="Kill XT:9",m=1442,x=64.1,y=56.6},{"o",1068,i=1,txt="Kill XT:4",m=1442,x=67.2,y=46.7}}},
  {t="Sun Rock Retreat", lv=24, n="Up the Webwinder Path past Ziz Fizziks and west to Sun Rock Retreat; coming from XT:4, back west past Ziz's hut.", g={{"a",6562,n2="Tsunaman: Je'neu Sancrea at Zoram'gar, next guide",m=1442,x=47.4,y=64.2,ml=17},{"a",6393,m=1442,x=47.4,y=64.2,ml=19},{"a",5881,n2="Maggran Earthbinder: Grish is at the Great Lift, later in this guide",m=1442,x=47.2,y=61.2,ml=23},{"a",86576,n2="Maggran Earthbinder: Glittering Sunstones from the Bloodfury harpies",m=1442,x=47.2,y=61.2,ml=18},{"a",6282,m=1442,x=47.2,y=61.2,ml=18},{"b",0,txt="Set your hearthstone at Sun Rock Retreat",m=1442,x=47.5,y=62.1,at="Sun Rock Retreat"},{"a",6301,m=1442,x=47.5,y=58.4,ml=17},{"a",1087,n2="Braelyn Firehand, outside the gate",m=1442,x=45.9,y=60.4,ml=20},{"fp",29,txt="Get the Sun Rock Retreat flight path (Tharm)",m=1442,x=45.1,y=59.8},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Tammra Windfield", lv=24, n="Tammra Windfield stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her.", w={{k="onquest",q={6401}}}, g={{"t",6401,m=1442,x=47.5,y=58.4}}},
  {t="Gaea Seeds", lv=24, n="The Gaea Seeds lie in the grass around the southern shore of Mirkfallon Lake, north of Sun Rock.\nCareful: Pridewings around the lake can aggro as a linked group.", g={{"o",6301,i=1,txt="Gaea Seed x10",m=1442,x=49.7,y=45.1}}},
  {t="Mirkweed", lv=24, n="The Mirkweed grows on the bottom of Mirkfallon Lake, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath.", w={{k="onquest",q={97538}}}, g={{"o",97538,i=1,txt="Mirkweed Pods x30",m=1442,x=48.5,y=40.2}}},
  {t="Stonetalon Mountains: kill these as you meet them", lv=24, n="Follow the road north toward Stonetalon Peak. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there.", g={{"o",1058,i=3,txt="Courser Eye x30",m=1442,x=46.8,y=38.2},{"o",1058,i=1,txt="Stonetalon Sap x5",m=1442,x=36.8,y=19.5},{"o",1058,i=2,txt="Twilight Whisker x5",m=1442,x=39.6,y=17.7},{"o",1058,i=4,txt="Fey Dragon Scale",m=1442,x=39.8,y=13.8},{"o",1087,i=2,txt="Kill Daughter of Cenarius x4",m=1442,x=38.3,y=13.3},{"o",1087,i=1,txt="Kill Son of Cenarius x4",m=1442,x=37.5,y=13.1},{"o",1087,i=3,txt="Kill Cenarion Botanist x4",m=1442,x=37,y=15}}},
  {t="Sun Rock Retreat", lv=24, g={{"t",6301,m=1442,x=47.5,y=58.4},{"a",6381,m=1442,x=47.5,y=58.4,ml=17},{"t",1087,m=1442,x=45.9,y=60.4},{"i",0,txt="Braelyn's next quest, Ordanus, is on the Alliance side of Ashenvale. Skip it."}}},
  {t="The Charred Vale: kill these as you meet them", lv=24, n="South-west of Sun Rock lies the burned Charred Vale. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop Incendrites. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south.", g={{"o",6393,i=1,txt="Incendrites x10",m=1442,x=37.3,y=60.5},{"o",86576,i=1,txt="Glittering Sunstone x15",n2="Glittering Sunstone, from any Bloodfury harpy",m=1442,x=35.3,y=63.2},{"o",6282,i=1,txt="Kill Bloodfury Harpy x7",m=1442,x=35.2,y=63.2},{"o",6381,i=1,txt="Gaea Dirt Mound",n2="Gaea Dirt Mounds",m=1442,x=35.2,y=63.7},{"o",6282,i=4,txt="Kill Bloodfury Roguefeather x7",m=1442,x=35.5,y=66.6},{"o",6282,i=3,txt="Kill Bloodfury Slayer x7",m=1442,x=36.2,y=67.4},{"o",6282,i=2,txt="Kill Bloodfury Ambusher x7",m=1442,x=35.4,y=64.3}}},
  {t="Sun Rock Retreat", lv=24, g={{"t",6381,m=1442,x=47.5,y=58.4},{"t",6282,m=1442,x=47.2,y=61.2},{"t",86576,n2="Mor'rogal, beside Tsunaman",m=1442,x=47.2,y=64},{"t",6393,n2="Tsunaman, up on the ledge",m=1442,x=47.4,y=64.2}}},
  {t="Malaka'jin", lv=24, n="Head back down the Webwinder Path to Malaka'jin.", g={{"t",1058,n2="Witch Doctor Jin'Zil, below ground",m=1442,x=74.5,y=97.9}}},
  {t="Seereth Stonebreak", lv=24, n="East along the road from Malaka'jin to Seereth's camp, on the way to Camp Taurajo.", w={{k="complete",q=1068}}, g={{"t",1068,m=1413,x=35.3,y=27.9}}},
  {t="To Camp Taurajo", lv=24, g={{"g",0,txt="Camp Taurajo",m=1413,x=45.6,y=59}}},
  {t="Camp Taurajo", lv=24, n="From Malaka'jin follow the road east to Seereth's camp, then south-east across the plains to Camp Taurajo.", g={{"a",893,n2="Tatternack Steelforge, at the north edge of the camp",m=1413,x=45.1,y=57.7,ml=17},{"a",874,m=1413,x=44.9,y=59.1,ml=9},{"a",879,n2="Mangletooth, in the cage",m=1413,x=44.5,y=59.3,ml=17},{"b",0,txt="Set your hearthstone at Camp Taurajo",m=1413,x=45.6,y=59,at="Camp Taurajo"}}},
  {t="Grunt Logmar", lv=24, n="Grunt Logmar stands by the flight master. His Outraged Pillager (23) is elite: grouping up is advised; the two Encroaching Soldiers are not.", w={{k="group",q=97250}}, g={{"a",97250,n2="Grunt Logmar: the soldiers and the pillager camp just east of Gann Stonespire, on the way south",m=1413,x=44.6,y=59.3,ml=18}}},
  {t="The Barrens", lv=24, w={{k="onquest",q={1536}}}, f={c={"SHAMAN"}}, g={{"g",0,txt="Brine",m=1413,x=43.4,y=77.4}}},
  {t="Brine", lv=24, n="Brine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo, on the way to Bael Modan.", f={c={"SHAMAN"}}, g={{"t",1536,n2="Brine: the red waterskin from Tarren Mill",m=1413,x=43.4,y=77.4},{"a",1534,n2="Brine: the blue waterskin is filled in Ashenvale, next guide",m=1413,x=43.4,y=77.4,ml=20}}},
  {t="Gann Stonespire", lv=24, n="Gann walks the road south toward Bael Modan, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. Sulhasa sits up in the tree just east of the road at 47.9,77.5.", g={{"a",843,n2="Gann Stonespire walks around Blackthorn Ridge: look inside the circle on the map",m=1413,x=45.9,y=77,ml=17},{"a",98093,n2="Sulhasa, up in the tree just east of Gann",m=1413,x=47.8,y=77.6,ml=18}}},
  {t="Wrongly Blamed, Justly Corrected", lv=24, n="A few steps east of Sulhasa's tree, a small camp: two Encroaching Soldiers and the Outraged Pillager for Logmar. The Outraged Pillager is elite: grouping up is advised.", w={{k="group",q=97250}}, g={{"o",97250,i=1,txt="Kill Encroaching Soldier x2",m=1413,x=48.8,y=77},{"o",97250,i=2,txt="Kill Outraged Pillager",m=1413,x=48.8,y=77,grp=true}}},
  {t="Bael Modan", lv=24, n="South of Gann, the Bael'dun dwarves dig at Bael Modan. Excavators and Foremen work the pit; Prospector Khazgorm (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight.", g={{"o",843,i=1,txt="Kill Bael'dun Excavator x15",m=1413,x=47.1,y=83.9},{"o",843,i=2,txt="Kill Bael'dun Foreman x5",n2="Bael'dun Foreman walks around Bael Modan: look inside the circle on the map",m=1413,x=47.4,y=84.3},{"o",843,i=3,txt="Khazgorm's Journal",m=1413,x=47.5,y=85.1}}},
  {t="Blackthorn Ridge", lv=24, n="West of Gann, the Razormane hold Blackthorn Ridge. Kuz is on the east side, Nak to the south, Lok Orcbane at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; Hagg Taurenbane, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. Washte Pawne, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with Sinister Strike, so they can join a fight without warning.", g={{"o",879,i=2,txt="Nak's Skull",m=1413,x=43.8,y=83.3},{"o",893,i=2,txt="Charred Razormane Wand",m=1413,x=43.8,y=82.8},{"o",893,i=3,txt="Razormane War Shield",m=1413,x=42.2,y=81.7},{"o",879,i=3,txt="Lok's Skull",m=1413,x=40.1,y=80.5},{"h",5103,txt="Get Washte Pawne's Feather",m=1413,x=43.1,y=80.8,n=1,opt=true},{"a",885,opt=true,ml=10},{"g",0,txt="Blackthorn Ridge",m=1413,x=42.5,y=81},{"o",893,i=1,txt="Razormane Backstabber",m=1413,x=42.5,y=81.3},{"o",879,i=1,txt="Kuz's Skull",m=1413,x=45.1,y=80.1}}},
  {t="Field to Clear", lv=24, n="On the way back east to Gann: Hecklefang Stalkers and Stormhide lizards roam the plain between the ridge and his camp.", g={{"o",98093,i=1,txt="Kill Hecklefang Stalker x7",n2="Hecklefang Stalker walks around Southern Barrens: look inside the circle on the map",m=1413,x=45.3,y=79},{"o",98093,i=2,txt="Kill Stormhide x7",m=1413,x=44.6,y=79.2}}},
  {t="Gann Stonespire", lv=24, g={{"t",843,n2="Gann Stonespire walks around Blackthorn Ridge: look inside the circle on the map",m=1413,x=45.9,y=77},{"a",846,m=1413,x=45.9,y=77,ml=17},{"t",98093,m=1413,x=47.8,y=77.6}}},
  {t="Bael'dun fortress", lv=24, n="The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them.\nCareful: Riflemen (level 24-25) Shoot from 5-30 yd, so nearby ones can join a fight from range.", g={{"o",846,i=1,txt="Nitroglycerin x6",m=1413,x=48.5,y=83.8},{"o",846,i=2,txt="Wood Pulp x6",m=1413,x=48.5,y=83.8},{"o",846,i=3,txt="Sodium Nitrate x6",m=1413,x=48.5,y=83.8}}},
  {t="Gann Stonespire", lv=24, g={{"t",846,n2="Gann Stonespire walks around Blackthorn Ridge: look inside the circle on the map",m=1413,x=45.9,y=77},{"a",849,m=1413,x=45.9,y=77,ml=17}}},
  {t="The flying machine", lv=24, n="The dwarves' flying machine sits on its platform inside the dig site. Use the Explosive Stick of Gann that Gann gave you on it.", g={{"o",849,i=1,txt="Bael Modan Flying Machine",m=1413,x=47,y=85.6}}},
  {t="Gann Stonespire", lv=24, g={{"t",849,n2="Gann Stonespire walks around Blackthorn Ridge: look inside the circle on the map",m=1413,x=45.9,y=77}}},
  {t="The Great Lift", lv=24, g={{"g",0,txt="The top of the Great Lift",m=1441,x=31.9,y=23.9}}},
  {t="The Great Lift", lv=24, n="South-west of Bael Modan, Grish Longrunner waits at the top of the Great Lift.", g={{"t",5881,m=1441,x=31.9,y=21.7}}},
  {t="The Great Lift", lv=24, n="Brave Moonhorn stands at the top of the Great Lift, beside Grish Longrunner.", g={{"g",0,txt="The Great Lift",m=1413,x=44.2,y=92.2},{"a",4542,n2="Brave Moonhorn, at the top of the lift",m=1441,x=32.2,y=22.2,ml=23}}},
  {t="To Camp Taurajo", lv=24, g={{"g",0,txt="Camp Taurajo",m=1413,x=45.6,y=59}}},
  {t="Camp Taurajo", lv=24, g={{"t",879,m=1413,x=44.5,y=59.3},{"a",906,m=1413,x=44.5,y=59.3,ml=17},{"t",885,m=1413,x=44.9,y=59.1,opt=true},{"i",0,txt="Sell and repair",opt=true},{"t",893,m=1413,x=45.1,y=57.7}}},
  {t="Grunt Logmar", lv=24, w={{k="group",q=97250}}, g={{"t",97250,n2="Grunt Logmar, beside the flight master",m=1413,x=44.6,y=59.3}}},
  {t="Fly to Crossroads", lv=24, g={{"g",0,txt="Camp Taurajo flight master",m=1413,x=44.5,y=59.1},{"z",0,txt="Fly to Crossroads",at="Crossroads"}}},
  {t="The Crossroads", lv=24, g={{"t",906,n2="Thork, at the top of the tower",m=1413,x=51.5,y=30.9}}},
  {t="Fly to Ratchet", lv=24, w={{k="onquest",q={1094,874,873}}}, g={{"g",0,txt="Crossroads flight master",m=1413,x=51.5,y=30.4},{"z",0,txt="Fly to Ratchet",at="Ratchet"}}},
  {t="Sputtervalve", lv=24, n="Sputtervalve stands beside the flight master you land at.", w={{k="onquest",q={1094}}}, g={{"t",1094,n2="Sputtervalve: Further Instructions, from Ziz Fizziks",m=1413,x=63,y=37.2}}},
  {t="Merchant Coast", lv=24, n="Mahren Skyseer camps on the shore just north of Ratchet's flight master.", g={{"t",874,m=1413,x=65.8,y=43.9},{"a",873,m=1413,x=65.8,y=43.9,ml=10}}},
  {t="Isha Awak", lv=24, n="Isha Awak, a big threshadon, swims in the shallows off the Merchant Coast, east of Mahren.", g={{"o",873,i=1,txt="Heart of Isha Awak",m=1413,x=65.6,y=46.8}}},
  {t="The Tidus Stair", lv=24, g={{"t",873,m=1413,x=65.8,y=43.9}}},
} end)

R:Segment({id="horde/05-stonetalon-mountains",title="Ashenvale & Silverpine Forest",faction="Horde",min=21,max=23,zone=1440,zoneName="Ashenvale",next="horde/06-hillsbrad-foothills"}, function() return {
  {t="Taskmaster Fizzule", lv=21, n="On the way north from Seereth's camp, keep east of the road to the Venture Co. tower north of the Sludge Fen. Before you go near Fizzule, use Flare Gun to fire two flares, then target him and /salute: he attacks anyone who comes in without signalling first.", f={c={"ROGUE"}}, g={{"t",2458,m=1413,x=55.4,y=5.6},{"a",2478,m=1413,x=55.4,y=5.6,opt=true,ml=20},{"i",0,txt="Mission: Possible But Not Probable is for level 23 or more: the tower's drones are 25 and Gallywix a 23 elite. Do it when you can, with a group, from the Class guide Poisons (Horde)."}}},
  {t="Kadrak", lv=21, n="From Seereth's camp head north-east across the Barrens to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. Kadrak stands on the watch tower of the Mor'shan Rampart where the road enters Ashenvale.", g={{"t",6541,m=1413,x=48.1,y=5.4}}},
  {t="Into Ashenvale", lv=21, g={{"g",0,txt="The road north to Splintertree Post",m=1440,x=71.1,y=68.1}}},
  {t="Splintertree Post", lv=21, n="Splintertree Post is just north up the road. Coming in from the south, the flight master and Senani Thunderheart's hunt board at Night Run come first, then the vendors. Kuray'bin at the lumber camp offers Ashenvale Outrunners: leave it for the next Ashenvale visit, at 26.", g={{"fp",61,txt="Get the Splintertree Post flight path (Vhulgra)",m=1440,x=73.2,y=61.6},{"t",6382,m=1440,x=73.8,y=61.5},{"t",6383,m=1440,x=73.8,y=61.5},{"i",0,txt="Senani's hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next Ashenvale visit, at 26."},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Va'xug Firefure", lv=21, n="On the way west, Va'xug Firefure is stuck in a ravine south of the main road, south-east of Astranaar. Shadowhorn Stags and Ashenvale Bears roam the woods all around it.", g={{"a",98251,m=1440,x=40.4,y=61.5,ml=18},{"o",98251,i=1,txt="Kill Shadowhorn Stag x6",m=1440,x=40,y=63.5},{"o",98251,i=2,txt="Kill Ashenvale Bear x6",m=1440,x=37.9,y=62.2},{"t",98251,m=1440,x=40.5,y=61.4},{"a",98252,m=1440,x=40.5,y=61.4,ml=18}}},
  {t="A Void Path", lv=21, n="Steer Va'xug's Eye of Kilrogg out of the ravine to the main road within four minutes; if the channel breaks, ask Va'xug again.", g={{"t",98252,n2="Eye of Kilrogg, on the road",m=1440,x=38.2,y=58.1}}},
  {t="Zoram'gar Outpost", lv=21, n="Head west along the main road across Ashenvale, past Astranaar (Alliance: keep to the road), to the coast. Zoram'gar Outpost is on the Zoram Strand in the north-west: Marukai, Mitsuwa and Karang Amakkar stand around it, the Warsong Runner beside the flight master. Its other quests are for the next visit, at 26.", g={{"fp",58,txt="Get the Zoram'gar Outpost flight path (Andruk)",m=1440,x=12.2,y=33.8},{"a",6442,m=1440,x=11.7,y=34.9,ml=14},{"a",6462,n2="Mitsuwa: the troll charms are in Thistlefur Hold, east of the outpost",m=1440,x=11.7,y=34.9,ml=19},{"a",216,m=1440,x=11.9,y=34.5,ml=21},{"a",6641,n2="Muglash: take it last, his escort starts at once",m=1440,x=12.1,y=34.6,ml=20}}},
  {t="Vorsha the Lasher", lv=21, n="Muglash walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads Marukai wants.", g={{"g",0,txt="Naga brazier",m=1440,x=9.6,y=27.6},{"c",6641,txt="Defeat Vorsha the Lasher"}}},
  {t="Naga heads", lv=21, n="Every Wrathtail naga along the strand north of the outpost drops heads.", g={{"o",6442,i=1,txt="Wrathtail Head x20",m=1440,x=8.9,y=29.1}}},
  {t="Zoram'gar Outpost", lv=21, n="Back to the outpost before heading east to Thistlefur.", g={{"t",6641,m=1440,x=12.2,y=34.2},{"t",6442,m=1440,x=11.7,y=34.9}}},
  {t="Thistlefur Village", lv=21, n="East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs.", g={{"o",216,i=1,txt="Kill Thistlefur Avenger x12",m=1440,x=31.7,y=38},{"o",216,i=2,txt="Kill Thistlefur Shaman x12",m=1440,x=32.1,y=38.9}}},
  {t="Thistlefur Hold", lv=21, n="Inside the hold, Troll Chests lie along the tunnels. Ruul Snowhoof is held deep inside: free him and protect him all the way out, then he runs home to Night Run.\nCareful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where Dal Bloodclaw roams.", g={{"o",6462,i=1,txt="Troll Charm x8",n2="Below ground",m=1440,x=39.9,y=34.2},{"a",6482,n2="Ruul Snowhoof, below ground",m=1440,x=41.5,y=34.5,ml=19},{"c",6482,txt="Escort Ruul from the Thistlefurs."}}},
  {t="Zoram'gar Outpost", lv=21, n="Back west to Zoram'gar. Karang offers King of the Foulweald now; leave it for the next Ashenvale visit at 26, when the walk east passes the Foulweald.", g={{"t",216,m=1440,x=11.9,y=34.5},{"t",6462,m=1440,x=11.7,y=34.9}}},
  {t="Splintertree Post", lv=21, n="Fly to Splintertree Post: Yama Snowhoof waits in the inn for news of Ruul.", g={{"z",0,txt="Fly to Splintertree Post",at="Splintertree Post"},{"t",6482,n2="Yama Snowhoof, inside the inn",m=1440,x=74.1,y=60.9}}},
  {t="Fly to Orgrimmar", lv=21, n="Out of the inn to the Splintertree Post flight master and fly to Orgrimmar.", g={{"g",0,txt="Splintertree Post flight master",m=1440,x=73.3,y=61.7},{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"}}},
  {t="Druid trainer", lv=21, f={c={"DRUID"}}, g={{"tr",0,txt="Visit your class trainer",n2="Sheal Runetotem in Mulgore; Orgrimmar has no druid trainer",f={c={"DRUID"}}}}},
  {t="Orgrimmar", lv=21, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="The Binding", lv=21, n="Gan'rul Bloodeye stands in the Cleft of Shadow. Use Dogran's Pendant on the summoning circle there and defeat the succubus to bind her.", f={c={"WARLOCK"}}, g={{"t",1512,m=1454,x=48.2,y=45.3},{"a",1513,m=1454,x=48.2,y=45.3,ml=20},{"i",0,txt="Use Dogran's Pendant",m=1454,x=49.4,y=50},{"o",1513,i=1,txt="Kill Summoned Succubus",m=1454,x=49.4,y=50},{"t",1513,m=1454,x=48.2,y=45.3}}},
  {t="Shenthul", lv=21, n="If you did Mission: Possible But Not Probable with a group, Shenthul in the Cleft of Shadow takes it now.", w={{k="complete",q=2478}}, f={c={"ROGUE"}}, g={{"t",2478,n2="Shenthul, Cleft of Shadow",m=1454,x=43,y=53.7},{"a",2479,n2="Serge Hinott in Tarren Mill teaches Poisons: keep it",m=1454,x=43,y=53.7,ml=20}}},
  {t="Zeppelin to Undercity", lv=21, g={{"g",0,txt="Zeppelin to Undercity",m=1411,x=50.8,y=13.5}}},
  {t="Brill", lv=21, n="Shari Stilwell trains Paladins in Brill, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine.", f={c={"PALADIN"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Strange Lockbox", lv=21, n="From the zeppelin towers, run south into Silverpine and west past the Dead Field to the coast: the Strange Lockbox lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the Half Pendant of Aquatic Endurance for Trial of the Sea Lion. Then on to the Sepulcher.", w={{k="onquest",q={30}}}, f={c={"DRUID"},r={"Tauren","Skyborne"}}, g={{"h",15882,txt="Get Half Pendant of Aquatic Endurance",n2="Half Pendant of Aquatic Endurance, from the Strange Lockbox",m=1421,x=29.6,y=29.2,n=1}}},
  {t="The Sepulcher", lv=21, n="Down the road through Silverpine to the Sepulcher: from the zeppelin towers, south through Tirisfal; from the Strange Lockbox, south-east from the coast to the road. Shadow Priest Allister and Apothecary Renferrel stand by the crypt entrance.", g={{"a",493,n2="Apothecary Renferrel: Lydon in Tarren Mill, next guide",m=1421,x=42.8,y=40.9,ml=19},{"a",95981,m=1421,x=44,y=40.9,ml=10},{"a",516,n2="Shadow Priest Allister: Beren's Peril, south-east of Ambermill",m=1421,x=44,y=40.9,ml=16}}},
  {t="Deathguard Podrig", lv=21, n="Deathguard Podrig stands just west of the crypt entrance: hand him Gordon's Crate from the Undercity.", w={{k="onquest",q={6324}}}, f={r={"Scourge"}}, g={{"t",6324,m=1421,x=43.4,y=41.7}}},
  {t="Silverpine Forest: kill these as you meet them", lv=21, n="South down the road past Pyrewood: Dalaran Watchers and Wizards patrol the roads around Ambermill, and south-west of the town the Ravenclaw Drudgers and Guardians haunt the ruins of Beren's Peril in the south-east of the forest.", g={{"o",95981,i=2,txt="Kill Dalaran Wizard x8",m=1421,x=64.8,y=49.8},{"o",95981,i=1,txt="Kill Dalaran Watcher x8",m=1421,x=65.2,y=56.3},{"o",516,i=2,txt="Kill Ravenclaw Guardian x6",n2="Below ground",m=1421,x=59.7,y=69.9},{"o",516,i=1,txt="Kill Ravenclaw Drudger x6",m=1421,x=59.6,y=70.8}}},
  {t="Beren's Peril", lv=21, n="The Ravenclaw undead haunt the ruins of Beren's Peril, east of the road in the south-east of the forest; a Ravenclaw Guardian drops the Note Scrap that leads to the Offering Stone.\nAn elite spirit (20) often stands beside the Offering Stone: pull the Ravenclaws away from the stone before you fight them.", g={{"a",95884,n2="Note Scrap, from a Ravenclaw Guardian",ml=20},{"t",95884,m=1421,x=58.1,y=69.8},{"a",95883,n2="the Offering Stone offers The Tortured Soul once the Note Scrap is in; below ground",m=1421,x=58.1,y=69.8,ml=20},{"o",95883,i=1,txt="Tortured Soul",n2="Tortured Soul, from the Tortured Souls among the ruins; below ground",m=1421,x=58.1,y=69.9},{"t",95883,n2="Below ground",m=1421,x=58.1,y=69.8}}},
  {t="The Offering of Blood", lv=21, n="The quest hands you a Tortured Soul: use it beside the Offering Stone to offer your blood, then kill the elite spirit that answers.\nThe Tortured Soul is elite: grouping up is advised.", g={{"g",0,txt="Offering Stone",m=1421,x=58.1,y=69.8},{"a",95885,n2="Below ground",m=1421,x=58.1,y=69.8,opt=true,ml=20},{"i",0,txt="Use Tortured Soul",n2="Tortured Soul, beside the Offering Stone: summons the elite spirit",m=1421,x=58.1,y=69.8,opt=true},{"o",95885,i=3,txt="Kill Tortured Soul",m=1421,x=58.1,y=69.9,opt=true,grp=true},{"t",95885,n2="Below ground",m=1421,x=58.1,y=69.8,opt=true}}},
  {t="Into Hillsbrad", lv=21, g={{"g",0,txt="The road east to Southpoint Tower",m=1424,x=20.8,y=47.4}}},
  {t="Southpoint Tower", lv=21, n="Back on the road south. Where it turns east into Hillsbrad, Deathstalker Lesh waits at Southpoint Tower.", g={{"a",494,n2="Deathstalker Lesh: Darthalia in Tarren Mill",m=1424,x=20.8,y=47.4,ml=19}}},
} end)

R:Segment({id="horde/06-hillsbrad-foothills",title="Hillsbrad Foothills",faction="Horde",min=22,max=25,zone=1424,zoneName="Hillsbrad Foothills",next="horde/04-the-barrens"}, function() return {
  {t="Tarren Mill", lv=22, n="Tarren Mill is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square.", g={{"fp",13,txt="Get the Tarren Mill flight path (Zarise)",m=1424,x=60.1,y=18.6},{"o",1536,i=1,txt="Filled Red Waterskin",n2="Fill the Empty Red Waterskin at the Spring Well beside the inn",m=1424,x=62.2,y=20.8,f={c={"SHAMAN"}}},{"a",501,m=1424,x=61.4,y=19.1,ml=21},{"a",496,m=1424,x=61.4,y=19.1,ml=19},{"t",493,m=1424,x=61.4,y=19.1},{"t",494,m=1424,x=62.3,y=20.4},{"a",527,m=1424,x=62.3,y=20.4,ml=19},{"a",549,n2="The WANTED poster by the inn",m=1424,x=62.6,y=20.6,ml=17},{"a",498,n2="Krusk, inside",m=1424,x=63.2,y=20.7,ml=17},{"b",0,txt="Set your hearthstone at Tarren Mill",m=1424,x=62.8,y=19,at="Tarren Mill"}}},
  {t="Serge Hinott", lv=22, n="After returning Mission: Possible But Not Probable to Shenthul, bring Hinott's Assistance to Serge Hinott in Tarren Mill. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill.", f={c={"ROGUE"}}, g={{"t",2479,m=1424,x=61.6,y=19.2,opt=true},{"a",2480,m=1424,x=61.6,y=19.2,opt=true,ml=20},{"c",2480,txt="Cure Completed",opt=true},{"t",2480,n2="Serge Hinott: Poisons",m=1424,x=61.6,y=19.2,opt=true},{"i",0,txt="Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."}}},
  {t="Bears, creepers and lions", lv=22, n="West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop Creeper Ichor rarely; you need only one.", g={{"o",496,i=1,txt="Gray Bear Tongue x10",m=1424,x=54.3,y=39.6},{"o",496,i=2,txt="Creeper Ichor",m=1424,x=59,y=35.3}}},
  {t="Hillsbrad Fields", lv=22, n="The farms east of Hillsbrad town. Farmer Ray works the field by the northern farmhouse, Farmer Getz the one further south-east; Farmhands and Farmers are everywhere. Farmer Kalaba tends the field south of the farms.", g={{"o",527,i=1,txt="Kill Hillsbrad Farmer x6",m=1424,x=36.4,y=39.8},{"o",527,i=2,txt="Kill Hillsbrad Farmhand x6",m=1424,x=36.8,y=39.6},{"o",527,i=3,txt="Kill Farmer Ray",m=1424,x=33.2,y=34.8},{"o",527,i=4,txt="Kill Farmer Getz",m=1424,x=35.2,y=38}}},
  {t="Mountain Lion Blood", lv=22, n="Careful: When one lion is attacked, nearby lions come to its aid, and the Vicious Black Bears sharing those fields can also join the fight.", g={{"o",501,i=1,txt="Mountain Lion Blood x10",m=1424,x=54.3,y=39.6}}},
  {t="Tarren Mill", lv=22, g={{"t",527,m=1424,x=62.3,y=20.4},{"a",528,m=1424,x=62.3,y=20.4,ml=19},{"a",546,m=1424,x=62.1,y=19.7,ml=20},{"t",501,n2="Apothecary Lydon, inside",m=1424,x=61.4,y=19.1},{"a",502,m=1424,x=61.4,y=19.1,ml=21},{"t",496,n2="Apothecary Lydon, inside",m=1424,x=61.4,y=19.1},{"a",499,m=1424,x=61.4,y=19.1,ml=19},{"t",499,n2="Umpi, next to Lydon; inside",m=1424,x=61.5,y=19.1},{"a",567,n2="The Dangerous! poster: Kalaba with the peasants, Wilkes at the smithy; the clerk and the miner on the visit at about 30; inside",m=1424,x=62.5,y=19.7,ml=19}}},
  {t="Stanley", lv=22, n="Stanley is Farmer Ray's dog, at the northern farmhouse in Hillsbrad Fields.", g={{"t",502,m=1424,x=32.7,y=35.3}}},
  {t="Hillsbrad Fields: kill these as you meet them", lv=22, n="The Peasants work the fields south of the farmhouses. Every Hillsbrad human drops skulls; the Peasants drop them most often.\nCareful: A fleeing peasant that reaches the town hall can bring back many adds, including Hillsbrad footmen; snares, roots or similar effects keep them from escaping.", g={{"o",546,i=1,txt="Hillsbrad Human Skull x30",n2="Hillsbrad Human Skull: the Peasants in the fields",m=1424,x=30.3,y=40.3},{"o",528,i=1,txt="Kill Hillsbrad Peasant x15",m=1424,x=30.3,y=40.3},{"o",567,i=4,txt="Kill Farmer Kalaba",n2="Farmer Kalaba walks around Hillsbrad Fields: look inside the circle on the map",m=1424,x=35.9,y=46.6}}},
  {t="Tarren Mill", lv=24, g={{"t",528,m=1424,x=62.3,y=20.4},{"a",98094,n2="High Executor Darthalia: orders for Deathstalker Masoj, on the way to Durnholde",m=1424,x=62.3,y=20.4,ml=19},{"a",529,m=1424,x=62.3,y=20.4,ml=19},{"t",546,m=1424,x=62.1,y=19.7},{"a",509,n2="Apothecary Lydon, inside: the Mudsnout Blossoms grow south-west of Durnholde, on the walk there",m=1424,x=61.4,y=19.1,ml=24}}},
  {t="Durnholde Keep: kill these as you meet them", lv=24, n="Drull and Tog'thar are chained inside Durnholde Keep's courtyard buildings. Their locks need keys: Jailor Eston carries the Dull Iron Key and Jailor Marlgen the Burnished Gold Key, both in the keep. Kill them, then open both locks.\nFrom Tarren Mill go south-east into the hills on the way to Durnholde Keep. Rogues and Watchmen hold the camps along the way.", g={{"o",549,i=1,txt="Kill Syndicate Rogue x10",m=1424,x=66.1,y=45.6},{"o",549,i=2,txt="Kill Syndicate Watchman x10",n2="Syndicate Watchman walks around here: look inside the circle on the map",m=1424,x=67,y=46.2},{"o",498,i=1,txt="Locked ball and chain",n2="Drull's ball and chain",m=1424,x=75.3,y=41.5},{"o",498,i=2,txt="Locked ball and chain",n2="Tog'thar's ball and chain",m=1424,x=79.8,y=39.6}}},
  {t="Deathstalker Masoj", lv=24, n="Masoj hides on the hillside above Dun Garok, south-west of Durnholde, on the way down to the blossoms.", g={{"t",98094,m=1424,x=64.2,y=54},{"a",98095,n2="Deathstalker Masoj, once Scout Support is in",m=1424,x=63.6,y=53.1,ml=19}}},
  {t="Mudsnout Blossoms", lv=24, n="Just south of Masoj, the Mudsnout Blossoms grow on the hillsides above the river.", g={{"o",509,i=1,txt="Mudsnout Blossoms x6",m=1424,x=64,y=59.7}}},
  {t="The southern peak", lv=24, n="Masoj wants an Apothecary Vial placed on three peaks. The southern one is the hilltop above Dun Garok, south-east of the blossoms: use a vial at the top.", g={{"o",98095,i=3,txt="Use Apothecary Vials",m=1424,x=74.1,y=73.4}}},
  {t="The smithy", lv=24, n="The smithy stands in the middle of Hillsbrad town. Blacksmith Verringtan and his apprentices work at the forge; the Shipment of Iron is stacked beside it. Citizen Wilkes walks the street north of it.", g={{"o",529,i=1,txt="Kill Blacksmith Verringtan",m=1424,x=32.1,y=44.4},{"o",529,i=2,txt="Kill Hillsbrad Apprentice Blacksmith x4",m=1424,x=31.6,y=44.5},{"o",529,i=3,txt="Shipment of Iron",n2="Inside",m=1424,x=32,y=45.5},{"o",567,i=2,txt="Kill Citizen Wilkes",m=1424,x=32.6,y=39.8}}},
  {t="The western peak", lv=24, n="From Hillsbrad town climb the mountain to the north, right up to its top on the Alterac border: the western vial goes there, not on the lower slope.", g={{"o",98095,i=1,txt="Use Apothecary Vials",m=1416,x=38.6,y=94.8}}},
  {t="Back to Tarren Mill", lv=24, n="East along the foothills, then down into Tarren Mill.", g={{"g",0,txt="Tarren Mill",m=1424,x=60,y=21}}},
  {t="Tarren Mill", lv=24, g={{"t",498,n2="Krusk, inside",m=1424,x=63.2,y=20.7},{"t",549,m=1424,x=62.3,y=20.4},{"t",529,m=1424,x=62.3,y=20.4},{"t",509,n2="Apothecary Lydon, inside",m=1424,x=61.4,y=19.1},{"a",513,n2="Master Apothecary Faranell, in the Undercity",m=1424,x=61.4,y=19.1,ml=24}}},
  {t="The northern peak", lv=24, n="The northern peak rises south-east of Tarren Mill, on the way down towards Durnholde.", g={{"o",98095,i=2,txt="Use Apothecary Vials",m=1424,x=71.6,y=30.2}}},
  {t="Deathstalker Masoj", lv=24, n="Back down to Masoj on the hillside above Dun Garok.", g={{"t",98095,m=1424,x=63.6,y=53.1}}},
  {t="The Sepulcher", lv=24, n="Walk back up to Tarren Mill and fly to the Sepulcher: Shadow Priest Allister stands by the crypt entrance.", g={{"g",0,txt="Tarren Mill flight master",m=1424,x=60.2,y=18.8},{"z",0,txt="Fly to The Sepulcher",at="The Sepulcher"},{"t",516,m=1421,x=44,y=40.9},{"t",95981,m=1421,x=44,y=40.9}}},
  {t="Fly to the Undercity", lv=24, n="Fly on from Karos Razok, the bat handler just east of the crypt, to the Undercity.", g={{"z",0,txt="Fly to Undercity",at="Undercity"}}},
  {t="Aelthalyste", lv=24, n="Aelthalyste stands in the War Quarter.", f={c={"PRIEST"},r={"Scourge"}}, g={{"t",5646,n2="Aelthalyste: Dark Sacrifice",m=1458,x=49.3,y=17.1,f={r={"Scourge"}}}}},
  {t="Master Apothecary Faranell", lv=24, g={{"t",513,n2="Master Apothecary Faranell, in the Apothecarium",m=1458,x=48.8,y=69.3},{"a",515,n2="Keep it: the Hillsbrad coast, later on the route",m=1458,x=48.8,y=69.3,opt=true,ml=24},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","PALADIN","ROGUE","PRIEST","MAGE","WARLOCK"}}},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Archibald", lv=24, n="While you're here: learn Two-Handed Swords from Archibald (War Quarter, 10 silver); two-handers level a Warrior fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Swords",skillLine=55}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Archibald",m=1458,x=57.3,y=32.8}}},
  {t="Archibald", lv=24, n="While you're here: learn Polearms from Archibald (War Quarter, 1 gold); two-handers level a Warrior fastest.", w={{k="level",op=">=",n=20},{k="money",op=">=",n=10000},{k="skill",neg=true,n=1,name="Polearms",skillLine=229}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Archibald",m=1458,x=57.3,y=32.8}}},
  {t="Archibald", lv=24, n="While you're here: learn Two-Handed Swords from Archibald (War Quarter, 10 silver); two-handers level a Paladin fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Swords",skillLine=55}}, f={c={"PALADIN"}}, g={{"tr",0,txt="Train with Archibald",m=1458,x=57.3,y=32.8}}},
  {t="Archibald", lv=24, n="While you're here: learn Polearms from Archibald (War Quarter, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most.", w={{k="level",op=">=",n=20},{k="money",op=">=",n=10000},{k="skill",neg=true,n=1,name="Polearms",skillLine=229}}, f={c={"HUNTER"}}, g={{"tr",0,txt="Train with Archibald",m=1458,x=57.3,y=32.8}}},
  {t="Archibald", lv=24, n="While you're here: learn Swords from Archibald (War Quarter, 10 silver); a sword in the main hand levels a Rogue steadily.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Swords",skillLine=43}}, f={c={"ROGUE"}}, g={{"tr",0,txt="Train with Archibald",m=1458,x=57.3,y=32.8}}},
  {t="Trial of the Sea Lion", lv=24, n="Cast Teleport: Moonglade. Join the two pendant halves at the Shrine of Remulos, on the north-west shore of the lake, before you see Dendrite Starblaze in Nighthaven. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", w={{k="onquest",q={30}}}, f={c={"DRUID"},r={"Tauren","Skyborne"}}, g={{"o",30,i=1,txt="Pendant of the Sea Lion",n2="Pendant of the Sea Lion: use a half at the Shrine of Remulos",m=1450,x=36,y=41.4},{"t",30,m=1450,x=56.2,y=30.6}}},
  {t="Aquatic Form", lv=24, n="Take Aquatic Form from Dendrite Starblaze, who stands upstairs in his building. Then Bunthen Plainswind in Nighthaven flies druids to Thunder Bluff: Turak Runetotem is on Elder Rise.", w={{k="turnedin",q=30},{k="turnedin",neg=true,q=31}}, f={c={"DRUID"},r={"Tauren","Skyborne"}}, g={{"a",31,m=1450,x=56.2,y=30.6,ml=16},{"z",0,txt="Fly to Thunder Bluff",n2="Bunthen Plainswind in Nighthaven flies druids there",at="Thunder Bluff"},{"t",31,n2="Turak Runetotem: Aquatic Form",m=1456,x=76.5,y=27.2}}},
  {t="Back to the Crossroads", lv=24, n="Train with Turak Runetotem. Before you fly on, Tah Winterhoof and Zangen Stonehoof, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts.", w={{k="zone",name="Thunder Bluff",area=1638}}, f={c={"DRUID"},r={"Tauren","Skyborne"}}, g={{"tr",0,txt="Visit your class trainer"},{"a",97538,n2="Tah Winterhoof: Pigments for Paints, the Mirkweed in Mirkfallon Lake by Sun Rock",m=1456,x=54.1,y=47,ml=20},{"a",1195,n2="Zangen Stonehoof: The Sacred Flame, the phial from Ashenvale's Laughing Sisters",m=1456,x=55,y=51.4,opt=true,ml=20},{"z",0,txt="Fly to Crossroads",at="Crossroads"}}},
  {t="Zeppelin to Orgrimmar", lv=24, w={{k="turnedin",neg=true,q=31}}, g={{"g",0,txt="Zeppelin to Orgrimmar",m=1420,x=60.7,y=58.9}}},
  {t="Orgrimmar", lv=24, w={{k="turnedin",neg=true,q=31}}, g={{"g",0,txt="The middle of Orgrimmar",m=1454,x=51.5,y=45.6}}},
  {t="Orgrimmar", lv=24, n="Train before you fly on: the next guide flies from here to the Crossroads.", f={c={"HUNTER","SHAMAN"}}, g={{"tr",0,txt="Visit your class trainer"}}},
} end)

R:Segment({id="horde/07-ashenvale",title="Ashenvale & Thousand Needles",faction="Horde",min=26,max=30,zone=1440,zoneName="Ashenvale",next="horde/30-40/01-hillsbrad-foothills"}, function() return {
  {t="Fly to Zoram'gar Outpost", lv=26, g={{"g",0,txt="Ratchet flight master",m=1413,x=63.1,y=37.1},{"z",0,txt="Fly to Zoram'gar Outpost",at="Zoram'gar Outpost"}}},
  {t="Zoram'gar Outpost", lv=26, n="Je'neu Sancrea stands in the outpost.", g={{"t",6562,m=1440,x=11.6,y=34.3},{"a",6563,m=1440,x=11.6,y=34.3,ml=17}}},
  {t="Blackfathom Deeps ruins", lv=26, n="The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit.", g={{"g",0,txt="Blackfathom Deeps ruins",m=1440,x=14.5,y=14.2}}},
  {t="Sapphires of Aku'Mai", lv=26, n="The Sapphires are blue crystals on the walls of the tunnels leading to the Blackfathom Deeps portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep.", g={{"o",6563,i=1,txt="Sapphire of Aku'Mai x20",m=1440,x=13.6,y=13.1}}},
  {t="Zoram'gar Outpost", lv=26, n="Back to Zoram'gar from the ruins before heading east for good.", g={{"i",0,txt="Je'neu offers a Blackfathom Deeps quest next; leave it unless you have a group."},{"t",6563,m=1440,x=11.6,y=34.3},{"a",6621,m=1440,x=11.9,y=34.5,ml=21}}},
  {t="Ruins of Stardust fountain", lv=26, n="The fountain stands in the middle of the Ruins of Stardust, where Ursangous roams: use the Empty Blue Waterskin there.", f={c={"SHAMAN"}}, g={{"o",1534,i=1,txt="Filled Blue Waterskin",m=1440,x=33.5,y=67.5}}},
  {t="Ursangous", lv=26, n="Follow the main road east past Astranaar (Alliance: keep to the road). Ursangous, a big grizzly, roams the Ruins of Stardust south of the road, west of Mystral Lake. His paw starts the next hunt quest.", w={{k="turnedin",q=6383}}, g={{"h",16303,txt="Get Ursangous's Paw",m=1440,x=39.8,y=65.2,n=1},{"a",23,ml=20}}},
  {t="Alonso", lv=26, n="Alonso, a Forever addition, stands on the west shore of Mystral Lake with three quick Dragonslayer quests.", f={c={"WARRIOR"}}, g={{"g",0,txt="Alonso",m=1440,x=42.4,y=70},{"a",78132,n2="Alonso walks around the Talondeep Path: the map marks where to look",m=1440,x=42.4,y=70,opt=true,ml=15},{"t",78132,m=1440,x=42.4,y=70},{"a",78133,m=1440,x=42.4,y=70,opt=true,ml=15},{"t",78133,m=1440,x=42.4,y=70},{"a",78134,m=1440,x=42.4,y=70,opt=true,ml=15},{"t",78134,m=1440,x=42.4,y=70}}},
  {t="King of the Foulweald", lv=26, n="The Foulweald furbolgs hold the woods east of Mystral Lake, south of the road. Place Karang's Banner on the Foulweald Totem Mound and guard it: the furbolgs come to tear it down. Chief Murgut comes last; his totem drops in the basket.", g={{"o",6621,i=1,txt="Use Karang's Banner",m=1440,x=56.4,y=63.5},{"o",6621,i=1,txt="Murgut's Totem",m=1440,x=56.4,y=63.5}}},
  {t="Torek's Assault", lv=26, n="Keep east on the road. Torek waits south-west of the Warsong lumber camp. He and his grunts storm the Silverwing Outpost: let them take aggro and stay with Torek until Duriel Moonfire is dead.", g={{"a",6544,m=1440,x=68.3,y=75.3,ml=20},{"c",6544,txt="Take Silverwing Outpost."}}},
  {t="Warsong lumber camp", lv=26, n="From the Silverwing Outpost head north-east to the Warsong lumber camp on the road: Kuray'bin stands there.", g={{"a",6503,m=1440,x=71.1,y=68.1,ml=19}}},
  {t="Ashenvale Outrunners", lv=26, n="The night elf Ashenvale Outrunners (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them.", g={{"o",6503,i=1,txt="Kill Ashenvale Outrunner x9",m=1440,x=72.5,y=69.5}}},
  {t="Sharptalon", lv=26, n="Sharptalon, a big nightsaber, prowls the same woods further east, on the way north to Splintertree. Her claw starts the next hunt quest.", w={{k="turnedin",q=6383}}, g={{"h",16305,txt="Get Sharptalon's Claw",m=1440,x=75,y=70.1,n=1},{"a",2,ml=20}}},
  {t="Warsong lumber camp", lv=26, n="Back to Kuray'bin at the lumber camp, on the road north to Splintertree.", g={{"t",6503,m=1440,x=71.1,y=68.1}}},
  {t="Splintertree Post", lv=26, g={{"t",6544,m=1440,x=73,y=62.5},{"a",6441,m=1440,x=73.1,y=61.5,ml=21}}},
  {t="Senani Thunderheart", lv=26, n="Senani Thunderheart keeps the hunt board at Night Run, by the flight master: take The Ashenvale Hunt and hand it straight back. Ursangous, Sharptalon and Shadumbra drop their trophies only after it.", w={{k="turnedin",neg=true,q=6383}}, g={{"t",6383,m=1440,x=73.8,y=61.5}}},
  {t="Splintertree Post", lv=26, w={{k="onquest",q={23}}}, g={{"t",23,m=1440,x=73.8,y=61.5}}},
  {t="Splintertree Post", lv=26, g={{"a",25,m=1440,x=73.7,y=60,ml=23},{"b",0,txt="Set your hearthstone at Splintertree Post",n2="Innkeeper Kaylisk, beside her",m=1440,x=74,y=60.6,at="Splintertree Post"},{"a",6504,n2="Gurda Ragescar: only if you carry the manual pages",m=1440,x=70,y=71.2,opt=true,ml=23},{"t",6504,m=1440,x=70,y=71.2,opt=true},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Felmusk satyrs", lv=26, n="North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns.", g={{"o",6441,i=1,txt="Satyr Horns x16",m=1440,x=66.7,y=57.2}}},
  {t="Shadumbra", lv=26, n="Shadumbra, a shadow panther, stalks the woods around Raynewood Retreat, west of the Felmusk camp. Her head starts the next hunt quest.", w={{k="turnedin",q=6383}}, g={{"h",16304,txt="Get Shadumbra's Head",m=1440,x=57.5,y=56,n=1},{"a",24,ml=20}}},
  {t="Laughing Sisters", lv=26, n="The Laughing Sisters, dryads, wander Raynewood Retreat around Shadumbra's woods; one of them drops Zangen's Etched Phial, which can take several kills.", w={{k="onquest",q={1195}}}, g={{"h",5867,txt="Get Etched Phial",n2="Etched Phial, from a Laughing Sister",m=1440,x=59,y=56.1,n=1}}},
  {t="Ashenvale Moonwell", lv=26, n="South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; Mystral Lake is west of it. Use the Etched Phial at the moonwell to fill it.", w={{k="onquest",q={1195}}}, g={{"o",1195,i=1,txt="Use Etched Phial",n2="Etched Phial, at the Ashenvale Moonwell",m=1440,x=60.2,y=72.9},{"o",1195,i=1,txt="Filled Etched Phial",m=1440,x=60.2,y=72.9}}},
  {t="Tideress", lv=26, n="Back south-west to Mystral Lake. Tideress, a corrupted water elemental, drifts around the lake's island and under the water. She drops the Befouled Water Globe only once you have Stonetalon Standstill from Mastok; it starts a quest for Splintertree.", g={{"h",16408,txt="Get Befouled Water Globe",m=1440,x=46,y=70,n=1},{"a",1918,ml=23}}},
  {t="Mystral Lake", lv=26, n="Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost.", g={{"o",25,i=1,txt="Kill Befouled Water Elemental x12",n2="Underwater",m=1440,x=46.1,y=69.9},{"g",0,txt="Gazebo",m=1440,x=48.9,y=69.6},{"c",25,txt="Befouled Water Elemental; Scout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost."}}},
  {t="Ursangous", lv=26, n="West of Mystral Lake, Ursangous, a big grizzly, roams the Ruins of Stardust: his paw now drops for you.", w={{k="turnedin",q=6383},{k="onquest",neg=true,q={23}},{k="turnedin",neg=true,q=23}}, g={{"h",16303,txt="Get Ursangous's Paw",m=1440,x=39.8,y=65.2,n=1},{"a",23,ml=20}}},
  {t="Sharptalon", lv=26, n="On the way back north-east to Splintertree: Sharptalon prowls the woods south-east of the Warsong lumber camp.", w={{k="turnedin",q=6383},{k="onquest",neg=true,q={2}},{k="turnedin",neg=true,q=2}}, g={{"h",16305,txt="Get Sharptalon's Claw",m=1440,x=75,y=70.1,n=1},{"a",2,ml=20}}},
  {t="Splintertree Post", lv=26, w={{k="onquest",q={2,23,24}}}, g={{"t",23,m=1440,x=73.8,y=61.5,opt=true},{"t",2,m=1440,x=73.8,y=61.5,opt=true},{"t",24,m=1440,x=73.8,y=61.5,opt=true}}},
  {t="Splintertree Post", lv=26, g={{"t",247,m=1440,x=73.8,y=61.5},{"t",6441,m=1440,x=73.1,y=61.5}}},
  {t="Splintertree Post", lv=26, g={{"t",25,m=1440,x=73.7,y=60}}},
  {t="Splintertree Post", lv=26, w={{k="onquest",q={1918}}}, g={{"t",1918,m=1440,x=73.7,y=60},{"a",824,m=1440,x=73.7,y=60,ml=23}}},
  {t="Zoram'gar Outpost", lv=26, g={{"z",0,txt="Fly to Zoram'gar Outpost",at="Zoram'gar Outpost"},{"t",6621,m=1440,x=11.9,y=34.5}}},
  {t="Zoram'gar Outpost", lv=26, w={{k="onquest",q={824}}}, g={{"t",824,m=1440,x=11.6,y=34.3}}},
  {t="Fly to Thunder Bluff", lv=26, n="Fly to Thunder Bluff from Zoram'gar. If you don't know its flight path, fly to Camp Taurajo and walk north through Mulgore instead.", g={{"g",0,txt="Zoram'gar Outpost flight master",m=1440,x=12.2,y=33.8},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Skywatcher Plateau", lv=26, n="The Earthen Ring camp and its three quests stand up on Skywatcher Plateau, north of Thunder Bluff. Fly to Thunder Bluff if you know its flight path and take a lift down, else fly to Camp Taurajo and walk north through Mulgore; the arrow then leads round to the plateau's north end and up onto it.", f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK","DRUID"},r={"Orc","Troll","Scourge"}}, g={{"g",0,txt="North of Thunder Bluff",m=1412,x=40.9,y=31.7}}},
  {t="Skywatcher Plateau", lv=26, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK","DRUID"},r={"Orc","Troll","Scourge"}}, g={{"g",0,txt="Skywatcher Plateau",m=1412,x=32.5,y=20}}},
  {t="The Earthen Ring", lv=26, n="The Earthen Ring camp stands north of the bluffs: Mazu'kon, Yorn Grimtotem and Muln Earthfury. From Thunder Bluff, take a lift down; coming on foot from Camp Taurajo, keep north past the bluffs.", g={{"a",96260,m=1412,x=32.5,y=20,ml=23},{"a",96241,m=1412,x=32.5,y=20.6,ml=23},{"a",96259,n2="Muln Earthfury: The Broodmother comes once this is handed in",m=1412,x=33.4,y=22.6,ml=23}}},
  {t="Gloomrise: kill these as you meet them", lv=26, n="North of the camp, spiders overrun the burial ground at Gloomrise. Use Mazu'kon's Toxin Extractor on the Gnawed Corpses; the Spinners drop the Crystalline Silk. Broodmother Valraxx sits at the north end: her Bloody Parchment starts A Darker Truth.", g={{"o",96260,i=1,txt="Crystalline Silk x3",n2="Crystalline Silk, from Gloomrise Spinners",m=1412,x=33.3,y=14.6},{"o",96259,i=2,txt="Kill Gloomrise Soldier x5",m=1412,x=33,y=14.2},{"o",96259,i=1,txt="Kill Gloomrise Hatchling x10",m=1412,x=32.8,y=14.4},{"o",96241,i=1,txt="Gloomrise Toxin Sample x5",n2="Gloomrise Toxin Samples, from the Gnawed Corpses",m=1412,x=33.6,y=12.8}}},
  {t="The Earthen Ring", lv=26, n="Muln Earthfury offers The Broodmother only once Defending the Dead is handed in.", g={{"t",96260,m=1412,x=32.5,y=20},{"t",96241,m=1412,x=32.5,y=20.7},{"t",96259,m=1412,x=33.4,y=22.6}}},
  {t="The Broodmother", lv=26, w={{k="group",q=96261}}, g={{"a",96261,m=1412,x=33.4,y=22.6,ml=23}}},
  {t="Broodmother Valraxx", lv=26, n="Broodmother Valraxx sits at the north end of Gloomrise; her Bloody Parchment starts A Darker Truth. Broodmother Valraxx is elite: grouping up is advised.", w={{k="group",q=96261}}, g={{"o",96261,i=1,txt="Kill Broodmother Valraxx",m=1412,x=33.2,y=10.7,grp=true},{"h",273658,txt="Get Bloody Parchment",n2="Bloody Parchment, from Broodmother Valraxx: it does not drop for everyone",m=1412,x=33.4,y=7.6,n=1,opt=true,grp=true},{"a",96294,opt=true,ml=23}}},
  {t="The Earthen Ring", lv=26, n="Back south to the camp, then up into Thunder Bluff for the flight to Camp Taurajo.", w={{k="group",q=96261}}, g={{"t",96261,m=1412,x=33.4,y=22.6},{"t",96294,m=1412,x=33.4,y=22.6,opt=true}}},
  {t="Class trainer", lv=26, f={c={"PALADIN","PRIEST","SHAMAN","MAGE","DRUID"}}, g={{"tr",0,txt="Visit your class trainer",f={c={"PALADIN","PRIEST","SHAMAN","MAGE","DRUID"}}}}},
  {t="Thunder Bluff", lv=26, g={{"g",0,txt="Thunder Bluff's central rise",m=1456,x=47,y=49.8}}},
  {t="Thunder Bluff", lv=26, n="Into Thunder Bluff by a lift: Tal, the wind rider master, stands on the central rise. Take his flight path if you don't know it yet.", g={{"fp",22,txt="Get the Thunder Bluff flight path (Tal)",m=1456,x=47,y=49.8},{"o",93739,i=3,txt="Talk to Cairne Bloodhoof",n2="Speak with Cairne Bloodhoof, in Thunder Bluff: Exploring the Horde",m=1456,x=60.3,y=51.7,opt=true,f={r={"Skyborne"}}}}},
  {t="Zangen Stonehoof", lv=26, n="Zangen Stonehoof stands a short walk east of Tal.", w={{k="complete",q=1195}}, g={{"t",1195,m=1456,x=55,y=51.4},{"a",1196,n2="Zangen Stonehoof: Rau Cliffrunner at Freewind Post, later in this guide",m=1456,x=55,y=51.4,ml=20}}},
  {t="Tah Winterhoof", lv=26, n="Tah Winterhoof stands beside Zangen, east of Tal.", w={{k="complete",q=97538}}, g={{"t",97538,m=1456,x=54.1,y=47}}},
  {t="Ansekhwa", lv=26, n="While you're here: learn Two-Handed Maces from Ansekhwa (10 silver); two-handers level a Warrior fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Maces",skillLine=160}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Ansekhwa",m=1456,x=40.9,y=62.7}}},
  {t="Fly to Camp Taurajo", lv=26, g={{"g",0,txt="Thunder Bluff flight master",m=1456,x=46.7,y=49.9},{"z",0,txt="Fly to Camp Taurajo",at="Camp Taurajo"}}},
  {t="Brine", lv=26, n="Brine's hut stands on the ridge above the quilboar watering hole south of Camp Taurajo, on the road to the Great Lift.", f={c={"SHAMAN"}}, g={{"t",1534,m=1413,x=43.4,y=77.4},{"a",220,n2="for Islen Waterseer, south of Ratchet: next guide",m=1413,x=43.4,y=77.4,ml=20}}},
  {t="Tear of the Moons", lv=26, n="On the road south to the Great Lift, turn east into the Bael Modan dig. Feegly the Exiled hides at its south edge. General Twinbraid's Strongbox stands on the bottom floor of the dwarves' fortress, beside General Twinbraid (30) and his Officers (26): pull them to you one at a time.", g={{"a",857,m=1413,x=49,y=86.3,ml=22},{"o",857,i=1,txt="Tear of the Moons",n2="General Twinbraid's Strongbox; below ground",m=1413,x=49.1,y=84.3},{"t",857,m=1413,x=49,y=86.3}}},
  {t="The Great Lift", lv=26, g={{"g",0,txt="The Great Lift, down into Thousand Needles",m=1441,x=31.9,y=23.9}}},
  {t="Freewind Post's lift", lv=26, g={{"g",0,txt="Freewind Post's lift",m=1441,x=44.9,y=48.9}}},
  {t="Freewind Post", lv=26, n="Ride the lift down, then follow the road east through the canyons to Freewind Post, a Tauren village on top of the mesas. Its lift is on the north side.", g={{"fp",30,txt="Get the Freewind Post flight path (Nyse)",m=1441,x=45.1,y=49.1},{"a",4767,n2="Elu, by the wind rider master",m=1441,x=44.9,y=48.9,ml=25},{"a",4821,m=1441,x=44.6,y=50.3,ml=24},{"t",4542,m=1441,x=45.7,y=50.7},{"a",4841,m=1441,x=45.7,y=50.7,ml=23},{"a",5147,n2="The Wanted poster beside Cliffwatcher",m=1441,x=46,y=50.9,ml=25},{"a",98070,n2="Jandia, the trade supplies vendor: the Screeching harpies of Roguefeather Den; inside the inn",m=1441,x=46.2,y=51.5,ml=25},{"a",98069,n2="Jandia: her stolen supplies lie in the same harpy den",m=1441,x=46.2,y=51.5,ml=25}}},
  {t="Rau Cliffrunner", lv=26, n="Rau Cliffrunner stands in Freewind Post: Zangen's filled phial is for him.", w={{k="onquest",q={1196}}}, g={{"t",1196,m=1441,x=46.1,y=51.7},{"a",1197,n2="Rau Cliffrunner: the Ancient Brazier in Splithoof Hold, among the Galak camps",m=1441,x=46.1,y=51.7,ml=20}}},
  {t="Alien Egg", lv=26, n="Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1).", g={{"o",4821,i=1,txt="Alien Egg",m=1441,x=37.6,y=56.1}}},
  {t="Galak centaurs", lv=26, n="The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone Galak Messenger walks a long path between the camps: if you meet him, kill him, his note starts a quest for Whitereach Post. Don't wait for him.", g={{"o",4841,i=1,txt="Kill Galak Scout x12",m=1441,x=45.5,y=43.5},{"o",4841,i=2,txt="Kill Galak Wrangler x10",m=1441,x=46.1,y=41.9},{"o",4841,i=3,txt="Kill Galak Windchaser x6",m=1441,x=46.6,y=41.2},{"h",12564,txt="Get Assassination Note",n2="Galak Messenger's Assassination Plot, if you meet him",m=1441,x=39.4,y=33.1,n=1,opt=true},{"a",4881,opt=true,ml=23}}},
  {t="Splithoof Hold", lv=26, n="A short walk north of the Galak camps, the cave of Splithoof Hold leads down to its deepest chamber, where the Ancient Brazier burns. Use the Filled Etched Phial on it, then loot the Cloven Hoof at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to Dorn's mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame.", w={{k="onquest",q={1197}}}, g={{"o",1197,i=1,txt="Use Filled Etched Phial",n2="Filled Etched Phial, at the Ancient Brazier",m=1441,x=42,y=31.5},{"o",1197,i=1,txt="Cloven Hoof",n2="Cloven Hoof, from the Ancient Brazier",m=1441,x=42,y=31.5}}},
  {t="Dorn Plainstalker", lv=26, n="Dorn Plainstalker stands on a mesa top east of the Galak camps. For the Test of Faith, walk off the end of the planks beside him: you land safely.", g={{"a",1149,n2="Dorn Plainstalker, below ground",m=1441,x=54,y=41.5,ml=25},{"c",1149,txt="If you have faith, leap from the planks overlooking Thousand Needles."},{"t",1149,m=1441,x=54,y=41.5},{"a",1150,m=1441,x=54,y=41.5,ml=25}}},
  {t="Freewind Post", lv=26, g={{"t",4841,m=1441,x=45.7,y=50.7},{"a",5064,m=1441,x=45.7,y=50.7,ml=24},{"t",4821,m=1441,x=44.6,y=50.3},{"a",4865,m=1441,x=44.6,y=50.3,ml=24},{"b",0,txt="Set your hearthstone at Freewind Post",n2="Innkeeper Abeqwa, beside Jandia",m=1441,x=46.1,y=51.5,at="Freewind Post"}}},
  {t="Rau Cliffrunner", lv=26, w={{k="complete",q=1197}}, g={{"t",1197,m=1441,x=46.1,y=51.7}}},
  {t="Darkcloud Pinnacle", lv=26, n="West of Freewind, the Grimtotem camps below Darkcloud Pinnacle. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps.", g={{"o",5064,i=3,txt="Document Chest",n2="Document Chest, south-east camp",m=1441,x=39.3,y=41.5},{"o",5064,i=2,txt="Document Chest",n2="Document Chest, south-west camp",m=1441,x=33.8,y=40},{"o",5064,i=1,txt="Document Chest",n2="Document Chest, north-west camp",m=1441,x=31.8,y=32.6}}},
  {t="Level 28.9", lv=28, n="Short of 28.9? The Grimtotem around these camps (25-28) are the right level: kill a few more before the climb to Lakota. Past it, this step skips itself. Or, with a group, run the Blackfathom Deeps dungeon or the Razorfen Kraul dungeon instead.", w={{k="level",op="<",n=28,frac=0.9}}, g={{"g",0,txt="Grimtotem camps below Darkcloud Pinnacle",m=1441,x=35,y=31.5},{"l",28,txt="Reach level 28 (90% in): grind Grimtotem Stomper",n2="grind on Grimtotem Stomper",m=1441,x=35,y=31,fr=0.9}}},
  {t="Lakota Windsong", lv=28, n="Climb the path to the top of Darkcloud Pinnacle. Lakota Windsong is held captive beside Arnak Grimtotem (29): clear the guards and Arnak first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way.", g={{"o",5147,i=1,txt="Arnak's Hoof",m=1441,x=38.1,y=26.9},{"a",4904,m=1441,x=38,y=26.4,ml=25},{"c",4904,txt="Escort Lakota Windsong from the Darkcloud Pinnacle."}}},
  {t="Highperch", lv=28, n="West of Whitereach the wyverns nest on the Highperch cliffs; the eggs lie in the nests. Pao'ka Swiftmountain waits on the east side of the nesting grounds: free him and keep him alive on the walk back to Whitereach Post.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom.", g={{"o",4767,i=1,txt="Highperch Wyvern Egg x10",m=1441,x=18,y=41.7},{"a",4770,m=1441,x=17.9,y=40.6,ml=25},{"c",4770,txt="Escort Pao'ka from Highperch"}}},
  {t="Whitereach Post", lv=28, g={{"t",4770,m=1441,x=21.5,y=32.4},{"t",4865,m=1441,x=21.5,y=32.4},{"i",0,txt="Motega's next quest, Sacred Fire, ends in Thunder Bluff, off this route. Skip it."}}},
  {t="Kanati Greycloud", lv=28, n="Only if the Galak Messenger dropped his plot for you: Kanati Greycloud stands at Whitereach Post.", w={{k="onquest",q={4881,4966}}}, g={{"t",4881,m=1441,x=21.2,y=32.1},{"a",4966,m=1441,x=21.2,y=32.1,ml=23}}},
  {t="Wizlo Bearingshiner", lv=28, w={{k="group",q=5151}}, g={{"a",5151,m=1441,x=21.4,y=32.5,ml=24}}},
  {t="Hypercapacitor Gizmo", lv=28, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Enraged Panther is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=5151}}, g={{"o",5151,i=1,txt="Hypercapacitor Gizmo",m=1441,x=22.8,y=24.6,grp=true}}},
  {t="Whitereach Post", lv=28, w={{k="onquest",q={4966}}}, g={{"c",4966,txt="Galak Assassin",n2="Kill the Galak Assassin that comes for Kanati",m=1441,x=21.2,y=32.1}}},
  {t="Whitereach Post", lv=28, w={{k="onquest",q={4966}}}, g={{"t",4966,m=1441,x=21.2,y=32.1}}},
  {t="Wizlo Bearingshiner", lv=28, w={{k="group",q=5151}}, g={{"t",5151,m=1441,x=21.4,y=32.5}}},
  {t="Level 29.49", lv=29, n="If you skipped Hypercapacitor Gizmo and are still short of 29.49, kill harpies here first: Roguefeather Den is your next stop anyway. Past it, this step skips itself. Or, with a group, run the Blackfathom Deeps dungeon or the Scarlet Monastery dungeon (Graveyard) instead.", w={{k="group",neg=true,q=5151},{k="level",op="<",n=29,frac=0.49}}, g={{"g",0,txt="Screeching Roguefeather",m=1441,x=27,y=51.9},{"l",29,txt="Reach level 29 (49% in): grind Screeching Roguefeather",n2="grind on Screeching Roguefeather",m=1441,x=27.2,y=52.2,fr=0.49}}},
  {t="The Screeching Canyon: kill these as you meet them", lv=29, n="South of Darkcloud, the harpies of Roguefeather Den. Grenka Bloodscreech (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are Jandia's; her Stolen Freewind Supplies lie on the ground along the foot of the cliff and in the cave up on top.", g={{"o",98070,i=2,txt="Kill Screeching Roguefeather x5",m=1441,x=27.2,y=52.2},{"o",98070,i=3,txt="Kill Screeching Windcaller x5",m=1441,x=26.7,y=52.1},{"o",98070,i=1,txt="Kill Screeching Harpy x5",m=1441,x=26.5,y=52.3},{"o",98069,i=1,txt="Stolen Freewind Supplies x8",n2="Stolen Freewind Supplies, on the ground around the den",m=1441,x=27,y=51.9},{"o",1150,i=1,txt="Grenka's Claw",m=1441,x=26.8,y=55.4}}},
  {t="Freewind Post", lv=29, n="Back east to Freewind Post: it lies on the way from Roguefeather Den to Dorn's mesa.", g={{"t",4767,m=1441,x=44.9,y=48.9},{"t",5147,m=1441,x=45.7,y=50.7},{"t",5064,m=1441,x=45.7,y=50.7},{"t",4904,n2="Thalia Amberhide, inside",m=1441,x=46,y=51.6},{"t",98070,n2="Jandia, inside",m=1441,x=46.2,y=51.5},{"t",98069,n2="Jandia, inside",m=1441,x=46.2,y=51.5},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Test of Endurance", lv=29, n="Dorn Plainstalker's mesa is north-east of Freewind.", g={{"t",1150,n2="Dorn Plainstalker, below ground",m=1441,x=54,y=41.5},{"a",1151,n2="Dorn Plainstalker offers Test of Strength once Test of Endurance is in",m=1441,x=54,y=41.5,opt=true,ml=25}}},
  {t="Rok'Alim the Pounder", lv=29, n="Rok'Alim, a hard-hitting rock elemental, walks the cliffs of Highperch, back west past Whitereach Post. Rok'Alim the Pounder is elite: grouping up is advised.", g={{"o",1151,i=1,txt="Fragments of Rok'Alim",m=1441,x=17.1,y=38.1,opt=true,grp=true},{"t",1151,n2="Dorn Plainstalker, below ground",m=1441,x=54,y=41.5,opt=true}}},
  {t="Freewind Post", lv=29, n="Back to Freewind Post. The Mirage Raceway's quests come with the next visit to the Shimmering Flats, at 33.", g={{"i",0,txt="The next guide flies on from here to the Crossroads and Orgrimmar."}}},
} end)

R:Segment({id="horde/30-40/01-hillsbrad-foothills",title="Hillsbrad Foothills & Arathi Highlands",faction="Horde",min=29,max=33,zone=1424,zoneName="Hillsbrad Foothills",next="horde/30-40/02-thousand-needles"}, function() return {
  {t="Freewind Post flight master", lv=29, g={{"g",0,txt="Freewind Post flight master",m=1441,x=45,y=49.1}}},
  {t="Thunder Bluff", lv=29, n="Fly from Freewind Post to Thunder Bluff and train with Turak Runetotem on Elder Rise; fly on to the Crossroads from there.", f={c={"DRUID"}}, g={{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"},{"tr",0,txt="Visit your class trainer"}}},
  {t="Ratchet", lv=29, n="Fly from Freewind Post to Ratchet. Islen Waterseer camps on the coast a short walk south of the town; fly on to the Crossroads from Ratchet.", f={c={"SHAMAN"}}, g={{"z",0,txt="Fly to Ratchet",at="Ratchet"},{"t",220,n2="Islen Waterseer: your Water Sapta, for the brazier",m=1413,x=65.8,y=43.8},{"a",63,m=1413,x=65.8,y=43.8,ml=20}}},
  {t="Fly to the Crossroads", lv=29, f={c={"DRUID"}}, g={{"g",0,txt="Thunder Bluff flight master",m=1456,x=46.7,y=49.9},{"z",0,txt="Fly to Crossroads",at="Crossroads"}}},
  {t="Fly to the Crossroads", lv=29, f={c={"SHAMAN"}}, g={{"g",0,txt="Ratchet flight master",m=1413,x=63.1,y=37.1},{"z",0,txt="Fly to Crossroads",at="Crossroads"}}},
  {t="Fly to the Crossroads", lv=29, f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","MAGE","WARLOCK"}}, g={{"z",0,txt="Fly to Crossroads",at="Crossroads"}}},
  {t="Korran", lv=29, n="Korran stands beside the Crossroads flight master.", g={{"a",1145,n2="Korran: for Belgrom Rockmaul in Orgrimmar",m=1413,x=51.1,y=29.6,ml=29}}},
  {t="Fly to Orgrimmar", lv=29, g={{"g",0,txt="Crossroads flight master",m=1413,x=51.5,y=30.4},{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"}}},
  {t="Thrall", lv=29, n="Thrall waits in Grommash Hold, in the Valley of Wisdom.", f={r={"Skyborne"}}, g={{"t",93739,n2="Thrall, Grommash Hold, if you carry it",m=1454,x=31.7,y=37.8,opt=true}}},
  {t="Train", lv=29, n="Train your new spells.", f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Belgrom Rockmaul", lv=29, n="Belgrom Rockmaul stands in the Valley of Honor, on the way out to the main gate.", g={{"t",1145,m=1454,x=75.2,y=34.2},{"a",1146,n2="for Moktar Krin in the Shimmering Flats, next guide",m=1454,x=75.2,y=34.2,ml=29}}},
  {t="Zeppelin to Undercity", lv=29, g={{"g",0,txt="Zeppelin to Undercity",m=1411,x=50.8,y=13.5}}},
  {t="The Undercity", lv=29, n="Elixir of Agony needs a Lesser Troll's Blood Elixir, an Alchemy item: buy one at the auction house if you can (or ask an alchemist). The quest text says Strong, but it takes a Lesser Troll's Blood Elixir. No elixir: skip the Elixir steps in Hillsbrad.", g={{"i",0,txt="Lesser Troll's Blood Elixir: auction house or an alchemist, for Elixir of Agony."}}},
  {t="Garen Largo", lv=29, n="Garen Largo trains Paladins in the Undercity.", f={c={"PALADIN"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Undercity flight master", lv=29, f={c={"SHAMAN"}}, g={{"g",0,txt="Undercity flight master",m=1458,x=63.1,y=48.3}}},
  {t="Brazier of Everfount", lv=29, n="Fly to the Sepulcher. The Brazier of Everfount stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the Minor Manifestation of Water and keep the Shard of Water for Islen. Fly on to Tarren Mill from the Sepulcher.", f={c={"SHAMAN"}}, g={{"z",0,txt="Fly to The Sepulcher",at="The Sepulcher"},{"o",63,i=1,txt="Use Water Sapta",n2="Water Sapta: drink it by the standing stone to see the elemental",m=1421,x=38.5,y=44.4},{"o",63,i=1,txt="Corrupt Manifestation's Bracers",m=1421,x=38.8,y=44.3},{"t",63,m=1421,x=38.3,y=44.6},{"a",100,m=1421,x=38.3,y=44.6,ml=20},{"t",100,m=1421,x=38.6,y=44.6},{"a",96,n2="for Islen Waterseer, next guide",m=1421,x=38.6,y=44.6,ml=20}}},
  {t="Fly to Tarren Mill", lv=29, f={c={"SHAMAN"}}, g={{"g",0,txt="The Sepulcher flight master",m=1421,x=45.6,y=42.4},{"z",0,txt="Fly to Tarren Mill",at="Tarren Mill"}}},
  {t="Fly to Tarren Mill", lv=29, f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","MAGE","WARLOCK","DRUID"}}, g={{"g",0,txt="Undercity flight master",m=1458,x=63.1,y=48.3},{"z",0,txt="Fly to Tarren Mill",at="Tarren Mill"}}},
  {t="High Executor Darthalia", lv=29, n="You missed Darthalia's first errands, from the 22-25 Hillsbrad guide: they come first now. They are a few levels below you and quick, and they open the rest of the Battle of Hillsbrad in this guide.", w={{k="turnedin",neg=true,q=529}}, g={{"a",527,m=1424,x=62.3,y=20.4,ml=19}}},
  {t="Krusk", lv=29, n="Krusk wants his two scouts freed from Durnholde Keep before he trusts you with Infiltration.", w={{k="turnedin",neg=true,q=498}}, g={{"a",498,n2="Krusk, inside",m=1424,x=63.2,y=20.7,ml=17}}},
  {t="Hillsbrad Fields", lv=29, n="West past the hills to the farms east of Hillsbrad town. Farmer Ray works the field by the northern farmhouse, Farmer Getz the one further south-east; Farmhands and Farmers are everywhere.", w={{k="turnedin",neg=true,q=529}}, g={{"o",527,i=1,txt="Kill Hillsbrad Farmer x6",m=1424,x=36.4,y=39.8},{"o",527,i=2,txt="Kill Hillsbrad Farmhand x6",m=1424,x=36.8,y=39.6},{"o",527,i=3,txt="Kill Farmer Ray",m=1424,x=33.2,y=34.8},{"o",527,i=4,txt="Kill Farmer Getz",m=1424,x=35.2,y=38}}},
  {t="Tarren Mill", lv=29, n="Back east to Tarren Mill.", w={{k="turnedin",neg=true,q=529}}, g={{"t",527,m=1424,x=62.3,y=20.4},{"a",528,m=1424,x=62.3,y=20.4,ml=19}}},
  {t="Hillsbrad Peasants", lv=29, n="Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping.", w={{k="turnedin",neg=true,q=529}}, g={{"o",528,i=1,txt="Kill Hillsbrad Peasant x15",m=1424,x=35.4,y=42},{"o",567,i=4,txt="Kill Farmer Kalaba",m=1424,x=35.9,y=46.6}}},
  {t="Tarren Mill", lv=29, w={{k="turnedin",neg=true,q=529}}, g={{"t",528,m=1424,x=62.3,y=20.4},{"a",529,m=1424,x=62.3,y=20.4,ml=19}}},
  {t="Durnholde Keep", lv=29, n="South-east of Tarren Mill. Drull and Tog'thar are chained in the keep's courtyard buildings: Jailor Eston carries the Dull Iron Key and Jailor Marlgen the Burnished Gold Key, both in the keep. Kill them, then open both locks.", w={{k="turnedin",neg=true,q=498}}, g={{"o",498,i=1,txt="Locked ball and chain",n2="Drull's ball and chain",m=1424,x=75.3,y=41.5},{"o",498,i=2,txt="Locked ball and chain",n2="Tog'thar's ball and chain",m=1424,x=79.8,y=39.6}}},
  {t="The smithy", lv=29, n="West across the foothills to Hillsbrad town: the smithy stands in the middle of it. Blacksmith Verringtan and his apprentices work at the forge; the Shipment of Iron is stacked beside it.", w={{k="turnedin",neg=true,q=529}}, g={{"o",529,i=1,txt="Kill Blacksmith Verringtan",m=1424,x=32.1,y=44.4},{"o",529,i=2,txt="Kill Hillsbrad Apprentice Blacksmith x4",m=1424,x=31.6,y=44.5},{"o",529,i=3,txt="Shipment of Iron",n2="Inside",m=1424,x=32,y=45.5},{"o",567,i=2,txt="Kill Citizen Wilkes",m=1424,x=32.6,y=39.8}}},
  {t="Krusk", lv=29, n="Back to Tarren Mill.", w={{k="turnedin",neg=true,q=498}}, g={{"t",498,n2="Krusk, inside",m=1424,x=63.2,y=20.7}}},
  {t="High Executor Darthalia", lv=29, w={{k="turnedin",neg=true,q=529}}, g={{"t",529,m=1424,x=62.3,y=20.4}}},
  {t="Tarren Mill", lv=29, g={{"a",552,m=1424,x=63.9,y=19.7,ml=29},{"a",533,n2="Krusk, inside",m=1424,x=63.2,y=20.7,ml=29},{"a",532,m=1424,x=62.3,y=20.4,ml=19},{"b",0,txt="Set your hearthstone at Tarren Mill",m=1424,x=62.8,y=19,at="Tarren Mill"},{"h",3703,txt="Buy Southshore Stout (Innkeeper Shay)",n2="Southshore Stout, for Henchman Valik",m=1424,x=62.8,y=19,n=1}}},
  {t="Helcular's Rod", lv=29, n="South-west, the Cave and Ferocious Yetis (30-32) fill the Foothill Caverns in the hills west of Tarren Mill; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but at 29-30 they hit hard and come in pairs.", g={{"o",552,i=1,txt="Helcular's Rod",m=1424,x=44.5,y=29.4}}},
  {t="Level 30", lv=30, n="Tarren Mill's Prison Break In, Stone Tokens and The Hammer May Fall are offered from level 30. Below it? Keep killing the yetis in these caves until level 30. Or, with a group, run the Scarlet Monastery dungeon (Graveyard) or the Blackfathom Deeps dungeon instead.", w={{k="level",op="<",n=30}}, g={{"g",0,txt="Foothill Caverns",m=1424,x=44,y=28},{"l",30,txt="Reach level 30: grind Cave Yeti",n2="grind on Cave Yeti",m=1424,x=44,y=27.4}}},
  {t="Town hall", lv=30, n="On to Hillsbrad town, south-west of the yeti caves. The town hall is on the town's west side: Magistrate Burnside (30) and Clerk Horrace Whitesteed are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town.", g={{"o",532,i=2,txt="Kill Hillsbrad Councilman x5",m=1424,x=32.1,y=42.4},{"o",532,i=3,txt="Hillsbrad Proclamation",n2="Hillsbrad Proclamation, inside",m=1424,x=29.7,y=41.8},{"o",532,i=4,txt="Hillsbrad Town Registry",n2="Inside",m=1424,x=29.5,y=41.5},{"o",567,i=1,txt="Kill Clerk Horrace Whitesteed",n2="Inside",m=1424,x=29.5,y=42.4},{"o",532,i=1,txt="Kill Magistrate Burnside",n2="Inside",m=1424,x=29.7,y=41.6}}},
  {t="Tarren Mill", lv=30, n="Back east to Tarren Mill.", g={{"t",532,m=1424,x=62.3,y=20.4},{"a",539,m=1424,x=62.3,y=20.4,ml=19},{"t",552,m=1424,x=63.9,y=19.7},{"a",553,m=1424,x=63.9,y=19.7,ml=29},{"a",544,n2="Magus Wordeen Voidglare, inside: offered from level 30",m=1424,x=61.6,y=20.9,ml=30},{"a",93680,n2="Magus Wordeen Voidglare: Key to the City, the Grimy Key is by the traitors",m=1424,x=61.6,y=20.9,ml=30},{"a",556,n2="Keeper Bel'varil, inside: offered from level 30",m=1424,x=61.5,y=20.9,ml=30},{"a",676,n2="Tallow: for Drum Fel in Hammerfall, later in this guide (from level 30)",m=1424,x=61.9,y=19.6,ml=30}}},
  {t="Foothill Caverns", lv=30, n="Back into the yeti caves west of Tarren Mill with the Rod of Helcular. The path splits just inside: the Flame of Azel burns on the upper level to the right, the Flame of Veraz on the lower level to the left, past more yetis.", g={{"o",553,i=1,txt="Use Rod of Helcular",n2="Flame of Azel",m=1424,x=43.9,y=28.1},{"o",553,i=2,txt="Use Rod of Helcular",n2="Flame of Veraz",m=1424,x=44.1,y=26.6}}},
  {t="Flame of Uzel", lv=30, n="The third flame burns in the smaller cave up in the hills north of the caverns.\nCareful: Giant and Mountain Yetis (32-34) stand around the flame, often in pairs, and Frostmaw, a rare yeti (37), roams nearby. At 30-31 they are over your level: pull the yetis one at a time from the cave mouth before you use the Rod, and watch for Frostmaw before you go in.", g={{"o",553,i=3,txt="Use Rod of Helcular",n2="Flame of Uzel",m=1424,x=41.7,y=6.4}}},
  {t="Alterac Mountains", lv=30, g={{"g",0,txt="The Dalaran crater's eastern rim",m=1416,x=24.5,y=82.8}}},
  {t="The Dalaran crater", lv=30, n="Head west along the foot of the mountains to the violet dome of Dalaran. Ricter, Alina and Dermot (33-34) stand together inside the crater's eastern rim, Kegan Darkmar (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-33) around them drop the Worn Stone Tokens. Careful: Many guards stand in linked pairs and others patrol alone around the camp.", g={{"o",544,i=1,txt="Bloodstone Wedge",m=1416,x=19.3,y=91.5},{"o",544,i=2,txt="Bloodstone Marble",m=1416,x=19.5,y=90},{"o",544,i=3,txt="Bloodstone Shard",m=1416,x=19.6,y=90.9},{"o",544,i=4,txt="Bloodstone Oval",m=1416,x=16.8,y=89.4},{"o",93680,i=1,txt="Grimy Key",n2="Grimy Key: an object to loot, by the traitors",m=1416,x=16.4,y=89.3},{"o",556,i=1,txt="Worn Stone Token x10",m=1416,x=18.4,y=88}}},
  {t="Hillsbrad Foothills", lv=30, g={{"g",0,txt="Azurelode Mine",m=1424,x=28.5,y=55}}},
  {t="Azurelode Mine", lv=30, n="Head south past Hillsbrad town to the Azurelode Mine. Miners work the tunnels; Foreman Bonds (30) and Miner Hackett (29) are deep inside.", g={{"o",539,i=2,txt="Kill Hillsbrad Miner x10",m=1424,x=28.3,y=54.8},{"o",567,i=3,txt="Kill Miner Hackett",m=1424,x=31.8,y=52.7},{"o",539,i=1,txt="Kill Foreman Bonds",n2="Inside Azurelode Mine",m=1424,x=31.2,y=56}}},
  {t="Torn Fin murlocs", lv=30, n="The Torn Fin murlocs camp on the beaches south-west of Southshore's bay, below the mine.", w={{k="onquest",q={515}}}, g={{"g",0,txt="Torn Fin beach",m=1424,x=36,y=68},{"o",515,i=3,txt="Torn Fin Eye x5",m=1424,x=36.1,y=68.7,opt=true}}},
  {t="Helcular's Grave", lv=30, n="Head east to Southshore's graveyard, on the north-east edge of the town: Helcular's grave lies among the others. Come at it from the north, down the slope above the town. Southshore Guards (55) stand at the graveyard's north-west corner and south-east of the grave: walk in between them, hand the quest in and leave the way you came.", g={{"g",0,txt="North of Southshore's graveyard",m=1424,x=53.4,y=48.8},{"t",553,m=1424,x=52.8,y=53.4}}},
  {t="Daggerspine naga", lv=30, n="The Daggerspine naga line the shore south-east of the town.", w={{k="onquest",q={515}}}, g={{"g",0,txt="Daggerspine shore",m=1424,x=53,y=65},{"o",515,i=2,txt="Daggerspine Scale x5",m=1424,x=52.7,y=65.5,opt=true}}},
  {t="Henchman Valik", lv=30, n="From Southshore head north past Tarren Mill and follow the road on into the Alterac foothills. Valik waits by the Syndicate camp. He offers his errand only while you carry Krusk's Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes Valik.", w={{k="onquest",q={533}},{k="complete",neg=true,q=533}}, g={{"a",535,m=1416,x=57.2,y=69.5,ml=29},{"t",535,m=1416,x=57.2,y=69.5}}},
  {t="Syndicate missives", lv=30, n="Only if Valik's missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one. Careful: at 31-32 they are still above you and stand close together, with Wizards (34-35) among them: pull one at a time from the camp's edge.", g={{"o",533,i=1,txt="Syndicate Missive",m=1416,x=57.6,y=68.5}}},
  {t="Tarren Mill", lv=30, n="Head back south down the road to Tarren Mill.", g={{"t",533,n2="Krusk, inside",m=1424,x=63.2,y=20.7},{"t",539,m=1424,x=62.3,y=20.4},{"t",567,m=1424,x=62.3,y=20.4},{"t",556,n2="Keeper Bel'varil, inside",m=1424,x=61.5,y=20.9},{"t",544,n2="Magus Wordeen Voidglare, inside",m=1424,x=61.6,y=20.9},{"t",93680,n2="Magus Wordeen Voidglare: he offers Dalaran Patrols after it",m=1424,x=61.6,y=20.9},{"a",557,n2="Keeper Bel'varil: for the 38-39 visit to Alterac",m=1424,x=61.5,y=20.9,ml=30},{"a",545,n2="Magus Wordeen Voidglare: for the 38-39 visit to Alterac",m=1424,x=61.6,y=20.9,ml=30},{"i",0,txt="Krusk now offers Gol'dir (level 36): leave it for the 38-39 visit."},{"t",515,n2="Apothecary Lydon, inside",m=1424,x=61.4,y=19.1,opt=true}}},
  {t="Elixir of Agony with a group", lv=30, n="Lydon's next errand is a keg of Shindigger Stout from the cellar of Dun Garok, the elite dwarven keep south-east of Southshore: take it only if you go there with a group.", w={{k="group",q=517},{k="turnedin",q=515}}, g={{"a",517,n2="Apothecary Lydon, inside",m=1424,x=61.4,y=19.1,ml=24}}},
  {t="Battle of Hillsbrad with a group", lv=30, n="Darthalia's last battle is at Dun Garok, the dwarven keep south-east of Southshore: every dwarf there is elite (28-32), Captain Ironhill too. Great XP if you have a group for it.", w={{k="group",q=541}}, g={{"a",541,m=1424,x=62.3,y=20.4,ml=19}}},
  {t="Humbert's Sword with a group", lv=30, n="Deathguard Humbert's sword drops from the same Dun Garok dwarves (about one in twelve).", w={{k="group",q=547}}, g={{"a",547,m=1424,x=62.8,y=20.2,ml=26}}},
  {t="Dun Garok", lv=30, n="Clear Dun Garok from the gate in; the dwarves run for help at 30% health.", w={{k="onquest",q={541,547}}}, g={{"o",541,i=1,txt="Kill Dun Garok Mountaineer x10",m=1424,x=71.2,y=79,grp=true},{"o",541,i=2,txt="Kill Dun Garok Rifleman x8",m=1424,x=71,y=78.3,grp=true},{"o",541,i=3,txt="Kill Dun Garok Priest x4",m=1424,x=71.6,y=79.2,grp=true},{"o",541,i=4,txt="Kill Captain Ironhill",m=1424,x=72.2,y=79.8,grp=true},{"o",547,i=1,txt="Humbert's Sword",m=1424,x=71.2,y=79,grp=true}}},
  {t="Tarren Mill", lv=30, w={{k="onquest",q={541}}}, g={{"t",541,m=1424,x=62.3,y=20.4},{"a",550,n2="for Varimathras in the Undercity, at the end of this guide",m=1424,x=62.3,y=20.4,ml=19}}},
  {t="Deathguard Humbert", lv=30, w={{k="onquest",q={547}}}, g={{"t",547,m=1424,x=62.8,y=20.2}}},
  {t="Shindigger keg", lv=30, n="The Kegs of Shindigger Stout stand in the cellar of Dun Garok, the dwarven keep south-east of Southshore, beside Captain Ironhill (32); every dwarf there is elite (28-32).", w={{k="onquest",q={517}}}, g={{"o",517,i=1,txt="Keg of Shindigger Stout",n2="Below ground",m=1424,x=72,y=80.5}}},
  {t="Back to Tarren Mill", lv=30, n="Head back north to Tarren Mill.", w={{k="onquest",q={517}}}, g={{"t",517,n2="Apothecary Lydon, inside",m=1424,x=61.4,y=19.1},{"a",524,m=1424,x=61.4,y=19.1,ml=24},{"t",524,n2="Place the Tainted Keg on the Dusty Rug beside the inn; upstairs",m=1424,x=62.8,y=18.7}}},
  {t="Arathi Highlands", lv=30, g={{"g",0,txt="Boulderfist camp",m=1417,x=32.6,y=40.4}}},
  {t="Boulderfist camp", lv=30, n="Head east out of Tarren Mill through Thoradin's Wall and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south of Northfold Manor; the Enforcers stay in the cave there.", g={{"o",676,i=1,txt="Kill Boulderfist Ogre x8",m=1417,x=33.1,y=40.8},{"o",676,i=2,txt="Kill Boulderfist Enforcer x10",n2="Below ground",m=1417,x=32.8,y=43.1}}},
  {t="Level 31", lv=31, n="Hammerfall's quests are 32-36. Below 31? Keep killing the Boulderfist Ogres and Enforcers at this camp until level 31. Or, with a group, run the Scarlet Monastery dungeon (Graveyard) or the Blackfathom Deeps dungeon instead.", w={{k="level",op="<",n=31}}, g={{"g",0,txt="Boulderfist camp",m=1417,x=31.2,y=48},{"l",31,txt="Reach level 31: grind Boulderfist Ogre",n2="grind on Boulderfist Ogre",m=1417,x=31.2,y=48}}},
  {t="Hammerfall", lv=31, n="The orc stronghold at the eastern end of the road. Urda, the wind rider master, stands by the gate.\nRutherford Twing offers the Defiler's Basic Care Package only once you are Friendly with the Defilers (Arathi Basin): skip it if he doesn't offer it.", g={{"a",655,n2="Gor'mul, by the gate",m=1417,x=72.6,y=33.9,ml=29},{"fp",17,txt="Get the Hammerfall flight path (Urda)",m=1417,x=73,y=32.7},{"t",8263,m=1417,x=73.4,y=29.7,opt=true},{"t",676,m=1417,x=74.2,y=33.9},{"a",677,m=1417,x=74.2,y=33.9,ml=30},{"t",655,m=1417,x=74.7,y=36.3},{"a",672,m=1417,x=74.7,y=36.3,ml=29},{"a",671,n2="Tor'gan: its Syndicate are by the road in from Tarren Mill, on the 38-39 visit",m=1417,x=74.7,y=36.3,ml=30},{"a",97539,m=1417,x=73.4,y=36.9,ml=30}}},
  {t="Witherbark Village", lv=31, n="South of Hammerfall, the Witherbark trolls hold the village in the hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village. Careful: All three troll types flee for help at 15% health, which can pull more trolls from the nearby camps.", g={{"o",677,i=2,txt="Kill Witherbark Headhunter x10",m=1417,x=72.3,y=63.7},{"o",677,i=1,txt="Kill Witherbark Axe Thrower x10",m=1417,x=73,y=64.8},{"o",677,i=3,txt="Kill Witherbark Witch Doctor x8",m=1417,x=73.7,y=64.6}}},
  {t="Highland raptors and Plains Creepers", lv=31, n="On the way back north, Highland Striders roam the hills all around Hammerfall and drop the eyes, and south of it the Plains Creepers (32-33) spin their webs in the grass; they carry the spidersilk.", g={{"o",672,i=1,txt="Highland Raptor Eye x10",m=1417,x=67.1,y=56.3},{"o",97539,i=1,txt="Surgical Spidersilk x12",n2="Surgical Spidersilk, from Plains Creepers",m=1417,x=69.5,y=50.5}}},
  {t="Hammerfall", lv=31, n="Back north to Hammerfall.", g={{"t",97539,n2="Doctor Gregory Victor, at the south gate",m=1417,x=73.4,y=36.9},{"t",672,m=1417,x=74.7,y=36.3},{"a",674,m=1417,x=74.7,y=36.3,ml=29},{"t",677,m=1417,x=74.2,y=33.9},{"t",674,m=1417,x=72.6,y=33.9},{"a",675,m=1417,x=72.6,y=33.9,ml=29},{"t",675,m=1417,x=74.7,y=36.3},{"i",0,txt="Tor'gan's Guile of the Raptor, Drum Fel's next Call to Arms and the doctor's Ward Restocking wait for the 38-39 visit."}}},
  {t="Fly to Undercity", lv=31, g={{"g",0,txt="Hammerfall flight master",m=1417,x=73.1,y=32.7},{"z",0,txt="Fly to Undercity",at="Undercity"}}},
  {t="Varimathras", lv=31, n="Varimathras stands beside Sylvanas in the Royal Quarter.", w={{k="onquest",q={550}}}, g={{"t",550,n2="Varimathras: Darthalia's commendation",m=1458,x=56.2,y=92.2}}},
  {t="Undercity trainers", lv=31, n="Train while you are in the Undercity: the trainers stand in the War Quarter, the Rogues' Quarter and the Magic Quarter (Paladins: Garen Largo).", f={c={"WARRIOR","PALADIN","ROGUE","PRIEST","MAGE","WARLOCK"}}, g={{"tr",0,txt="Visit your class trainer"}}},
} end)

R:Segment({id="horde/30-40/02-thousand-needles",title="Thousand Needles & Desolace",faction="Horde",min=32,max=34,zone=1441,zoneName="Thousand Needles",next="horde/30-40/03-stranglethorn-vale"}, function() return {
  {t="Zeppelin to Orgrimmar", lv=32, g={{"g",0,txt="Zeppelin to Orgrimmar",m=1420,x=60.7,y=58.8}}},
  {t="Alliance Relations", lv=32, n="The zeppelin lands at the tower outside Orgrimmar's main gate. Craven Drok walks the Drag: if he isn't at the arrow, look along its streets to the south-west. Keldran stands in the Valley of Spirits on the west side of the city.", g={{"a",1431,n2="Craven Drok: offered from level 30",m=1454,x=51.3,y=45.9,ml=30},{"t",1431,m=1454,x=22.6,y=52.6},{"a",1432,n2="for Takata Steelblade in Desolace, later in this guide",m=1454,x=22.6,y=52.6,ml=30}}},
  {t="Orgrimmar trainers", lv=32, n="Train while you are in the city.", f={c={"HUNTER","SHAMAN"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Searn Firewarder", lv=32, n="Searn Firewarder stands in the Valley of Wisdom.", f={c={"SHAMAN"}}, g={{"a",1531,n2="Searn Firewarder: for Prate Cloudseer by Freewind Post, later in this guide",m=1454,x=38,y=37.7,ml=30}}},
  {t="Nogg", lv=32, n="Nogg's workshop is in the Valley of Honor. Rig Wars is Gnomeregan's last boss: great XP if you run it with a group. Run it whenever your group is ready; hand it in on a later Orgrimmar stop.", w={{k="dungeon",name="Gnomeregan",map=90}}, g={{"a",2841,m=1454,x=76,y=25.4,grp=true,ml=25}}},
  {t="Gnomeregan", lv=32, w={{k="dungeon",name="Gnomeregan",map=90}}, g={{"i",0,txt="Run Gnomeregan with a group when it suits you: Mekgineer Thermaplugg at the end drops his Safe Combination; open his safe behind the northern bomb pillar for the Rig Blueprints."}}},
  {t="Orgrimmar flight master", lv=32, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7}}},
  {t="Thunder Bluff", lv=32, n="Fly from Orgrimmar to Thunder Bluff and train with Turak Runetotem on Elder Rise; fly on to Freewind Post from there.", f={c={"DRUID"}}, g={{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"},{"tr",0,txt="Visit your class trainer"}}},
  {t="Islen Waterseer", lv=32, n="Fly from Orgrimmar to Ratchet. Islen Waterseer camps on the coast a short walk south of the town; fly on to Freewind Post from Ratchet.", f={c={"SHAMAN"}}, g={{"z",0,txt="Fly to Ratchet",at="Ratchet"},{"t",96,n2="Islen Waterseer: Healing Stream Totem and your Water Totem",m=1413,x=65.8,y=43.8}}},
  {t="Fly to Freewind Post", lv=32, f={c={"DRUID"}}, g={{"g",0,txt="Thunder Bluff flight master",m=1456,x=46.7,y=49.9},{"z",0,txt="Fly to Freewind Post",at="Freewind Post"}}},
  {t="Fly to Freewind Post", lv=32, f={c={"SHAMAN"}}, g={{"g",0,txt="Ratchet flight master",m=1413,x=63.1,y=37.1},{"z",0,txt="Fly to Freewind Post",at="Freewind Post"}}},
  {t="Fly to Freewind Post", lv=32, f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","MAGE","WARLOCK"}}, g={{"z",0,txt="Fly to Freewind Post",at="Freewind Post"}}},
  {t="Prate Cloudseer", lv=32, n="Prate Cloudseer hides in a small cave in the canyon wall north-east of the post, on the way east.", f={c={"SHAMAN"}}, g={{"t",1531,n2="Prate Cloudseer: your Air Totem",m=1441,x=53.5,y=42.6},{"i",0,txt="Prate also starts Elemental Aid (Razorfen Kraul), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."}}},
  {t="Moktar Krin", lv=32, n="Take the lift down and follow the canyon east. Moktar Krin camps on the north-western edge of the salt flats.", g={{"t",1146,m=1441,x=67.6,y=63.9},{"a",1147,m=1441,x=67.6,y=63.9,ml=29}}},
  {t="Mirage Raceway", lv=32, n="The goblins and gnomes of the Mirage Raceway are neutral and give quests to both factions.", g={{"a",1110,m=1441,x=77.8,y=77.3,ml=28},{"a",5762,n2="Kravel's crate for Hemet Nesingwary in Stranglethorn, later on the route",m=1441,x=77.8,y=77.3,ml=28},{"a",1104,m=1441,x=78.1,y=77.1,ml=28},{"a",1105,m=1441,x=78.1,y=77.1,ml=28},{"a",1176,m=1441,x=80.2,y=75.9,ml=29},{"a",1175,m=1441,x=81.6,y=78,ml=28}}},
  {t="The southern flats", lv=32, n="South of the raceway, the Saltstone Crystalhides (32-33) and Gazers (34-35) roam the far end of the flats.", g={{"o",1175,i=2,txt="Kill Saltstone Crystalhide x10",m=1441,x=78.4,y=87.9},{"o",1175,i=3,txt="Kill Saltstone Gazer x6",m=1441,x=77.1,y=88.4}}},
  {t="The Rustmaul Dig Site", lv=32, n="West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a Cracked Silithid Carapace: open it.\nCareful: Hive Drones call for help when they fall to 20% health.", g={{"o",1147,i=1,txt="Kill Silithid Searcher x5",m=1441,x=69.8,y=83.3},{"o",1147,i=2,txt="Kill Silithid Hive Drone x5",m=1441,x=68,y=85.7},{"o",1147,i=3,txt="Kill Silithid Invader x5",m=1441,x=64.8,y=86},{"h",5877,txt="Get Cracked Silithid Carapace",m=1441,x=64.5,y=85.8,n=1},{"a",1148,ml=28}}},
  {t="Parts of the Swarm", lv=32, n="Keep killing silithid at the dig site for the heart, the talons and the carapaces.", g={{"o",1148,i=1,txt="Silithid Heart",m=1441,x=64.5,y=85.8},{"o",1148,i=2,txt="Silithid Talon x5",m=1441,x=64.5,y=85.8},{"o",1148,i=3,txt="Intact Silithid Carapace x3",m=1441,x=64.5,y=85.8}}},
  {t="Moktar Krin", lv=32, n="North from the dig to Moktar Krin's camp on the western edge of the flats.", g={{"t",1147,m=1441,x=67.6,y=63.9}}},
  {t="Shimmering Flats: kill these as you meet them", lv=32, n="East onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it; the Sparkleshell tortoises crowd round a half-buried ship in the north-east, and the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low; the Snappers (34-35) hit hardest of the tortoises.", g={{"o",1175,i=1,txt="Kill Saltstone Basilisk x10",m=1441,x=75.7,y=57.3},{"o",1105,i=1,txt="Hardened Tortoise Shell x9",m=1441,x=82.1,y=55},{"o",1176,i=1,txt="Hollow Vulture Bone x10",m=1441,x=87.9,y=65.4},{"o",1110,i=1,txt="Rocket Car Parts x30",n2="Rocket Car Rubble, all over the northern flats",m=1441,x=88.9,y=66.5},{"o",1104,i=1,txt="Salty Scorpid Venom x6",n2="Salt Flat Venom, from the Scorpid Reavers of the north half",m=1441,x=88.2,y=69}}},
  {t="Mirage Raceway", lv=32, n="South-west back to the raceway.", g={{"t",1110,m=1441,x=77.8,y=77.3},{"a",1111,n2="Kravel Koalbeard: his parts order goes to Wharfmaster Dizzywig in Ratchet, later on the route",m=1441,x=77.8,y=77.3,ml=30},{"t",1104,m=1441,x=78.1,y=77.1},{"t",1105,m=1441,x=78.1,y=77.1},{"a",1106,n2="Fizzle Brassbolts: his letter goes to Martek in the Badlands, at 39",m=1441,x=78.1,y=77.1,ml=26},{"t",1176,m=1441,x=80.2,y=75.9},{"a",1178,n2="Pozzik: for Gazlowe in Ratchet, later on the route",m=1441,x=80.2,y=75.9,ml=29},{"t",1175,m=1441,x=81.6,y=78}}},
  {t="Level 32.5", lv=32, n="Desolace's quests are 33-38. Still below 32.5 after the raceway's hand-ins? Keep killing the Sparkleshell Snappers on the flats just north of the raceway until level 32.5. Or, with a group, run the Scarlet Monastery dungeon (Graveyard or Library) instead.", w={{k="level",op="<",n=32,frac=0.5}}, g={{"g",0,txt="Sparkleshell Snappers",m=1441,x=77.5,y=70.5},{"l",32,txt="Reach level 32 (50% in): grind Sparkleshell Snapper",n2="grind on Sparkleshell Snapper",m=1441,x=77.2,y=70.9,fr=0.5}}},
  {t="Freewind Post", lv=32, n="West back to Freewind Post. Cliffwatcher Longhorn stands in the middle of the post, on the way to the flight master.", g={{"a",5361,n2="Cliffwatcher Longhorn: for Nataka Longhorn in Desolace, next",m=1441,x=45.7,y=50.7,ml=32},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Fly to Sun Rock Retreat", lv=32, g={{"g",0,txt="Freewind Post flight master",m=1441,x=45,y=49.1},{"z",0,txt="Fly to Sun Rock Retreat",at="Sun Rock Retreat"}}},
  {t="Desolace", lv=32, g={{"g",0,txt="Scrabblescrew's Camp",m=1443,x=60.9,y=61.9}}},
  {t="Scrabblescrew's Camp", lv=32, n="Head south out of Stonetalon into Desolace and follow the road south to Smeed's camp.", g={{"a",5561,m=1443,x=60.9,y=61.9,ml=30}}},
  {t="Ghost Walker Post", lv=32, n="Felgur stands in the post, Nataka Longhorn up on its rise; Takata Steelblade and Maurin Bonesplitter wait on the rise west of it, above the Kodo Graveyard.", g={{"a",1365,m=1443,x=56.2,y=59.6,ml=30},{"t",5361,n2="Nataka Longhorn, up on the rise",m=1443,x=55.4,y=55.8},{"t",1432,m=1443,x=52.6,y=54.4},{"a",1433,m=1443,x=52.6,y=54.4,ml=30},{"a",1434,m=1443,x=52.6,y=54.4,ml=25},{"t",1433,m=1443,x=52.2,y=53.4},{"a",1435,m=1443,x=52.2,y=53.4,ml=25}}},
  {t="Kodo Graveyard", lv=32, n="Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo in the graveyard and walk the tamed kodo back to Smeed. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time.", g={{"i",0,txt="Use Kodo Kombobulator",n2="on an Aged, Dying or Ancient Kodo in the graveyard; don't kill it",m=1443,x=51,y=58.5},{"o",5561,i=1,txt="Talk to Aged Kodo",n2="the tamed kodo, at Smeed's camp: talk to it, five times",m=1443,x=60.6,y=61.6}}},
  {t="Scrabblescrew's Camp", lv=32, g={{"t",5561,m=1443,x=60.9,y=61.9}}},
  {t="Level 33", lv=33, n="Shadowprey's Hand of Iruxos and the coast's naga want 33. Below that? The Scorpashi Lashers on the slopes north of Smeed's camp are on your way west: kill them until level 33. Or, with a group, run the Scarlet Monastery dungeon (Library) instead.", w={{k="level",op="<",n=33}}, g={{"g",0,txt="Scorpashi Lashers",m=1443,x=59.9,y=54.6},{"l",33,txt="Reach level 33: grind Scorpashi Lasher",n2="grind on Scorpashi Lasher",m=1443,x=60.8,y=54.5}}},
  {t="Shadowprey Village", lv=33, n="Head west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.\nAka'rai may not be here on Forever: if Aka'rai doesn't offer Hate the Hatefury, skip it.", g={{"a",97265,n2="Aka'rai: the Hatefury satyrs of Sargeron, later in this guide",m=1443,x=25.4,y=67.2,opt=true,ml=28},{"a",5381,m=1443,x=25.8,y=68.2,ml=32},{"b",0,txt="Set your hearthstone at Shadowprey Village",m=1443,x=24.1,y=68.2,at="Shadowprey Village"},{"a",5763,n2="Roon Wildmane: for Hemet Nesingwary in Stranglethorn, next guide",m=1443,x=25.1,y=72.3,ml=28},{"a",6143,m=1443,x=23.3,y=72.9,ml=32},{"a",6142,m=1443,x=22.6,y=72,ml=31},{"fp",38,txt="Get the Shadowprey Village flight path (Thalon)",n2="Thalon, at the village's south-west end",m=1443,x=21.6,y=74.1}}},
  {t="Ethel Rethor", lv=33, n="Head north along the coast, then inland to the ruined tower of Ethel Rethor: Azore Aldamort waits inside. The coast's clams and naga come after Thunder Axe Fortress, on one walk north to Ranazjar Isle.", g={{"a",5741,m=1443,x=38.9,y=27.2,ml=30}}},
  {t="Thunder Axe Fortress", lv=33, n="Head east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it. Hand of Iruxos: clear the middle of the largest building, then use the Demon Pick on the red Hand of Iruxos Crystal there. A Demon Spirit (37) comes out: kill it for the Demon Box.", g={{"o",1435,i=1,txt="Infused Burning Gem x15",m=1443,x=55,y=26.5},{"o",5741,i=1,txt="Sceptre of Light",n2="On the top floor",m=1443,x=55.2,y=30.1},{"o",5381,i=1,txt="Use Demon Pick",n2="Demon Pick, on the Hand of Iruxos Crystal",m=1443,x=55,y=26.7},{"o",5381,i=1,txt="Demon Box",m=1443,x=55,y=26.6},{"h",20310,txt="Get Flayed Demon Skin",m=1443,x=55,y=26.2,n=1,opt=true},{"a",1480,opt=true,ml=25}}},
  {t="Ethel Rethor", lv=33, n="Back west to Azore.", g={{"t",5741,m=1443,x=38.9,y=27.2},{"a",6027,m=1443,x=38.9,y=27.2,ml=30}}},
  {t="Rackmore's Log", lv=33, n="Rackmore's Log lies on the ground just south-west of Azore's tower, on the way down to the shore: read it. Its two keys drop only while you have the quest.", g={{"a",6161,m=1443,x=36.1,y=30.4,ml=30}}},
  {t="Clam beds", lv=33, n="West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a Soft-shelled Clam. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry Rackmore's Silver Key, about one in seven.", g={{"o",6142,i=1,txt="Giant Softshell Clam",n2="Giant Softshell Clams, on the sea floor",m=1443,x=30.6,y=31.9},{"o",6142,i=1,txt="Use Soft-shelled Clam",n2="Soft-shelled Clam: open it in your bags",m=1443,x=30.6,y=31.9},{"o",6142,i=1,txt="Soft-shelled Clam Meat x10",n2="Underwater",m=1443,x=30.5,y=31.9},{"o",6161,i=1,txt="Rackmore's Silver Key",n2="Rackmore's Silver Key, from the Drysnap crabs",m=1443,x=33.4,y=30.1}}},
  {t="Sar'theris Strand", lv=33, n="Keep north to Sar'theris Strand. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time. Any Slitherblade can drop Rackmore's Golden Key.", g={{"o",6143,i=1,txt="Kill Slitherblade Myrmidon x7",m=1443,x=32.2,y=23.4},{"o",6143,i=2,txt="Kill Slitherblade Naga x7",m=1443,x=32.7,y=23.9},{"o",6143,i=3,txt="Kill Slitherblade Sorceress x5",m=1443,x=32.9,y=23.3},{"o",6161,i=2,txt="Rackmore's Golden Key",n2="Rackmore's Golden Key, from the Slitherblade naga",m=1443,x=42.2,y=19}}},
  {t="The Book of the Ancients", lv=33, n="Swim out to Ranazjar Isle off the far northern tip and use the Gem of the Serpent on the Serpent Statue: Lord Kragaru (38) rises; kill him for the Book of the Ancients. He is well above you: rest to full first. Rackmore's Chest stands on the shore beside the statue: open it with both keys.", g={{"o",6027,i=1,txt="Use Gem of the Serpent",n2="Gem of the Serpent, on the Serpent Statue",m=1443,x=28.2,y=6.7},{"o",6027,i=1,txt="Book of the Ancients",m=1443,x=28.2,y=6.7},{"t",6161,m=1443,x=30,y=8.7}}},
  {t="Azore Aldamort", lv=33, n="Back south to Azore's tower.", g={{"t",6027,m=1443,x=38.9,y=27.2}}},
  {t="Sargeron", lv=33, n="Head east past Thunder Axe Fortress and along the northern hills to the satyrs' ruins of Sargeron. Kill every kind you meet for Aka'rai; the Shadowstalkers walk unseen.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them.", g={{"o",1434,i=1,txt="Kill Hatefury Rogue x7",m=1443,x=70.9,y=16.6},{"o",1434,i=2,txt="Kill Hatefury Felsworn x7",m=1443,x=71.5,y=20.1},{"o",1434,i=3,txt="Kill Hatefury Betrayer x7",m=1443,x=72.2,y=18.9},{"o",1434,i=4,txt="Kill Hatefury Hellcaller x7",m=1443,x=72.3,y=19.2},{"o",97265,i=3,txt="Kill Hatefury Shadowstalker x2",m=1443,x=75.7,y=15.8,opt=true},{"o",97265,i=2,txt="Kill Hatefury Hellcaller x2",m=1443,x=75.1,y=16.4,opt=true},{"o",97265,i=1,txt="Kill Hatefury Trickster x2",n2="Hatefury Trickster, on the way south",m=1443,x=76.5,y=20.5,opt=true},{"o",97265,i=4,txt="Kill Hatefury Felsworn x2",m=1443,x=75.3,y=19.3,opt=true},{"o",97265,i=5,txt="Kill Hatefury Rogue x2",m=1443,x=73.5,y=19.1,opt=true}}},
  {t="Khan Dez'hepah", lv=33, n="South to Kolkar Village. Khan Dez'hepah (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health.\nCareful: Kolkar Battle Lords call nearby allies within 30 yd once they fall to 20% health.", g={{"o",1365,i=1,txt="Khan Dez'hepah's Head",m=1443,x=73.2,y=41.8}}},
  {t="Ghost Walker Post", lv=33, n="South-west down the road to the post.", g={{"t",1434,m=1443,x=52.6,y=54.4},{"t",1435,m=1443,x=52.2,y=53.4},{"t",1480,m=1443,x=52.2,y=53.4,opt=true},{"a",1436,n2="Takata Steelblade: for Keldran in Orgrimmar, next guide",m=1443,x=52.6,y=54.4,ml=30},{"i",0,txt="Takata's next errand sends you after a demon lord with an elite guard: skip it."},{"t",1365,m=1443,x=56.2,y=59.6},{"a",1366,n2="for the second Desolace visit, in forever/horde/30-40/04-dustwallow-marsh",m=1443,x=56.2,y=59.6,ml=30}}},
  {t="Shadowprey Village", lv=33, n="West to Shadowprey: your hearthstone is bound there.", g={{"t",97265,n2="Aka'rai, on the path just north of the village",m=1443,x=25.4,y=67.2,opt=true},{"t",5381,m=1443,x=25.8,y=68.2},{"t",6142,m=1443,x=22.6,y=72},{"t",6143,m=1443,x=23.3,y=72.9},{"i",0,txt="Taiga's Portals of the Legion and Desolace's other 38-40 quests wait for the second visit, at 38: the next guides fly to Orgrimmar and take the zeppelin to Stranglethorn Vale."}}},
} end)

R:Segment({id="horde/30-40/03-stranglethorn-vale",title="Stranglethorn Vale",faction="Horde",min=34,max=36,zone=1434,zoneName="Stranglethorn Vale",next="horde/30-40/04-dustwallow-marsh"}, function() return {
  {t="Fly to Orgrimmar", lv=34, f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"g",0,txt="Shadowprey Village flight master",m=1443,x=21.6,y=74},{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"}}},
  {t="Thunder Bluff", lv=34, n="Fly from Shadowprey Village to Thunder Bluff and train with Turak Runetotem on Elder Rise; fly on to Orgrimmar from there.", f={c={"DRUID"}}, g={{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"},{"tr",0,txt="Visit your class trainer"}}},
  {t="Back to Orgrimmar", lv=34, f={c={"DRUID"}}, g={{"g",0,txt="Thunder Bluff flight master",m=1456,x=46.7,y=49.9},{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"}}},
  {t="Keldran", lv=34, n="Keldran stands in the Valley of Spirits on the west side of the city.", g={{"t",1436,m=1454,x=22.6,y=52.6}}},
  {t="Orgrimmar trainers", lv=34, n="Train while you are in the city.", f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Fly to Ratchet", lv=34, n="Booty Bay first: the goblins' boat sails there from Ratchet, and every Booty Bay quest is for the north of the vale, which you then walk up into.", g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Ratchet",at="Ratchet"}}},
  {t="Ratchet", lv=34, n="Gazlowe waits upstairs in the house by the flight master; Wharfmaster Dizzywig stands on the docks, beside the boat.", g={{"t",1178,n2="Gazlowe, upstairs",m=1413,x=62.7,y=36.2},{"a",1180,n2="Gazlowe: for Wharfmaster Lozgil in Booty Bay, where the boat goes",m=1413,x=62.7,y=36.2,ml=29},{"t",1111,n2="Wharfmaster Dizzywig, on the docks",m=1413,x=63.4,y=38.5},{"i",0,txt="Dizzywig's parts go back to Kravel in the Shimmering Flats, off the route: leave them."}}},
  {t="Boat to Booty Bay", lv=34, g={{"g",0,txt="Boat to Booty Bay",m=1413,x=63.4,y=38.5}}},
  {t="Booty Bay", lv=34, n="Wharfmaster Lozgil stands on the pier where the boat docks. Drizzlik's shop is in the building east of the inn; Crank Fizzlebub is on the inn's bottom floor, Baron Revilgaz, Kebok and Krazek upstairs, Gringer the flight master on the upper deck.", g={{"t",1180,n2="Wharfmaster Lozgil, on the pier",m=1434,x=26.4,y=73.6},{"a",1181,m=1434,x=26.4,y=73.6,ml=29},{"a",575,n2="Drizzlik, inside",m=1434,x=28.3,y=77.6,ml=26},{"i",0,txt="Sell and repair",opt=true},{"a",605,n2="Crank Fizzlebub, inside, on the bottom floor",m=1434,x=27.1,y=77.2,ml=30},{"t",1181,n2="Baron Revilgaz, upstairs",m=1434,x=27.2,y=76.9},{"a",1182,n2="Baron Revilgaz: Cozzle's footlocker is at Lake Nazferiti, later in this guide",m=1434,x=27.2,y=76.9,ml=29},{"a",213,n2="Kebok, upstairs",m=1434,x=27,y=77.1,ml=31},{"a",189,m=1434,x=27,y=77.1,ml=30},{"a",201,n2="Krazek, upstairs",m=1434,x=26.9,y=77.2,ml=28},{"fp",18,txt="Get the Booty Bay flight path (Gringer)",m=1434,x=26.9,y=77.1}}},
  {t="Grom'gol", lv=34, n="Leave Booty Bay through the tunnel and follow the road north to Grom'gol, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level.", g={{"a",568,m=1434,x=32.2,y=28.9,ml=33},{"a",638,n2="Nimboya: for Arathi, later on the route",m=1434,x=32.2,y=27.7,ml=32},{"a",581,m=1434,x=32.2,y=27.7,ml=30},{"a",629,m=1434,x=32.3,y=27.7,ml=30},{"a",596,m=1434,x=32.3,y=27.7,ml=30},{"fp",20,txt="Get the Grom'gol flight path (Thysta)",m=1434,x=32.5,y=29.4}}},
  {t="Nesingwary's camp", lv=34, n="Follow the road north out of Grom'gol; Nesingwary's hunting camp sits on the hill north-east of the river. Krazek wants it investigated: walk among its tents. From here on, keep every page of The Green Hills of Stranglethorn you loot: Barnil takes them on your next Stranglethorn visit.", g={{"a",583,m=1434,x=35.7,y=10.5,ml=28},{"t",583,m=1434,x=35.7,y=10.8},{"t",5762,m=1434,x=35.7,y=10.8},{"t",5763,m=1434,x=35.7,y=10.8},{"a",194,m=1434,x=35.7,y=10.8,ml=28},{"a",185,m=1434,x=35.6,y=10.6,ml=28},{"a",190,m=1434,x=35.5,y=10.6,ml=28},{"c",201,txt="Locate the hunters' camp",m=1434,x=35.6,y=10.6}}},
  {t="Nesingwary's Expedition: kill these as you meet them", lv=34, n="River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A Pendant of Myzrael is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight.", g={{"o",575,i=1,txt="Large River Crocolisk Skin x2",m=1434,x=34.6,y=10.5},{"o",185,i=1,txt="Kill Young Stranglethorn Tiger x10",m=1434,x=34.1,y=11.3},{"o",190,i=1,txt="Kill Young Panther x10",m=1434,x=35,y=14.2},{"o",581,i=1,txt="Bloodscalp Tusk x9",m=1434,x=34.3,y=14.6},{"h",4614,txt="Get Pendant of Myzrael",m=1434,x=34.7,y=21.9,n=1,opt=true},{"a",635,opt=true,ml=30}}},
  {t="Nesingwary's camp", lv=34, g={{"t",185,m=1434,x=35.6,y=10.6},{"a",186,m=1434,x=35.6,y=10.6,ml=28},{"t",190,m=1434,x=35.5,y=10.6},{"a",191,m=1434,x=35.5,y=10.6,ml=28}}},
  {t="Stranglethorn Vale: kill these as you meet them", lv=34, n="Stranglethorn Tigers (32) roam the hills around the camp and south of it, Panthers (32) the clearings west and south-west of it. The Venture Co. Geologists, who carry the Tumbled Crystals, work the camps by Lake Nazferiti, south-east of the camp.", g={{"o",186,i=1,txt="Kill Stranglethorn Tiger x10",m=1434,x=36.4,y=13.8},{"o",213,i=1,txt="Tumbled Crystal x8",m=1434,x=42.7,y=18.3},{"o",191,i=1,txt="Kill Panther x10",m=1434,x=30.4,y=11.3}}},
  {t="Cozzle's Footlocker", lv=34, n="Foreman Cozzle (38) is inside the Venture Co. house on Lake Nazferiti's west shore, among the geologists: his key opens Cozzle's Footlocker in the same house, which holds the blueprints for Baron Revilgaz.", g={{"h",5851,txt="Get Cozzle's Key",n2="from Foreman Cozzle",m=1434,x=42.6,y=18.4,n=1},{"o",1182,i=1,txt="Fuel Regulator Blueprints",n2="Fuel Regulator Blueprints, in Cozzle's Footlocker",m=1434,x=43.3,y=20.3}}},
  {t="Nesingwary's camp", lv=34, g={{"t",191,m=1434,x=35.5,y=10.6},{"a",192,n2="The Shadowmaw Panthers come much later, by Grom'gol",m=1434,x=35.5,y=10.6,ml=28},{"t",186,m=1434,x=35.6,y=10.6},{"a",187,m=1434,x=35.6,y=10.6,ml=28},{"a",338,m=1434,x=35.7,y=10.5,opt=true,ml=30},{"a",339,m=1434,x=35.7,y=10.5,opt=true,ml=30},{"a",340,m=1434,x=35.7,y=10.5,opt=true,ml=30},{"a",341,m=1434,x=35.7,y=10.5,opt=true,ml=30},{"a",342,m=1434,x=35.7,y=10.5,opt=true,ml=30}}},
  {t="Elder Stranglethorn Tigers", lv=34, n="The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp. Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.", g={{"o",187,i=1,txt="Kill Elder Stranglethorn Tiger x10",m=1434,x=34,y=17.6}}},
  {t="Nesingwary's camp", lv=34, n="Back north to the camp.", g={{"t",187,m=1434,x=35.6,y=10.6},{"a",188,m=1434,x=35.6,y=10.6,ml=28}}},
  {t="The Savage Coast: kill these as you meet them", lv=34, n="West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\nSin'Dall, a level 37 tiger, prowls the hilltop south-west of the camp.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults.", g={{"o",605,i=1,txt="Singing Crystal Shard x10",m=1434,x=36.6,y=8.3},{"o",189,i=1,txt="Bloodscalp Ear x15",m=1434,x=34.3,y=14.6},{"o",194,i=1,txt="Kill Stranglethorn Raptor x10",m=1434,x=27.8,y=14.3},{"o",188,i=1,txt="Paw of Sin'Dall",m=1434,x=31.8,y=16.4}}},
  {t="Nesingwary's camp", lv=34, g={{"t",194,m=1434,x=35.7,y=10.8},{"a",195,m=1434,x=35.7,y=10.8,ml=28},{"t",188,m=1434,x=35.6,y=10.6}}},
  {t="Lashtail Raptors", lv=34, n="On your way back south to Grom'gol, the Lashtail Raptors (35-36) hunt the jungle between the camp and Grom'gol: they count for Hemet and for Commander Aggro'gosh.", g={{"o",195,i=1,txt="Kill Lashtail Raptor x10",m=1434,x=32.4,y=23.2},{"o",568,i=1,txt="Kill Lashtail Raptor x15",m=1434,x=32.4,y=23.2}}},
  {t="Grom'gol", lv=34, n="Commander Aggro'gosh stands in the middle of Grom'gol, Nimboya near the zeppelin tower, Far Seer Mok'thardin beside the flight master.", g={{"t",568,m=1434,x=32.2,y=28.9},{"a",569,m=1434,x=32.2,y=28.9,ml=33},{"t",581,m=1434,x=32.2,y=27.7},{"a",582,m=1434,x=32.2,y=27.7,ml=30},{"a",570,n2="Far Seer Mok'thardin: the Shadowmaw claws and the tigress fang come at the end of this guide",m=1434,x=32.1,y=29.2,ml=33}}},
  {t="Level 35", lv=35, n="Booty Bay's and Grom'gol's next quests are 35-38. Still below 35 after Aggro'gosh's hand-in? The Lashtail Raptors (35) hunt the jungle just north of Grom'gol: kill them until level 35. Or, with a group, run the Scarlet Monastery dungeon (Library or Armory) instead.", w={{k="level",op="<",n=35}}, g={{"g",0,txt="Lashtail Raptors",m=1434,x=32.4,y=24.6},{"l",35,txt="Reach level 35: grind Lashtail Raptor",n2="grind on Lashtail Raptor",m=1434,x=32.4,y=24.6}}},
  {t="Fly to Booty Bay", lv=35, g={{"g",0,txt="Grom'gol flight master",m=1434,x=32.5,y=29.3},{"z",0,txt="Fly to Booty Bay",at="Booty Bay"}}},
  {t="Booty Bay", lv=35, n="Drizzlik's shop is in the building east of the inn; Crank Fizzlebub is on the inn's bottom floor, Baron Revilgaz, Kebok and Krazek upstairs beside the flight master.", g={{"t",575,n2="Drizzlik, inside",m=1434,x=28.3,y=77.6},{"a",577,m=1434,x=28.3,y=77.6,ml=31},{"t",605,n2="Crank Fizzlebub, inside",m=1434,x=27.1,y=77.2},{"t",1182,n2="Baron Revilgaz, upstairs",m=1434,x=27.2,y=76.9},{"a",1183,n2="Baron Revilgaz: for Pozzik at the Mirage Raceway, on the way to Tanaris around level 43",m=1434,x=27.2,y=76.9,ml=29},{"t",213,n2="Kebok, upstairs",m=1434,x=27,y=77.1},{"t",189,m=1434,x=27,y=77.1},{"t",201,n2="Krazek, upstairs",m=1434,x=26.9,y=77.2}}},
  {t="Fly to Grom'gol", lv=35, g={{"g",0,txt="Booty Bay flight master",m=1434,x=26.8,y=77},{"z",0,txt="Fly to Grom'gol",at="Grom'gol"}}},
  {t="The Vile Reef", lv=35, n="North-west of Grom'gol the Vile Reef lies under the water off the coast. The Tablet Shard rests on the sea floor by the sunken ruins; watch your breath and the murlocs.", g={{"o",629,i=1,txt="Tablet Shard",n2="Underwater",m=1434,x=24.8,y=22.9}}},
  {t="Ruins of Zul'Kunda: kill these as you meet them", lv=35, n="The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a Bloody Bone Necklace. Keep looting pages of The Green Hills of Stranglethorn.", g={{"o",596,i=1,txt="Bloody Bone Necklace x25",m=1434,x=28.8,y=19.9},{"o",582,i=1,txt="Shrunken Head x20",m=1434,x=24.7,y=10.5}}},
  {t="Grom'gol", lv=35, g={{"t",582,m=1434,x=32.2,y=27.7},{"t",596,m=1434,x=32.3,y=27.7},{"t",629,m=1434,x=32.3,y=27.7},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Stranglethorn Vale: kill these as you meet them", lv=35, n="East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for Drizzlik. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them.", g={{"o",570,i=1,txt="Shadowmaw Claw x8",m=1434,x=36,y=34},{"o",570,i=2,txt="Pristine Tigress Fang",m=1434,x=36,y=34},{"o",192,i=1,txt="Kill Shadowmaw Panther x10",m=1434,x=41.3,y=34.8},{"o",577,i=1,txt="Snapjaw Crocolisk Skin x5",m=1434,x=39.9,y=28.4}}},
  {t="Green Hills pages", lv=35, n="Pages of The Green Hills of Stranglethorn drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. Barnil takes the chapters on your next Stranglethorn visit, at about 40.", g={{"o",339,i=1,txt="Green Hills of Stranglethorn - Page 1",m=1434,x=35.5,y=23.7,opt=true},{"o",339,i=2,txt="Green Hills of Stranglethorn - Page 4",m=1434,x=35.5,y=23.7,opt=true},{"o",339,i=3,txt="Green Hills of Stranglethorn - Page 6",m=1434,x=44.7,y=11,opt=true},{"o",339,i=4,txt="Green Hills of Stranglethorn - Page 8",m=1434,x=44.7,y=11,opt=true},{"o",340,i=1,txt="Green Hills of Stranglethorn - Page 10",m=1434,x=44.7,y=11,opt=true},{"o",340,i=2,txt="Green Hills of Stranglethorn - Page 11",m=1434,x=44.7,y=11,opt=true},{"o",340,i=3,txt="Green Hills of Stranglethorn - Page 14",m=1434,x=37,y=53.8,opt=true},{"o",340,i=4,txt="Green Hills of Stranglethorn - Page 16",m=1434,x=44.7,y=11,opt=true},{"o",341,i=1,txt="Green Hills of Stranglethorn - Page 18",m=1434,x=44.7,y=11,opt=true},{"o",341,i=2,txt="Green Hills of Stranglethorn - Page 20",m=1434,x=44.7,y=11,opt=true},{"o",341,i=3,txt="Green Hills of Stranglethorn - Page 21",m=1434,x=44.7,y=11,opt=true},{"o",341,i=4,txt="Green Hills of Stranglethorn - Page 24",m=1434,x=37.4,y=31.2,opt=true},{"o",342,i=1,txt="Green Hills of Stranglethorn - Page 25",m=1434,x=37.3,y=31.3,opt=true},{"o",342,i=2,txt="Green Hills of Stranglethorn - Page 26",m=1434,x=37.4,y=31.2,opt=true},{"o",342,i=3,txt="Green Hills of Stranglethorn - Page 27",m=1434,x=37.4,y=31.2,opt=true}}},
  {t="Mosh'Ogg camp", lv=35, n="The Mosh'Ogg ogres camp in the hills just east of Grom'gol, on your way back. Kill 10 Brutes and 5 Witch Doctors (36-37); pull them one at a time.", g={{"o",569,i=1,txt="Kill Mosh'Ogg Brute x10",m=1434,x=37.3,y=31.3},{"o",569,i=2,txt="Kill Mosh'Ogg Witch Doctor x5",m=1434,x=37.5,y=31}}},
  {t="Grom'gol", lv=35, n="Back to Grom'gol.", g={{"t",569,m=1434,x=32.2,y=28.9},{"t",570,m=1434,x=32.1,y=29.2},{"a",572,n2="Far Seer Mok'thardin: for forever/horde/40-50/01-stranglethorn-vale",m=1434,x=32.1,y=29.2,ml=33},{"a",584,n2="Nimboya: for forever/horde/40-50/01-stranglethorn-vale",m=1434,x=32.2,y=27.7,ml=30},{"i",0,txt="The next guide takes the zeppelin to Orgrimmar from the tower on the west side of the camp."}}},
  {t="Level 36", lv=36, n="Dustwallow's quests are 35-38. Still below 36 after Grom'gol's hand-ins? The Mosh'Ogg Brutes and Witch Doctors camp in the hills just east of the camp: kill them until level 36, pulling one at a time, then walk back to the zeppelin tower. Or, with a group, run the Scarlet Monastery dungeon (Armory) or the Razorfen Downs dungeon instead.", w={{k="level",op="<",n=36}}, g={{"g",0,txt="Mosh'Ogg camp",m=1434,x=36.7,y=31.9},{"l",36,txt="Reach level 36: grind Mosh'Ogg Brute",n2="grind on Mosh'Ogg Brute",m=1434,x=36.7,y=31.9}}},
} end)

R:Segment({id="horde/30-40/04-dustwallow-marsh",title="Dustwallow Marsh & Desolace",faction="Horde",min=36,max=38,zone=1445,zoneName="Dustwallow Marsh",next="horde/30-40/05-arathi-highlands"}, function() return {
  {t="Zeppelin to Orgrimmar", lv=36, g={{"g",0,txt="Zeppelin to Orgrimmar",m=1434,x=31.4,y=29.9}}},
  {t="Orgrimmar", lv=36, g={{"g",0,txt="The middle of Orgrimmar",m=1454,x=51.5,y=45.6}}},
  {t="Orgrimmar", lv=36, g={{"h",3713,txt="Buy Soothing Spices x3",n2="Soothing Spices, for \"Swamp Eye\" Jarl",n=3},{"a",1718,n2="Sorek, Valley of Honor: for Fray Island, later in this guide (offered from level 30)",m=1454,x=80.4,y=32.4,f={c={"WARRIOR"}},ml=30}}},
  {t="Fly to the Crossroads", lv=36, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Crossroads",at="Crossroads"}}},
  {t="Korran", lv=36, n="Korran stands beside the Crossroads flight master.", g={{"t",1148,m=1413,x=51.1,y=29.6},{"a",1184,n2="for Belgrom Rockmaul in Orgrimmar, at the end of this guide",m=1413,x=51.1,y=29.6,ml=28}}},
  {t="Fly to Camp Taurajo", lv=36, g={{"g",0,txt="Crossroads flight master",m=1413,x=51.5,y=30.4},{"z",0,txt="Fly to Camp Taurajo",at="Camp Taurajo"}}},
  {t="Dustwallow Marsh", lv=36, g={{"g",0,txt="Shady Rest Inn",m=1445,x=29.7,y=47.6}}},
  {t="Shady Rest Inn", lv=36, n="Head east from Camp Taurajo along the road into the marsh. The burned-out Shady Rest Inn stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin.", g={{"a",1268,m=1445,x=29.7,y=47.6,ml=30},{"a",1251,m=1445,x=29.6,y=48.6,ml=30},{"a",1269,m=1445,x=29.8,y=48.2,ml=30}}},
  {t="Dustwallow Marsh", lv=36, g={{"g",0,txt="Brackenwall Village",m=1445,x=35.1,y=38.3}}},
  {t="Brackenwall Village", lv=36, n="Take the road north at the fork to the ogre village of Brackenwall.", g={{"a",1177,n2="Mudcrush Durtfeet, at the south edge of the village where the road comes in",m=1445,x=35.1,y=38.3,ml=32},{"t",1269,m=1445,x=36.4,y=31.9},{"t",1251,m=1445,x=36.4,y=31.9},{"a",1321,m=1445,x=36.4,y=31.9,ml=30},{"t",1268,m=1445,x=36.4,y=31.9},{"fp",55,txt="Get the Brackenwall Village flight path (Shardi)",m=1445,x=35.6,y=31.9},{"a",1201,m=1445,x=35.2,y=30.7,ml=30},{"t",1321,m=1445,x=36.5,y=30.8},{"a",1322,m=1445,x=36.5,y=30.8,ml=30}}},
  {t="Questioning Reethe", lv=36, n="Ogron waits in the Quagmire east of the village. Follow him to Reethe and keep him alive through the fight that breaks out.", g={{"a",1273,m=1445,x=41,y=36.7,ml=30},{"c",1273,txt="Paval Reethe; Question Reethe with Ogron",m=1445,x=42.6,y=38.1}}},
  {t="Stinky Ignatz", lv=36, n="Head north to Witch Hill. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it.", g={{"a",1270,m=1445,x=46.9,y=17.5,ml=30},{"c",1270,txt="Help Stinky find Bogbean Leaves"}}},
  {t="Mirefin murlocs", lv=36, n="The Mirefin murlocs crowd the coast east and north-east of Witch Hill; every kind drops heads.", g={{"o",1177,i=1,txt="Mirefin Head x12",m=1445,x=53.8,y=15.2}}},
  {t="Swamp Eye Jarl", lv=36, n="Jarl lives in the Swamplight Manor south-east of Witch Hill.", g={{"a",1238,n2="Loose Dirt, beside the manor",m=1445,x=55.4,y=25.9,ml=30},{"a",1218,m=1445,x=55.4,y=26.3,ml=30},{"h",3713,txt="Buy Soothing Spices x3",n2="Soothing Spices, if you did not buy them in Orgrimmar",n=3},{"t",1218,m=1445,x=55.4,y=26.3},{"a",1206,m=1445,x=55.4,y=26.3,ml=30}}},
  {t="Brackenwall Village: kill these as you meet them", lv=36, n="Head west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them.", g={{"o",1322,i=1,txt="Acidic Venom Sac x6",m=1445,x=56.3,y=23.8},{"o",1206,i=1,txt="Unpopped Darkmist Eye x40",m=1445,x=35.7,y=21.1},{"o",1201,i=1,txt="Kill Theramore Infiltrator x9",m=1445,x=38,y=23.6}}},
  {t="Brackenwall Village", lv=36, g={{"t",1238,m=1445,x=35.2,y=30.7},{"t",1201,m=1445,x=35.2,y=30.7},{"a",1202,m=1445,x=35.2,y=30.7,ml=30},{"t",1322,m=1445,x=36.5,y=30.8},{"a",1323,m=1445,x=36.5,y=30.8,ml=30},{"t",1323,m=1445,x=36.4,y=31.9},{"t",1273,m=1445,x=36.4,y=31.9}}},
  {t="Swamp Eye Jarl", lv=36, n="Head east back to the Swamplight Manor.", g={{"a",1239,n2="Loose Dirt, now that Nazeer has read the report",m=1445,x=55.4,y=25.9,ml=30},{"t",1206,m=1445,x=55.4,y=26.3},{"a",1203,n2="only if you carry a Moonsteel Broadsword (Blacksmithing or the Auction House)",m=1445,x=55.4,y=26.3,opt=true,ml=30},{"t",1203,m=1445,x=55.4,y=26.3,opt=true}}},
  {t="The Theramore Docks", lv=36, n="South-east from the manor to Theramore Isle: the Captain's Footlocker lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57.", g={{"o",1202,i=1,txt="Captain's Documents",n2="Underwater",m=1445,x=71.5,y=51.2}}},
  {t="Brackenwall Village", lv=36, n="Head back west to Brackenwall with the head: Mudcrush Durtfeet stands at the south edge of the village where the road comes in, Nazeer Bloodpike in the village.", g={{"t",1177,m=1445,x=35.1,y=38.3},{"t",1202,m=1445,x=35.2,y=30.7},{"t",1239,m=1445,x=35.2,y=30.7},{"a",1240,n2="For Kin'weelay at Grom'gol, in forever/horde/40-50/01-stranglethorn-vale",m=1445,x=35.2,y=30.7,ml=30}}},
  {t="Level 37.5", lv=37, n="Desolace's last quests and Alterac are 38-41. Still below 37.5 after Brackenwall's hand-ins? The Darkmist spiders and Lurkers (35-38) by the cavern north-west of the village are the closest: kill them until level 37.5. Or, with a group, run the Razorfen Downs dungeon or the Scarlet Monastery dungeon (Armory) instead.", w={{k="level",op="<",n=37,frac=0.5}}, g={{"g",0,txt="Darkmist cavern",m=1445,x=31.4,y=22.2},{"l",37,txt="Reach level 37 (50% in): grind Darkmist Lurker",n2="grind on Darkmist Lurker",m=1445,x=31.4,y=22.4,fr=0.5}}},
  {t="Fly to Ratchet", lv=37, g={{"g",0,txt="Brackenwall Village flight master",m=1445,x=35.6,y=31.8},{"z",0,txt="Fly to Ratchet",at="Ratchet"}}},
  {t="Ratchet", lv=37, n="Mebok Mizzyrix stands below Gazlowe's house by the flight master, towards the docks.", g={{"t",1270,m=1413,x=62.4,y=37.6}}},
  {t="The Affray", lv=37, n="Head south along the coast from Ratchet to Fray Island. Klannoc Macleod stands by the arena: step on the grate to start the fight; the challengers come one at a time, then Big Will (33).", f={c={"WARRIOR"}}, g={{"t",1718,m=1413,x=68.6,y=49.2},{"a",1719,m=1413,x=68.6,y=49.2,ml=30},{"c",1719,txt="Big Will; Step on the grate to begin the Affray",m=1413,x=68.6,y=48.7},{"t",1719,n2="Klannoc Macleod: Berserker Stance",m=1413,x=68.6,y=49.2}}},
  {t="Fly to Shadowprey Village", lv=37, g={{"g",0,txt="Ratchet flight master",m=1413,x=63.1,y=37.1},{"z",0,txt="Fly to Shadowprey Village",at="Shadowprey Village"}}},
  {t="Shadowprey Village", lv=37, n="Taiga Wisemane stands in the village.", g={{"a",5581,m=1443,x=25.8,y=68.2,ml=32}}},
  {t="Portals of the Legion", lv=37, n="Head east to Mannoroc Coven. With the Hand of Iruxos from Taiga in your bags, open a demon portal's ring: a Demon Portal Guardian (38-39) comes out; kill it to close that portal. Six portals. Careful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake.", g={{"g",0,txt="Mannoroc Coven",m=1443,x=52,y=78},{"c",5581,txt="Portals Banished"}}},
  {t="Ghost Walker Post", lv=37, n="North to the post; Gurda Wildmane stands beside Felgur.", g={{"a",93225,m=1443,x=56.3,y=59.7,ml=30}}},
  {t="Valley of Spears", lv=37, n="West of the post, the Maraudine centaurs hold the Valley of Spears. Every Maraudine can drop a Carved Centaur Totem and an ear for Felgur's Centaur Bounty.", g={{"o",93225,i=1,txt="Carved Centaur Totem x5",m=1443,x=65.6,y=70.3},{"o",1366,i=1,txt="Centaur Ear x15",m=1443,x=65.6,y=70.3}}},
  {t="Melizza Brimbuzzle", lv=37, n="Melizza is held in the Maraudine camp at the valley's western end; free her and escort her out east of the valley.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help.", g={{"a",6132,m=1443,x=34,y=53.5,ml=34},{"c",6132,txt="Melizza Brimbuzzle escorted to safety"}}},
  {t="Hornizz Brimbuzzle", lv=37, n="Hornizz waits at the goblin camp on the west side of the Kodo Graveyard.", g={{"t",6132,m=1443,x=47.8,y=61.8},{"a",6134,m=1443,x=47.8,y=61.8,ml=34}}},
  {t="The Valley of Bones", lv=37, n="Head south-east to the bone fields of the Valley of Bones, where Undead Ravagers roam. At the far south-east, use the Crate of Ghost Magnets to draw the Magrami Spectres: they drop the ghost-o-plasm.", g={{"o",6134,i=1,txt="Use Crate of Ghost Magnets",m=1443,x=63.5,y=91.6},{"o",6134,i=1,txt="Ghost-o-plasm x8",m=1443,x=64.2,y=91.6}}},
  {t="Hornizz Brimbuzzle", lv=37, n="North to the goblin camp on the west side of the Kodo Graveyard.", g={{"t",6134,m=1443,x=47.8,y=61.8}}},
  {t="Ghost Walker Post", lv=37, g={{"t",1366,m=1443,x=56.2,y=59.6},{"t",93225,m=1443,x=56.3,y=59.7}}},
  {t="Shadowprey", lv=37, n="West to Shadowprey.", g={{"t",5581,m=1443,x=25.8,y=68.2}}},
  {t="Thunder Bluff", lv=37, n="Fly from Shadowprey Village to Thunder Bluff and train with Turak Runetotem on Elder Rise; fly on to Orgrimmar from there.", f={c={"DRUID"}}, g={{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"},{"tr",0,txt="Visit your class trainer"}}},
  {t="Fly to Orgrimmar", lv=37, f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"g",0,txt="Shadowprey Village flight master",m=1443,x=21.6,y=74},{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"}}},
  {t="Back to Orgrimmar", lv=37, f={c={"DRUID"}}, g={{"g",0,txt="Thunder Bluff flight master",m=1456,x=46.7,y=49.9},{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"}}},
  {t="Belgrom Rockmaul", lv=37, n="Belgrom Rockmaul stands in the Valley of Honor.", g={{"t",1184,m=1454,x=75.2,y=34.2}}},
  {t="Nogg", lv=37, n="Nogg's workshop is in the Valley of Honor beside Belgrom: hand in Rig Wars if you ran Gnomeregan.", w={{k="complete",q=2841}}, g={{"t",2841,m=1454,x=76,y=25.4,grp=true}}},
  {t="Orgrimmar trainers", lv=37, n="Train while you are in the city; everyone else trains in the Undercity, next.", f={c={"HUNTER","SHAMAN"}}, g={{"tr",0,txt="Visit your class trainer"},{"i",0,txt="The next guide takes the Undercity zeppelin from the tower outside the main gate."}}},
} end)

R:Segment({id="horde/30-40/05-arathi-highlands",title="Alterac Mountains & Arathi Highlands",faction="Horde",min=38,max=39,zone=1417,zoneName="Arathi Highlands",next="horde/30-40/06-badlands"}, function() return {
  {t="Zeppelin to Undercity", lv=38, g={{"g",0,txt="Zeppelin to Undercity",m=1411,x=50.8,y=13.5}}},
  {t="Undercity trainers", lv=38, n="Train while you are in the Undercity: the trainers stand in the War Quarter, the Rogues' Quarter and the Magic Quarter (Paladins: Garen Largo).", f={c={"WARRIOR","PALADIN","ROGUE","PRIEST","MAGE","WARLOCK"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Fly to Tarren Mill", lv=38, g={{"g",0,txt="Undercity flight master",m=1458,x=63.1,y=48.3},{"z",0,txt="Fly to Tarren Mill",at="Tarren Mill"}}},
  {t="Tarren Mill", lv=38, g={{"a",503,n2="Krusk, inside the inn",m=1424,x=63.2,y=20.7,ml=29},{"a",566,n2="The WANTED poster by the inn",m=1424,x=62.6,y=20.8,ml=35},{"b",0,txt="Set your hearthstone at Tarren Mill",m=1424,x=62.8,y=19,at="Tarren Mill"}}},
  {t="Alterac Mountains", lv=38, g={{"g",0,txt="Gol'dir",m=1416,x=61.8,y=43}}},
  {t="Gol'dir", lv=38, n="Head north past Valik's camp to Strahnbrad, the Syndicate-held village (35-37). Jailor Borhuin carries the Rusted Iron Key; Gol'dir sits in a cage in the house on the north side.\nCareful: Stealthed Syndicate spies roam Strahnbrad, and the buildings hold many Syndicate mobs, mages among them.", g={{"o",503,i=1,txt="Rusted Iron Key",n2="Inside",m=1416,x=60.8,y=43.6},{"c",503,txt="Rusted Iron Key; Find where Gol'dir is being held",n2="Find where Gol'dir is held, on the top floor",m=1416,x=60.6,y=43.8},{"t",503,n2="Gol'dir, on the top floor",m=1416,x=60,y=43.7},{"a",506,m=1416,x=60,y=43.7,ml=29}}},
  {t="Hillsbrad Foothills", lv=38, g={{"g",0,txt="Tarren Mill",m=1424,x=61.5,y=20.9}}},
  {t="Tarren Mill", lv=38, n="Krusk waits inside the inn at Tarren Mill, back south down the road.", g={{"t",506,n2="Krusk, inside",m=1424,x=63.2,y=20.7},{"a",507,m=1424,x=63.2,y=20.7,ml=29}}},
  {t="Baron Vardus", lv=38, n="Baron Vardus (40) carries the head. He turns up in one spot at a time: the cellar of Strahnbrad's inn, or one of the Syndicate tent camps in the uplands north and north-west of the village, which lie on your way to the Perenolde manor. If you already met him while freeing Gol'dir, this step is done.", g={{"o",566,i=1,txt="Head of Baron Vardus",m=1416,x=55.2,y=27.4}}},
  {t="Alterac Mountains", lv=38, g={{"g",0,txt="Perenolde manor",m=1416,x=39.3,y=14.6}}},
  {t="Lord Aliden Perenolde", lv=38, n="Head north-west through the mountains to the Perenolde manor on the northern shore of Lordamere Lake. Lord Aliden Perenolde (41) waits in a room upstairs: he shields himself, puts you to sleep and heals below half health. Elysa stands beside him.", g={{"o",507,i=1,txt="Kill Lord Aliden Perenolde",m=1416,x=39.3,y=14.6},{"t",507,m=1416,x=39.3,y=14.3},{"a",508,m=1416,x=39.3,y=14.3,ml=29}}},
  {t="Old Dalaran Ruins: kill these as you meet them", lv=38, n="South along the lake shore to the ruins around the Dalaran crater. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves.", g={{"o",545,i=2,txt="Kill Elemental Slave x8",m=1416,x=22.4,y=58.6},{"o",557,i=1,txt="Bracers of Earth Binding x4",m=1416,x=21.6,y=61.9},{"o",545,i=1,txt="Kill Dalaran Summoner x6",m=1416,x=22,y=57.9}}},
  {t="Hillsbrad Foothills", lv=38, g={{"g",0,txt="Tarren Mill",m=1424,x=61.5,y=20.9}}},
  {t="Tarren Mill", lv=38, n="Head back east to Tarren Mill.", g={{"t",557,n2="Keeper Bel'varil, inside",m=1424,x=61.5,y=20.9},{"t",545,n2="Magus Wordeen Voidglare, inside",m=1424,x=61.6,y=20.9},{"i",0,txt="The magus offers a dungeon errand next: leave it."},{"t",508,n2="Krusk, inside the inn",m=1424,x=63.2,y=20.7},{"t",566,m=1424,x=62.3,y=20.4}}},
  {t="Thoradin's Wall", lv=38, g={{"g",0,txt="The road east through Thoradin's Wall",m=1417,x=32.6,y=40.4}}},
  {t="Northfold Manor", lv=38, n="Head east out of Tarren Mill through Thoradin's Wall. The Syndicate hold the walled manor and its farm north of the road; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets.\nCareful: Highwaymen (level 30-31) can be in Sneak, so they may be hidden when you approach.", g={{"o",671,i=1,txt="Bloodstone Amulet x10",m=1417,x=31.8,y=33}}},
  {t="The Shards of Myzrael", lv=38, n="Follow the road east. The violet shards glow just off the road a short way west of Hammerfall.", g={{"t",635,m=1417,x=62.5,y=33.7,opt=true},{"a",642,m=1417,x=62.5,y=33.7,ml=30}}},
  {t="Hammerfall", lv=38, g={{"t",638,m=1417,x=73.8,y=34},{"a",678,m=1417,x=74.2,y=33.9,ml=30},{"t",671,m=1417,x=74.7,y=36.3},{"a",701,m=1417,x=74.7,y=36.3,ml=29},{"a",92519,n2="Doctor Gregory Victor, at the south gate",m=1417,x=73.4,y=36.9,ml=30}}},
  {t="Stromgarde quests for a group", lv=38, n="Zengu's Sigil of Strom drops from the elite Syndicate (35-38) in Stromgarde's ruins, the west of the highlands. Great XP if you have a group for it: the route passes Stromgarde on its way to the inner circle.", w={{k="group",q=639}}, g={{"a",639,m=1417,x=73.8,y=34,ml=32}}},
  {t="Foul Magics with a group", lv=38, n="Tor'gan's next Foul Magics is Marez Cowl, a level 40 elite warlock in Stromgarde's Syndicate quarter.", w={{k="group",q=673}}, g={{"a",673,m=1417,x=74.7,y=36.3,ml=35}}},
  {t="Drywhisker Gorge", lv=38, n="North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them.", g={{"o",642,i=1,txt="Mote of Myzrael x12",m=1417,x=77.5,y=35.6}}},
  {t="Iridescent Shards", lv=38, n="The Iridescent Shards lie at the far end of the gorge.", g={{"t",642,n2="Below ground",m=1417,x=84.3,y=30.9},{"a",651,m=1417,x=84.3,y=30.9,ml=30}}},
  {t="The Stone of East Binding", lv=38, n="Each Circle of Binding is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of Hammerfall.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East.", g={{"o",651,i=2,txt="Cresting Key",m=1417,x=66.7,y=29.7}}},
  {t="Boulderfist Hall", lv=38, n="The Boulderfist Brutes camp outside the ogres' hall, far south-west of Hammerfall; the Magus stand among them. Pull them one at a time.", g={{"o",678,i=1,txt="Kill Boulderfist Brute x10",m=1417,x=55.1,y=72.7},{"o",678,i=2,txt="Kill Boulderfist Magus x4",m=1417,x=54,y=71.8}}},
  {t="Fleshstalker raptors", lv=38, n="Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of Boulderfist Hall and another on the plain to its west. Pull them one at a time.", g={{"o",701,i=1,txt="Raptor Heart x12",m=1417,x=53.1,y=68.8}}},
  {t="Go'shek Farm", lv=38, n="Apothecary Jorell's lab shack stands at Go'shek Farm, north-east of the raptors' plain on the way back to Hammerfall; the case of Packaged Tonics is inside.", g={{"o",92519,i=1,txt="Packaged Tonics",m=1417,x=60.1,y=59.3}}},
  {t="Back to Hammerfall", lv=38, n="Back north-east to Hammerfall.", g={{"t",92519,n2="Doctor Gregory Victor, at the south gate",m=1417,x=73.4,y=36.9},{"t",701,m=1417,x=74.7,y=36.3},{"a",702,m=1417,x=74.7,y=36.3,ml=29},{"t",678,m=1417,x=74.2,y=33.9},{"t",702,n2="Gor'mul, by the gate",m=1417,x=72.6,y=33.9},{"a",847,m=1417,x=72.6,y=33.9,ml=29},{"t",847,m=1417,x=74.7,y=36.3},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Boulderfist quests for a group", lv=38, n="Drum Fel's next Call to Arms and Korin Fel's The Real Threat are the elite ogres (38-40) in Stromgarde's ogre quarter, on the same group trip as the Sigil.", w={{k="group",q=679}}, g={{"a",679,m=1417,x=74.2,y=33.9,ml=30},{"a",680,n2="Korin Fel, beside him",m=1417,x=74,y=33.1,ml=30}}},
  {t="The Stone of Outer Binding", lv=38, n="Head west; the outer circle stands in the middle of the highlands.", g={{"o",651,i=3,txt="Thundering Key",m=1417,x=52,y=50.7}}},
  {t="Circle of West Binding", lv=38, n="The western circle is near Thoradin's Wall, north-west of the outer one.", g={{"o",651,i=1,txt="Burning Key",m=1417,x=25.5,y=30.1}}},
  {t="The Stone of Inner Binding", lv=38, n="The inner circle lies south of the western circle, east of Stromgarde.", g={{"t",651,m=1417,x=36.2,y=57.4},{"i",0,txt="The stone's next task needs Fozruk, a level 42 elite who roams west of Hammerfall: leave it."}}},
  {t="Stromgarde", lv=38, n="West of the inner circle, Stromgarde's ruins: the Syndicate hold the east half (the Sigil drops from their Conjurors, Prowlers and Magi; Marez Cowl is among them), the Boulderfist the west half by the Tower of Arathor (Or'Kalar waits in one of the roofless houses beside it).", w={{k="onquest",q={639,673,679,680}}}, g={{"o",639,i=1,txt="Sigil of Strom",m=1417,x=27.3,y=63.8,grp=true},{"o",673,i=1,txt="Befouled Bloodstone Orb",m=1417,x=29.6,y=63.6,grp=true},{"o",679,i=1,txt="Kill Boulderfist Shaman x15",m=1417,x=20,y=67.4,grp=true},{"o",679,i=2,txt="Kill Boulderfist Lord x10",m=1417,x=19,y=67.8,grp=true},{"o",680,i=1,txt="Or'Kalar's Head",m=1417,x=19.5,y=67.2,grp=true}}},
  {t="Faldir's Cove", lv=38, n="Head south to the goblins' cove on the southern coast. Lolo the Lookout keeps watch on the cliff above it.", g={{"a",663,m=1417,x=31.8,y=82.7,ml=35},{"t",663,m=1417,x=32.3,y=81.4},{"a",662,m=1417,x=32.8,y=81.5,ml=35},{"a",664,m=1417,x=34,y=80.8,ml=35},{"a",665,m=1417,x=33.9,y=80.5,ml=35}}},
  {t="Professor Phizzlethorpe", lv=38, n="Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming.", g={{"g",0,txt="Go here",m=1417,x=33.9,y=80.6},{"c",665,txt="Defend Professor Phizzlethorpe"}}},
  {t="Doctor Draxlegauge", lv=38, g={{"t",665,m=1417,x=33.9,y=80.5},{"a",666,m=1417,x=33.9,y=80.5,ml=35}}},
  {t="The Drowned Reef: kill these as you meet them", lv=38, n="West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks.", g={{"o",664,i=1,txt="Kill Daggerspine Raider x10",n2="Underwater",m=1417,x=25.4,y=85.2},{"o",666,i=1,txt="Elven Gem x10",n2="Underwater",m=1417,x=25,y=86},{"o",664,i=2,txt="Kill Daggerspine Sorceress x3",n2="Underwater",m=1417,x=23.8,y=84.8},{"o",662,i=2,txt="Maiden's Folly Log",n2="Underwater",m=1417,x=23.4,y=85.1},{"o",662,i=1,txt="Maiden's Folly Charts",n2="Underwater",m=1417,x=23.1,y=84.5},{"o",662,i=4,txt="Spirit of Silverpine Log",n2="Underwater",m=1417,x=20.6,y=85.1},{"o",662,i=3,txt="Spirit of Silverpine Charts",n2="Underwater",m=1417,x=20.5,y=85.6}}},
  {t="Faldir's Cove", lv=38, g={{"t",662,m=1417,x=32.8,y=81.5},{"t",664,m=1417,x=34,y=80.8},{"t",666,m=1417,x=33.9,y=80.5},{"a",668,m=1417,x=33.9,y=80.5,ml=35},{"t",668,m=1417,x=32.3,y=81.4},{"a",669,n2="for Fleet Master Seahorn in Booty Bay, around level 41",m=1417,x=32.3,y=81.4,ml=35},{"i",0,txt="The next guide crosses the Thandol Span into the Wetlands and heads for the Badlands."}}},
  {t="Back to Hammerfall", lv=38, n="Only if you ran Stromgarde with a group: back to Hammerfall for its hand-ins, then on to the Thandol Span.", w={{k="onquest",q={639,673,679,680}}}, g={{"t",639,m=1417,x=73.8,y=34},{"t",673,m=1417,x=74.7,y=36.3},{"t",679,m=1417,x=74.2,y=33.9},{"t",680,m=1417,x=74,y=33.1}}},
} end)

R:Segment({id="horde/30-40/06-badlands",title="Badlands",faction="Horde",min=39,max=40,zone=1418,zoneName="Badlands",next="horde/40-50/01-stranglethorn-vale"}, function() return {
  {t="Into the Badlands", lv=39, n="Head for the Thandol Span, the great bridge at Arathi's southern edge, cross it and follow the road south through the Wetlands to the Dun Algaz tunnel into Loch Modan. Thelsamar, the dwarf town on the road in the middle of Loch Modan, has guards who attack the Horde: leave the road before it and pass the town on the hills to its west. The road leaves Loch Modan to the south into the Badlands; follow it to the goblin camp in the Valley of Fangs.", g={{"g",0,txt="Valley of Fangs",m=1418,x=42.3,y=52.8}}},
  {t="Valley of Fangs", lv=39, g={{"t",1106,n2="Martek the Exiled: Fizzle's letter from the Shimmering Flats",m=1418,x=42.2,y=52.7},{"a",1108,m=1418,x=42.2,y=52.7,ml=28},{"a",703,m=1418,x=42.4,y=52.9,ml=33}}},
  {t="The Dustbowl", lv=39, n="Head west along the road towards Kargath; Lotwil's camp sits in the Dustbowl halfway there.", g={{"a",710,m=1418,x=25.9,y=44.9,ml=35}}},
  {t="Kargath", lv=39, n="Kargath is the Horde fortress built into the cliffs at the zone's western edge. Neeka Bloodscar stands on Kargath's upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart.", g={{"fp",21,txt="Get the Kargath flight path (Gorrik)",m=1418,x=4,y=44.8},{"b",0,txt="Set your hearthstone at Kargath",m=1418,x=2.8,y=45.9,at="Kargath"},{"a",1419,m=1418,x=6.5,y=47.2,ml=30},{"a",1420,n2="for Helgrum in Stonard, around level 42",m=1418,x=6.5,y=47.2,ml=30},{"a",2258,n2="Jarkal Mossmeld, inside",m=1418,x=2.4,y=46.1,ml=36},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Lesser Rock Elementals", lv=39, n="The small elementals drift across the flats between Kargath and Lotwil's camp, on the road back east. Every rock elemental in the zone can drop Jarkal's Rock Elemental Shards.", g={{"o",710,i=1,txt="Small Stone Shard x10",m=1418,x=13.1,y=39.2},{"o",2258,i=3,txt="Rock Elemental Shard x5",m=1418,x=13.1,y=39.2}}},
  {t="Lotwil Veriatus", lv=39, g={{"t",710,m=1418,x=25.9,y=44.9},{"a",711,m=1418,x=25.9,y=44.9,ml=35}}},
  {t="Badlands: kill these as you meet them", lv=39, n="The Elder Crag Coyotes and Giant Buzzards roam the basin south of the Dustbowl. Coyotes drop both the jawbones and the fangs; the Giant Buzzards drop the gizzards.", g={{"o",1419,i=1,txt="Coyote Jawbone x30",m=1418,x=28.2,y=47.6},{"o",2258,i=2,txt="Crag Coyote Fang x10",m=1418,x=28.2,y=47.6},{"o",2258,i=1,txt="Buzzard Gizzard x5",m=1418,x=33.4,y=59.8}}},
  {t="Rock Elementals", lv=39, n="South-east across the basin, the bigger Rock Elementals (39) stand on the slopes west of Agmond's End; each one drops a slab. Every rock elemental can drop Jarkal's Rock Elemental Shards.", g={{"o",711,i=1,txt="Large Stone Slab x3",m=1418,x=40.4,y=77.1},{"o",2258,i=3,txt="Rock Elemental Shard x5",m=1418,x=40.4,y=75.8}}},
  {t="Agmond's End", lv=39, n="Theldurin sits among the dwarven ruins at Agmond's End, just east of the elementals.", g={{"a",709,m=1418,x=51.4,y=76.9,ml=30}}},
  {t="Stonevault troggs", lv=39, n="The Stonevault troggs dig around the cave mouths south of the Valley of Fangs, on the way north from Agmond's End; the Bonesnappers and Shamans drop the flakes. The Buzzards for Rigglefuzz's wings circle the hills between the Valley of Fangs and Agmond's End.", g={{"o",1108,i=1,txt="Indurium Flake x10",m=1418,x=51.2,y=71.7},{"o",703,i=1,txt="Buzzard Wing x4",m=1418,x=50.1,y=77.9}}},
  {t="Valley of Fangs", lv=39, n="The road north to Uldaman runs through the Valley of Fangs: Rigglefuzz and Martek take the wings and the flakes on the way.", g={{"t",703,m=1418,x=42.4,y=52.9},{"t",1108,m=1418,x=42.2,y=52.7},{"a",1137,n2="for Fizzle at the Mirage Raceway, on the way from Freewind Post to Tanaris around level 43",m=1418,x=42.2,y=52.7,ml=28}}},
  {t="Ancient Chest", lv=39, n="Keep north on the road; the chest lies in the Uldaman dig site, at the foot of the ruins north-west of the road.", g={{"o",709,i=1,txt="Tablet of Ryun'eh",n2="Below ground",m=1418,x=39.3,y=18.8}}},
  {t="Agmond's End", lv=39, n="Head back south down the road, past the Valley of Fangs.", g={{"t",709,m=1418,x=51.4,y=76.9},{"a",728,m=1418,x=51.4,y=76.9,ml=30}}},
  {t="The Dustbowl", lv=39, n="North-west across the basin to Lotwil's camp. Short of Jarkal's shards? The Lesser Rock Elementals (37) on the flats west of the camp drop them about one kill in five.", g={{"t",711,m=1418,x=25.9,y=44.9},{"i",0,txt="Lotwil's next study wants bracers from the Greater Rock Elementals (42-44) in the south-western gulches, well above you: leave it."},{"o",2258,i=3,txt="Rock Elemental Shard x5",m=1418,x=26,y=45.8}}},
  {t="Kargath", lv=39, n="Head west back to Kargath. Neeka Bloodscar stands on Kargath's upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart.", g={{"t",1419,m=1418,x=6.5,y=47.2},{"t",2258,n2="Jarkal Mossmeld, inside",m=1418,x=2.4,y=46.1},{"i",0,txt="The next guide flies from Kargath to Grom'gol."}}},
} end)

R:Segment({id="horde/40-50/01-stranglethorn-vale",title="Stranglethorn Vale & Swamp of Sorrows",faction="Horde",min=39,max=43,zone=1434,zoneName="Stranglethorn Vale",next="horde/40-50/02-feralas"}, function() return {
  {t="Fly to Grom'gol", lv=39, g={{"g",0,txt="Kargath flight master",m=1418,x=4.1,y=44.9},{"z",0,txt="Fly to Grom'gol",at="Grom'gol"}}},
  {t="Grom'gol Base Camp", lv=39, g={{"t",1240,m=1434,x=32.3,y=27.7},{"a",95748,n2="Kin'weelay: the legend lies in Zul'Kunda, where this guide goes for Gan'zulah",m=1434,x=32.3,y=27.7,ml=30}}},
  {t="Jungle Stalkers", lv=39, n="The Jungle Stalkers (40-41) hunt the coast south of Grom'gol. They are well above you: pull one at a time and rest between fights.", g={{"o",572,i=1,txt="Jungle Stalker Feather x10",m=1434,x=33,y=36.5}}},
  {t="Far Seer Mok'thardin", lv=39, g={{"t",572,m=1434,x=32.1,y=29.2},{"a",571,m=1434,x=32.1,y=29.2,ml=33}}},
  {t="Fly to Booty Bay", lv=39, g={{"g",0,txt="Grom'gol flight master",m=1434,x=32.5,y=29.3},{"z",0,txt="Fly to Booty Bay",at="Booty Bay"}}},
  {t="Booty Bay", lv=39, n="Gringer, the flight master, waits on Booty Bay's upper deck. The quest givers stand on the boardwalks around the harbour and in the inn.", g={{"t",577,n2="Drizzlik: the Snapjaw skins gathered earlier; inside",m=1434,x=28.3,y=77.6},{"a",628,n2="Drizzlik: the Elder Saltwater Crocolisk suns on the coast between Zul'Kunda and Grom'gol, later on this loop",m=1434,x=28.3,y=77.6,ml=31},{"t",213,m=1434,x=27,y=77.1},{"t",1180,n2="Wharfmaster Lozgil, on the docks: Gazlowe's letter, if you carry it",m=1434,x=26.4,y=73.6},{"a",1181,m=1434,x=26.4,y=73.6,ml=29},{"a",606,n2="\"Sea Wolf\" MacKinley, on the top floor",m=1434,x=27.8,y=77.1,ml=30},{"t",1181,n2="Baron Revilgaz, on the balcony beside MacKinley",m=1434,x=27.2,y=76.9},{"t",669,m=1434,x=27.2,y=77},{"a",621,n2="Inside",m=1434,x=27.1,y=77.2,ml=35},{"a",600,m=1434,x=27.1,y=77.2,ml=30},{"a",617,m=1434,x=26.8,y=76.4,ml=38},{"i",0,txt="Sell and repair",opt=true},{"a",595,m=1434,x=28.1,y=76.2,ml=37}}},
  {t="Bloodsail Correspondence", lv=39, n="Leave town by the tunnel; the note lies in the pirates' cove just north of Booty Bay.", g={{"t",595,m=1434,x=27.3,y=69.5},{"a",597,m=1434,x=27.3,y=69.5,ml=37}}},
  {t="Booty Bay", lv=39, g={{"t",597,m=1434,x=28.1,y=76.2},{"a",599,m=1434,x=28.1,y=76.2,ml=37},{"a",576,m=1434,x=28.6,y=75.9,ml=37},{"t",599,m=1434,x=27.2,y=77},{"a",604,m=1434,x=27.2,y=77,ml=37},{"a",587,n2="Deeg, on the top floor",m=1434,x=26.9,y=77.3,ml=37}}},
  {t="The Wild Shore", lv=39, n="South of Booty Bay the Bloodsail swashbucklers camp on the Wild Shore; the charts and the orders lie in their tents. Any Bloodsail can carry snuff and Dizzy's eye, so keep killing until you have both.", g={{"o",604,i=2,txt="Bloodsail Charts",m=1434,x=27,y=82.5},{"o",604,i=3,txt="Bloodsail Orders",m=1434,x=27,y=82.6},{"o",587,i=1,txt="Snuff x15",m=1434,x=26.8,y=82.6},{"o",576,i=1,txt="Dizzy's Eye",m=1434,x=26.8,y=82.6},{"o",604,i=1,txt="Kill Bloodsail Swashbuckler x10",m=1434,x=26.7,y=82.8}}},
  {t="Booty Bay", lv=40, g={{"t",587,n2="Deeg, on the top floor",m=1434,x=26.9,y=77.3},{"t",604,m=1434,x=27.2,y=77},{"t",576,m=1434,x=28.6,y=75.9},{"a",348,m=1434,x=27.6,y=76.7,ml=40}}},
  {t="The Bloodsail ships", lv=40, n="Optional, and tough at 41: the scroll, Cortello's Riddle, lies on the decks of the three ships off the Wild Shore, crewed by pirates of 42-45 who come in pairs. Take it only if you can pull the crew to the rail one at a time, or with a friend; its chain runs on through the Swamp of Sorrows, Dustwallow Marsh and the Hinterlands.", g={{"h",4056,txt="Get Cortello's Riddle",m=1434,x=29.2,y=88.6,n=1,opt=true},{"a",624,n2="for a later stop in the Swamp of Sorrows",opt=true,ml=35}}},
  {t="Mistvale gorillas", lv=40, n="The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang.", g={{"h",2799,txt="Get Gorilla Fang x10",m=1434,x=38.8,y=85.9,n=10},{"o",571,i=1,txt="Aged Gorilla Sinew",m=1434,x=33,y=66.1}}},
  {t="Witch Doctor Unbagwa", lv=40, n="Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then Mokk. Fight them one at a time.", g={{"t",349,n2="Inside Spirit Den",m=1434,x=35.3,y=60.4},{"o",348,i=1,txt="Heart of Mokk",m=1434,x=35,y=60.9}}},
  {t="Mistvale gorillas", lv=40, g={{"o",606,i=1,txt="Mistvale Giblets x5",m=1434,x=34.4,y=62.5}}},
  {t="Venture Co. mine", lv=40, n="Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp.", g={{"o",600,i=1,txt="Singing Blue Crystal x10",m=1434,x=42,y=46.3}}},
  {t="Grom'gol Base Camp", lv=40, g={{"t",571,m=1434,x=32.1,y=29.2},{"b",0,txt="Set your hearthstone at Grom'gol Base Camp",m=1434,x=31.5,y=29.8,at="Grom'gol Base Camp"},{"a",573,m=1434,x=32.1,y=29.2,ml=33}}},
  {t="Nesingwary's camp", lv=40, n="Head north up the road; the hunters camp on the hill above the river.", g={{"t",195,m=1434,x=35.7,y=10.8},{"a",196,m=1434,x=35.7,y=10.8,ml=28},{"t",192,m=1434,x=35.5,y=10.6},{"t",339,m=1434,x=35.7,y=10.5,opt=true},{"t",340,m=1434,x=35.7,y=10.5,opt=true},{"t",341,m=1434,x=35.7,y=10.5,opt=true},{"t",342,m=1434,x=35.7,y=10.5,opt=true},{"t",338,m=1434,x=35.7,y=10.5,opt=true}}},
  {t="Nesingwary's camp", lv=40, w={{k="group",q=193}}, g={{"a",193,m=1434,x=35.5,y=10.6,ml=28}}},
  {t="Zul'Kunda", lv=41, n="West of the expedition, the Bloodscalp chiefs Gan'zulah and Nezzliok stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them. Stay on the Bloodscalps here until level 41: Speaking with Gan'zulah, at the cauldron next, sends you to Skullsplitters of 41-43. Or, with a group, run the Uldaman dungeon instead.\nOn the coast between Zul'Kunda and Grom'gol an Elder Saltwater Crocolisk (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for Drizzlik.", g={{"o",584,i=1,txt="Gan'zulah's Head",m=1434,x=23.4,y=8.1},{"o",95748,i=1,txt="The Third Troll Legend",n2="from the Fall of Gurubashi, in the ruins",m=1434,x=23,y=12},{"o",584,i=2,txt="Nezzliok's Head",m=1434,x=23.5,y=9.5},{"o",628,i=1,txt="Elder Crocolisk Skin",m=1434,x=29.3,y=22.3,opt=true,grp=true},{"l",41,txt="Reach level 41",n2="grind on the Bloodscalps here: Speaking with Gan'zulah, at the cauldron next, sends you to Skullsplitters of 41-43"}}},
  {t="Grom'gol", lv=41, g={{"t",584,n2="the Bubbling Cauldron, beside Nimboya",m=1434,x=32.2,y=27.6},{"t",95748,m=1434,x=32.3,y=27.7},{"a",586,m=1434,x=32.2,y=27.6,ml=30},{"a",585,m=1434,x=32.2,y=27.6,ml=30},{"a",2932,n2="Nimboya: for the Hinterlands, around level 48",m=1434,x=32.2,y=27.7,ml=35},{"a",598,n2="Kin'weelay: the trophy skulls stand in the Skullsplitter ruins, later on this loop",m=1434,x=32.3,y=27.7,ml=30},{"a",95770,n2="Kin'weelay: the cavern entrance under the Vile Reef, west of the camp",m=1434,x=32.3,y=27.7,ml=30}}},
  {t="The Vile Reef", lv=41, n="Locating the Lost City: west of Grom'gol, swim out over the Vile Reef and dive to the cavern entrance in the reef; the quest completes as you find it. Leave the cavern for now: the jungle stalkers are south along the coast.", w={{k="onquest",q={95770}},{k="complete",neg=true,q=95770}}, g={{"g",0,txt="the Drowned City's entrance, underwater",m=1434,x=21.8,y=27.6}}},
  {t="Jungle stalkers", lv=41, n="The stalker raptors hunt the jungle south of Grom'gol, out towards the west coast.", g={{"o",196,i=1,txt="Kill Jungle Stalker x10",m=1434,x=27.3,y=43.4}}},
  {t="The Cape of Stranglethorn: kill these as you meet them", lv=41, n="Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the Holy Spring bubbles in the hills just east of them.", g={{"o",617,i=1,txt="Akiris Reed x10",m=1434,x=25.1,y=58.8},{"o",573,i=1,txt="Kill Naga Explorer x10",m=1434,x=25.1,y=58.8},{"o",573,i=2,txt="Holy Spring Water",m=1434,x=29,y=61.9}}},
  {t="Booty Bay", lv=41, n="Head south to Booty Bay. Shaky Phillipe waits on the docks.", g={{"t",606,m=1434,x=26.9,y=73.6},{"a",607,m=1434,x=26.9,y=73.6,ml=30},{"b",0,txt="Set your hearthstone at Booty Bay",n2="Innkeeper Skindle, upstairs",m=1434,x=27,y=77.3,at="Booty Bay"},{"a",580,n2="Whiskey Slim, in the inn: his bottles wash up on the Hinterlands coast, around level 48",m=1434,x=27.1,y=77.5,ml=40},{"t",617,m=1434,x=26.8,y=76.4},{"t",600,n2="Inside",m=1434,x=27.1,y=77.2},{"a",209,n2="Kebok, upstairs: the tusks come from the Skullsplitters, later on this loop",m=1434,x=27,y=77.1,ml=37},{"t",607,n2="\"Sea Wolf\" MacKinley, on the top floor",m=1434,x=27.8,y=77.1},{"a",2872,n2="MacKinley, on the top floor: for Stoley in Tanaris",m=1434,x=27.8,y=77.1,ml=40},{"a",609,m=1434,x=27.8,y=77.1,ml=30},{"t",348,m=1434,x=27.6,y=76.7},{"t",628,n2="Drizzlik, inside: the Elder Crocolisk Skin",m=1434,x=28.3,y=77.6,opt=true},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Zanzil's camps", lv=41, n="North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture.", g={{"o",621,i=1,txt="Zanzil's Mixture x12",m=1434,x=38.7,y=59.8}}},
  {t="Pirate ghosts", lv=41, n="The three ghostly pirates haunt the jungle north of Booty Bay, near Zanzil's camps: Maury and Jon-Jon stand together, Chucky further east.", g={{"i",0,txt="Kill Chucky \"Ten Thumbs\"",m=1434,x=40,y=58.2},{"o",609,i=3,txt="Chucky's Huge Ring",m=1434,x=40,y=58.2},{"i",0,txt="Kill Maury \"Club Foot\" Wilkins",m=1434,x=35.3,y=51.3},{"o",609,i=1,txt="Maury's Clubbed Foot",m=1434,x=35.3,y=51.3},{"i",0,txt="Kill Jon-Jon the Crow",m=1434,x=34.9,y=51.8},{"o",609,i=2,txt="Jon-Jon's Golden Spyglass",m=1434,x=34.9,y=51.8}}},
  {t="Zul'Mamwe", lv=41, n="Head north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. Ana'thek the Cruel guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all.", g={{"g",0,txt="Skullsplitter warriors",m=1434,x=45.4,y=36.2},{"o",209,i=1,txt="Skullsplitter Tusk x18",m=1434,x=45.4,y=36.2},{"o",586,i=1,txt="Kill Skullsplitter Hunter x8",n2="Skullsplitter Hunter walks around here: look inside the circle on the map",m=1434,x=45.6,y=38.6},{"o",586,i=2,txt="Kill Skullsplitter Headhunter x6",m=1434,x=47.7,y=42.5},{"o",586,i=3,txt="Kill Skullsplitter Berserker x4",m=1434,x=47.9,y=43},{"o",586,i=4,txt="Broken Armor of Ana'thek",n2="Below ground",m=1434,x=44.3,y=45},{"o",585,i=3,txt="Zul'Mamwe Trophy",m=1434,x=47.6,y=39.5}}},
  {t="Balia'mah Ruins: kill these as you meet them", lv=41, n="The next trophy skulls stand in the small ruins just north of the warriors' camp.\nThe last skulls are in the ruins a short walk west, on the way back to Grom'gol.", g={{"o",598,i=1,txt="Split Bone Necklace x25",m=1434,x=47.4,y=39},{"o",585,i=1,txt="Balia'mah Trophy",m=1434,x=46.1,y=32.3},{"o",585,i=2,txt="Ziata'jai Trophy",m=1434,x=42.2,y=36.1}}},
  {t="Grom'gol Base Camp", lv=41, n="Head west to Grom'gol.", g={{"t",598,m=1434,x=32.3,y=27.7},{"t",95770,m=1434,x=32.3,y=27.7},{"t",586,n2="the Bubbling Cauldron",m=1434,x=32.2,y=27.6},{"t",585,m=1434,x=32.2,y=27.6},{"a",588,n2="the Bubbling Cauldron again: Yenniku's fate",m=1434,x=32.2,y=27.6,ml=30},{"t",588,m=1434,x=32.3,y=27.7},{"a",589,n2="Kin'weelay: the basilisks graze beside the road back from Booty Bay",m=1434,x=32.3,y=27.7,ml=30},{"t",573,m=1434,x=32.1,y=29.2}}},
  {t="Fly to Booty Bay", lv=41, g={{"g",0,txt="Grom'gol flight master",m=1434,x=32.5,y=29.3},{"z",0,txt="Fly to Booty Bay",at="Booty Bay"}}},
  {t="Booty Bay", lv=41, g={{"t",609,n2="\"Sea Wolf\" MacKinley, on the top floor",m=1434,x=27.8,y=77.1},{"t",621,n2="Crank Fizzlebub, inside",m=1434,x=27.1,y=77.2},{"t",209,n2="Kebok, upstairs",m=1434,x=27,y=77.1},{"a",2864,n2="Krazek, upstairs: for Tran'rek in Gadgetzan",m=1434,x=26.9,y=77.2,ml=40}}},
  {t="Ironjaw Basilisks", lv=41, n="Ride north out of Booty Bay along the road; the basilisks bask on the rocks east of it in the middle of the jungle, on the way back to Grom'gol. Their shards drop often.", g={{"o",589,i=1,txt="Pulsing Blue Shard x3",n2="Below ground",m=1434,x=42.6,y=49.4}}},
  {t="Grom'gol Base Camp", lv=41, n="Ride on north to Grom'gol.", g={{"t",589,m=1434,x=32.3,y=27.7}}},
  {t="Stranglethorn Vale", lv=41, g={{"g",0,txt="Nesingwary's Expedition",m=1434,x=35.7,y=10.8}}},
  {t="Nesingwary's Expedition", lv=41, n="Head north up the road to the hunters' camp.", g={{"t",196,m=1434,x=35.7,y=10.8}}},
  {t="Nesingwary's Expedition", lv=41, w={{k="group",q=197}}, g={{"a",197,m=1434,x=35.7,y=10.8,ml=28}}},
  {t="Raptor Mastery", lv=41, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Tethis is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=197}}, g={{"o",197,i=1,txt="Talon of Tethis",m=1434,x=31.5,y=41.2,grp=true}}},
  {t="Panther Mastery", lv=41, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Bhag'thera is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=193}}, g={{"o",193,i=1,txt="Fang of Bhag'thera",m=1434,x=49.4,y=24,grp=true}}},
  {t="Sir S. J. Erlgadin", lv=41, w={{k="group",q=193}}, g={{"t",193,m=1434,x=35.5,y=10.6}}},
  {t="Hemet Nesingwary", lv=41, w={{k="group",q=197}}, g={{"t",197,m=1434,x=35.7,y=10.8}}},
  {t="Hemet Nesingwary", lv=41, w={{k="group",q=208}}, g={{"a",208,m=1434,x=35.7,y=10.8,ml=28}}},
  {t="Level 42.68", lv=42, n="If you skipped Panther Mastery or Raptor Mastery, grind here to level 42.68 to stay on the route's plan. Or, with a group, run the Uldaman dungeon instead.", w={{k="level",op="<",n=42,frac=0.68}}, g={{"g",0,txt="Skullsplitter Warrior",m=1434,x=42.5,y=35.7},{"l",42,txt="Reach level 42 (68% in): grind Skullsplitter Warrior",n2="grind on Skullsplitter Warrior",m=1434,x=42.4,y=35,fr=0.68}}},
  {t="Big Game Hunter", lv=42, n="These are elite mobs: grouping up is encouraged, look for people to do it with. King Bangalash is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, King Bangalash calls for help from creatures within 20 yd.", w={{k="group",q=208}}, g={{"o",208,i=1,txt="Head of Bangalash",m=1434,x=38.2,y=35.6,grp=true}}},
  {t="Hemet Nesingwary", lv=42, w={{k="group",q=208}}, g={{"t",208,m=1434,x=35.7,y=10.8}}},
  {t="Level 42.74", lv=42, n="If you skipped Big Game Hunter, grind here to level 42.74 to stay on the route's plan. Or, with a group, run the Uldaman dungeon instead.", w={{k="group",neg=true,q=208},{k="level",op="<",n=42,frac=0.74}}, g={{"g",0,txt="Skullsplitter Warrior",m=1434,x=42.5,y=35.7},{"l",42,txt="Reach level 42 (74% in): grind Skullsplitter Warrior",n2="grind on Skullsplitter Warrior",m=1434,x=42.4,y=35,fr=0.74}}},
  {t="Duskwood", lv=42, g={{"g",0,txt="Deathstalker Zraedus",m=1431,x=87.8,y=35.6}}},
  {t="Deathstalker Zraedus", lv=42, g={{"a",1372,m=1431,x=87.8,y=35.6,ml=37},{"t",1372,m=1431,x=87.5,y=35.2}}},
  {t="Swamp of Sorrows", lv=42, g={{"g",0,txt="Magtoor",m=1435,x=26,y=31.4}}},
  {t="Into the Swamp of Sorrows", lv=42, n="Follow the road east from Duskwood through Deadwind Pass into the swamp. Magtoor waits at the Harborage, the draenei camp just off the road where it comes in from Deadwind Pass.", g={{"a",1389,m=1435,x=26,y=31.4,ml=30}}},
  {t="Stonard", lv=42, n="Head east to Stonard, in the reeds south of the road. Bind here.", g={{"a",698,n2="Dar, inside",m=1435,x=44.7,y=57.2,ml=35},{"a",1430,n2="Dar, inside",m=1435,x=44.7,y=57.2,ml=35},{"fp",56,txt="Get the Stonard flight path (Breyk)",m=1435,x=46.1,y=54.8},{"t",1420,n2="Helgrum the Swift, upstairs",m=1435,x=47.7,y=55.2},{"b",0,txt="Set your hearthstone at Stonard",n2="Innkeeper Karakul, upstairs",m=1435,x=45.2,y=56.7,at="Stonard"},{"a",1424,n2="Fel'zerul, on the top floor",m=1435,x=47.9,y=54.8,ml=38}}},
  {t="Sawtooth crocolisks", lv=42, n="The crocolisks wallow in the pools around Galen's camp and south towards Stonard; about one in four drops a flank.", g={{"o",698,i=1,txt="Unprepared Sawtooth Flank x8",m=1435,x=53.6,y=56}}},
  {t="Noboru the Cudgel", lv=42, n="Noboru wanders the clearing south-west of the Fallow Sanctuary; his cudgel starts a quest.", g={{"i",0,txt="Kill Noboru the Cudgel",m=1435,x=54.9,y=34.1},{"h",6196,txt="Get Noboru's Cudgel",m=1435,x=54.9,y=34.1,n=1},{"a",1392,ml=29}}},
  {t="Draenethyst crystals", lv=42, n="Ride north-east to the Fallow Sanctuary. The crystals stand along the way up to Galen Goodward's cage.", g={{"o",1389,i=1,txt="Draenethyst Crystal x6",m=1435,x=55.1,y=30.1}}},
  {t="Galen's Escape", lv=42, n="Galen Goodward is held in the Fallow Sanctuary in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him.", g={{"a",1393,m=1435,x=65.5,y=18.2,ml=30},{"c",1393,txt="Escort Galen out of the Fallow Sanctuary."}}},
  {t="Galen's Strongbox", lv=42, n="His strongbox waits at his old camp north of Stonard, on the way back west.", g={{"t",1393,m=1435,x=47.8,y=39.8}}},
  {t="The Harborage", lv=42, n="Ride west along the road to the draenei camp at the Harborage, near the way in from Deadwind Pass. Lack of Surplus goes to Tok'Kar at Misty Reed Post on the next swamp visit: keep the flanks.", g={{"t",1392,m=1435,x=26,y=31.4},{"t",1389,m=1435,x=26,y=31.4}}},
} end)

R:Segment({id="horde/40-50/02-feralas",title="Feralas & Tanaris",faction="Horde",min=43,max=45,zone=1444,zoneName="Feralas",next="horde/40-50/03-feralas"}, function() return {
  {t="Swamp of Sorrows", lv=43, g={{"g",0,txt="Stonard",m=1435,x=46.1,y=54.7}}},
  {t="Fly to Grom'gol", lv=43, g={{"g",0,txt="Stonard flight master",m=1435,x=46.1,y=54.7},{"z",0,txt="Fly to Grom'gol",at="Grom'gol"}}},
  {t="Zeppelin to Orgrimmar", lv=43, g={{"g",0,txt="Zeppelin to Orgrimmar",m=1434,x=31.4,y=29.9}}},
  {t="Orgrimmar", lv=43, g={{"g",0,txt="The middle of Orgrimmar",m=1454,x=51.5,y=45.6}}},
  {t="Orgrimmar", lv=43, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}},{"a",3631,n2="Zevrost, Cleft of Shadow",m=1454,x=48.5,y=45.4,f={c={"WARLOCK"}},ml=40}}},
  {t="Riding at 40", lv=43, n="Riding needs level 40 and costs 100 gold; learning it gives you a mount. Kildar teaches Orcs in the Valley of Honor, by Ogunaro Wolfrunner's kennel. Skyborne learn it from Genn Fairweather at the Fairweather Stables in Valanaar on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of Skywatcher Plateau, north of Thunder Bluff, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each.", w={{k="level",op=">=",n=40}}, f={r={"Orc","Skyborne"}}, g={{"tr",0,txt="Train with Kildar",n2="Kildar, riding trainer",m=1454,x=69.4,y=13.1,opt=true,f={r={"Orc"}}},{"i",0,txt="Wolves: Ogunaro Wolfrunner, beside Kildar.",f={r={"Orc"}}},{"i",0,txt="Riding and Galestriders: Genn Fairweather, at the Fairweather Stables in Valanaar on Zephras Isle.",f={r={"Skyborne"}}}}},
  {t="Belgrom Rockmaul", lv=43, g={{"a",2981,m=1454,x=75.2,y=34.2,ml=38}}},
  {t="Riding at 40", lv=43, n="Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is Xar'Ti in Sen'jin Village, a short ride south of Orgrimmar down the Durotar road, with Zjolnir's raptors (20 gold each) beside him. Ride back to Orgrimmar's flight master afterwards.", w={{k="level",op=">=",n=40}}, f={r={"Troll"}}, g={{"tr",0,txt="Train with Xar'Ti",n2="Xar'Ti, riding trainer",m=1411,x=55.3,y=75.5,opt=true},{"i",0,txt="Raptors: Zjolnir, beside Xar'Ti in Sen'jin Village."}}},
  {t="Fly to Thunder Bluff", lv=43, f={c={"PALADIN","DRUID"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Fly to Thunder Bluff", lv=43, w={{k="level",op=">=",n=40}}, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"},r={"Tauren"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Thunder Bluff", lv=43, n="Your trainer is in Thunder Bluff: Turak Runetotem (Druids) on Elder Rise, Alodan the Hopeful (Paladins).", f={c={"PALADIN","DRUID"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Mulgore", lv=43, w={{k="level",op=">=",n=40}}, f={r={"Tauren"}}, g={{"g",0,txt="Bloodhoof Village",m=1412,x=46.8,y=62}}},
  {t="Riding at 40", lv=43, n="Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is Kar Stormsinger in Bloodhoof Village, with Harb Clawhoof's kodos (20 gold each) beside him. Ride back up to Thunder Bluff's flight master afterwards.", w={{k="level",op=">=",n=40}}, f={r={"Tauren"}}, g={{"tr",0,txt="Train with Kar Stormsinger",n2="Kar Stormsinger, riding trainer",m=1412,x=46.8,y=62,opt=true},{"i",0,txt="Kodos: Harb Clawhoof, beside Kar Stormsinger in Bloodhoof Village."}}},
  {t="Fly to Freewind Post", lv=43, f={c={"PALADIN","DRUID"}}, g={{"g",0,txt="Thunder Bluff flight master",m=1456,x=46.7,y=49.9},{"z",0,txt="Fly to Freewind Post",at="Freewind Post"}}},
  {t="Fly to Freewind Post", lv=43, w={{k="level",op=">=",n=40}}, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"},r={"Tauren"}}, g={{"g",0,txt="Thunder Bluff flight master",m=1456,x=46.7,y=49.9},{"z",0,txt="Fly to Freewind Post",at="Freewind Post"}}},
  {t="Ratchet for the Felsteed", lv=43, n="Fly from Orgrimmar to Ratchet; Strahad Farsan stands on the hill above the docks.", f={c={"WARLOCK"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Ratchet",at="Ratchet"},{"t",3631,m=1413,x=62.6,y=35.5},{"a",4490,m=1413,x=62.6,y=35.5,ml=40},{"t",4490,m=1413,x=62.6,y=35.5}}},
  {t="Fly to Freewind Post", lv=43, f={c={"WARLOCK"}}, g={{"g",0,txt="Ratchet flight master",m=1413,x=63.1,y=37.1},{"z",0,txt="Fly to Freewind Post",at="Freewind Post"}}},
  {t="Fly to Freewind Post", lv=43, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE"},r={"Orc","Troll","Scourge","Skyborne"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Freewind Post",at="Freewind Post"}}},
  {t="Fly to Freewind Post", lv=43, w={{k="level",op="<",n=40}}, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE"},r={"Tauren"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Freewind Post",at="Freewind Post"}}},
  {t="Mirage Raceway", lv=43, n="The road from Freewind Post to Tanaris runs past the Mirage Raceway on the Shimmering Flats: Fizzle Brassbolts is in the gnomes' camp beside the track, Pozzik and Zamek by the goblins' camp. Pozzik first, then Zamek, who runs off to keep Rizzle busy; then take Rizzle's plans from the gnomes' camp and bring them back to Pozzik.", g={{"t",1137,n2="Fizzle Brassbolts: News for Fizzle, from Martek in the Badlands",m=1441,x=78.1,y=77.1},{"a",1190,m=1441,x=80.2,y=75.9,ml=29},{"t",1183,n2="Pozzik: the Fuel Regulator Blueprints from Baron Revilgaz, if you carry them",m=1441,x=80.2,y=75.9},{"a",1186,m=1441,x=80.2,y=75.9,ml=29},{"t",1186,n2="Razzeric, beside Pozzik",m=1441,x=80.3,y=76.1},{"t",1191,m=1441,x=79.8,y=77},{"t",1190,m=1441,x=77.2,y=77.4},{"a",1194,m=1441,x=77.2,y=77.4,ml=29},{"t",1194,m=1441,x=80.2,y=75.9}}},
  {t="To Gadgetzan", lv=43, g={{"g",0,txt="Gadgetzan",m=1446,x=50.2,y=27.5}}},
  {t="Gadgetzan", lv=43, n="Gadgetzan is the walled goblin town just past the Tanaris border.", g={{"fp",40,txt="Get the Gadgetzan flight path (Bulkrek Ragefist)",m=1446,x=51.6,y=25.4},{"a",992,m=1446,x=50.2,y=27.5,ml=38},{"t",2864,m=1446,x=51.6,y=26.8},{"a",1690,m=1446,x=52.5,y=28.5,ml=40},{"a",1707,m=1446,x=52.5,y=28.4,ml=40}}},
  {t="Noonshade Ruins: kill these as you meet them", lv=43, n="The bandits and thieves camp in the dunes east of Gadgetzan. Every Wastewander can carry a water pouch: keep ten, five for each of Luglunket's bounties.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen.", g={{"o",1707,i=1,txt="Wastewander Water Pouch x5",m=1446,x=59,y=23.4},{"h",8483,txt="Get Wastewander Water Pouch x10",n2="water pouches in your bags",m=1446,x=59,y=23.4,n=10},{"o",1690,i=2,txt="Kill Wastewander Thief x10",m=1446,x=59,y=23.4},{"o",1690,i=1,txt="Kill Wastewander Bandit x10",m=1446,x=59.4,y=24.7}}},
  {t="Gadgetzan", lv=43, g={{"t",1690,m=1446,x=52.5,y=28.5},{"a",1691,m=1446,x=52.5,y=28.5,ml=40},{"t",1707,m=1446,x=52.5,y=28.4}}},
  {t="Steamwheedle Port", lv=43, n="Ride north-east to the goblin harbour on the coast.", g={{"a",8365,m=1446,x=66.6,y=22.3,ml=40},{"a",2781,m=1446,x=66.8,y=22.3,ml=39},{"a",2875,m=1446,x=66.8,y=22.3,ml=40},{"a",8366,n2="Security Chief Bilgewhizzle, inside",m=1446,x=67.1,y=23.9,ml=40},{"t",2872,n2="Stoley, inside",m=1446,x=67.1,y=24},{"a",2873,m=1446,x=67.1,y=24,ml=40},{"a",3520,n2="Yeh'kinya: the screechers live in Feralas, on the next Feralas visit",m=1446,x=67,y=22.4,ml=40}}},
  {t="Lost Rigger Cove: kill these as you meet them", lv=43, n="South along the coast, the Southsea pirates hold the cove. Andre Firebeard and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often.\nCareful: Two or three pirates stand with Andre, and many more pirates from the town join the fight once it starts.", g={{"o",8366,i=1,txt="Kill Southsea Pirate x10",m=1446,x=70.9,y=42.5},{"o",8365,i=1,txt="Southsea Pirate Hat x20",m=1446,x=70.9,y=42.5},{"o",8366,i=2,txt="Kill Southsea Freebooter x10",m=1446,x=71,y=43.1},{"o",8366,i=4,txt="Kill Southsea Swashbuckler x10",m=1446,x=72.2,y=46.6},{"o",2873,i=1,txt="Stoley's Shipment",n2="Upstairs",m=1446,x=72.1,y=46.7},{"o",8366,i=3,txt="Kill Southsea Dock Worker x10",m=1446,x=72.9,y=47.8},{"o",2875,i=1,txt="Firebeard's Head",m=1446,x=73.4,y=47.1}}},
  {t="Waterspring Field: kill these as you meet them", lv=43, n="The shadow mages, rogues and assassins camp south-east of Gadgetzan.\nSouth-east of Gadgetzan the Wastewander bandits camp in the dunes; Caliph stands in the eastern camp.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them.", g={{"o",1691,i=3,txt="Kill Wastewander Shadow Mage x10",m=1446,x=65.2,y=40},{"o",1691,i=2,txt="Kill Wastewander Assassin x6",m=1446,x=64.7,y=40},{"o",1691,i=1,txt="Kill Wastewander Rogue x8",m=1446,x=64.6,y=39.3},{"o",2781,i=1,txt="Caliph Scorpidsting's Head",m=1446,x=61.8,y=38.2}}},
  {t="Steamwheedle Port", lv=43, n="Ride north-east back to the port: Stoley, the Haughty Modiste and the Security Chief take what Lost Rigger Cove gave you. Gadgetzan is west of it.", g={{"t",8365,m=1446,x=66.6,y=22.3},{"t",2873,n2="Stoley, inside",m=1446,x=67.1,y=24},{"a",2874,n2="for Booty Bay, around level 50",m=1446,x=67.1,y=24,ml=40},{"t",2875,n2="Security Chief Bilgewhizzle, inside",m=1446,x=67.1,y=23.9},{"t",8366,m=1446,x=67.1,y=23.9}}},
  {t="Gadgetzan", lv=43, g={{"t",1878,m=1446,x=52.5,y=28.4},{"t",2781,m=1446,x=52.5,y=28.5},{"t",1691,m=1446,x=52.5,y=28.5},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Fly to Freewind Post", lv=43, g={{"g",0,txt="Gadgetzan flight master",m=1446,x=51.6,y=25.5},{"z",0,txt="Fly to Freewind Post",at="Freewind Post"}}},
  {t="Feralas", lv=43, g={{"g",0,txt="Camp Mojache",m=1444,x=75.7,y=44.3}}},
  {t="Camp Mojache", lv=43, g={{"fp",42,txt="Get the Camp Mojache flight path (Shyn)",m=1444,x=75.5,y=44.4},{"b",0,txt="Set your hearthstone at Camp Mojache",m=1444,x=74.8,y=45.2,at="Camp Mojache"},{"a",2987,m=1444,x=75.7,y=44.3,ml=38},{"t",2981,n2="Rok Orhan walks around Camp Mojache: look inside the circle on the map",m=1444,x=75.8,y=43.6},{"a",2975,m=1444,x=75.8,y=43.6,ml=38},{"a",3121,n2="Witch Doctor Uzer'i: for Orgrimmar, around level 45",m=1444,x=74.4,y=43.4,ml=40},{"a",2822,n2="Jangdor Swiftstrider, inside",m=1444,x=74.4,y=42.9,ml=40},{"b",0,txt="Set your hearthstone at Camp Mojache",m=1444,x=74.8,y=45.2,at="Camp Mojache"},{"a",2862,m=1444,x=74.9,y=42.5,ml=39},{"a",2973,m=1444,x=75.9,y=42.7,ml=38}}},
  {t="Gordunni Outpost", lv=43, n="North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it.", g={{"o",2987,i=1,txt="Use Orwin's Shovel",m=1444,x=74.5,y=30.2},{"o",2987,i=1,txt="Gordunni Cobalt x12",m=1444,x=74.6,y=30.2},{"o",2975,i=1,txt="Kill Gordunni Ogre x10",m=1444,x=75.2,y=29.6},{"o",2975,i=2,txt="Kill Gordunni Ogre Mage x10",m=1444,x=74.8,y=29.3},{"o",2975,i=3,txt="Kill Gordunni Brute x5",m=1444,x=74.7,y=29.6},{"h",9370,txt="Get Gordunni Scroll",m=1444,x=75.1,y=29.7,n=1},{"a",2978,ml=38}}},
  {t="Woodpaw north camp", lv=43, n="The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane.\nCareful: Every Woodpaw gnoll except the Alpha runs off for help at 15% health, which can pull more gnolls into the fight.", g={{"o",2862,i=1,txt="Woodpaw Gnoll Mane x10",m=1444,x=73.2,y=35.6}}},
  {t="Camp Mojache", lv=43, g={{"t",2862,m=1444,x=74.9,y=42.5},{"a",2863,n2="Alpha Strike: one hour from now",m=1444,x=74.9,y=42.5,ml=39},{"t",2975,n2="Rok Orhan walks around Camp Mojache: look inside the circle on the map",m=1444,x=75.8,y=43.6},{"t",2978,m=1444,x=75.8,y=43.6},{"a",2979,m=1444,x=75.8,y=43.6,ml=38},{"a",2980,m=1444,x=75.8,y=43.6,ml=38},{"t",2987,m=1444,x=75.7,y=44.3}}},
  {t="Feralas: kill these as you meet them", lv=43, n="The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps.", g={{"o",2973,i=1,txt="Iridescent Sprite Darter Wing x10",m=1444,x=70.2,y=46.6},{"o",2863,i=1,txt="Kill Woodpaw Alpha x5",m=1444,x=66.1,y=51.6}}},
  {t="Camp Mojache", lv=43, g={{"t",2973,m=1444,x=75.9,y=42.7},{"a",2974,m=1444,x=75.9,y=42.7,ml=38},{"t",2863,m=1444,x=74.9,y=42.5},{"a",2902,m=1444,x=74.9,y=42.5,ml=39}}},
  {t="Grimtotem camp", lv=43, n="The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns.", g={{"o",2974,i=1,txt="Grimtotem Horn x20",m=1444,x=69.9,y=40}}},
  {t="Woodpaw battle map", lv=43, n="The battle map lies in the Woodpaw camp south of Mojache.", g={{"t",2902,m=1444,x=71.6,y=55.9},{"a",2903,m=1444,x=71.6,y=55.9,ml=39}}},
  {t="Camp Mojache", lv=43, g={{"t",2974,m=1444,x=75.9,y=42.7},{"a",2976,n2="for Orgrimmar, around level 45",m=1444,x=75.9,y=42.7,ml=37},{"t",2903,m=1444,x=74.9,y=42.5},{"a",7730,m=1444,x=74.9,y=42.5,ml=39},{"a",7731,m=1444,x=74.9,y=42.5,ml=39}}},
  {t="The Writhing Deep", lv=43, n="The Zukk'ash hive burrows into the hills south-east of the camp; Stinglasher waits in its deepest chamber.", g={{"o",7730,i=1,txt="Zukk'ash Carapace x20",m=1444,x=76.2,y=59.2},{"o",7731,i=1,txt="Stinglasher's Glands",m=1444,x=75.6,y=60.9}}},
  {t="Ruins of Isildien: kill these as you meet them", lv=43, n="Ride west from the hive to the ogre ruins below Feral Scar Vale. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb.", g={{"o",2980,i=3,txt="Kill Gordunni Mauler x5",n2="Gordunni Mauler walks around Ruins of Isildien: look inside the circle on the map",m=1444,x=61.8,y=54.6},{"o",2980,i=2,txt="Kill Gordunni Warlock x10",m=1444,x=61.8,y=55.7},{"o",2980,i=1,txt="Kill Gordunni Shaman x10",m=1444,x=60,y=63.3},{"o",2979,i=1,txt="Gordunni Orb",m=1444,x=60.3,y=67.2}}},
  {t="Feral Scar Vale yetis", lv=43, n="North-west of the ruins, the yetis den in Feral Scar Vale; every yeti there can drop a thick hide.", g={{"o",2822,i=1,txt="Thick Yeti Hide x10",m=1444,x=55.9,y=58.8}}},
  {t="Homing Robot OOX-22/FE", lv=43, n="Only with the distress beacon: any beast, gnoll or ogre in Feralas can drop it, about one kill in a hundred; use it to start the quest. The robot sits in a small cave on the north side of Feral Scar Vale, just north-west of the ruins. Escort it to the dock on the Forgotten Coast; yetis and gorillas ambush you on the way. Its reward waits in Booty Bay for a later visit.\nCareful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock.", g={{"h",8705,txt="Get OOX-22/FE Distress Beacon",m=1444,x=55.3,y=53.8,n=1,opt=true},{"a",2766,opt=true,ml=40},{"t",2766,m=1444,x=53.4,y=55.7,opt=true},{"a",2767,m=1444,x=53.4,y=55.7,opt=true,ml=40},{"c",2767,txt="Escort OOX-22/FE to the dock along the Forgotten Coast",opt=true}}},
  {t="Camp Mojache", lv=43, g={{"t",7730,m=1444,x=74.9,y=42.5},{"t",7731,m=1444,x=74.9,y=42.5},{"i",0,txt="Sell and repair",opt=true},{"t",2822,n2="Jangdor Swiftstrider, inside",m=1444,x=74.4,y=42.9},{"a",7734,n2="the Rage Scar yetis, on the next visit to Feralas",m=1444,x=74.4,y=42.9,ml=40},{"a",7732,n2="Hadoken Swiftstrider: for Zilzibin Drumlore in Orgrimmar",m=1444,x=74.9,y=42.5,ml=39},{"t",2980,n2="Rok Orhan walks around Camp Mojache: look inside the circle on the map",m=1444,x=75.8,y=43.6},{"t",2979,m=1444,x=75.8,y=43.6},{"a",3002,n2="for Orgrimmar, around level 45",m=1444,x=75.8,y=43.6,ml=38}}},
  {t="Fly to Orgrimmar", lv=43, g={{"g",0,txt="Camp Mojache flight master",m=1444,x=75.4,y=44.3},{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"}}},
  {t="Orgrimmar", lv=43, n="Fly to Orgrimmar. From the flight master: the Cleft of Shadow, then the Drag, then the Valley of Honor.", g={{"t",3121,n2="Neeru Fireblade, Cleft of Shadow",m=1454,x=49.5,y=50.6},{"a",3122,m=1454,x=49.5,y=50.6,ml=40},{"t",7732,n2="Zilzibin Drumlore, the Drag",m=1454,x=56.3,y=46.7},{"a",649,n2="Dran Droffers, the Drag",m=1454,x=59.5,y=36.6,ml=42},{"t",649,m=1454,x=59.6,y=36.9},{"a",650,n2="for the Hinterlands, around level 48",m=1454,x=59.6,y=36.9,ml=42},{"t",2976,n2="Belgrom Rockmaul, Valley of Honor",m=1454,x=75.2,y=34.2},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}}}},
  {t="Orgrimmar", lv=43, w={{k="onquest",q={3002}}}, g={{"t",3002,n2="Uthel'nay, Valley of Spirits",m=1454,x=39.2,y=86.3}}},
} end)

R:Segment({id="horde/40-50/03-feralas",title="Feralas, Dustwallow Marsh & Swamp of Sorrows",faction="Horde",min=45,max=47,zone=1444,zoneName="Feralas",next="horde/40-50/04-tanaris"}, function() return {
  {t="Zeppelin to Undercity", lv=45, g={{"g",0,txt="Zeppelin to Undercity",m=1411,x=50.8,y=13.5}}},
  {t="Apothecary Zinge", lv=45, g={{"a",232,m=1458,x=50.1,y=68,ml=38},{"t",232,m=1458,x=58.6,y=54.7},{"a",238,m=1458,x=58.6,y=54.7,ml=38},{"t",728,n2="Keeper Bel'dugur, on the way back to Zinge",m=1458,x=53.7,y=54.5},{"t",238,m=1458,x=50.1,y=68},{"a",243,m=1458,x=50.1,y=68,ml=38},{"h",8523,txt="Get Field Testing Kit",n2="the Field Testing Kit from these errands: keep it, Tanaris Field Sampling hands it back in Gadgetzan",m=1458,x=58.6,y=54.7,n=1}}},
  {t="Undercity", lv=45, g={{"a",2995,n2="Oran Snakewrithe, the Royal Quarter",m=1458,x=73.1,y=32.9,ml=42},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","PALADIN","ROGUE","PRIEST","MAGE","WARLOCK"}}}}},
  {t="Riding at 40", lv=45, n="Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is Velma Warnam in Brill, a short ride north of the zeppelin towers, with Zachariah Post's skeletal horses (20 gold each) beside her. Ride back to the towers for the Grom'gol zeppelin.", w={{k="level",op=">=",n=40}}, f={r={"Scourge"}}, g={{"tr",0,txt="Train with Velma Warnam",n2="Velma Warnam, riding trainer",m=1420,x=60.1,y=52.6,opt=true},{"i",0,txt="Skeletal horses: Zachariah Post, beside Velma Warnam in Brill."}}},
  {t="Zeppelin to Grom'gol", lv=45, g={{"g",0,txt="Zeppelin to Grom'gol",m=1420,x=61.8,y=59.2}}},
  {t="Fly to Stonard", lv=45, g={{"g",0,txt="Grom'gol flight master",m=1434,x=32.5,y=29.3},{"z",0,txt="Fly to Stonard",at="Stonard"}}},
  {t="Stonard", lv=45, n="Coming from Stranglethorn, you carry these already. Starting here: Dar stands inside Stonard's great hall and Fel'zerul on its top floor.", g={{"a",698,n2="Dar, inside",m=1435,x=44.7,y=57.2,ml=35},{"a",1430,n2="Dar, inside",m=1435,x=44.7,y=57.2,ml=35},{"a",1424,n2="Fel'zerul, on the top floor",m=1435,x=47.9,y=54.8,ml=38}}},
  {t="A Soggy Scroll", lv=45, n="Ride west along the road; the scroll lies at the water's edge in the swamp's far west.", w={{k="onquest",q={624}}}, g={{"t",624,m=1435,x=22.9,y=48.2},{"a",625,n2="for the Musty Scroll in Dustwallow Marsh, later in this guide",m=1435,x=22.9,y=48.2,opt=true,ml=35}}},
  {t="Sawtooth crocolisks", lv=45, n="The crocolisks wallow in the pools around Galen's old camp, just north of Stonard, on the way back east; about one in four drops a flank.", g={{"o",698,i=1,txt="Unprepared Sawtooth Flank x8",m=1435,x=47.5,y=43}}},
  {t="Pool of Tears", lv=45, n="Back east past Stonard: the Atal'ai artifacts lie in the water and on the banks of the Pool of Tears.", g={{"o",1424,i=1,txt="Atal'ai Artifact x10",m=1435,x=62.4,y=52.9}}},
  {t="Misty Reed Post", lv=45, n="Follow the road south-east to the small Horde post on the shore. Tok'Kar takes the crocolisk flanks from the last swamp visit.", g={{"t",698,m=1435,x=81.3,y=81},{"a",699,m=1435,x=81.3,y=81,ml=35}}},
  {t="The Forbidding Sea: kill these as you meet them", lv=45, n="The snappers line the strand south of the post.\nThe Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see, the ones on the ride down from the pool too.", g={{"o",699,i=1,txt="Sawtooth Snapper Claw x6",m=1435,x=83.8,y=95.4},{"o",1430,i=1,txt="Monstrous Crawler Leg x10",n2="Underwater",m=1435,x=85,y=97.2}}},
  {t="Misty Reed Post", lv=45, g={{"t",699,m=1435,x=81.3,y=81},{"a",1422,m=1435,x=81.3,y=81,ml=35},{"t",1422,m=1435,x=83.8,y=80.4},{"a",1426,m=1435,x=83.8,y=80.4,ml=35}}},
  {t="Murlocs of the Misty Reed", lv=45, n="The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore.", g={{"o",1426,i=1,txt="Kill Marsh Murloc x10",m=1435,x=87.1,y=80.7},{"o",1426,i=3,txt="Kill Marsh Flesheater x10",n2="Below ground",m=1435,x=71.8,y=97.6},{"o",1426,i=2,txt="Kill Marsh Inkspewer x10",m=1435,x=68.9,y=96.9}}},
  {t="Misty Reed Post", lv=45, g={{"t",1426,m=1435,x=83.8,y=80.4},{"a",1427,m=1435,x=83.8,y=80.4,ml=35},{"t",1427,m=1435,x=81.3,y=81},{"a",1428,m=1435,x=83.8,y=80.4,ml=35}}},
  {t="Continued Threat", lv=45, n="The same murloc shore again: Inkspewers east of the post, Flesheaters around the western huts, and the Oracles among both.", g={{"o",1428,i=1,txt="Kill Marsh Inkspewer x10",m=1435,x=85.3,y=82.9},{"o",1428,i=2,txt="Kill Marsh Flesheater x10",m=1435,x=71.8,y=97.6},{"o",1428,i=3,txt="Kill Marsh Oracle x10",m=1435,x=63.6,y=86.8}}},
  {t="Misty Reed Post", lv=45, g={{"t",1428,m=1435,x=83.8,y=80.4}}},
  {t="Stonard", lv=45, g={{"t",1424,n2="Fel'zerul, on the top floor",m=1435,x=47.9,y=54.8},{"a",1429,n2="for the Atal'ai Exile in the Hinterlands, around level 48",m=1435,x=47.9,y=54.8,ml=38},{"t",1430,n2="Dar, inside",m=1435,x=44.7,y=57.2}}},
  {t="To Camp Mojache", lv=45, g={{"g",0,txt="Camp Mojache",m=1444,x=74.8,y=45.2}}},
  {t="Camp Mojache", lv=45, g={{"b",0,txt="Set your hearthstone at Camp Mojache",m=1444,x=74.8,y=45.2,at="Camp Mojache"},{"t",3122,m=1444,x=74.4,y=43.4},{"a",3123,n2="for the Hinterlands owlbeasts, around level 48",m=1444,x=74.4,y=43.4,ml=40},{"a",3128,m=1444,x=74.4,y=43.4,ml=40},{"a",3063,m=1444,x=76.2,y=43.8,ml=45}}},
  {t="Fly to Brackenwall Village", lv=45, g={{"g",0,txt="Camp Mojache flight master",m=1444,x=75.4,y=44.3},{"z",0,txt="Fly to Brackenwall Village",at="Brackenwall Village"}}},
  {t="Brackenwall Village", lv=45, n="Overlord Mok'Morokk, Tharg and Draz'Zilb (below ground) are in the village; their quests are for the Wyrmbog on this trip.", g={{"a",1166,m=1445,x=36.3,y=31.4,ml=38},{"a",1168,m=1445,x=37.4,y=31.4,ml=38},{"a",1169,n2="Draz'Zilb, below ground",m=1445,x=37.1,y=33.1,ml=38}}},
  {t="Dustwallow Marsh", lv=45, w={{k="onquest",q={625}}}, g={{"g",0,txt="The Musty Scroll",m=1445,x=31.1,y=66.1}}},
  {t="The Musty Scroll", lv=45, n="Ride south-west to the Musty Scroll.", w={{k="onquest",q={625}}}, g={{"t",625,n2="the Musty Scroll",m=1445,x=31.1,y=66.1},{"a",626,n2="Inside Bloodfen Burrow",m=1445,x=31.1,y=66.1,opt=true,ml=35}}},
  {t="The Dragonmurk: kill these as you meet them", lv=45, n="East through the Wyrmbog: the Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps.", g={{"o",1168,i=2,txt="Kill Firemane Ash Tail x10",m=1445,x=36.8,y=69},{"o",1168,i=3,txt="Kill Firemane Scalebane x5",m=1445,x=36.6,y=69.6},{"o",1168,i=1,txt="Kill Firemane Scout x15",n2="Firemane Scout walks around The Dragonmurk: look inside the circle on the map",m=1445,x=36.8,y=69},{"o",1166,i=3,txt="Mok'Morokk's Strongbox",n2="Below ground",m=1445,x=36.6,y=69.6},{"o",1169,i=1,txt="Searing Tongue x15",m=1445,x=37.4,y=74.2},{"o",1169,i=2,txt="Searing Heart x15",m=1445,x=37.4,y=74.2},{"o",1166,i=2,txt="Mok'Morokk's Grog",m=1445,x=38.7,y=65.6},{"o",1166,i=1,txt="Mok'Morokk's Snuff",m=1445,x=44.5,y=66}}},
  {t="Brackenwall Village", lv=45, n="Ride back north to Brackenwall.", g={{"t",1169,n2="Draz'Zilb, below ground",m=1445,x=37.1,y=33.1},{"a",1170,m=1445,x=37.1,y=33.1,ml=38},{"t",1168,m=1445,x=37.4,y=31.4},{"t",1170,m=1445,x=36.3,y=31.4},{"a",1171,m=1445,x=36.3,y=31.4,ml=38},{"t",1166,m=1445,x=36.3,y=31.4},{"t",1171,m=1445,x=37.1,y=33.1},{"a",1172,m=1445,x=37.1,y=33.1,ml=38}}},
  {t="Onyxia's eggs", lv=45, n="The Eggs of Onyxia lie in the dragon caves in the Wyrmbog's south-east, guarded by the scalebanes; smash five.", g={{"g",0,txt="Dragon caves",m=1445,x=53.4,y=74.7},{"o",1172,i=1,txt="Egg of Onyxia",m=1445,x=53.6,y=72.5}}},
  {t="Level 45.37", lv=45, n="Overlord Mok'Morokk's challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the Wyrmbog's northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the Zul'Farrak dungeon or the Uldaman dungeon instead.", w={{k="group",neg=true,q=1173},{k="level",op="<",n=45,frac=0.37}}, g={{"g",0,txt="Firemane Scout",m=1445,x=37.5,y=68.3},{"l",45,txt="Reach level 45 (37% in): grind Firemane Scout",n2="grind on Firemane Scout",m=1445,x=36.8,y=69,fr=0.37}}},
  {t="Brackenwall Village", lv=45, n="Ride back north to Brackenwall.", g={{"t",1172,n2="Draz'Zilb, below ground",m=1445,x=37.1,y=33.1}}},
  {t="Challenge Overlord Mok'Morokk", lv=45, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Challenge Overlord Mok'Morokk needs a group of 3. Skip it if you are alone: the route has you grind the XP back.\nOverlord Mok'Morokk is elite: grouping up is advised. Beat him down until he gives up, then report to Draz'Zilb.", w={{k="group",q=1173}}, g={{"a",1173,m=1445,x=36.3,y=31.4,ml=38},{"c",1173,txt="Drive Overlord Mok'Morokk from Brackenwall Village"},{"t",1173,n2="Draz'Zilb, below ground",m=1445,x=37.1,y=33.1}}},
  {t="Fly to Camp Mojache", lv=45, g={{"g",0,txt="Brackenwall Village flight master",m=1445,x=35.6,y=31.8},{"z",0,txt="Fly to Camp Mojache",at="Camp Mojache"}}},
  {t="Sprite darters and forest walkers", lv=45, n="The sprite darters flit over the grove just west of the camp and carry the Encrusted Minerals; the Wandering Forest Walkers, a little further west, carry the Splintered Logs.", g={{"o",3128,i=2,txt="Encrusted Minerals x6",m=1444,x=68,y=47.5},{"o",3128,i=1,txt="Splintered Log x2",m=1444,x=54,y=47.2}}},
  {t="Frayfeather hippogryphs", lv=45, n="South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments.", g={{"o",3128,i=3,txt="Resilient Sinew x20",m=1444,x=54.9,y=60.8},{"o",3128,i=4,txt="Metallic Fragments x40",m=1444,x=54.9,y=60.8}}},
  {t="Zorbin Fandazzle", lv=45, n="Ride north-west to the Forgotten Coast; Zorbin waits on the dock.", g={{"a",7003,m=1444,x=44.8,y=43.4,ml=45},{"a",7721,m=1444,x=44.8,y=43.4,ml=45}}},
  {t="Rogue Vale screechers", lv=45, n="Rogue Vale opens just north of Zorbin's dock. Kill a Rogue Vale Screecher, use Yeh'kinya's Bramble on its body and kill the spirit that rises.", g={{"o",3520,i=1,txt="Use Yeh'kinya's Bramble",m=1444,x=45,y=38},{"o",3520,i=1,txt="Kill Screecher Spirit x3",m=1444,x=46,y=37.7}}},
  {t="The Forgotten Coast: kill these as you meet them", lv=45, n="Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with Zorbin's Ultra-Shrinker first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north.", g={{"o",7721,i=1,txt="Water Elemental Core x10",m=1444,x=44.8,y=38.8},{"o",7003,i=1,txt="Miniaturization Residue x15",m=1444,x=40.1,y=38.6},{"o",7003,i=1,txt="Use Zorbin's Ultra-Shrinker",m=1444,x=40.1,y=38.6}}},
  {t="Northspring harpies", lv=45, n="The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time.", g={{"o",3063,i=1,txt="Kill Northspring Harpy x4",m=1444,x=37.8,y=15.9},{"o",3063,i=2,txt="Kill Northspring Roguefeather x4",m=1444,x=37.4,y=15.6},{"o",3063,i=3,txt="Kill Northspring Slayer x4",m=1444,x=37.9,y=15.9},{"o",3063,i=4,txt="Kill Northspring Windcaller x4",m=1444,x=38.6,y=14.3}}},
  {t="Rage Scar yetis", lv=45, n="On the way back south-east from the harpies, the Rage Scar yetis live around the caves in the hills by the road. Any of them can also drop a Perfect Yeti Hide, which starts a quest of its own.", g={{"o",7734,i=1,txt="Rage Scar Yeti Hide x10",m=1444,x=51.8,y=30.8},{"h",18972,txt="Get Perfect Yeti Hide",n2="Perfect Yeti Hide, a rare drop",m=1444,x=51.8,y=30.8,n=1,opt=true},{"a",7738,opt=true,ml=40}}},
  {t="Camp Mojache", lv=45, g={{"t",7734,n2="Jangdor Swiftstrider, inside",m=1444,x=74.4,y=42.9},{"t",7738,m=1444,x=74.4,y=42.9,opt=true},{"t",3128,m=1444,x=74.4,y=43.4},{"t",3063,m=1444,x=76.2,y=43.8}}},
} end)

R:Segment({id="horde/40-50/04-tanaris",title="Tanaris & Searing Gorge",faction="Horde",min=46,max=48,zone=1446,zoneName="Tanaris",next="horde/40-50/05-the-hinterlands"}, function() return {
  {t="Feralas", lv=46, g={{"g",0,txt="Camp Mojache",m=1444,x=75.4,y=44.3}}},
  {t="Fly to Gadgetzan", lv=46, g={{"g",0,txt="Camp Mojache flight master",m=1444,x=75.4,y=44.3},{"z",0,txt="Fly to Gadgetzan",at="Gadgetzan"}}},
  {t="Gadgetzan", lv=46, n="The flight lands beside Tran'rek. Take the town's quests before riding west to Sandsorrow Watch.", g={{"a",3362,n2="Tran'rek, beside the wind rider master",m=1446,x=51.6,y=26.8,ml=45},{"a",5863,m=1446,x=52.8,y=27.4,ml=44},{"t",243,m=1446,x=52.5,y=28.5},{"a",379,m=1446,x=52.5,y=28.5,ml=38},{"b",0,txt="Set your hearthstone at Gadgetzan",m=1446,x=52.5,y=27.9,at="Gadgetzan"},{"a",2605,m=1446,x=51.8,y=28.7,ml=44}}},
  {t="Tanaris", lv=46, g={{"g",0,txt="Sandsorrow Watch",m=1446,x=39,y=29}}},
  {t="Sandsorrow Watch", lv=46, n="West of Gadgetzan, use the Untapped Dowsing Widget beside the water hole in the troll camp.", g={{"o",992,i=1,txt="Use Untapped Dowsing Widget",m=1446,x=39,y=29.2},{"o",992,i=1,txt="Tapped Dowsing Widget",m=1446,x=39,y=29.2}}},
  {t="Senior Surveyor Fizzledowser", lv=46, n="Back east to Fizzledowser on the west side of Gadgetzan; Marvon is south from there.", g={{"t",992,m=1446,x=50.2,y=27.5},{"a",82,m=1446,x=50.2,y=27.5,ml=39}}},
  {t="Marvon Rivetseeker", lv=46, n="West along the road south; Marvon camps by the ruins at the Broken Pillar. Put on his Gahz'ridian Detector: it shows the buried ornaments, here and around the Dunemaul Compound.", g={{"a",3161,m=1446,x=52.7,y=45.9,ml=43}}},
  {t="Broken Pillar: kill these as you meet them", lv=46, n="South of the Noxious Lair the Dunemaul ogres hold their compound, with Gor'marok the Ravager at its eastern end. Dig up Gahz'ridian ornaments between the fights.", g={{"o",3161,i=1,txt="Gahz'ridian Ornament x30",m=1446,x=52.3,y=45.3},{"o",5863,i=1,txt="Kill Dunemaul Brute x10",m=1446,x=42.7,y=53.1},{"o",5863,i=2,txt="Kill Dunemaul Enforcer x10",m=1446,x=42.2,y=53.3},{"o",5863,i=3,txt="Kill Gor'marok the Ravager",n2="Below ground",m=1446,x=41.5,y=57.8}}},
  {t="The Noxious Lair", lv=46, n="West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast Silithid Swarm both in and out of combat, which brings small adds that interrupt you.", g={{"o",82,i=1,txt="Centipaar Insect Parts x5",m=1446,x=35.1,y=48.4}}},
  {t="Thistleshrub Valley: kill these as you meet them", lv=46, n="West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in Tanaris can drop OOX-17/TN's distress beacon, rarely: keep it if you see one.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs.", g={{"o",3362,i=1,txt="Kill Gnarled Thistleshrub x8",m=1446,x=29.3,y=62.4},{"h",8623,txt="Get OOX-17/TN Distress Beacon",n2="OOX-17/TN Distress Beacon, a rare drop",m=1446,x=30.4,y=77.7,n=1,opt=true},{"o",3362,i=2,txt="Kill Thistleshrub Rootshaper x8",m=1446,x=29.5,y=67.6},{"o",2605,i=1,txt="Laden Dew Gland",m=1446,x=29.2,y=66.1}}},
  {t="Tooga's escort", lv=46, n="Tooga waits in the valley. Walk him all the way to his wife Torta in Steamwheedle Port, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. Yeh'kinya stands in the port too.", g={{"a",1560,m=1446,x=30,y=65,ml=40},{"c",1560,txt="Torta",m=1446,x=66.6,y=25.7}}},
  {t="Steamwheedle Port", lv=46, g={{"t",1560,n2="Torta, Steamwheedle Port",m=1446,x=66.6,y=25.7},{"t",3520,m=1446,x=67,y=22.4}}},
  {t="Slake That Thirst", lv=46, n="Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and Shadow Bolt. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less.", g={{"o",379,i=1,txt="Wastewander Water Pouch x5",m=1446,x=60,y=23.4}}},
  {t="Gadgetzan", lv=46, g={{"t",5863,m=1446,x=52.8,y=27.4},{"t",379,m=1446,x=52.5,y=28.5},{"i",0,txt="Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts Tanaris Field Sampling, a two-hour timer, so use it on the way back north from Scrimshank's hive."}}},
  {t="Gadgetzan", lv=46, g={{"t",2605,m=1446,x=51.8,y=28.7},{"a",2606,m=1446,x=51.8,y=28.7,ml=44},{"t",3362,m=1446,x=51.6,y=26.8},{"t",2606,m=1446,x=51.1,y=26.9},{"a",2641,n2="the Violet Tragan grows in the Hinterlands, around level 48",m=1446,x=51.1,y=26.9,ml=44},{"t",82,n2="Alchemist Pestlezugg, inside",m=1446,x=50.9,y=27},{"a",10,m=1446,x=50.2,y=27.5,ml=39}}},
  {t="Marvon Rivetseeker", lv=46, g={{"t",3161,m=1446,x=52.7,y=45.9}}},
  {t="Scrimshank's gear", lv=46, n="Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds.", g={{"o",10,i=1,txt="Scrimshank's Surveying Gear",n2="Below ground",m=1446,x=56,y=71.2}}},
  {t="OOX-17/TN", lv=46, n="Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to Steamwheedle Port; its reward waits with Oglethorpe in Booty Bay.\nCareful: The escort has two ambushes. Three level 47 scorpids attack near the start. Near the end, by the beach, three Wastewander humans attack: one mage and two assassins, around level 44.", g={{"a",351,opt=true,ml=43},{"t",351,m=1446,x=60.2,y=64.7,opt=true},{"a",648,m=1446,x=60.2,y=64.7,opt=true,ml=43},{"c",648,txt="Escort OOX-17/TN to Steamwheedle Port",opt=true}}},
  {t="Tanaris Field Sampling", lv=46, n="Back north, just south of Gadgetzan, use the Model 4711-FTZ Power Source now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each.", g={{"a",654,n2="Use the Model 4711-FTZ Power Source",ml=38},{"o",654,i=2,txt="Acceptable Hyena Sample x8",m=1446,x=50.2,y=31.6},{"o",654,i=1,txt="Acceptable Basilisk Sample x8",m=1446,x=49.4,y=31},{"o",654,i=3,txt="Acceptable Scorpid Sample x8",m=1446,x=53.2,y=31.2}}},
  {t="Gadgetzan", lv=46, g={{"t",654,m=1446,x=52.5,y=28.5},{"a",864,n2="for Apothecary Zinge in the Undercity, around level 52",m=1446,x=52.5,y=28.5,ml=38},{"t",10,m=1446,x=50.2,y=27.5},{"a",110,m=1446,x=50.2,y=27.5,ml=39},{"t",110,n2="Alchemist Pestlezugg, inside",m=1446,x=50.9,y=27},{"a",113,m=1446,x=50.9,y=27,ml=39},{"t",113,m=1446,x=50.2,y=27.5},{"a",32,n2="for Zilzibin Drumlore in Orgrimmar, around level 50",m=1446,x=50.2,y=27.5,ml=39}}},
  {t="Boat to Powderfuse Port", lv=46, g={{"g",0,txt="Boat to Powderfuse Port",m=1446,x=67.6,y=23.1}}},
  {t="Into Searing Gorge", lv=46, g={{"g",0,txt="Into Searing Gorge",m=1427,x=76.6,y=56.7}}},
  {t="Searing Gorge", lv=46, g={{"g",0,txt="The Grimesilt Dig Site",m=1427,x=65.6,y=62.2}}},
  {t="The Grimesilt Dig Site", lv=46, n="From Powderfuse Port, ride into the Searing Gorge by its eastern pass, then west to the dig site. The Wooden Outhouse stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 Silk Cloth (the Auction House sells it).", g={{"a",4449,n2="the Wooden Outhouse",m=1427,x=65.6,y=62.2,ml=43},{"o",4449,i=1,txt="Kill Dark Iron Geologist x8",m=1427,x=63.9,y=60.4},{"o",4449,i=2,txt="Silk Cloth x15",m=1427,x=63.9,y=60.4},{"t",4449,m=1427,x=65.6,y=62.2}}},
  {t="Searing Gorge", lv=46, g={{"g",0,txt="Thorium Point",m=1427,x=37.7,y=26.5}}},
  {t="Thorium Point", lv=46, n="Ride north-west across the gorge; Thorium Point is the scaffolded camp in the north-west.", g={{"fp",75,txt="Get the Thorium Point flight path (Grisha)",m=1427,x=34.8,y=30.9},{"a",7728,n2="The Wanted/Missing/Lost & Found board",m=1427,x=37.6,y=26.5,ml=45},{"a",7729,m=1427,x=37.6,y=26.5,ml=45},{"a",7723,m=1427,x=38.6,y=27.8,ml=45},{"a",7724,m=1427,x=38.6,y=27.8,ml=45},{"a",7727,m=1427,x=38.6,y=27.8,ml=45},{"a",7722,m=1427,x=38.8,y=28.5,ml=45}}},
  {t="The Cauldron's slavers and golems", lv=46, n="Ride south from Thorium Point into the Cauldron: the Dark Iron Taskmasters and Slavers drive the slaves on the paths, and the Heavy War Golems patrol the floor below Velarok.", g={{"o",7729,i=1,txt="Kill Dark Iron Taskmaster x15",m=1427,x=38,y=31.9},{"o",7729,i=2,txt="Kill Dark Iron Slaver x15",m=1427,x=40.2,y=32},{"o",7723,i=1,txt="Kill Heavy War Golem x20",m=1427,x=44.8,y=38.7}}},
  {t="Velarok Windblade", lv=46, n="Velarok stands alone south of Thorium Point, at the edge of the Cauldron. Listen to his story.", g={{"a",3441,m=1427,x=39.1,y=39,ml=40}}},
  {t="Divine Retribution", lv=46, g={{"o",3441,i=1,txt="Talk to Velarok Windblade",m=1427,x=39.1,y=39}}},
  {t="Velarok Windblade", lv=46, g={{"t",3441,m=1427,x=39.1,y=39},{"a",3442,m=1427,x=39.1,y=39,ml=40}}},
  {t="Searing Gorge: kill these as you meet them", lv=46, n="Heavy War Golems patrol the Cauldron below Velarok and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the Grimesilt Outhouse Key: keep it.\nThe Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.\nThe Slag Pit opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee.", g={{"h",11818,txt="Get Grimesilt Outhouse Key",n2="Grimesilt Outhouse Key, a rare drop",m=1427,x=39.1,y=37.9,n=1,opt=true},{"o",3442,i=1,txt="Heart of Flame x4",m=1427,x=40.7,y=36.7},{"o",3442,i=2,txt="Golem Oil x4",m=1427,x=42.5,y=38.6},{"o",7724,i=1,txt="Kill Greater Lava Spider x20",m=1427,x=38,y=33.3},{"o",7727,i=1,txt="Kill Incendosaur x20",n2="Below ground",m=1427,x=43.4,y=28.3}}},
  {t="Velarok Windblade", lv=46, g={{"t",3442,m=1427,x=39.1,y=39},{"a",3443,m=1427,x=39.1,y=39,ml=40}}},
  {t="Thorium Point", lv=46, n="Ride back north to Thorium Point, just past Velarok.", g={{"t",7729,m=1427,x=39,y=27.5},{"t",7727,m=1427,x=38.6,y=27.8},{"t",7724,m=1427,x=38.6,y=27.8},{"t",7723,m=1427,x=38.6,y=27.8}}},
  {t="The Steamsmiths' furnaces", lv=46, n="The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a Thorium Plated Dagger, one in ten the Smithing Tuyere. Slaves, Slavers and Taskmasters carry daggers too.", g={{"o",3443,i=1,txt="Thorium Plated Dagger x8",m=1427,x=39.9,y=27.8},{"o",7728,i=1,txt="Smithing Tuyere",m=1427,x=40,y=48.3}}},
  {t="Velarok Windblade", lv=46, g={{"t",3443,m=1427,x=39.1,y=39},{"i",0,txt="His next request needs the Symbol of Ragnaros from elite cultists: leave it."}}},
  {t="The Slag Pit", lv=46, g={{"o",7722,i=1,txt="Secret Plans: Fiery Flux",n2="Below ground",m=1427,x=40.5,y=35.7}}},
  {t="Dark Iron Lookouts", lv=46, n="The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the Lookout's Spyglass.", g={{"o",7728,i=2,txt="Lookout's Spyglass",m=1427,x=33.7,y=51.9}}},
  {t="The Key to Freedom", lv=46, n="Only with the Grimesilt Outhouse Key: back east to the Wooden Outhouse at the dig site.", g={{"a",4451,opt=true,ml=43},{"t",4451,m=1427,x=65.6,y=62.2,opt=true}}},
  {t="Thorium Point", lv=46, g={{"t",7722,m=1427,x=38.8,y=28.5},{"t",7728,m=1427,x=39,y=27.5}}},
} end)

R:Segment({id="horde/40-50/05-the-hinterlands",title="The Hinterlands & Blasted Lands",faction="Horde",min=48,max=50,zone=1425,zoneName="The Hinterlands",next="horde/40-50/06-azshara"}, function() return {
  {t="Fly to Tarren Mill", lv=48, g={{"g",0,txt="Thorium Point flight master",m=1427,x=34.8,y=30.6},{"z",0,txt="Fly to Tarren Mill",at="Tarren Mill"}}},
  {t="The Hinterlands", lv=48, g={{"g",0,txt="Gilveradin's camp",m=1425,x=26.7,y=48.6}}},
  {t="Gilveradin's camp", lv=48, n="Ride north-east from Tarren Mill into the Hinterlands and east along the road; Gilveradin Sunchaser camps on the hill south of the elves' Quel'Danil Lodge.", g={{"t",650,m=1425,x=26.7,y=48.6},{"a",77,m=1425,x=26.7,y=48.6,ml=42}}},
  {t="Highvale", lv=48, n="The Highvale elves camp around Quel'Danil Lodge. Burn the report, the notes and the records in their camps. Rin'ji is held inside the lodge: lead him out and fight off the ambush on the way.\nCareful: Groups of about three elves ambush the escort, usually twice.", g={{"o",2995,i=3,txt="Highvale Report",m=1425,x=28.6,y=46},{"o",2995,i=2,txt="Highvale Notes",m=1425,x=29.6,y=48.7},{"o",2995,i=1,txt="Highvale Records",m=1425,x=32,y=46.8},{"a",2742,m=1425,x=30.7,y=46.9,ml=42},{"c",2742,txt="Escort Rin'ji to safety"}}},
  {t="Violet Tragan", lv=48, n="East of the village, the violet flower grows in the hills.", g={{"o",2641,i=1,txt="Violet Tragan",n2="Underwater",m=1425,x=40.6,y=59.7}}},
  {t="Revantusk Village", lv=48, n="Follow the roads east across the Hinterlands to the troll village on the eastern coast.", g={{"a",7839,m=1425,x=77.2,y=80.1,ml=44},{"b",0,txt="Set your hearthstone at Revantusk Village",m=1425,x=78.1,y=81.4,at="Revantusk Village"},{"a",7840,m=1425,x=78.1,y=81.4,ml=44},{"fp",76,txt="Get the Revantusk Village flight path (Gorkas)",m=1425,x=81.7,y=81.8},{"a",7815,m=1425,x=80.3,y=81.5,ml=44},{"a",7830,m=1425,x=79.2,y=79.5,ml=44},{"a",7829,m=1425,x=79.2,y=79.5,ml=44},{"a",7828,m=1425,x=79.2,y=79.5,ml=44},{"a",7841,m=1425,x=79.4,y=79.1,ml=44},{"a",7844,m=1425,x=78.8,y=78.2,ml=44}}},
  {t="Revantusk Village", lv=48, w={{k="group",q=7816}}, g={{"a",7816,m=1425,x=80.3,y=81.5,ml=44}}},
  {t="Revantusk Village", lv=48, n="Separation Anxiety, Kidnapped Elder Torntusk! and Dark Vessels are group quests: they send you into Jintha'Alor, whose trolls are elite (46-50). Take them with a group of three or more; skip them if you are alone, the route has you grind the experience back.\nPrimal Torntusk stands up on top of the inn, above Lard: go up, the arrow cannot tell the levels apart.", w={{k="group",q=7849}}, g={{"a",7849,m=1425,x=79.2,y=79.5,ml=46},{"a",7845,m=1425,x=78.2,y=81.2,ml=46},{"a",7850,m=1425,x=78.2,y=81.2,ml=46}}},
  {t="The Overlook Cliffs: kill these as you meet them", lv=48, n="The big turtles crawl along the beaches north of the village, and Whiskey Slim's bottles of port lie on the same beaches, from the village up to the Overlook Cliffs: pick them up as you go. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.", g={{"o",7815,i=1,txt="Kill Saltwater Snapjaw x15",m=1425,x=76.2,y=84},{"o",580,i=1,txt="Pupellyverbos Port x12",n2="Pupellyverbos Port, on the beaches",m=1425,x=76.3,y=85.6},{"h",8704,txt="Get OOX-09/HL Distress Beacon",n2="OOX-09/HL Distress Beacon, a rare drop",m=1425,x=69.3,y=62.4,n=1,opt=true}}},
  {t="The Overlook Cliffs: kill these as you meet them", lv=48, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Gammerita is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nGammerita walks the shore below the Overlook Cliffs, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore.", w={{k="group",q=7816}}, g={{"o",7816,i=1,txt="Katoom's Best Lure",m=1425,x=80.4,y=58.2,grp=true}}},
  {t="Rin'ji's Secret", lv=48, n="The secret lies on the Overlook Cliffs, above the beach.", g={{"t",2742,m=1425,x=86.3,y=59},{"a",2782,n2="for Oran Snakewrithe in the Undercity, around level 50",m=1425,x=86.3,y=59,ml=42}}},
  {t="Lard's lunch", lv=48, n="North along the coast, Lard's picnic basket is on the small island; a Vilebranch Kidnapper guards it.", g={{"o",7840,i=1,txt="Lard's Lunch",m=1425,x=84.5,y=41.2}}},
  {t="Cortello's Riddle", lv=48, w={{k="onquest",q={626}}}, g={{"t",626,n2="Underwater",m=1425,x=80.8,y=46.8}}},
  {t="Shaol'watha: kill these as you meet them", lv=48, n="West of the island, the Vilebranch scalpers hold the temples of Agol'watha and Shaol'watha. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and Skulk Rock. Use the Wildkin Muisek Vessel on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for Otho's second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use Infected Bite. When a Silvermane Howler falls to 50% health or lower, it calls for help from anything within 25 yd.", g={{"o",7828,i=1,txt="Kill Silvermane Stalker x15",m=1425,x=78,y=52.2},{"o",7839,i=1,txt="Slagtree's Lost Tools",m=1425,x=72.6,y=52.9},{"o",7844,i=1,txt="Kill Vilebranch Scalper x30",m=1425,x=71.9,y=48.5},{"o",7844,i=2,txt="Kill Vilebranch Soothsayer x15",m=1425,x=71.3,y=48.3},{"o",7830,i=1,txt="Skylord Plume",m=1425,x=71.2,y=49.8},{"o",7829,i=1,txt="Kill Savage Owlbeast x20",m=1425,x=64.8,y=50.6}}},
  {t="Skulk Rock", lv=48, n="The crates of Hinterlands Honey Ripple lie around the abandoned Horde camp at Skulk Rock, among the oozes.", g={{"o",77,i=1,txt="Hinterlands Honey Ripple x10",m=1425,x=60,y=42.5}}},
  {t="Wildkin Muisek", lv=48, n="Careful: Stealthed wolves and griffons roam the Valorwind Lake area.", g={{"o",3123,i=1,txt="Wildkin Muisek x10",m=1425,x=61,y=42.8},{"o",3123,i=1,txt="Use Wildkin Muisek Vessel",m=1425,x=61,y=42.8},{"h",4589,txt="Get Long Elegant Feather x10",m=1425,x=61.4,y=42.4,n=10}}},
  {t="The Altar of Zul: kill these as you meet them", lv=48, n="South-west of the lake, the Vilebranch soothsayers hold the Altar of Zul, the troll temple south of the central hills. Qiaga and Morta'gya the Keeper (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages.", g={{"o",7844,i=1,txt="Kill Vilebranch Scalper x30",m=1425,x=65.3,y=44.8},{"o",7844,i=2,txt="Kill Vilebranch Soothsayer x15",m=1425,x=66.2,y=44.8},{"o",7828,i=2,txt="Kill Silvermane Howler x15",m=1425,x=51.1,y=40.6}}},
  {t="OOX-09/HL", lv=48, n="Only with the distress beacon: the robot sits at the head of the river west of Skulk Rock. Escort it east to the shore beyond the Overlook Cliffs; its reward waits with Oglethorpe in Booty Bay.\nCareful: Two ambushes spawn during the escort: first three wildkin owlbeasts, then three trolls. Before each, the robot halts and announces it senses danger. Oozes, stealthed wolves and a large turtle along the path can join fights, and they respawn even if cleared beforehand.", g={{"a",485,opt=true,ml=43},{"t",485,m=1425,x=49.4,y=37.7,opt=true},{"a",836,m=1425,x=49.4,y=37.7,opt=true,ml=43},{"c",836,txt="Escort OOX-09/HL to the shoreline beyond Overlook Cliff",opt=true}}},
  {t="Gilveradin's camp", lv=48, g={{"t",77,m=1425,x=26.7,y=48.6},{"a",81,n2="for Dran Droffers in Orgrimmar, around level 50",m=1425,x=26.7,y=48.6,ml=42}}},
  {t="Highvale", lv=48, n="Back west to Quel'Danil Lodge; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it.", g={{"o",7841,i=1,txt="Kill Highvale Scout x15",m=1425,x=29.7,y=50},{"o",7841,i=2,txt="Kill Highvale Outrunner x15",m=1425,x=29.6,y=51.4},{"o",7841,i=3,txt="Kill Highvale Ranger x15",m=1425,x=30.2,y=48.8},{"o",7841,i=4,txt="Kill Highvale Marksman x15",m=1425,x=29.8,y=48.5}}},
  {t="Jintha'Alor", lv=48, n="Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of Jintha'Alor. The Vessels of Tainted Blood sit on the lower terraces, and Elder Torntusk is held at the top. The trolls inside are elite: stay with your group and keep to the paths.", w={{k="group",q=7849}}, g={{"o",7849,i=1,txt="Huntsman Malkhor's Skull",m=1425,x=58.6,y=64.8},{"t",7845,n2="Elder Torntusk, at the top of Jintha'Alor",m=1425,x=59.7,y=77.8},{"i",0,txt="His next request, going on to the Altar of Zul, is for a group."},{"o",7849,i=2,txt="Huntsman Malkhor's Bones",m=1425,x=62.1,y=75.3},{"o",7850,i=1,txt="Vessel of Tainted Blood x10",m=1425,x=63.6,y=73.4}}},
  {t="Revantusk Village", lv=48, g={{"t",7839,m=1425,x=77.2,y=80.1},{"t",7840,n2="Lard, inside",m=1425,x=78.1,y=81.4},{"t",7815,m=1425,x=80.3,y=81.5},{"t",7830,m=1425,x=79.2,y=79.5},{"t",7829,m=1425,x=79.2,y=79.5},{"t",7828,m=1425,x=79.2,y=79.5},{"t",7841,m=1425,x=79.4,y=79.1},{"a",7842,m=1425,x=79.4,y=79.1,ml=44},{"t",7844,m=1425,x=78.8,y=78.2},{"t",7842,m=1425,x=79.4,y=79.1},{"a",7843,m=1425,x=79.4,y=79.1,ml=44}}},
  {t="Revantusk Village", lv=48, n="Primal Torntusk stands up on top of the inn, above Lard: go up, the arrow cannot tell the levels apart.", w={{k="group",q=7849}}, g={{"t",7850,m=1425,x=78.2,y=81.2},{"t",7849,m=1425,x=79.2,y=79.5}}},
  {t="Revantusk Village", lv=48, w={{k="group",q=7816}}, g={{"t",7816,m=1425,x=80.3,y=81.5}}},
  {t="Level 49.02", lv=49, n="If you skipped Gammerita, Mon! or the Jintha'Alor group quests, grind here to level 49.02 to stay on the route's plan. Or, with a group, run the Maraudon dungeon instead.", w={{k="level",op="<",n=49,frac=0.02}}, g={{"g",0,txt="Saltwater Snapjaw",m=1425,x=77.8,y=68.9},{"l",49,txt="Reach level 49 (2% in): grind Saltwater Snapjaw",n2="grind on Saltwater Snapjaw",m=1425,x=78.2,y=68.5,fr=0.02}}},
  {t="The Atal'ai Exile", lv=49, n="South-west again, the exile hides by the ruins of Shadra'Alor.", g={{"t",1429,m=1425,x=33.8,y=75.2},{"a",1444,m=1425,x=33.8,y=75.2,ml=38}}},
  {t="Venom Bottles", lv=49, g={{"a",2933,m=1425,x=31.6,y=57.8,ml=40}}},
  {t="Grim Message", lv=49, n="South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use Nimboya's Pike to make the Laden Pike, then plant it inside the village.", w={{k="onquest",q={2932}}}, g={{"g",0,txt="Go here",m=1425,x=23.4,y=58.1},{"h",9320,txt="Get Witherbark Skull x20",m=1425,x=23.1,y=58.5,n=20},{"i",0,txt="Use Nimboya's Pike",m=1425,x=29.5,y=58.5},{"i",0,txt="Use Nimboya's Laden Pike",m=1425,x=29.5,y=58.5},{"c",2932,txt="Place the grim message."}}},
  {t="Aerie Peak", lv=49, n="Ride all the way west to the Wildhammer town of Aerie Peak and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out.", g={{"g",0,txt="Aerie Peak well",m=1425,x=14.3,y=48.1},{"c",7843,txt="Message to the Wildhammer Delivered"}}},
  {t="Revantusk Village", lv=49, g={{"t",7843,m=1425,x=79.4,y=79.1}}},
  {t="Fly to Stonard", lv=49, g={{"g",0,txt="Revantusk Village flight master",m=1425,x=81.7,y=81.9},{"z",0,txt="Fly to Stonard",at="Stonard"}}},
  {t="Fel'zerul", lv=49, g={{"t",1444,n2="On the top floor",m=1435,x=47.9,y=54.8}}},
  {t="Fallen Hero of the Horde", lv=49, n="The ghostly orc stands by the road where the swamp meets the canyon into the Blasted Lands. Listen to his story.", g={{"a",2784,m=1435,x=34.3,y=66.1,ml=45}}},
  {t="Fall From Grace", lv=49, g={{"o",2784,i=1,txt="Talk to Fallen Hero of the Horde",m=1435,x=34.3,y=66.1}}},
  {t="Fallen Hero of the Horde", lv=49, g={{"t",2784,m=1435,x=34.3,y=66.1},{"a",2621,n2="for Dispatch Commander Ruag in Stonard, after the Blasted Lands",m=1435,x=34.3,y=66.1,ml=45}}},
  {t="The bloodmages", lv=49, n="Ride west out of Stonard and south through the canyon into the Blasted Lands; the two bloodmages stand by the road just inside.", g={{"a",2583,m=1419,x=50.5,y=14.2,ml=45},{"a",2585,m=1419,x=50.5,y=14.2,ml=45},{"a",2581,m=1419,x=50.5,y=14.2,ml=45},{"a",2601,m=1419,x=50.6,y=14.3,ml=45},{"a",2603,m=1419,x=50.6,y=14.3,ml=45}}},
  {t="Serpent's Coil: kill these as you meet them", lv=49, n="The five quests share the same parts: gather them all in one sweep. West of the road the Black Slayer vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills.\nEast of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south.\nCareful: Scorpok Stingers use Venom Sting; Clack the Reaver adds Knockdown.", g={{"o",2581,i=3,txt="Scorpok Pincer",m=1419,x=50,y=15.4},{"o",2583,i=2,txt="Scorpok Pincer x2",m=1419,x=50,y=15.4},{"o",2585,i=1,txt="Scorpok Pincer x3",m=1419,x=50,y=15.4},{"o",2601,i=2,txt="Vulture Gizzard x2",m=1419,x=50.2,y=17.2},{"o",2585,i=2,txt="Vulture Gizzard x2",m=1419,x=50.2,y=17.2},{"o",2603,i=1,txt="Vulture Gizzard x10",m=1419,x=50.2,y=17.2},{"o",2581,i=1,txt="Snickerfang Jowl x3",m=1419,x=48.3,y=17.8},{"o",2603,i=2,txt="Snickerfang Jowl x2",m=1419,x=48.3,y=17.8},{"o",2601,i=1,txt="Basilisk Brain x10",m=1419,x=48.5,y=20.3},{"o",2583,i=3,txt="Basilisk Brain",m=1419,x=48.5,y=20.3},{"o",2583,i=1,txt="Blasted Boar Lung x3",m=1419,x=52.3,y=27.4},{"o",2585,i=3,txt="Blasted Boar Lung",m=1419,x=52.3,y=27.4},{"o",2581,i=2,txt="Blasted Boar Lung x2",m=1419,x=52.3,y=27.4}}},
  {t="The bloodmages", lv=49, n="Ride back north to the bloodmages.", g={{"t",2601,m=1419,x=50.6,y=14.3},{"t",2603,m=1419,x=50.6,y=14.3},{"i",0,txt="Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."},{"t",2583,m=1419,x=50.5,y=14.2},{"t",2585,m=1419,x=50.5,y=14.2},{"t",2581,m=1419,x=50.5,y=14.2}}},
  {t="Stonard", lv=49, n="Ride back north through the canyon to Stonard.", g={{"t",2621,m=1435,x=47.8,y=54.9},{"a",2622,m=1435,x=47.8,y=54.9,ml=45},{"t",2622,m=1435,x=45,y=57.4},{"i",0,txt="Bengor's The Swamp Talker is a level 55 quest: leave it."}}},
} end)

R:Segment({id="horde/40-50/06-azshara",title="Azshara, Feralas & Stranglethorn Vale",faction="Horde",min=50,max=51,zone=1447,zoneName="Azshara",next="horde/50-60/01-un-goro-crater"}, function() return {
  {t="Swamp of Sorrows", lv=50, g={{"g",0,txt="Stonard",m=1435,x=46.1,y=54.7}}},
  {t="Fly to Grom'gol", lv=50, g={{"g",0,txt="Stonard flight master",m=1435,x=46.1,y=54.7},{"z",0,txt="Fly to Grom'gol",at="Grom'gol"}}},
  {t="To Grom'gol", lv=50, n="The flight from Stonard lands at Grom'gol Base Camp.", g={{"g",0,txt="Grom'gol Base Camp",m=1434,x=32.2,y=27.7}}},
  {t="Grom'gol Base Camp", lv=50, g={{"t",2932,m=1434,x=32.2,y=27.7}}},
  {t="Fly to Booty Bay", lv=50, g={{"g",0,txt="Grom'gol flight master",m=1434,x=32.5,y=29.3},{"z",0,txt="Fly to Booty Bay",at="Booty Bay"}}},
  {t="Booty Bay", lv=50, n="Continue south to Booty Bay. Oglethorpe Obnoticus has his workshop on the upper ring of the bay.", g={{"t",2767,n2="Oglethorpe Obnoticus, inside",m=1434,x=28.4,y=76.3,opt=true},{"t",836,m=1434,x=28.4,y=76.3,opt=true},{"t",648,m=1434,x=28.4,y=76.3,opt=true},{"t",3721,m=1434,x=28.4,y=76.3,opt=true},{"t",580,n2="Whiskey Slim, in the inn",m=1434,x=27.1,y=77.5},{"t",2874,n2="\"Sea Wolf\" MacKinley, on the top floor",m=1434,x=27.8,y=77.1},{"a",608,n2="Fleet Master Seahorn, on the balcony of the same building",m=1434,x=27.2,y=77,ml=37}}},
  {t="The Bloodsail ships", lv=50, n="South of Booty Bay, three Bloodsail ships lie off the Wild Shore: Captain Stillwater, Captain Keelhaul and Fleet Master Firallon each stand on a deck with their crews. Swim out and work from ship to ship.", g={{"o",608,i=1,txt="Kill Captain Stillwater",m=1434,x=32.9,y=88.2},{"o",608,i=2,txt="Kill Captain Keelhaul",m=1434,x=29.3,y=88.3},{"o",608,i=3,txt="Kill Fleet Master Firallon",m=1434,x=30.6,y=90.6}}},
  {t="Booty Bay", lv=50, g={{"t",608,m=1434,x=27.2,y=77}}},
  {t="Monogrammed Sash", lv=50, n="These are elite mobs: grouping up is encouraged, look for people to do it with. The Monogrammed Sash needs a group of 2. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=8552}}, g={{"h",3985,txt="Get Monogrammed Sash",m=1434,x=23.3,y=72.1,n=1,grp=true},{"a",8552,ml=35}}},
  {t="Captain Hecklebury Smotts", lv=50, w={{k="group",q=8552}}, g={{"t",8552,m=1434,x=26.7,y=73.6},{"a",8553,m=1434,x=26.7,y=73.6,ml=35}}},
  {t="Sprogger", lv=50, w={{k="group",q=8552}}, g={{"t",8553,m=1434,x=26.7,y=73.6}}},
  {t="Carefully Folded Note", lv=50, g={{"h",4098,txt="Get Carefully Folded Note",m=1434,x=33.8,y=77.7,n=1,opt=true},{"a",594,opt=true,ml=45}}},
  {t="Princess Poobah", lv=50, w={{k="onquest",q={594}}}, g={{"t",594,m=1434,x=38.5,y=80.6}}},
  {t="Fly to Grom'gol", lv=50, g={{"g",0,txt="Booty Bay flight master",m=1434,x=26.8,y=77},{"z",0,txt="Fly to Grom'gol",at="Grom'gol"}}},
  {t="Back to Grom'gol", lv=50, w={{k="group",q=591}}, g={{"a",591,m=1434,x=32.3,y=27.7,ml=30}}},
  {t="The Mind's Eye", lv=50, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Mai'Zoth (level 47 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\nCareful: Two elite caster guards, around level 45, stand with Mai'Zoth and join the fight together with him.", w={{k="group",q=591}}, g={{"o",591,i=1,txt="Mind's Eye",n2="Below ground",m=1434,x=52.9,y=27.6,grp=true}}},
  {t="Kin'weelay", lv=50, w={{k="group",q=591}}, g={{"t",591,m=1434,x=32.3,y=27.7},{"a",592,m=1434,x=32.3,y=27.7,ml=30}}},
  {t="Saving Yenniku", lv=50, w={{k="group",q=591}}, g={{"o",592,i=1,txt="Filled Soul Gem",m=1434,x=39,y=58.4,grp=true},{"o",592,i=1,txt="Use Soul Gem",m=1434,x=39,y=58.4}}},
  {t="Nimboya", lv=50, w={{k="group",q=591}}, g={{"t",592,m=1434,x=32.2,y=27.7}}},
  {t="Zeppelin to Orgrimmar", lv=50, g={{"g",0,txt="Zeppelin to Orgrimmar",m=1434,x=31.4,y=29.9}}},
  {t="Zilzibin Drumlore", lv=50, n="On the way through Orgrimmar to the flight master, step into the Drag: Zilzibin takes the insect report from Tanaris, and its experience shortens the top-up to 50 in Azshara.", w={{k="onquest",q={32}}}, g={{"t",32,n2="Zilzibin Drumlore, the Drag",m=1454,x=56.3,y=46.7}}},
  {t="Dran Droffers", lv=50, n="The Droffers' shop is a few steps further into the Drag.", w={{k="onquest",q={81}}}, g={{"t",81,n2="Dran Droffers, the Drag",m=1454,x=59.5,y=36.6}}},
  {t="Azshara", lv=50, g={{"g",0,txt="Loh'atu",m=1447,x=11.4,y=78.2}}},
  {t="Ride into Azshara", lv=50, n="Ride east along the road out of Splintertree. Loh'atu waits at the Shadowsong Shrine just off the road, a few steps west of the Alliance's Talrendis Point: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite).", g={{"a",5535,m=1447,x=11.4,y=78.2,ml=45},{"a",5536,m=1447,x=11.4,y=78.2,ml=45}}},
  {t="Haldarr Encampment: kill these as you meet them", lv=50, n="The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north.", g={{"o",5535,i=2,txt="Kill Highborne Lichling x6",n2="Highborne Lichling walks around Shadowsong Shrine: look inside the circle on the map",m=1447,x=13.5,y=73.2},{"o",5535,i=1,txt="Kill Highborne Apparition x6",m=1447,x=14,y=71.8},{"o",5536,i=3,txt="Kill Haldarr Felsworn x2",m=1447,x=19.1,y=64},{"o",5536,i=2,txt="Kill Haldarr Trickster x2",m=1447,x=19.7,y=63.8},{"o",5536,i=1,txt="Kill Haldarr Satyr x6",m=1447,x=20.4,y=63.7}}},
  {t="Level 50", lv=50, n="Top up here to level 50: March of the Silithid, from Zilzibin in Orgrimmar at the end of Azshara, needs it. Or, with a group, run the Maraudon dungeon or the Sunken Temple dungeon instead.", w={{k="level",op="<",n=50}}, g={{"g",0,txt="Haldarr Satyr",m=1447,x=20.1,y=62},{"l",50,txt="Reach level 50: grind Haldarr Satyr",n2="grind on Haldarr Satyr",m=1447,x=19.8,y=62.2}}},
  {t="Loh'atu", lv=50, n="Back to Loh'atu at the shrine; stay west of the Talrendis Point guards.", g={{"t",5535,m=1447,x=11.4,y=78.2},{"t",5536,m=1447,x=11.4,y=78.2}}},
  {t="Valormok", lv=50, n="Follow the road north to Valormok, the Horde camp.", g={{"a",3381,n2="Sanath Lim-yo, at the east edge of the camp: no experience, only a teleport to Azshara Tower",m=1447,x=28.1,y=50.1,opt=true,ml=45}}},
  {t="Valormok", lv=50, g={{"fp",44,txt="Get the Valormok flight path (Kroum)",m=1447,x=22,y=49.6},{"a",3517,m=1447,x=22.6,y=51.4,ml=45}}},
  {t="Undamaged Hippogryph Feathers", lv=50, n="The Thunderhead Hippogryphs fly over the hills just south of Valormok.", g={{"o",3381,i=1,txt="Undamaged Hippogryph Feather x2",m=1447,x=21.1,y=54.2,opt=true}}},
  {t="Sanath Lim-yo", lv=50, w={{k="complete",q=3381}}, g={{"t",3381,m=1447,x=28.1,y=50.1}}},
  {t="Kim'jael", lv=50, n="Ride north-east to the goblin's camp on the cliffs above the Bay of Storms.", g={{"a",3601,m=1447,x=53.5,y=21.8,ml=47}}},
  {t="Thalassian Base Camp", lv=50, n="The blood elves' camp lies just south of Kim'jael. His four pieces of equipment lie in the crates around the camp.", g={{"o",3601,i=1,txt="Kim'Jael's Compass",m=1447,x=56.4,y=28.4},{"o",3601,i=2,txt="Kim'Jael's Scope",m=1447,x=56.4,y=28.4},{"o",3601,i=4,txt="Kim'Jael's Wizzlegoober",m=1447,x=56.4,y=28.4},{"o",3601,i=3,txt="Kim'Jael's Stuffed Chicken",m=1447,x=56.4,y=28.4}}},
  {t="Kim'jael", lv=50, g={{"t",3601,m=1447,x=53.5,y=21.8},{"a",5534,m=1447,x=53.5,y=21.8,ml=47}}},
  {t="Ruins of Eldarath: kill these as you meet them", lv=50, n="Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry Kim'jael's rune.", g={{"o",5534,i=1,txt="Some Rune",m=1447,x=46.4,y=39.8},{"o",3517,i=3,txt="Tablet of Markri",m=1447,x=40.2,y=45},{"o",3517,i=1,txt="Tablet of Beth'Amara",m=1447,x=39.6,y=48.1},{"o",3517,i=4,txt="Tablet of Sael'hai",m=1447,x=38.6,y=47.5},{"o",3517,i=2,txt="Tablet of Jin'yael",m=1447,x=38,y=51.3}}},
  {t="Kim'jael", lv=50, n="Back north-east to Kim'jael.", g={{"t",5534,m=1447,x=53.5,y=21.8}}},
  {t="Jediga", lv=50, n="Ride west back to Valormok.", g={{"t",3517,m=1447,x=22.6,y=51.4},{"a",3518,m=1447,x=22.6,y=51.4,ml=45},{"a",3541,m=1447,x=22.6,y=51.4,ml=45},{"a",3542,m=1447,x=22.6,y=51.4,ml=45},{"a",3561,m=1447,x=22.6,y=51.4,ml=45},{"i",0,txt="Keep the deliveries for Magatha, Jes'rimon and Andron Gant: you pass Thunder Bluff, Orgrimmar and the Undercity later."}}},
  {t="Archmage Xylem", lv=50, n="Xylem's tower stands on the cliff just north of Valormok; the path winds up its north side.", g={{"t",3561,n2="Upstairs",m=1447,x=29.2,y=40.2},{"a",3565,m=1447,x=29.2,y=40.2,ml=45}}},
  {t="Jediga", lv=50, g={{"t",3565,m=1447,x=22.6,y=51.4}}},
  {t="Fly to Orgrimmar", lv=50, g={{"g",0,txt="Valormok flight master",m=1447,x=22,y=49.7},{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"}}},
  {t="Orgrimmar", lv=50, g={{"t",32,n2="Zilzibin Drumlore, the Drag: if you still carry it",m=1454,x=56.3,y=46.7},{"a",4494,m=1454,x=56.3,y=46.7,ml=50},{"t",3541,n2="Jes'rimon, the Cleft of Shadow",m=1454,x=55.5,y=34.1},{"a",3563,m=1454,x=55.5,y=34.1,ml=45},{"a",4300,m=1454,x=55.5,y=34.1,ml=48},{"t",81,n2="Dran Droffers, the Drag",m=1454,x=59.5,y=36.6}}},
  {t="Orgrimmar", lv=50, g={{"t",2976,m=1454,x=75.2,y=34.2},{"a",3504,n2="Belgrom Rockmaul, Valley of Honor",m=1454,x=75.2,y=34.2,ml=44},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}},{"i",0,txt="Keep Jes'rimon's payment and Ag'tor's Betrayed: they go back to Valormok on a later visit."}}},
  {t="Paladin trainer", lv=50, f={c={"PALADIN"}}, g={{"tr",0,txt="Visit your class trainer",n2="Alodan the Hopeful in Thunder Bluff; Orgrimmar has no paladin trainer",f={c={"PALADIN"}}}}},
  {t="Fly to Thunder Bluff", lv=50, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.8},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Thunder Bluff", lv=50, n="Fly to Thunder Bluff; it is on the way to Camp Mojache. No flight path there yet? Fly to Camp Taurajo and ride west through Mulgore. Hamuul and Magatha are on the Elder Rise; Druids and Paladins train here (Turak Runetotem, Alodan the Hopeful).", g={{"a",3761,m=1456,x=78.6,y=28.6,ml=47}}},
  {t="Class trainer", lv=50, f={c={"DRUID"}}, g={{"tr",0,txt="Visit your class trainer",f={c={"DRUID"}}}}},
  {t="Thunder Bluff", lv=50, g={{"t",3518,m=1456,x=69.8,y=30.9},{"a",3562,m=1456,x=69.8,y=30.9,ml=45},{"tr",0,txt="Visit your class trainer",f={c={"PALADIN","DRUID"}}},{"i",0,txt="Un'Goro Soil is gathered in the next guide; Magatha's payment goes back to Jediga later."}}},
  {t="Fly to Camp Mojache", lv=50, g={{"g",0,txt="Thunder Bluff flight master",m=1456,x=46.7,y=49.9},{"z",0,txt="Fly to Camp Mojache",at="Camp Mojache"}}},
  {t="Camp Mojache", lv=50, g={{"b",0,txt="Set your hearthstone at Camp Mojache",m=1444,x=74.8,y=45.2,at="Camp Mojache"},{"t",3123,m=1444,x=74.4,y=43.4},{"a",3124,m=1444,x=74.4,y=43.4,ml=40},{"a",3380,m=1444,x=74.4,y=43.4,ml=46},{"a",4120,n2="Talo Thornhoof: the bears are in Felwood",m=1444,x=76.2,y=43.8,ml=47}}},
  {t="Frayfeather Hippogryphs", lv=50, n="The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body.", g={{"o",3124,i=1,txt="Hippogryph Muisek x10",m=1444,x=58,y=62.8},{"o",3124,i=1,txt="Use Hippogryph Muisek Vessel",m=1444,x=58,y=62.8}}},
  {t="Hippogryph nests", lv=50, n="The hippogryph nests are on the hills to the south, around the Ruins of Isildien; each holds an egg for the Egg-O-Matic.", w={{k="available",q=2741,minLevel=42}}, g={{"h",8564,txt="Get Hippogryph Egg",m=1444,x=58,y=76.3,n=1}}},
  {t="Witch Doctor Uzer'i", lv=50, g={{"t",3124,m=1444,x=74.4,y=43.4},{"a",3125,m=1444,x=74.4,y=43.4,ml=40}}},
  {t="Sprite Darters", lv=50, n="The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill.", g={{"o",3125,i=1,txt="Faerie Dragon Muisek x8",m=1444,x=70.2,y=46.6},{"o",3125,i=1,txt="Use Faerie Dragon Muisek Vessel",m=1444,x=70.2,y=46.6}}},
  {t="Witch Doctor Uzer'i", lv=50, g={{"t",3125,m=1444,x=74.4,y=43.4},{"a",3126,m=1444,x=74.4,y=43.4,ml=40}}},
  {t="Wandering Forest Walkers", lv=50, n="The treants wander the forest roads between the camp and the middle of Feralas; there are only a few, so look along the paths.", g={{"o",3126,i=1,txt="Treant Muisek x3",m=1444,x=73.9,y=38.8},{"o",3126,i=1,txt="Use Treant Muisek Vessel",m=1444,x=73.9,y=38.8}}},
  {t="Witch Doctor Uzer'i", lv=50, g={{"t",3126,m=1444,x=74.4,y=43.4},{"a",3127,m=1444,x=74.4,y=43.4,ml=40}}},
  {t="Zorbin Fandazzle", lv=50, g={{"t",7003,m=1444,x=44.8,y=43.4},{"t",7721,m=1444,x=44.8,y=43.4},{"a",7725,m=1444,x=44.8,y=43.4,ml=45},{"a",7726,m=1444,x=44.8,y=43.4,ml=45}}},
  {t="The Forgotten Coast: kill these as you meet them", lv=50, n="The Sea Elementals and Sea Sprays wash along the shore around the dock.\nThe Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with Zorbin's Ultra-Shrinker first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too.", g={{"o",3127,i=1,txt="Mountain Giant Muisek x7",m=1444,x=39.9,y=22.2},{"o",3127,i=1,txt="Use Mountain Giant Muisek Vessel",m=1444,x=39.9,y=22.2},{"o",7726,i=1,txt="Water Elemental Core x6",m=1444,x=37.5,y=33.1},{"o",7725,i=1,txt="Miniaturization Residue x10",m=1444,x=37.7,y=34.5},{"o",7725,i=1,txt="Use Zorbin's Ultra-Shrinker",m=1444,x=44.3,y=46.6}}},
  {t="Zorbin Fandazzle", lv=50, g={{"t",7725,m=1444,x=44.8,y=43.4},{"t",7726,m=1444,x=44.8,y=43.4}}},
  {t="Back to Camp Mojache", lv=50, g={{"t",3127,m=1444,x=74.4,y=43.4},{"a",3129,m=1444,x=74.4,y=43.4,ml=40},{"t",3129,m=1444,x=74.4,y=43.4}}},
  {t="Fly to Gadgetzan", lv=50, g={{"g",0,txt="Camp Mojache flight master",m=1444,x=75.4,y=44.3},{"z",0,txt="Fly to Gadgetzan",at="Gadgetzan"}}},
  {t="Gadgetzan", lv=50, g={{"t",4494,n2="Alchemist Pestlezugg, inside",m=1446,x=50.9,y=27}}},
  {t="Alchemist Pestlezugg", lv=50, w={{k="available",q=4496,minLevel=50,pre={4493,4494}}}, g={{"a",4496,n2="Alchemist Pestlezugg, inside",m=1446,x=50.9,y=27,ml=50}}},
  {t="Gadgetzan", lv=50, g={{"t",2641,m=1446,x=51.1,y=26.9},{"a",2661,m=1446,x=51.1,y=26.9,ml=44},{"a",4504,n2="Tran'rek, beside the wind rider master",m=1446,x=51.6,y=26.8,ml=48},{"t",2741,n2="The Egg-O-Matic, in the middle of town",m=1446,x=52.4,y=27},{"b",0,txt="Set your hearthstone at Gadgetzan",m=1446,x=52.5,y=27.9,at="Gadgetzan"},{"t",2661,m=1446,x=51.8,y=28.7},{"a",2662,m=1446,x=51.8,y=28.7,ml=44},{"t",2662,m=1446,x=51.8,y=28.7},{"i",0,txt="Tran'rek's tar and Pestlezugg's samples come from Un'Goro Crater."}}},
  {t="Marvon Rivetseeker", lv=50, n="Ride south along the road to the Broken Pillar; Marvon Rivetseeker camps beside it. From here the road west leads down into Un'Goro Crater, where the next guide starts.", g={{"t",3380,m=1446,x=52.7,y=45.9},{"a",3444,m=1446,x=52.7,y=45.9,ml=46},{"i",0,txt="Keep The Stone Circle: Marvon's chest is opened on a later visit."}}},
} end)

R:Segment({id="horde/50-60/01-un-goro-crater",title="Un'Goro Crater, Burning Steppes & Western Plaguelands",faction="Horde",min=51,max=53,zone=1449,zoneName="Un'Goro Crater",next="horde/50-60/02-felwood"}, function() return {
  {t="Un'Goro Crater", lv=51, g={{"g",0,txt="Marshal's Refuge",m=1449,x=41.9,y=2.7}}},
  {t="Into Un'Goro Crater", lv=51, n="From the Broken Pillar ride west to the long ramp that winds down into Un'Goro Crater, then follow the crater's north wall to Marshal's Refuge, a camp in the cliff caves. Everyone here is neutral.", g={{"fp",79,txt="Get the Marshal's Refuge flight path (Gryfe)",m=1449,x=45.2,y=5.8},{"a",4501,n2="the wooden sign beside Spraggle Frock, by the flight master: the pterrordax are on this guide's ground",m=1449,x=43.5,y=8.4,ml=49},{"a",4284,n2="J.D. Collie, at the back of the cave; below ground",m=1449,x=41.9,y=2.7,ml=47},{"a",3882,m=1449,x=43.5,y=7.4,ml=49},{"a",3883,m=1449,x=43.9,y=7.2,ml=48},{"a",3881,m=1449,x=44,y=7.1,ml=48},{"a",4145,m=1449,x=45.5,y=8.7,ml=47}}},
  {t="Out of the refuge", lv=51, g={{"a",4503,n2="Shizzle, at the refuge entrance",m=1449,x=44.2,y=11.6,ml=49},{"a",4243,n2="Karna Remtravel, just outside",m=1449,x=46.4,y=13.4,ml=48},{"i",0,txt="From here on pick up every Power Crystal (blue, green, red, yellow) and every Un'Goro Soil pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."}}},
  {t="Lakkari Tar Pits", lv=51, n="The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the Super Sticky Tar.", g={{"o",4504,i=1,txt="Super Sticky Tar x12",m=1449,x=45.7,y=15.5},{"o",4145,i=4,txt="Kill Bloodpetal Thresher x5",m=1449,x=61.1,y=27.6}}},
  {t="Pterrordax", lv=51, n="Pterrordax fly over the east of the crater, from the slopes below the refuge southward; their webbed scales are for Shizzle.", g={{"o",4503,i=2,txt="Webbed Pterrordax Scale x8",m=1449,x=56.8,y=11.7},{"o",4501,i=1,txt="Kill Pterrordax x10",m=1449,x=56.4,y=11.4},{"l",51,txt="Reach level 51 (11% in): grind Pterrordax",n2="grind on Pterrordax",m=1449,x=56.4,y=11.4,fr=0.11}}},
  {t="Power Crystals and soil", lv=51, n="The crystal clusters stand all over the crater, many around Fire Plume Ridge. Take a few extra of each colour for the pylons.", g={{"o",4284,i=1,txt="Red Power Crystal x7",m=1449,x=55.8,y=7.9},{"o",4284,i=2,txt="Yellow Power Crystal x7",m=1449,x=55.8,y=7.9},{"o",4284,i=3,txt="Green Power Crystal x7",m=1449,x=55.8,y=7.9},{"o",4284,i=4,txt="Blue Power Crystal x7",m=1449,x=55.8,y=7.9}}},
  {t="Lakkari Tar Pits: kill these as you meet them", lv=51, n="Ride south-west to Fire Plume Ridge, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot.\nSouth of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales Shizzle wants. Ravasaurs hunt in packs in the south-west: their claws are for Jes'rimon, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon.\nRide south-west along the western cliffs. Frenzied Pterrordax fly over the west side, and Bloodpetal Trappers grow in the same jungle.", g={{"o",4145,i=3,txt="Kill Bloodpetal Flayer x5",m=1449,x=54.2,y=13.7},{"o",3882,i=1,txt="Dinosaur Bone x8",m=1449,x=36.3,y=65.2},{"o",4503,i=1,txt="Webbed Diemetradon Scale x8",m=1449,x=35.6,y=61.1},{"o",4501,i=2,txt="Kill Frenzied Pterrordax x15",m=1449,x=34.6,y=65.6},{"o",4145,i=2,txt="Kill Bloodpetal Trapper x5",m=1449,x=34.7,y=62.8}}},
  {t="Research Equipment", lv=51, n="The expedition's lost equipment lies in the south-west jungle.", g={{"o",3881,i=2,txt="Research Equipment",m=1449,x=38.5,y=66.1}}},
  {t="The Slithering Scar", lv=51, n="Careful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd.", g={{"o",4496,i=1,txt="Gorishi Scent Gland",m=1449,x=45.5,y=72.3},{"l",51,txt="Reach level 51 (26% in): grind Gorishi Wasp",n2="grind on Gorishi Wasp",m=1449,x=46.4,y=74.5,fr=0.26}}},
  {t="The Slithering Scar", lv=51, g={{"o",3883,i=1,txt="Use Unused Scraping Vial",m=1449,x=48.7,y=85.3},{"o",3883,i=1,txt="Hive Wall Sample",m=1449,x=48.7,y=85.3}}},
  {t="Stegodons and ravasaurs", lv=51, g={{"h",11116,txt="Get A Mangled Journal",n2="A Mangled Journal, a rare drop",m=1449,x=57.4,y=77.1,n=1,opt=true},{"a",3884,n2="Use the Mangled Journal to start it",opt=true,ml=48}}},
  {t="Torwa Pathfinder", lv=51, n="Torwa camps in the south-east corner of the crater.", g={{"a",4290,m=1449,x=71.6,y=76,ml=48}}},
  {t="Fresh Threshadon Carcass", lv=51, n="North of Torwa, a dead Threshadon lies by the water.", g={{"o",4290,i=1,txt="Piece of Threshadon Carcass",m=1449,x=68.7,y=56.7}}},
  {t="Torwa Pathfinder", lv=51, g={{"t",4290,m=1449,x=71.6,y=76},{"a",4291,m=1449,x=71.6,y=76,ml=48}}},
  {t="Lar'korwi Mates", lv=51, n="The Lar'korwi Mates prowl the jungle north-west of Torwa.", g={{"o",4291,i=1,txt="Ravasaur Pheromone Gland x2",m=1449,x=67,y=73}}},
  {t="A Wrecked Raft", lv=51, n="The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it.", g={{"a",3844,m=1449,x=63,y=68.6,ml=47},{"t",3844,n2="Underwater",m=1449,x=63.1,y=69.1},{"a",3845,m=1449,x=63.1,y=69.1,ml=47},{"o",3845,i=1,txt="Large Compass",m=1449,x=63.1,y=69.1},{"o",3845,i=2,txt="Curled Map Parchment",m=1449,x=63.1,y=69.1},{"o",3845,i=3,txt="Lion-headed Key",m=1449,x=63.1,y=69.1}}},
  {t="Torwa Pathfinder", lv=51, g={{"t",4291,m=1449,x=71.6,y=76}}},
  {t="Lashers and Threshers", lv=51, n="Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle.", g={{"o",4145,i=4,txt="Kill Bloodpetal Thresher x5",m=1449,x=75.1,y=48.6},{"l",51,txt="Reach level 51 (38% in): grind Bloodpetal Thresher",n2="grind on Bloodpetal Thresher",m=1449,x=76.1,y=48,fr=0.38}}},
  {t="Un'Goro Crater: kill these as you meet them", lv=51, n="The expedition's crate sits at an abandoned camp in the eastern jungle.", g={{"o",4145,i=1,txt="Kill Bloodpetal Lasher x5",m=1449,x=75,y=44.7},{"o",3881,i=1,txt="Crate of Foodstuffs",m=1449,x=68.5,y=36.5}}},
  {t="Marshal's Refuge", lv=51, g={{"t",4503,n2="Shizzle, at the entrance",m=1449,x=44.2,y=11.6},{"t",4501,n2="Spraggle Frock, beside the flight master",m=1449,x=43.6,y=8.5},{"t",4145,m=1449,x=45.5,y=8.7},{"a",4147,m=1449,x=45.5,y=8.7,ml=47},{"t",3845,m=1449,x=44.7,y=8.1},{"a",3908,m=1449,x=44.7,y=8.1,ml=47},{"t",3881,m=1449,x=44,y=7.1},{"t",3884,m=1449,x=44,y=7.1,opt=true},{"t",3883,m=1449,x=43.9,y=7.2},{"t",3882,m=1449,x=43.5,y=7.4},{"t",4284,n2="J.D. Collie, below ground",m=1449,x=41.9,y=2.7},{"a",4285,m=1449,x=41.9,y=2.7,ml=47},{"a",4287,m=1449,x=41.9,y=2.7,ml=47},{"a",4288,m=1449,x=41.9,y=2.7,ml=47},{"i",0,txt="Keep Larion's Marvon's Workshop and Linken's letter for later guides."}}},
  {t="Northern Pylon", lv=51, n="The pylon stands on the slope east of the refuge.", g={{"g",0,txt="Northern Crystal Pylon",m=1449,x=56.5,y=12.5},{"o",4285,i=1,txt="Northern Crystal Pylon",m=1449,x=56.5,y=12.5}}},
  {t="Gorillas", lv=51, n="The gorillas live on the north-east plateau. Stay out of the deepest cave: U'cha lives there.", g={{"t",4243,n2="A-Me 01, the robot on the plateau; below ground",m=1449,x=67.7,y=16.8},{"i",0,txt="A-Me 01 then wants a Mithril Casing, an Engineering item. Skip it unless you have one."}}},
  {t="Un'Goro Crater: kill these as you meet them", lv=51, n="Careful: Gorishi Workers may call for help within 25 yd when below 45% health; silithids cast Silithid Pox and Tunnelers and the Hive Guard use Tunneler Acid.", g={{"o",3761,i=1,txt="Un'Goro Soil x20",m=1449,x=69.2,y=20.5},{"o",4496,i=2,txt="Un'Goro Soil x5",m=1449,x=69.2,y=20.5}}},
  {t="Eastern Pylon", lv=51, n="Ride down the east side of the crater to the pylon on the eastern cliffs.", g={{"g",0,txt="Eastern Crystal Pylon",m=1449,x=77.2,y=50},{"o",4287,i=1,txt="Eastern Crystal Pylon",m=1449,x=77.2,y=50}}},
  {t="The Marshlands", lv=52, n="Careful: There are many ravasaurs roaming the area, so you can easily pull several at the same time.\nBelow level 52, keep hunting the ravasaurs here after the eighth claw: The Rise of the Machines at Kargath needs level 52, and the Plaguelands quests at the end of this guide are level 55. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.", g={{"o",4300,i=1,txt="White Ravasaur Claw x8",m=1449,x=79.7,y=49.8},{"l",52,txt="Reach level 52: grind Ravasaur",n2="grind on Ravasaur",m=1449,x=67.5,y=60.2}}},
  {t="Western Pylon", lv=52, n="Cross the south of the crater to the pylon on the western cliffs.", g={{"g",0,txt="Western Crystal Pylon",m=1449,x=23.9,y=59.2},{"o",4288,i=1,txt="Western Crystal Pylon",m=1449,x=23.9,y=59.2}}},
  {t="J.D. Collie", lv=52, n="Ride north back to Marshal's Refuge.", g={{"t",4285,n2="Below ground",m=1449,x=41.9,y=2.7},{"t",4287,m=1449,x=41.9,y=2.7},{"t",4288,m=1449,x=41.9,y=2.7},{"a",4321,m=1449,x=41.9,y=2.7,ml=47},{"t",4321,m=1449,x=41.9,y=2.7}}},
  {t="To Gadgetzan", lv=52, g={{"g",0,txt="Gadgetzan",m=1446,x=52.5,y=27.9}}},
  {t="Gadgetzan", lv=52, g={{"t",4504,m=1446,x=51.6,y=26.8},{"t",4496,n2="Alchemist Pestlezugg, inside",m=1446,x=50.9,y=27},{"a",4507,m=1446,x=50.9,y=27,ml=50}}},
  {t="Orgrimmar", lv=52, n="Fly to Orgrimmar and train before the boat to Powderfuse Port: the Undercity stop later in this guide has no Hunter or Shaman trainer.", f={c={"HUNTER","SHAMAN"}}, g={{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"},{"tr",0,txt="Visit your class trainer"}}},
  {t="Back to Gadgetzan", lv=52, f={c={"HUNTER","SHAMAN"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Gadgetzan",at="Gadgetzan"}}},
  {t="Boat to Powderfuse Port", lv=52, g={{"g",0,txt="Boat to Powderfuse Port",m=1446,x=67.6,y=23.1},{"a",4324,n2="Yorba Screwspigot, by the dock: for Yuka Screwspigot at Flame Crest, later in this guide",m=1446,x=67,y=24,ml=48}}},
  {t="Badlands", lv=52, n="Leave Riverglades on foot to the north-west, north of Twilight's Shroud, into the Badlands.", g={{"g",0,txt="Kargath",m=1418,x=3.4,y=48.1}}},
  {t="Kargath", lv=52, n="Kargath is built into the cliffs on the Badlands' west edge.", g={{"a",3821,m=1418,x=3.4,y=48.1,ml=48},{"a",4061,m=1418,x=3,y=47.8,ml=52}}},
  {t="Into the Searing Gorge", lv=52, n="Take the pass out of Kargath's west side into the Searing Gorge, then ride south across the gorge to the long bridge into Blackrock Mountain. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals.", g={{"g",0,txt="Bridge into Blackrock Mountain",m=1427,x=34.8,y=83}}},
  {t="Flame Crest", lv=52, n="The mountain lets you out beside Blackrock Stronghold, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at Flame Crest.", g={{"fp",70,txt="Get the Flame Crest flight path (Vahgruk)",m=1428,x=65.7,y=24.2},{"a",4296,m=1428,x=65.2,y=23.9,ml=50},{"a",4726,m=1428,x=65.2,y=24,ml=50},{"t",4324,m=1428,x=66.1,y=21.9}}},
  {t="Sha'ni Proudtusk", lv=52, n="Follow the cliffs south to Dreadmaul Rock, the Firegut ogres' hill. Sha'ni Proudtusk's remains lie at its foot.", g={{"t",3821,m=1428,x=80,y=45.4},{"a",3822,m=1428,x=80,y=45.4,ml=48}}},
  {t="Krom'Grul", lv=52, n="Krom'Grul walks the caves and mine tunnels of Dreadmaul Rock; if he isn't home, clear the ogres around the entrances until he comes back.", g={{"o",3822,i=1,txt="Sha'ni's Nose-Ring",n2="Below ground",m=1428,x=79.7,y=47.4}}},
  {t="Ruins of Thaurissan: kill these as you meet them", lv=52, n="Ride west to the dig site. War Reaver golems (53) stomp around it and drop the shards often; the Tablet of the Seven stands in its middle among the Thaurissan dwarves. Copy it.\nBlack Broodlings nest in the hills just east of Flame Crest. Use Tinkee's Draco-Incarcinatrix 900 on a broodling when it is almost dead to capture its essence.", g={{"o",4061,i=1,txt="Fractured Elemental Shard x10",m=1428,x=85.8,y=57.1},{"o",4726,i=1,txt="Broodling Essence x8",m=1428,x=81,y=28},{"o",4726,i=1,txt="Use Draco-Incarcinatrix 900",m=1428,x=81,y=28},{"o",4296,i=1,txt="Tablet Transcript",m=1428,x=54.1,y=40.8}}},
  {t="Flame Crest", lv=52, n="Back north-east to Flame Crest.", g={{"t",4296,m=1428,x=65.2,y=23.9},{"t",4726,m=1428,x=65.2,y=24},{"a",4808,m=1428,x=65.2,y=24,ml=50},{"i",0,txt="Keep Tinkee's letter: Felnok Steelspring is in Everlook, Winterspring."}}},
  {t="Kargath", lv=52, g={{"z",0,txt="Fly to Kargath",at="Kargath"},{"t",3822,m=1418,x=3.4,y=48.1},{"t",4061,m=1418,x=3,y=47.8},{"i",0,txt="Theodora's next errand goes to Lotwil east of town and then into Blackrock Depths: skip it."}}},
  {t="Fly to Tarren Mill", lv=52, g={{"g",0,txt="Kargath flight master",m=1418,x=4.1,y=44.9},{"z",0,txt="Fly to Tarren Mill",at="Tarren Mill"}}},
  {t="Apothecary Lydon", lv=52, g={{"t",2933,n2="Inside",m=1424,x=61.4,y=19.1}}},
  {t="Fly to Undercity", lv=52, g={{"g",0,txt="Tarren Mill flight master",m=1424,x=60.2,y=18.8},{"z",0,txt="Fly to Undercity",at="Undercity"}}},
  {t="Harbinger Balthazad", lv=52, g={{"a",5094,n2="Harbinger Balthazad, the Trade Quarter, beside the bat master",m=1458,x=63.9,y=44.1,ml=50}}},
  {t="Oran Snakewrithe", lv=52, n="Oran stands in the Magic Quarter.", g={{"t",2782,m=1458,x=73.1,y=32.9},{"t",2995,m=1458,x=73.1,y=32.9},{"t",8273,m=1458,x=73.1,y=32.9}}},
  {t="Undercity", lv=52, g={{"a",3568,n2="Chemist Cuely, the Apothecarium: the vials fill in Azshara later",m=1458,x=48.7,y=71.4,ml=45},{"t",864,n2="Apothecary Zinge, near Cuely in the Apothecarium",m=1458,x=50.1,y=68},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","PALADIN","ROGUE","PRIEST","MAGE","WARLOCK"}}},{"t",3542,n2="Andron Gant, the Rogues' Quarter",m=1458,x=54.8,y=76.3},{"a",3564,m=1458,x=54.8,y=76.3,ml=45}}},
  {t="Tirisfal Glades", lv=52, g={{"g",0,txt="The Bulwark",m=1420,x=83.3,y=72.3}}},
  {t="The Bulwark", lv=52, n="Leave the Undercity and ride east along the road through Tirisfal Glades to the Bulwark, the Forsaken fort on the border.", g={{"a",5901,m=1420,x=83.3,y=72.3,ml=48},{"i",0,txt="Take a Box of Incendiaries from the crate next to Derrington for Scarlet Diversions, done on the way back. Equip the Argent Dawn Commission: Scourgestones only drop while you wear it."},{"t",5094,m=1420,x=83.1,y=68.9},{"a",5096,m=1420,x=83.1,y=68.9,ml=50},{"t",5405,m=1420,x=83.2,y=68.5}}},
  {t="Scarlet forward camp", lv=52, n="From the Bulwark, follow the road east into the Western Plaguelands. The Scarlet Crusade's tents stand just past Felstone Farm, between Felstone Field and Dalson's Tears. Torch the command tent with the Box of Incendiaries and plant the Scourge banner.", g={{"g",0,txt="Go here",m=1422,x=40.7,y=52},{"i",0,txt="Scarlet Crusade Forward Camp",m=1422,x=40.7,y=51.9},{"c",5096,txt="Destroy the command tent and plant the Scourge banner in the camp"}}},
  {t="Janice Felstone", lv=52, n="Back a few steps west to Felstone Farm, the first farm along the road; Janice waits in the house.", g={{"a",5021,n2="Upstairs",m=1422,x=38.4,y=54,ml=50},{"t",5021,n2="Janice's Parcel, beside the house; inside",m=1422,x=38.7,y=55.2},{"a",5023,m=1422,x=38.7,y=55.2,ml=50},{"i",0,txt="Keep the parcel: Royal Overseer Bauhaus is in the Undercity. Keep A Plague Upon Thee: its termite mounds are in Terrordale, on the next guide's ride to Tirion. The next guide starts with Mulgris Deepriver by the Writhing Haunt, south-east of here."}}},
} end)

R:Segment({id="horde/50-60/02-felwood",title="Felwood & Western Plaguelands",faction="Horde",min=53,max=55,zone=1448,zoneName="Felwood",next="horde/50-60/03-winterspring"}, function() return {
  {t="Mulgris Deepriver", lv=53, n="He camps by the Writhing Haunt, south-east of Dalson's Tears.", g={{"a",4984,n2="Inside",m=1422,x=53.7,y=64.7,ml=51}}},
  {t="Tirion Fordring", lv=53, n="Ride north along the eastern hills; Tirion lives in a small house by the Thondroril River, at the border with the Eastern Plaguelands.", g={{"a",5542,m=1423,x=5.2,y=35.6,ml=52},{"a",5543,m=1423,x=5.2,y=35.6,ml=52},{"a",5544,m=1423,x=5.2,y=35.6,ml=52},{"i",0,txt="Tirion's hunts are in the Eastern Plaguelands: keep them for later."}}},
  {t="Augustus the Touched", lv=53, n="Cross the river east into Terrordale, the ruined town in the north-west of the Eastern Plaguelands. Augustus sits in a hut at its edge.", g={{"a",6164,n2="Inside",m=1423,x=11.4,y=26.4,ml=50}}},
  {t="Terrordale: kill these as you meet them", lv=53, n="The book lies in the ruined inn of Terrordale; the undead in the town are 54-56, so pull them one at a time.\nThe Large Termite Mounds stand all over the hills east of Terrordale. Use the Empty Termite Jar on each mound you pass.", g={{"o",6164,i=1,txt="Augustus' Receipt Book",n2="Upstairs",m=1423,x=14,y=24.2},{"o",5901,i=1,txt="Plagueland Termites x100",m=1423,x=15.9,y=26.8},{"h",12840,txt="Get Minion's Scourgestone x20",n2="Minion's Scourgestones: the Terrordale undead drop them while you wear the Argent Dawn Commission",m=1423,x=16.3,y=25.9,n=20,opt=true},{"i",0,txt="Keep Augustus' Receipt Book: Augustus takes it back on the Eastern Plaguelands guide's Terrordale stop."}}},
  {t="Kirsta Deepshadow", lv=53, n="Ride back west over the river and on to the Northridge Lumber Camp; Kirsta hides on the hill north-east of it.", g={{"a",6004,m=1422,x=51.9,y=28.1,ml=50}}},
  {t="Level 52.63", lv=53, n="Top up here to level 52.63 before the hand-ins at Dalson's Tears: they take you to level 53. The Scarlet Mages and Knights here count for Kirsta's Unfinished Business. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.", w={{k="level",op="<",n=52,frac=0.63}}, g={{"g",0,txt="Scarlet Mage",m=1422,x=53.1,y=37.3},{"l",52,txt="Reach level 52 (63% in): grind Scarlet Mage",n2="grind on Scarlet Mage",m=1422,x=52.8,y=37.6,fr=0.63}}},
  {t="Diseased Wolves", lv=53, n="The wolves roam the fields between Andorhal, Dalson's Tears and the Writhing Haunt. Finish them on the ride back east.", g={{"o",4984,i=1,txt="Kill Diseased Wolf x8",m=1422,x=49.8,y=35.6},{"o",6004,i=1,txt="Kill Scarlet Medic x2",m=1422,x=51.8,y=44.8},{"o",6004,i=2,txt="Kill Scarlet Hunter x2",m=1422,x=51.6,y=44.5},{"o",6004,i=4,txt="Kill Scarlet Knight x2",m=1422,x=50.2,y=42.2}}},
  {t="Dalson's Tears farmhouse", lv=53, n="The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A Wandering Skeleton carries the outhouse key; Farmer Dalson comes out when you open the outhouse and carries the cabinet key.", g={{"t",5058,m=1422,x=47.8,y=50.7},{"h",12738,txt="Get Dalson Outhouse Key",m=1422,x=47.7,y=49.9,n=1},{"h",12739,txt="Get Dalson Cabinet Key",m=1422,x=48.1,y=49.7,n=1},{"t",5059,m=1422,x=48.1,y=49.6},{"t",5060,m=1422,x=47.4,y=49.6}}},
  {t="Mulgris Deepriver", lv=53, g={{"t",4984,n2="Inside",m=1422,x=53.7,y=64.7},{"a",4985,m=1422,x=53.7,y=64.7,ml=51}}},
  {t="Diseased Grizzlies", lv=53, n="The bears roam the hills north and east of the Writhing Haunt. Below level 53.02, keep hunting them after the eighth: the hand-ins at the Writhing Haunt take you to level 54. Or, with a group, run the Sunken Temple dungeon or the Blackrock Depths dungeon instead.", g={{"o",4985,i=1,txt="Kill Diseased Grizzly x8",m=1422,x=55.2,y=64.5},{"l",53,txt="Reach level 53 (2% in): grind Diseased Grizzly",n2="grind on Diseased Grizzly",m=1422,x=55.2,y=64.5,fr=0.02}}},
  {t="Mulgris Deepriver", lv=53, g={{"t",4985,n2="Inside",m=1422,x=53.7,y=64.7},{"a",4987,m=1422,x=53.7,y=64.7,ml=51},{"i",0,txt="Keep the branch: Nara Wildmane is in Thunder Bluff."}}},
  {t="Scarlet Crusade", lv=53, n="Knights and magi work the Northridge Lumber Camp; the medics and hunters camp south of it.", g={{"o",6004,i=4,txt="Kill Scarlet Knight x2",m=1422,x=50.2,y=42.2},{"o",6004,i=2,txt="Kill Scarlet Hunter x2",m=1422,x=51.5,y=44.1},{"o",6004,i=3,txt="Kill Scarlet Mage x2",m=1422,x=51.3,y=40.5},{"o",6004,i=1,txt="Kill Scarlet Medic x2",m=1422,x=51.8,y=44.8},{"l",53,txt="Reach level 53 (24% in): grind Scarlet Medic",n2="grind on Scarlet Medic",m=1422,x=51.8,y=44.8,fr=0.24}}},
  {t="Tirisfal Glades", lv=53, g={{"g",0,txt="The Bulwark",m=1420,x=83.2,y=68.5}}},
  {t="The Bulwark", lv=53, n="Ride south-west past Felstone Farm and follow the road west back to the Bulwark.", g={{"t",5407,m=1420,x=83.2,y=68.5,opt=true},{"t",5408,m=1420,x=83.2,y=68.5,opt=true},{"t",5096,m=1420,x=83.1,y=68.9},{"a",5098,m=1420,x=83.1,y=68.9,ml=50},{"a",5228,m=1420,x=83.1,y=68.9,ml=50},{"t",5228,m=1420,x=83,y=71.9},{"a",5229,m=1420,x=83,y=71.9,ml=50},{"t",5901,m=1420,x=83.3,y=72.3},{"a",5902,m=1420,x=83.3,y=72.3,ml=48},{"i",0,txt="Derrington's watchtowers, Vandis' cauldron and Mickey's barrel are done on a later visit: keep them."}}},
  {t="Level 53.34", lv=53, n="Top up here to level 53.34 before the hand-ins at Jaedenar: they take you to level 54. Or, with a group, run the Sunken Temple dungeon or the Blackrock Depths dungeon instead.", w={{k="level",op="<",n=53,frac=0.34}}, g={{"g",0,txt="Scarlet Medic",m=1422,x=40.5,y=51.8},{"l",53,txt="Reach level 53 (34% in): grind Scarlet Medic",n2="grind on Scarlet Medic",m=1422,x=40.5,y=51.4,fr=0.34}}},
