  {t="Emerald Sanctuary", lv=53, n="The druids' camp is just past the border.", g={{"a",5156,m=1448,x=50.9,y=81.6,ml=48},{"a",5155,m=1448,x=51.2,y=82.1,ml=48},{"a",8460,n2="Grazle, at the south edge of the camp",m=1448,x=50.9,y=85,ml=45},{"a",4102,n2="Maybess Riverbreeze, on the west side of the camp",m=1448,x=46.8,y=83.1,ml=48}}},
  {t="Deadwood Village", lv=53, n="The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your Timbermaw Hold reputation; keep the headdress feathers. Keep killing them until level 53.92: the Sanctuary's next hand-ins and Jaedenar want it. Or, with a group, run the Sunken Temple dungeon or the Blackrock Depths dungeon instead.", g={{"o",8460,i=1,txt="Kill Deadwood Warrior x6",m=1448,x=46.3,y=89.2},{"o",8460,i=3,txt="Kill Deadwood Gardener x6",m=1448,x=46.2,y=90},{"l",53,txt="Reach level 53 (92% in): grind Deadwood Warrior",n2="grind on Deadwood Warrior",m=1448,x=46.3,y=89.2,fr=0.92},{"o",8460,i=2,txt="Kill Deadwood Pathfinder x6",m=1448,x=46.4,y=88.9}}},
  {t="Southern Jaedenar", lv=53, n="Follow the road north-west. The south of Jaedenar, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds.", g={{"o",5155,i=1,txt="Kill Jaedenar Hound x4",m=1448,x=38.7,y=61.9},{"o",5155,i=2,txt="Kill Jaedenar Guardian x4",m=1448,x=38.5,y=61.1},{"o",5155,i=3,txt="Kill Jaedenar Adept x6",m=1448,x=38.2,y=61.5},{"o",5155,i=4,txt="Kill Jaedenar Cultist x6",m=1448,x=38.1,y=61.1}}},
  {t="A Strange Red Key", lv=53, n="A Blood Red Key dropped: use it to start the quest, then free Arko'narin from her cage in Shadow Hold, the cave at the north end of Jaedenar.", w={{k="has",n=1,item=13140}}, g={{"a",5202,opt=true,ml=49}}},
  {t="Captured Arko'narin", lv=53, w={{k="onquest",q={5202}}}, g={{"t",5202,n2="Captured Arko'narin, below ground",m=1448,x=36.2,y=55.5}}},
