  {t="Rescue From Jaedenar", lv=53, n="Walk Arko'narin out of Shadow Hold and keep her alive until she is out of the cave.", w={{k="onquest",q={5203}}}, g={{"c",5203,txt="Protect Arko'narin out of Shadow Hold",n2="Arko'narin, below ground",m=1448,x=36.2,y=55.5}}},
