  {t="Emerald Sanctuary", lv=53, g={{"t",5155,m=1448,x=51.2,y=82.1},{"a",5157,m=1448,x=51.2,y=82.1,ml=48},{"t",8460,m=1448,x=50.9,y=85},{"a",8462,m=1448,x=50.9,y=85,ml=45},{"t",8466,m=1448,x=50.9,y=85,opt=true}}},
  {t="The Jaedenar moonwell", lv=53, n="Back north to Jaedenar. Fill Greta's canteen at the corrupted moonwell in the middle of the southern camp.", g={{"o",5157,i=1,txt="Use Empty Canteen",m=1448,x=35.2,y=59.8},{"o",5157,i=1,txt="Corrupt Moonwell Water",m=1448,x=35.2,y=59.8}}},
  {t="Rakaiah", lv=53, n="The succubus Rakaiah waits in the middle of Jaedenar, beside the Remains of Trey Lightforge.", w={{k="onquest",q={5204}}}, g={{"o",5204,i=1,txt="Kill Rakaiah",n2="Below ground",m=1448,x=38.3,y=50.5},{"t",5204,n2="Remains of Trey Lightforge, below ground",m=1448,x=38.5,y=50.4}}},
  {t="The Remains of Trey Lightforge", lv=53, w={{k="available",q=5385,minLevel=49,pre={5204}}}, g={{"a",5385,n2="Remains of Trey Lightforge, below ground",m=1448,x=38.5,y=50.4,opt=true,ml=49}}},
  {t="Bloodvenom Post", lv=53, n="The Horde camp just north of Jaedenar.", g={{"fp",48,txt="Get the Bloodvenom Post flight path (Brakkar)",m=1448,x=34.4,y=54},{"a",6162,m=1448,x=34.8,y=52.7,ml=46},{"a",4521,n2="Trull Failbane: the owlbeasts are in Winterspring",m=1448,x=34.7,y=52.8,ml=52},{"a",4505,m=1448,x=34.2,y=52.3,ml=49}}},
  {t="Shatter Scar Vale", lv=53, n="East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters.", g={{"g",0,txt="Southern crater",m=1448,x=41.6,y=43},{"g",0,txt="Western crater",m=1448,x=40.4,y=41.2},{"g",0,txt="Northern crater",m=1448,x=42.2,y=40.3},{"c",5156,txt="Entropic Beast; Entropic Horror; Explore the craters in Shatter Scar Vale"},{"o",5156,i=1,txt="Kill Entropic Beast x2",m=1448,x=41.7,y=40.1},{"o",5156,i=2,txt="Kill Entropic Horror x2",m=1448,x=41.7,y=40.1}}},
  {t="Irontree Woods", lv=54, n="Follow the road north-east to Irontree Woods. The Warpwood Moss Flayers and Shredders on the east side of the woods each carry a Blood Amber; Angerclaw Grizzlies and Felpaw Ravagers roam the same woods for Talo. Below level 54.21, keep hunting the grizzlies and ravagers: the hand-ins at Bloodvenom Post and the Emerald Sanctuary take you to level 55. Or, with a group, run the Blackrock Depths dungeon or the Sunken Temple dungeon instead.", g={{"o",4120,i=1,txt="Kill Angerclaw Grizzly x12",m=1448,x=53.5,y=28.1},{"o",4120,i=2,txt="Kill Felpaw Ravager x12",m=1448,x=53.8,y=27.7},{"l",54,txt="Reach level 54 (21% in): grind Angerclaw Grizzly",n2="grind on Angerclaw Grizzly",m=1448,x=53.5,y=28.1,fr=0.21}}},
  {t="Irontree Woods", lv=54, g={{"o",4102,i=1,txt="Blood Amber x15",n2="Below ground",m=1448,x=57.2,y=21.9},{"l",54,txt="Reach level 54 (30% in): grind Warpwood Shredder",n2="grind on Warpwood Shredder",m=1448,x=57.4,y=21.7,fr=0.3}}},
  {t="Felpaw Village", lv=54, n="The Deadwood furbolg village just west of the tunnel. Chieftain Bloodmaw (56) stands among them. Meilosh, a friendly furbolg, sits at the north end of the village.", g={{"a",6031,n2="Meilosh: keep 30 Runecloth for him; he trades only at Neutral with the Timbermaw; below ground",m=1448,x=65.7,y=2.8,opt=true,ml=50}}},
  {t="Nafien", lv=54, n="The road ends at Nafien, outside the Timbermaw Hold tunnel in the far north-east.", g={{"t",8462,m=1448,x=64.8,y=8.1},{"a",8461,m=1448,x=64.8,y=8.1,ml=45}}},
  {t="Felpaw Village", lv=54, n="Careful: Den Watchers are level 53-54; they call nearby allies within 25 yd once below 50% health and run off for help below 15%.\nBelow level 54.54, keep fighting the Deadwood here after Nafien's count: the hand-ins at Timbermaw Hold and the Emerald Sanctuary take you to level 55. Or, with a group, run the Blackrock Depths dungeon or the Sunken Temple dungeon instead.\nKeep killing them until one drops a Deadwood Ritual Totem, about one kill in thirty, then right-click it: Kernda in Timbermaw Hold takes it once the Timbermaw are Neutral to you, now if they already are, or when the last guide passes the cave again at 59.", g={{"o",8461,i=1,txt="Kill Deadwood Den Watcher x6",m=1448,x=63.7,y=6},{"o",8461,i=2,txt="Kill Deadwood Avenger x6",m=1448,x=63,y=7.3},{"o",8461,i=3,txt="Kill Deadwood Shaman x6",m=1448,x=62.7,y=7.1},{"h",20741,txt="Get Deadwood Ritual Totem",m=1448,x=62.7,y=7.1,n=1},{"a",8470,ml=45},{"l",54,txt="Reach level 54 (54% in): grind Deadwood Den Watcher",n2="grind on Deadwood Den Watcher",m=1448,x=62.8,y=8,fr=0.54}}},
  {t="Nafien", lv=54, g={{"t",8461,m=1448,x=64.8,y=8.1},{"a",8465,m=1448,x=64.8,y=8.1,ml=45},{"t",8467,m=1448,x=64.8,y=8.1,opt=true},{"i",0,txt="Keep Speak to Salfa for Winterspring."}}},
  {t="Timbermaw Hold", lv=54, n="Step into the cave: Kernda stands just inside.", g={{"t",8470,n2="Kernda: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map",m=1448,x=65.5,y=3.5,opt=true}}},
  {t="Emerald Sanctuary", lv=54, n="Ride the road south through Felwood to the Sanctuary.", g={{"t",5156,m=1448,x=50.9,y=81.6},{"t",5157,m=1448,x=51.2,y=82.1},{"a",5158,m=1448,x=51.2,y=82.1,ml=48},{"t",4102,n2="Maybess Riverbreeze, on the west side of the Sanctuary",m=1448,x=46.8,y=83.1},{"i",0,txt="Keep Seeking Spiritual Aid: Islen Waterseer is in the Barrens."}}},
  {t="Jessir Moonbow", lv=54, w={{k="onquest",q={5385}}}, g={{"t",5385,m=1448,x=51.4,y=82}}},
  {t="Overlord Ror", lv=54, n="Ror stands at the far south end of Deadwood Village.", g={{"o",6162,i=1,txt="Overlord Ror's Claw",m=1448,x=48.2,y=94.3}}},
  {t="Level 54.7", lv=54, n="Top up here to level 54.7 before the hand-ins at Bloodvenom Post : they take you to level 55. Or, with a group, run the Blackrock Depths dungeon or the Sunken Temple dungeon instead.", w={{k="level",op="<",n=54,frac=0.7}}, g={{"g",0,txt="Deadwood Pathfinder",m=1448,x=46.3,y=89.4},{"l",54,txt="Reach level 54 (70% in): grind Deadwood Pathfinder",n2="grind on Deadwood Pathfinder",m=1448,x=46.4,y=88.9,fr=0.7}}},
  {t="The Jadefire moonwell", lv=54, n="Ride back south past Jaedenar to the corrupted moonwell of the Jadefire satyrs and fill Winna's flasket there.", g={{"o",4505,i=1,txt="Use Hardened Flasket",m=1448,x=32.3,y=66.6},{"o",4505,i=1,txt="Filled Flasket",m=1448,x=32.3,y=66.6}}},
