  {t="Winna's kitten", lv=54, n="Take the kitten to the same moonwell and release it there with Winna's Kitten Carrier; once it has turned into a Corrupted Saber, bring it back to Winna and click on it to hand it over.", g={{"o",4506,i=1,txt="Use Winna's Kitten Carrier",n2="Winna's Kitten Carrier, at the Jadefire moonwell",m=1448,x=32.3,y=66.6},{"c",4506,txt="Return the corrupted cat to Winna Hazzard"}}},
