R:Segment({id="horde/50-60/03-winterspring",title="Winterspring",faction="Horde",min=55,max=56,zone=1452,zoneName="Winterspring",next="horde/50-60/04-azshara"}, function() return {
  {t="Into Winterspring", lv=55, g={{"g",0,txt="Into Winterspring",m=1452,x=28,y=34.6}}},
  {t="Salfa", lv=55, n="Salfa stands right at the Winterspring exit of Timbermaw Hold's tunnel, where you come out.", g={{"t",8465,m=1452,x=27.7,y=34.5},{"a",8464,m=1452,x=27.7,y=34.5,ml=45}}},
  {t="Donova Snowden", lv=55, n="Ride south from the tunnel: Donova camps among the steaming pools of Frostfire Hot Springs, in the west of the valley.", g={{"t",3908,n2="Linken's letter",m=1452,x=31.3,y=45.2},{"a",3909,m=1452,x=31.3,y=45.2,ml=47},{"a",5082,m=1452,x=31.3,y=45.2,ml=52},{"i",0,txt="The Videre Elixir comes from Gregan Brewspewer in Feralas, later in this guide."}}},
  {t="Frostfire Hot Springs: kill these as you meet them", lv=55, n="Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every Runecloth you loot for Meilosh.", g={{"o",5082,i=1,txt="Kill Winterfall Pathfinder x8",m=1452,x=33.4,y=37.7},{"o",5082,i=3,txt="Kill Winterfall Totemic x8",m=1452,x=33,y=36.8},{"o",5082,i=2,txt="Kill Winterfall Den Watcher x8",m=1452,x=30.5,y=36.9},{"o",8464,i=2,txt="Kill Winterfall Den Watcher x8",m=1452,x=30.5,y=36.9},{"o",4521,i=2,txt="Kill Ragged Owlbeast x15",m=1452,x=33,y=39.3},{"h",12771,txt="Get Empty Firewater Flask",n2="Empty Firewater Flask: about one Winterfall furbolg in ten carries one; keep killing them until it drops",m=1452,x=33.4,y=37.7,n=1},{"a",5083,ml=52},{"h",20742,txt="Get Winterfall Ritual Totem",n2="Winterfall Ritual Totem, a rare drop from the Winterfall furbolgs",m=1452,x=33.4,y=37.7,n=1,opt=true},{"a",8471,opt=true,ml=50}}},
  {t="Donova Snowden", lv=55, g={{"t",5082,m=1452,x=31.3,y=45.2},{"t",5083,m=1452,x=31.3,y=45.2},{"a",5084,m=1452,x=31.3,y=45.2,ml=52},{"i",0,txt="Falling to Corruption is turned in at the Deadwood Cauldron in Felwood, on a later trip."}}},
  {t="Raging Owlbeasts", lv=55, n="Raging Owlbeasts roam the hills north of Lake Kel'Theril, by the road between Frostfire Hot Springs and Everlook.", g={{"o",4521,i=1,txt="Kill Raging Owlbeast x15",m=1452,x=51.3,y=33.8}}},
  {t="Winterspring", lv=55, g={{"g",0,txt="Everlook",m=1452,x=60.7,y=38.2}}},
  {t="Everlook", lv=55, n="Everlook is the goblin town on the east side of the valley, past the owlbeast hills.", g={{"fp",53,txt="Get the Everlook flight path (Yugrek)",m=1452,x=60.5,y=36.3},{"i",0,txt="Gregor's quests lead to other zones: keep them."},{"a",3783,m=1452,x=60.9,y=37.6,ml=52},{"b",0,txt="Set your hearthstone at Everlook",m=1452,x=61.4,y=38.8,at="Everlook"},{"a",6029,n2="Gregor Greystone, inside",m=1452,x=61.4,y=39,ml=50},{"a",6030,m=1452,x=61.4,y=39,ml=50},{"t",4808,m=1452,x=61.6,y=38.6},{"a",4809,m=1452,x=61.6,y=38.6,ml=50}}},
  {t="Ice Thistle yetis", lv=55, n="The yeti hills start just south-east of Everlook. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in.", g={{"o",3783,i=1,txt="Thick Yeti Fur x10",m=1452,x=64,y=39.8}}},
  {t="Umi Rumplesnicker", lv=55, g={{"t",3783,m=1452,x=60.9,y=37.6},{"a",977,m=1452,x=60.9,y=37.6,ml=52}}},
  {t="Level 55.04", lv=55, n="Top up here to level 55.04 before the hand-ins at Everlook: they take you to level 56. Or, with a group, run the Blackrock Depths dungeon or the Blackrock Spire dungeon (Lower) instead.", w={{k="level",op="<",n=55,frac=0.04}}, g={{"g",0,txt="Ice Thistle Patriarch",m=1452,x=67,y=44.2},{"l",55,txt="Reach level 55 (4% in): grind Ice Thistle Patriarch",n2="grind on Ice Thistle Patriarch",m=1452,x=66.8,y=44.9,fr=0.04}}},
  {t="Pristine Yeti Horns", lv=55, n="Matriarchs and Patriarchs hit hard: pull them one at a time.", g={{"o",977,i=1,txt="Pristine Yeti Horn x2",n2="Below ground",m=1452,x=66.8,y=44.9}}},
  {t="Chillwind chimaeras", lv=55, n="The chimaeras roam the snowfields south and west of Everlook. Stay clear of Mazthoril's cave: its blue dragonkin are elite.", g={{"o",4809,i=1,txt="Uncracked Chillwind Horn x8",m=1452,x=66.8,y=47.4}}},
  {t="Umi Rumplesnicker", lv=55, g={{"t",977,m=1452,x=60.9,y=37.6},{"a",5163,m=1452,x=60.9,y=37.6,ml=52},{"i",0,txt="Umi's third prank targets goblins in Gadgetzan and Un'Goro: keep it for later."},{"t",4809,m=1452,x=61.6,y=38.6}}},
  {t="Winterfall Village", lv=55, n="The furbolg village fills the valley north-east of Everlook. Kill Shamans first; they heal. High Chief Winterfall in the cave at the back is elite: stay out.", g={{"o",8464,i=2,txt="Kill Winterfall Den Watcher x8",m=1452,x=66,y=35},{"o",8464,i=3,txt="Kill Winterfall Ursa x8",m=1452,x=66.7,y=37.1},{"o",8464,i=1,txt="Kill Winterfall Shaman x8",m=1452,x=67.6,y=35.7}}},
  {t="Fly to Camp Mojache", lv=55, g={{"g",0,txt="Everlook flight master",m=1452,x=60.5,y=36.3},{"z",0,txt="Fly to Camp Mojache",at="Camp Mojache"}}},
  {t="Talo Thornhoof", lv=55, g={{"t",4120,m=1444,x=76.2,y=43.8}}},
  {t="Evoroot", lv=55, n="The Evoroot grows inside a ruined building north of Gregan's camp, east of the harpies' Ruins of Ravenwind: climb in through the broken part of its wall.", g={{"h",11242,txt="Get Evoroot",m=1444,x=44.5,y=10.2,n=1}}},
  {t="The Videre Elixir", lv=55, n="Back south to Gregan. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by Gadgetzan later.", g={{"t",4041,m=1444,x=45.1,y=25.6},{"o",3909,i=1,txt="Videre Elixir",n2="Videre Elixir, Gregan's reward",m=1444,x=45.1,y=25.6}}},
  {t="Desolace", lv=55, g={{"g",0,txt="Shadowprey Village",m=1443,x=21.6,y=74}}},
