  {t="Bluff Runner Windstrider", lv=55, n="Bluff Runner Windstrider and Rumstag Proudstrider stand on Hunter Rise. Each of Rumstag's donations takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest.", g={{"a",1000,m=1456,x=44.3,y=58.8,ml=54},{"t",7820,m=1456,x=43,y=42.7,opt=true},{"t",7821,m=1456,x=43,y=42.7,opt=true},{"t",7822,m=1456,x=43,y=42.7,opt=true}}},
