R:Segment({id="horde/50-60/05-eastern-plaguelands",title="Eastern Plaguelands, Winterspring & Tanaris",faction="Horde",min=56,max=57,zone=1423,zoneName="Eastern Plaguelands",next="horde/50-60/06-silithus"}, function() return {
