  {t="Pamela Redpath", lv=56, n="Pamela's ghost stands in the ruins of Darrowshire, in the south-west.", g={{"a",5149,m=1423,x=31.1,y=78,ml=50}}},
  {t="Pamela's Doll", lv=56, n="The doll's head and its two sides lie in the houses around Pamela; join them from your bags.", g={{"h",12886,txt="Get Pamela's Doll's Head",n2="Inside",m=1423,x=32.6,y=79.6,n=1},{"h",12887,txt="Get Pamela's Doll's Left Side",m=1423,x=32.7,y=79.1,n=1},{"h",12888,txt="Get Pamela's Doll's Right Side",n2="Inside",m=1423,x=33.1,y=79.7,n=1},{"o",5149,i=1,txt="Pamela's Doll",m=1423,x=33,y=78.5}}},
  {t="Pamela Redpath", lv=56, g={{"t",5149,m=1423,x=31.1,y=78},{"a",5152,m=1423,x=31.1,y=78,ml=50},{"a",5241,n2="a message for Carlin at Light's Hope Chapel",m=1423,x=31.1,y=78,ml=50},{"i",0,txt="Keep Auntie Marlene: Marlene lives at Sorrow Hill in the Western Plaguelands."}}},
  {t="Zaeldarr the Outcast", lv=56, n="Zaeldarr lurks just west of Darrowshire.", g={{"o",6021,i=1,txt="Zaeldarr's Head",n2="Below ground",m=1423,x=23.1,y=72.6}}},
  {t="Pestilent Scar", lv=56, n="Careful: Eye of Naxxramas goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min.", g={{"h",12840,txt="Get Minion's Scourgestone x20",m=1423,x=21.1,y=78.2,n=20,opt=true}}},
  {t="Back to Light's Hope Chapel", lv=56, g={{"t",6021,m=1423,x=69.9,y=53.7},{"t",5241,m=1423,x=71.7,y=50},{"a",5211,m=1423,x=71.7,y=50,ml=50},{"i",0,txt="Defenders of Darrowshire's spirits come with the Corin's Crossing stop later in this guide: keep it."},{"t",5510,m=1423,x=71.6,y=50.1,opt=true}}},
  {t="Fly to Tarren Mill", lv=56, g={{"g",0,txt="Light's Hope Chapel flight master",m=1423,x=70.4,y=47.5},{"z",0,txt="Fly to Tarren Mill",at="Tarren Mill"}}},
  {t="To Sorrow Hill", lv=56, g={{"g",0,txt="Sorrow Hill",m=1422,x=49.2,y=78.6}}},
  {t="Sorrow Hill", lv=56, n="Ride north up the road from Tarren Mill. Marlene's house stands by the road at Sorrow Hill, and Joseph Redpath's monument is in the graveyard behind it.", g={{"t",5152,n2="Marlene Redpath, upstairs",m=1422,x=49.2,y=78.6},{"a",5153,m=1422,x=49.2,y=78.6,ml=50},{"o",5153,i=1,txt="Joseph's Wedding Ring",m=1422,x=49.7,y=76.8}}},
  {t="Chromie", lv=56, n="Ride north-west into Andorhal. Chromie waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges.", g={{"t",5153,n2="Upstairs",m=1422,x=39.5,y=66.8},{"a",5154,m=1422,x=39.5,y=66.8,ml=50}}},
  {t="The Annals of Darrowshire", lv=56, n="The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one.", g={{"o",5154,i=1,txt="Annals of Darrowshire",m=1422,x=43.4,y=69.5}}},
  {t="Chromie", lv=56, g={{"t",5154,n2="Upstairs",m=1422,x=39.5,y=66.8},{"a",5210,m=1422,x=39.5,y=66.8,ml=50}}},
  {t="Fly to Light's Hope Chapel", lv=56, n="Ride back south to Tarren Mill and fly to Light's Hope Chapel.", g={{"g",0,txt="Tarren Mill flight master",m=1424,x=60.2,y=18.8},{"z",0,txt="Fly to Light's Hope Chapel",at="Light's Hope Chapel"}}},
  {t="Light's Hope Chapel", lv=56, g={{"t",5210,m=1423,x=71.7,y=50},{"a",5168,m=1423,x=71.7,y=50,ml=50},{"a",5181,m=1423,x=71.7,y=50,ml=50},{"i",0,txt="Heroes of Darrowshire's items lie in the later Plaguelands zones: keep it."}}},
  {t="Eastern Plaguelands: kill these as you meet them", lv=56, n="Plaguehounds and their runts roam the shores of the lake south-west of the chapel; Plaguebats and Carrion Grubs share the ground.\nThe shattered sword lies on the ground north-west of the lake.", g={{"o",5542,i=2,txt="Kill Plaguehound x5",m=1423,x=68.2,y=56.3},{"o",5542,i=1,txt="Kill Plaguehound Runt x20",m=1423,x=62.7,y=69.8},{"o",5181,i=2,txt="Shattered Sword of Marduk",m=1423,x=46.9,y=55.4},{"o",5543,i=1,txt="Kill Plaguebat x30",m=1423,x=47.8,y=64.4},{"o",5544,i=1,txt="Slab of Carrion Worm Meat x15",m=1423,x=47.5,y=66.6}}},
  {t="Nathanos Blightcaller", lv=56, n="The Banshee Queen's champion holds the Marris Stead farmhouse, north of the Undercroft.", g={{"a",6022,m=1423,x=22.2,y=63.5,ml=54},{"t",5961,m=1423,x=22.2,y=63.5},{"a",6042,m=1423,x=22.2,y=63.5,ml=54},{"a",6133,m=1423,x=22.2,y=63.5,ml=54}}},
  {t="Eastern Plaguelands: kill these as you meet them", lv=56, n="Plaguehound Runts and Plaguebats roam the hills north of the Marris Stead, Carrion Grubs crawl among them; work north toward Terrordale.", g={{"o",5542,i=1,txt="Kill Plaguehound Runt x20",m=1423,x=20.8,y=60.5},{"o",5544,i=1,txt="Slab of Carrion Worm Meat x15",m=1423,x=19.1,y=61.9},{"o",5543,i=1,txt="Kill Plaguebat x30",m=1423,x=20.1,y=56.2}}},
  {t="Egan", lv=56, n="Egan the ghost stands by a hut in Terrordale, in the north-west corner.", g={{"t",5281,n2="Inside",m=1423,x=11.4,y=26.6},{"t",6164,n2="Inside",m=1423,x=11.4,y=26.4}}},
  {t="Plaguewood: kill these as you meet them", lv=56, n="Frenzied Plaguehounds and Monstrous Plaguebats share the fields around Northdale and Eastwall Tower, south of Zul'Mashar.", g={{"o",6042,i=2,txt="Kill Monstrous Plaguebat x10",m=1423,x=15.6,y=29},{"o",5542,i=3,txt="Kill Frenzied Plaguehound x5",m=1423,x=18.9,y=28},{"o",6042,i=1,txt="Kill Noxious Plaguebat x20",m=1423,x=39.5,y=53.8}}},
  {t="Eastern Plaguelands: kill these as you meet them", lv=56, n="The high elf Rangers, Pathstriders and Woodsmen guard the lodge by Northpass Tower; the Registry lies inside. Rangers reach 60: pull one at a time. Noxious Plaguebats fly over the fields on the way.\nThe skull sits in the Pestilent Scar, among Blighted Horrors and Plague Monstrosities.", g={{"o",6042,i=1,txt="Kill Noxious Plaguebat x20",m=1423,x=39.5,y=53.8},{"o",5181,i=1,txt="Skull of Horgus",n2="Underwater",m=1423,x=44.3,y=41.2}}},
  {t="Pathstrider", lv=56, g={{"o",6133,i=1,txt="Kill Pathstrider x8",n2="Pathstrider walks around Quel'Lithien Lodge: look inside the circle on the map",m=1423,x=44.7,y=15.3},{"o",6133,i=2,txt="Kill Ranger x8",m=1423,x=44.6,y=15.8},{"o",6133,i=3,txt="Kill Woodsman x8",m=1423,x=44.9,y=15.7},{"o",6133,i=4,txt="Quel'Thalas Registry",m=1423,x=45.3,y=12.7}}},
  {t="Corin's Crossing", lv=56, n="Ride south from the lodge to Corin's Crossing, on the road. Living Rot spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the Mortar and Pestle at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with Greater Invisibility. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith Defenders of Darrowshire in your log (from Carlin at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the Living Rot.", g={{"g",0,txt="Corin's Crossing",m=1423,x=52.3,y=58.2},{"o",5211,i=1,txt="Free Darrowshire Spirits: talk to them x15",m=1423,x=51.7,y=58.3},{"h",15447,txt="Get Living Rot x7",m=1423,x=51.7,y=58.3,n=7},{"c",6022,txt="Coagulated Rot"}}},
  {t="Nathanos Blightcaller", lv=56, n="Ride west to the Marris Stead.", g={{"t",6133,m=1423,x=22.2,y=63.5},{"t",6042,m=1423,x=22.2,y=63.5},{"t",6022,m=1423,x=22.2,y=63.5}}},
  {t="Nathanos Blightcaller", lv=56, w={{k="group",q=6135}}, g={{"a",6135,m=1423,x=22.2,y=63.5,ml=56}}},
  {t="Duskwing, Oh How I Hate Thee...", lv=56, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Duskwing is a level 60 elite: most classes solo it at level 62, but you may need help. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=6135}}, g={{"o",6135,i=1,txt="Patch of Duskwing's Fur",m=1423,x=26.1,y=59,grp=true}}},
  {t="Carlin Redpath", lv=56, g={{"t",5181,m=1423,x=71.7,y=50},{"t",5211,m=1423,x=71.7,y=50}}},
  {t="Fly to Undercity", lv=56, g={{"g",0,txt="Light's Hope Chapel flight master",m=1423,x=70.4,y=47.5},{"z",0,txt="Fly to Undercity",at="Undercity"}}},
  {t="Zeppelin to Orgrimmar", lv=56, g={{"g",0,txt="Zeppelin to Orgrimmar",m=1420,x=60.7,y=58.9}}},
  {t="Fly to Bloodvenom Post", lv=56, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Bloodvenom Post",at="Bloodvenom Post"}}},
  {t="Fly to Thunder Bluff", lv=56, f={c={"PALADIN","DRUID"}}, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Thunder Bluff", lv=56, n="Turak Runetotem (Druids) trains on Elder Rise, Alodan the Hopeful (Paladins) in the city too.", f={c={"PALADIN","DRUID"}}, g={{"tr",0,txt="Visit your class trainer",n2="Turak Runetotem on Elder Rise; Alodan the Hopeful",f={c={"PALADIN","DRUID"}}}}},
  {t="Fly to Bloodvenom Post", lv=56, f={c={"PALADIN","DRUID"}}, g={{"g",0,txt="Thunder Bluff flight master",m=1456,x=46.6,y=49.9},{"z",0,txt="Fly to Bloodvenom Post",at="Bloodvenom Post"}}},
  {t="Trull Failbane", lv=56, g={{"t",4521,m=1448,x=34.7,y=52.8},{"a",4741,m=1448,x=34.7,y=52.8,ml=52}}},
  {t="Deadwood Cauldron", lv=56, n="Ride north up the road. The cauldron stands in Felpaw Village, just south-west of Timbermaw Hold; the Deadwood furbolgs there are hostile.", g={{"t",5084,m=1448,x=60.2,y=5.8},{"a",5085,m=1448,x=60.2,y=5.8,ml=52}}},
  {t="Kernda", lv=56, n="Only if a Winterfall Ritual Totem dropped for you: Kernda waits at the Felwood entrance of Timbermaw Hold, and speaks to you only at Neutral with the Timbermaw.", w={{k="onquest",q={8471}}}, g={{"t",8471,n2="Kernda walks around here: look inside the circle on the map",m=1448,x=65.5,y=3.5,opt=true}}},
  {t="Moonglade", lv=56, g={{"g",0,txt="Rabine Saturna",m=1450,x=51.7,y=45.1}}},
  {t="Rabine Saturna", lv=56, n="Go through Timbermaw Hold and take the Moonglade branch of the tunnel. Rabine is in Nighthaven.", g={{"a",5527,m=1450,x=51.7,y=45.1,ml=56}}},
  {t="Class trainer", lv=56, f={c={"DRUID"}}, g={{"tr",0,txt="Visit your class trainer",f={c={"DRUID"}}}}},
  {t="Rabine Saturna", lv=56, g={{"t",1123,m=1450,x=51.7,y=45.1},{"a",1124,m=1450,x=51.7,y=45.1,ml=54},{"i",0,txt="Both quests lead to Silithus: keep them."}}},
  {t="Winterspring", lv=56, g={{"g",0,txt="Donova Snowden",m=1452,x=31.3,y=45.2}}},
  {t="Donova Snowden", lv=56, n="Back through the tunnel and take the Winterspring exit, then ride south to Frostfire Hot Springs.", g={{"t",5085,m=1452,x=31.3,y=45.2},{"a",5086,m=1452,x=31.3,y=45.2,ml=52},{"t",3909,m=1452,x=31.3,y=45.2},{"a",3912,m=1452,x=31.3,y=45.2,ml=47},{"i",0,txt="Toxic Horrors are in Felwood, on a later trip: keep it."}}},
  {t="Moontouched Owlbeasts", lv=56, n="Ride east to Everlook and north out of it; the Moontouched Owlbeasts roam the hills of Frostsaber Rock's southern slopes. Pull them one at a time.", g={{"o",4741,i=1,txt="Kill Moontouched Owlbeast x13",m=1452,x=59,y=59}}},
  {t="Winterspring", lv=56, g={{"g",0,txt="Everlook",m=1452,x=60.5,y=36.3}}},
  {t="Fly to Gadgetzan", lv=56, g={{"g",0,txt="Everlook flight master",m=1452,x=60.5,y=36.3},{"z",0,txt="Fly to Gadgetzan",at="Gadgetzan"}}},
  {t="Gaeriyan", lv=56, n="Drink the Videre Elixir at the graveyard just east of Gadgetzan: it kills you, and only as a ghost can you see Gaeriyan, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard.", g={{"i",0,txt="Use Videre Elixir",m=1446,x=54,y=28.7},{"t",3912,m=1446,x=53.9,y=23.3},{"a",3913,m=1446,x=53.9,y=23.3,ml=47}}},
  {t="Sprinkle", lv=56, n="Use Umi's Mechanical Yeti on Sprinkle, the goblin girl in Gadgetzan. Quixxil and Legacki are scared later in the route.", g={{"o",5163,i=2,txt="Scare Sprinkle with Umi's Mechanical Yeti",m=1446,x=51.1,y=26.9},{"o",5163,i=2,txt="Use Umi's Mechanical Yeti",m=1446,x=51.1,y=26.9}}},
  {t="Gaeriyan", lv=56, g={{"t",3913,m=1446,x=53.8,y=29.1},{"a",3914,m=1446,x=53.8,y=29.1,ml=47},{"i",0,txt="Linken's Sword goes back to Linken in Un'Goro: keep it."}}},
  {t="Marvon Rivetseeker", lv=56, n="Marvon camps by the Lost Rigger Cove road, south of Gadgetzan.", g={{"t",3444,m=1446,x=52.7,y=45.9}}},
  {t="Fly to Marshal's Refuge", lv=56, g={{"g",0,txt="Gadgetzan flight master",m=1446,x=51.6,y=25.5},{"z",0,txt="Fly to Marshal's Refuge",at="Marshal's Refuge"}}},
  {t="Marshal's Refuge", lv=56, n="The flight lands at Marshal's Refuge: Spraggle Frock stands beside the flight master, and Linken by the cave a few steps away. Spraggle's work is in Un'Goro on the next guide's way back north.", g={{"a",4492,m=1449,x=43.6,y=8.5,ml=50},{"t",3914,m=1449,x=44.7,y=8.1},{"a",3941,m=1449,x=44.7,y=8.1,ml=47},{"i",0,txt="A Gnome's Assistance goes to J.D. Collie in the cave here, on the next guide's return to Marshal's Refuge: keep it."}}},
  {t="Layo Starstrike", lv=56, n="The pass from Un'Goro comes out at Valor's Rest, the graveyard in north-east Silithus. Layo stands among the graves.", g={{"t",1124,m=1451,x=81.9,y=18.9},{"a",1125,m=1451,x=81.9,y=18.9,ml=54}}},
  {t="The Spirits of Southwind", lv=56, n="Ride south-west to the ruins of Southwind Village. The Dusty Reliquary for Rabine Saturna sits inside one of the ruined houses.", g={{"o",1125,i=1,txt="Kill Tortured Druid x8",m=1451,x=64.9,y=47.2},{"o",1125,i=2,txt="Kill Tortured Sentinel x8",m=1451,x=65.9,y=48.5}}},
  {t="Layo Starstrike", lv=56, g={{"t",1125,m=1451,x=81.9,y=18.9},{"a",1126,m=1451,x=81.9,y=18.9,ml=54}}},
} end)

R:Segment({id="horde/50-60/06-silithus",title="Silithus, Western Plaguelands & Eastern Plaguelands",faction="Horde",min=57,max=59,zone=1451,zoneName="Silithus",next="horde/50-60/07-felwood"}, function() return {
  {t="Cenarion Hold", lv=57, n="Ride west to the walled hold in the middle of the desert. Beetix Ficklespragg stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", g={{"b",0,txt="Set your hearthstone at Cenarion Hold",m=1451,x=51.9,y=39.2,at="Cenarion Hold"},{"a",8277,m=1451,x=51.6,y=38.6,ml=54},{"t",8276,m=1451,x=51.1,y=38.3},{"a",8280,m=1451,x=51.1,y=38.3,ml=54},{"a",8284,m=1451,x=49.7,y=37.5,ml=54},{"a",9416,m=1451,x=49,y=36.7,ml=1},{"fp",72,txt="Get the Cenarion Hold flight path (Runk Windtamer)",m=1451,x=48.7,y=36.7}}},
  {t="Silithus: kill these as you meet them", lv=57, n="Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold.", g={{"o",8280,i=1,txt="Kill Dredge Striker x15",m=1451,x=51.4,y=32},{"o",8277,i=2,txt="Sand Skitterer Fang x8",m=1451,x=51,y=30.3},{"o",8277,i=1,txt="Stonelash Scorpid Stinger x8",m=1451,x=56.1,y=30.2}}},
  {t="Twilight Base Camp", lv=57, n="The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too.", g={{"o",8284,i=1,txt="Twilight Tablet Fragment x8",m=1451,x=35.6,y=13}}},
  {t="Cenarion Hold", lv=57, n="Beetix Ficklespragg stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", g={{"t",8284,m=1451,x=49.7,y=37.5},{"a",8285,m=1451,x=49.7,y=37.5,ml=54},{"t",8280,m=1451,x=51.1,y=38.3},{"a",8281,m=1451,x=51.1,y=38.3,ml=54},{"t",8277,m=1451,x=51.6,y=38.6},{"a",8278,m=1451,x=51.6,y=38.6,ml=54}}},
  {t="Hive in the Tower", lv=57, n="Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the Encrusted Silithid Object.", g={{"o",1126,i=1,txt="Encrusted Silithid Object",m=1451,x=60.2,y=52.4}}},
  {t="The Spirits of Southwind", lv=57, g={{"o",5527,i=1,txt="Reliquary of Purity",n2="Inside",m=1451,x=63.2,y=55.4}}},
  {t="Hermit Ortell", lv=57, n="Ride south-east to Ortell's Hideout under the Un'Goro cliffs.", g={{"t",8285,n2="Below ground",m=1451,x=67.2,y=69.8},{"a",8279,m=1451,x=67.2,y=69.8,ml=54},{"o",8278,i=3,txt="Rock Stalker Fang x3",n2="Rock Stalker Fang from Rock Stalker, 130 yd south-west",m=1451,x=66.5,y=74.3}}},
  {t="Dredge Crushers and Pincers", lv=57, n="Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold.", g={{"o",8281,i=1,txt="Kill Dredge Crusher x20",n2="Dredge Crusher walks around Southwind Village: look inside the circle on the map",m=1451,x=63.6,y=63.1},{"o",8278,i=1,txt="Stonelash Flayer Stinger x3",m=1451,x=64.2,y=66.6},{"o",8278,i=3,txt="Rock Stalker Fang x3",m=1451,x=66.5,y=74.3}}},
  {t="General Kirika", lv=57, n="Ride west to the Horde camp north of Hive'Regal.", g={{"t",9416,m=1451,x=50.8,y=69.5},{"a",9422,m=1451,x=50.8,y=69.5,ml=1}}},
  {t="Scouring the Desert", lv=57, n="Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it.", g={{"c",9422,txt="Silithus Dust Turnin Quest Doodad Horde",m=1451,x=50.9,y=69.3},{"t",9422,m=1451,x=50.8,y=69.5}}},
  {t="Flayers and Rock Stalkers", lv=57, n="Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp.", g={{"o",8278,i=3,txt="Rock Stalker Fang x3",m=1451,x=48.6,y=67.2},{"o",8278,i=1,txt="Stonelash Flayer Stinger x3",m=1451,x=49.5,y=66.6}}},
  {t="Twilight Vanguard", lv=57, n="Twilight Keeper Exeter walks the Vanguard camp in the far south-west. Keep every Encrypted Twilight Text the cultists drop: Bor Wildmane and Ortell want ten each later.", g={{"o",8279,i=2,txt="Twilight Lexicon - Chapter 2",m=1451,x=16.1,y=86.4}}},
  {t="Stonelash Pincer Stinger", lv=57, g={{"o",8278,i=2,txt="Stonelash Pincer Stinger x3",m=1451,x=34.1,y=66.8}}},
  {t="Twilight Post", lv=57, n="Twilight Keeper Mayna holds the camp in the west.", g={{"o",8279,i=1,txt="Twilight Lexicon - Chapter 1",m=1451,x=26.4,y=36.6}}},
  {t="Twilight Outpost", lv=57, n="Twilight Keeper Havunth stands in the outpost west of Cenarion Hold. Keep any Encrypted Twilight Texts that drop here too.", g={{"o",8279,i=3,txt="Twilight Lexicon - Chapter 3",m=1451,x=40.9,y=42.2}}},
  {t="Level 58", lv=58, n="Commander Mar'alith's Dearest Natalia, at Cenarion Hold, needs level 58: top up on the Twilight Avengers, Geolords and Stonecallers west of the outpost. Or, with a group, run the Blackrock Spire dungeon (Lower) or the Scholomance dungeon instead.", w={{k="level",op="<",n=58}}, g={{"g",0,txt="Twilight Avenger",m=1451,x=33.8,y=47.8},{"l",58,txt="Reach level 58: grind Twilight Avenger",n2="grind on Twilight Avenger",m=1451,x=37.4,y=47.1}}},
  {t="Cenarion Hold", lv=58, n="Beetix and Noggle Ficklespragg stand upstairs in their building: go up inside, the arrow cannot tell the floors apart.", g={{"a",8318,n2="Bor Wildmane, on the west side of the Hold",m=1451,x=48.6,y=37.8,ml=57},{"a",8304,m=1451,x=49.2,y=34.2,ml=58},{"t",8281,m=1451,x=51.1,y=38.3},{"t",8278,m=1451,x=51.6,y=38.6},{"a",8282,m=1451,x=51.6,y=38.5,ml=54}}},
  {t="Hermit Ortell", lv=58, n="Ride north-east to Ortell's Hideout.", g={{"t",8279,n2="Below ground",m=1451,x=67.2,y=69.8},{"a",8287,m=1451,x=67.2,y=69.8,ml=54},{"a",8323,m=1451,x=67.2,y=69.8,ml=54}}},
  {t="Noggle's Lost Satchel", lv=58, n="The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away.", g={{"o",8282,i=1,txt="Noggle's Satchel",m=1451,x=44.6,y=91.4}}},
  {t="Dearest Natalia", lv=58, n="Frankal Stonebridge and Rutgar Glyphshaper camp at Bronzebeard's Encampment, just north of the satchel's mountains. Question them: go through each one's whole conversation; there is no need to fight them.", g={{"o",8304,i=1,txt="Talk to Frankal Stonebridge",m=1451,x=40.8,y=88.9},{"o",8304,i=2,txt="Talk to Rutgar Glyphshaper",m=1451,x=41.3,y=88.5}}},
  {t="Twilight Base Camp", lv=58, n="Collect twenty Encrypted Twilight Texts from the cultists here, ten for Bor Wildmane and ten for Ortell.", w={{k="onquest",q={8318}}}, g={{"o",8318,i=1,txt="Encrypted Twilight Text x10",m=1451,x=21.5,y=84.3},{"h",20404,txt="Get Encrypted Twilight Text x20",n2="ten for each quest: Bor Wildmane takes his ten before Ortell",m=1451,x=21.5,y=84.3,n=20}}},
  {t="Twilight Base Camp", lv=58, g={{"o",8323,i=1,txt="Encrypted Twilight Text x10",n2="The spare texts from the cultists",m=1451,x=21.5,y=84.3}}},
  {t="Back to Cenarion Hold", lv=58, n="Noggle Ficklespragg stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", g={{"t",8318,n2="Bor Wildmane, on the west side of the Hold",m=1451,x=48.6,y=37.8},{"t",8287,m=1451,x=49.2,y=34.2},{"t",8304,m=1451,x=49.2,y=34.2},{"t",8282,m=1451,x=51.6,y=38.5},{"i",0,txt="Mar'alith's next errand, Into the Maw of Madness, leads into Hive'Regal among elites. Skip it."}}},
  {t="Hermit Ortell", lv=58, g={{"t",8323,n2="Below ground",m=1451,x=67.2,y=69.8}}},
  {t="Layo Starstrike", lv=58, n="Ride north-east to Valor's Rest; you leave Silithus through the pass beside it.", g={{"t",1126,m=1451,x=81.9,y=18.9},{"a",6844,m=1451,x=81.9,y=18.9,ml=54}}},
  {t="Un'Goro Crater", lv=58, g={{"g",0,txt="Marshal's Refuge",m=1449,x=44.7,y=8.1}}},
  {t="Marshal's Refuge", lv=58, n="Through the pass and east along the northern cliffs to Marshal's Refuge. Spraggle Frock stands beside the flight master.", g={{"a",4492,m=1449,x=43.6,y=8.5,ml=50}}},
  {t="Krakle", lv=58, n="Krakle the goblin sits at Golakka Hot Springs, just east of the pylon.", g={{"a",974,m=1449,x=30.9,y=50.4,ml=51}}},
  {t="Krakle's Thermometer", lv=58, n="Ride east to Fire Plume Ridge, climb it and use Krakle's Thermometer at the lava vent near the top, then ride back west to Krakle.", g={{"g",0,txt="Go here",m=1449,x=49.7,y=45.6},{"c",974,txt="Fire Plume Ridge Hot Spot",m=1449,x=49.7,y=45.6}}},
  {t="Krakle", lv=58, g={{"t",974,m=1449,x=30.9,y=50.4},{"a",980,m=1449,x=30.9,y=50.4,ml=51},{"i",0,txt="Krakle sends you to Donova Snowden in Winterspring: keep it."}}},
  {t="Pawn Captures Queen", lv=58, n="Use the Gorishi Queen Lure where the arrow points, inside the Gorishi hive of the Slithering Scar, to call the Gorishi Hive Queen (level 56).", g={{"o",4507,i=1,txt="Use Gorishi Queen Lure",m=1449,x=43.5,y=81},{"o",4507,i=1,txt="Gorishi Queen Brain",m=1449,x=43.9,y=81.4}}},
  {t="Torwa Pathfinder", lv=58, g={{"a",4292,m=1449,x=71.6,y=76,ml=48},{"i",0,txt="Keep the bait: Lar'korwi is level 56, and the second loop passes his lair."},{"a",4289,m=1449,x=71.6,y=76,ml=47}}},
  {t="Lar'korwi", lv=58, n="Lar'korwi's lair is just south of the pylon. Use Torwa's bait there; Lar'korwi is level 56 and hits hard, so start at full health.", g={{"o",4292,i=1,txt="Lar'korwi's Head",m=1449,x=79.7,y=49.8}}},
  {t="Un'Goro Crater: kill these as you meet them", lv=58, n="Careful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds.", g={{"o",4289,i=1,txt="Un'Goro Gorilla Pelt x2",n2="Below ground",m=1449,x=69,y=17.6},{"o",4289,i=2,txt="Un'Goro Stomper Pelt x2",n2="Below ground",m=1449,x=69,y=17.6},{"o",4289,i=3,txt="Un'Goro Thunderer Pelt x2",n2="Below ground",m=1449,x=69,y=17.6}}},
  {t="Marshal's Refuge", lv=58, n="J.D. Collie is inside the cave.", g={{"t",3941,n2="J.D. Collie, below ground",m=1449,x=41.9,y=2.7},{"a",3942,m=1449,x=41.9,y=2.7,ml=47},{"i",0,txt="Keep Linken's Memory: Eridan Bluewind is at the Emerald Sanctuary, on the next guide's way through Felwood."},{"o",5163,i=3,txt="Scare Quixxil with Umi's Mechanical Yeti",n2="Use Umi's Mechanical Yeti on Quixxil",m=1449,x=43.7,y=9.4}}},
  {t="Ringo", lv=58, n="Ringo sits on the ridge, lost and exhausted.", g={{"t",4492,n2="Below ground",m=1449,x=51.9,y=49.9},{"a",4491,m=1449,x=51.9,y=49.9,ml=50}}},
  {t="Escort Ringo", lv=58, n="Lead Ringo north to Marshal's Refuge. When he faints, use Spraggle's Canteen on him to wake him.", g={{"g",0,txt="Go here",m=1449,x=43.7,y=8.3},{"c",4491,txt="Escort Ringo to Spraggle Frock at Marshal's Refuge"}}},
  {t="Marshal's Refuge", lv=58, g={{"t",4491,m=1449,x=43.6,y=8.5}}},
  {t="Torwa Pathfinder", lv=58, g={{"t",4292,m=1449,x=71.6,y=76},{"i",0,txt="Torwa now asks for U'cha's pelt, back in the north-east cave: skip it."},{"t",4289,m=1449,x=71.6,y=76}}},
  {t="Tanaris", lv=58, g={{"g",0,txt="Gadgetzan",m=1446,x=52.4,y=27}}},
  {t="Gadgetzan", lv=58, n="Fly to Gadgetzan. Still carrying The Super Egg-O-Matic? The machine stands in the middle of town.", g={{"t",2741,m=1446,x=52.4,y=27},{"t",4507,n2="Inside",m=1446,x=50.9,y=27},{"a",4509,m=1446,x=50.9,y=27,ml=50}}},
