  {t="Paladin trainer", lv=58, f={c={"PALADIN"}}, g={{"tr",0,txt="Visit your class trainer",n2="Alodan the Hopeful in Thunder Bluff; Orgrimmar has no paladin trainer",f={c={"PALADIN"}}}}},
