  {t="Radley and Durgen", lv=58, n="Huntsman Radley stands east of the lumber camp; Cavalier Durgen guards the road north-east of Kirsta, toward Hearthglen.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight.", g={{"o",6023,i=1,txt="Kill Huntsman Radley",m=1422,x=57.8,y=36.1},{"o",6023,i=2,txt="Kill Cavalier Durgen",m=1422,x=55.1,y=23.6}}},
  {t="Northridge Lumber Camp", lv=58, n="The lumber mill is right beside Radley: set Mickey's termite barrel down in the middle of it.", g={{"t",5902,m=1422,x=48.3,y=32},{"a",6390,m=1422,x=48.3,y=32,ml=48}}},
  {t="Kirsta Deepshadow", lv=58, g={{"t",6023,m=1422,x=51.9,y=28.1},{"a",6025,m=1422,x=51.9,y=28.1,ml=50}}},
  {t="Davil's Libram", lv=58, n="The libram lies further north, on the way to Hearthglen.", g={{"o",5168,i=1,txt="Davil's Libram",n2="Inside",m=1422,x=42.5,y=19}}},
  {t="Hearthglen", lv=58, n="Hearthglen's Scarlets are level 58-60. Ride in to the high point marked on your map, look over the town, and get out.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby.", g={{"g",0,txt="Go here",m=1422,x=45.8,y=18.3},{"c",6025,txt="Overlook Hearthglen from a high vantage point",m=1422,x=45.5,y=18.6}}},
  {t="Kirsta Deepshadow", lv=58, g={{"t",6025,m=1422,x=51.9,y=28.1}}},
  {t="Andorhal watchtowers and silos", lv=58, n="Ride south into Andorhal. Chromie waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the Beacon Torch to mark it; keep to the edges of town. Use the Temporal Displacer by the silos in the middle of town to bring out Temporal Parasites.", g={{"a",4971,n2="Chromie, upstairs",m=1422,x=39.5,y=66.8,ml=53},{"o",5098,i=2,txt="Use Beacon Torch",m=1422,x=42.3,y=66.2},{"o",5098,i=2,txt="Mark Andorhal Tower Two with the Beacon Torch",m=1422,x=42.3,y=66.2},{"i",0,txt="Use Temporal Displacer",m=1422,x=45.2,y=62.8},{"o",4971,i=1,txt="Kill Temporal Parasite x15",m=1422,x=45.2,y=62.8},{"o",5098,i=3,txt="Mark Andorhal Tower Three with the Beacon Torch",m=1422,x=44.3,y=63.2},{"o",5098,i=4,txt="Mark Andorhal Tower Four with the Beacon Torch",m=1422,x=46.6,y=71},{"o",5098,i=1,txt="Mark Andorhal Tower One with the Beacon Torch",m=1422,x=40,y=71.6}}},
  {t="Chromie", lv=58, g={{"t",4971,n2="Upstairs",m=1422,x=39.5,y=66.8},{"a",4972,m=1422,x=39.5,y=66.8,ml=53}}},
  {t="Counting Out Time", lv=58, n="The lockboxes sit in Andorhal's ruined houses around Chromie's inn. Careful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth.", g={{"o",4972,i=1,txt="Andorhal Watch x5",m=1422,x=40.3,y=68.2}}},
  {t="Chromie", lv=58, g={{"t",4972,n2="Upstairs",m=1422,x=39.5,y=66.8}}},
