  {t="Dalson's Tears", lv=58, n="East along the road, Cauldron Lord Malvinious guards the cauldron at Dalson's Tears.", g={{"o",5231,i=1,txt="Dalson's Tears Cauldron Key",m=1422,x=46.1,y=52.6},{"t",5231,m=1422,x=46.2,y=51.9}}},
