  {t="Redpath's Shield", lv=58, n="The shield lies at Gahrron's Withering, south of Tirion's hut.", g={{"o",5168,i=2,txt="Redpath's Shield",m=1422,x=63.8,y=57.2}}},
  {t="Tirion Fordring", lv=58, n="Ride east to Tirion's hut by the Thondroril River and hear him out.", g={{"t",5543,m=1423,x=5.2,y=35.6},{"t",5544,m=1423,x=5.2,y=35.6},{"t",5542,m=1423,x=5.2,y=35.6},{"a",5742,m=1423,x=5.2,y=35.6,ml=52},{"c",5742,txt="Tirion Fordring"},{"t",5742,m=1423,x=5.2,y=35.6},{"a",5781,m=1423,x=5.2,y=35.6,ml=52}}},
