  {t="Scourge Champions", lv=58, n="Scourge Champions roam the Noxious Glade, north of the chapel. Pass Carlin's Mystic Crystal over each one you kill: the skulls that resonate are the ones he wants.", g={{"o",5206,i=1,txt="Resonating Skull x5",m=1423,x=71.7,y=35.8}}},
