  {t="Pamela and the Undercroft", lv=58, n="Ride to Darrowshire in the south-west; Pamela plays among the houses. Mercutio Filthgorger lurks in the Undercroft, the crypt just west of the town.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot.", g={{"o",5781,i=1,txt="Taelan's Hammer",m=1423,x=23.9,y=74.2}}},
  {t="Nathanos Blightcaller", lv=58, w={{k="group",q=6135}}, g={{"t",6135,m=1423,x=22.2,y=63.5}}},
  {t="Tirion Fordring", lv=58, n="Ride north-west to Tirion's hut.", g={{"t",5781,m=1423,x=5.2,y=35.6},{"a",5845,m=1423,x=5.2,y=35.6,ml=52}}},
  {t="Western Plaguelands", lv=58, g={{"g",0,txt="Alas, Andorhal",m=1422,x=45.3,y=69.2}}},
