  {t="Level 59.14", lv=59, n="If you skipped Duskwing, Oh How I Hate Thee..., grind here to level 59.14 to stay on the route's plan. Or, with a group, run the Scholomance dungeon or the Stratholme dungeon instead.", w={{k="group",neg=true,q=6135},{k="level",op="<",n=59,frac=0.14}}, g={{"g",0,txt="Temporal Parasite",m=1422,x=48,y=64.8},{"l",59,txt="Reach level 59 (14% in): grind Temporal Parasite",n2="grind on Temporal Parasite",m=1422,x=48.2,y=64.4,fr=0.14}}},
  {t="Chromie", lv=59, n="Ride south-west to Chromie in Andorhal.", g={{"t",5941,m=1422,x=39.5,y=66.8},{"i",0,txt="Chromie's Battle of Darrowshire ends against elites. Skip it."}}},
  {t="The Bulwark", lv=59, n="West to the Bulwark.", g={{"t",5232,m=1420,x=83,y=71.9},{"a",5233,m=1420,x=83,y=71.9,ml=50},{"t",964,m=1420,x=83.3,y=69.2},{"t",105,m=1420,x=83.1,y=68.9}}},
  {t="Into Eastern Plaguelands", lv=59, g={{"g",0,txt="Into Eastern Plaguelands",m=1423,x=6.3,y=55.8}}},
