  {t="Infiltrator Hameya", lv=59, n="Hameya hides among the Mossflayer trolls of Zul'Mashar, in the north-east corner.\nCareful: The trolls along the path to Zul'Mashar are level 57-59. They run away at low health and call for help, so they often bring adds with them.", g={{"o",6024,i=1,txt="Hameya's Key",m=1423,x=62,y=11.1}}},
  {t="Tirion Fordring", lv=59, g={{"t",5845,m=1423,x=5.2,y=35.6},{"a",5846,m=1423,x=5.2,y=35.6,ml=52}}},
  {t="Hameya's mound", lv=59, n="Ride south-east from Tirion to the Undercroft; the Mound of Dirt is just behind it.", g={{"t",6024,m=1423,x=23.6,y=73.8}}},
