  {t="Fly to Splintertree Post", lv=59, g={{"g",0,txt="Orgrimmar flight master",m=1454,x=45.3,y=63.7},{"z",0,txt="Fly to Splintertree Post",at="Splintertree Post"}}},
  {t="Felwood", lv=59, g={{"g",0,txt="The Emerald Sanctuary",m=1448,x=51.2,y=82.1}}},
  {t="The Emerald Sanctuary", lv=59, n="Fly to Splintertree Post and ride north-west along the road out of Ashenvale into Felwood. The Emerald Sanctuary is the druids' camp just past the border.", g={{"t",5159,m=1448,x=51.2,y=82.1},{"a",5165,m=1448,x=51.2,y=82.1,ml=48},{"t",3942,n2="Eridan Bluewind, inside",m=1448,x=51.4,y=81.5},{"i",0,txt="Eridan's Silver Heart needs an Irontree Heart from northern Felwood and a ride back here. Skip it."}}},
  {t="Dousing the Flames of Protection", lv=59, n="Ride north-west to Jaedenar. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended.", g={{"o",5165,i=2,txt="Brazier of Malice",n2="Below ground",m=1448,x=37.7,y=52.7},{"o",5165,i=3,txt="Brazier of Suffering",n2="Below ground",m=1448,x=36.7,y=53.3},{"o",5165,i=1,txt="Brazier of Pain",n2="Below ground",m=1448,x=36.3,y=56.3},{"o",5165,i=4,txt="Brazier of Hatred",n2="Below ground",m=1448,x=36.5,y=55.2}}},
  {t="Greta Mosshoof", lv=59, n="Back south to the Sanctuary, a short ride.", g={{"t",5165,m=1448,x=51.2,y=82.1},{"a",5242,m=1448,x=51.2,y=82.1,ml=48}}},
  {t="Bloodvenom Post", lv=59, n="Ride north along the road, past Jaedenar, to Bloodvenom Post.", g={{"t",4741,m=1448,x=34.7,y=52.8},{"i",0,txt="Trull's next Wild Guardians would bring you back here from Winterspring. Skip it."}}},
  {t="A Final Blow", lv=59, n="Moora, Salia and Shadow Lord Fel'dan wait at the back of Shadow Hold, the cave in Jaedenar's north. Clear the tunnel as you go.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies.", g={{"o",5242,i=1,txt="Kill Moora",n2="Below ground",m=1448,x=38.8,y=46.9},{"o",5242,i=2,txt="Kill Salia",n2="Below ground",m=1448,x=38.8,y=46.7},{"o",5242,i=3,txt="Shadow Lord Fel'dan's Head",n2="Below ground",m=1448,x=38.8,y=46.8},{"h",11515,txt="Get Corrupted Soul Shard x6",n2="Corrupted Soul Shards from the cultists, Salve via Hunting",m=1448,x=38.8,y=46.9,n=6}}},
  {t="Maybess Riverbreeze", lv=59, n="On the way back south to Greta, Maybess takes the shards on the west side of the Sanctuary.", w={{k="available",q=5887,minLevel=48,pre={4102}}}, g={{"t",5887,m=1448,x=46.8,y=83.1}}},
  {t="Greta Mosshoof", lv=59, n="South to the Sanctuary once more.", g={{"t",5242,m=1448,x=51.2,y=82.1}}},
  {t="Toxic Horrors", lv=59, n="Ride north up the Felwood road to Irontree Woods; the Toxic Horrors ooze between the trees, and most of them drop a droplet.", g={{"o",5086,i=1,txt="Toxic Horror Droplet x3",m=1448,x=49.8,y=27.4}}},
  {t="Moonglade", lv=59, g={{"g",0,txt="Umber",m=1450,x=44.9,y=35.6}}},
  {t="Umber", lv=59, n="Through the Timbermaw tunnel to Moonglade. Umber reads in a house in Nighthaven.", g={{"t",6844,n2="Umber walks around Nighthaven: look inside the circle on the map",m=1450,x=44.9,y=35.6},{"a",6845,m=1450,x=44.9,y=35.6,ml=54}}},
  {t="Rabine Saturna", lv=59, g={{"t",5527,m=1450,x=51.7,y=45.1}}},
  {t="Class trainer", lv=59, f={c={"DRUID"}}, g={{"tr",0,txt="Visit your class trainer",f={c={"DRUID"}}}}},
  {t="Rabine Saturna", lv=59, g={{"t",6845,m=1450,x=51.7,y=45.1},{"i",0,txt="Rabine's Shards of the Felvine needs Dire Maul. Skip it."}}},
  {t="Umber", lv=59, g={{"t",1185,m=1450,x=44.9,y=35.6}}},
  {t="Winterspring", lv=59, g={{"g",0,txt="Donova Snowden",m=1452,x=31.3,y=45.2}}},
  {t="Donova Snowden", lv=59, n="Back into the Timbermaw tunnel and take the Winterspring exit; Donova camps by the hot springs just outside.", g={{"t",980,n2="From Krakle in Un'Goro",m=1452,x=31.3,y=45.2},{"a",4842,m=1452,x=31.3,y=45.2,ml=51},{"t",5086,m=1452,x=31.3,y=45.2},{"a",5087,m=1452,x=31.3,y=45.2,ml=52}}},
  {t="Winterfall Runners", lv=59, n="The runners walk the road from Timbermaw Hold toward Winterfall Village in small groups; wait by the road near Donova and kill them as they pass. Each one carries a crate.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with Feign Death, and they then gather by the lake so you can take the next quest.", g={{"o",5087,i=1,txt="Winterfall Crate",m=1452,x=27.9,y=34.5}}},
  {t="Salfa", lv=59, g={{"t",8464,m=1452,x=27.7,y=34.5}}},
  {t="Beads for Salfa", lv=59, n="Any Winterfall furbolg can carry the beads; the camps just south of Salfa are the closest.", g={{"g",0,txt="Frostfire Winterfall camp",m=1452,x=31.6,y=36.6},{"h",21383,txt="Get Winterfall Spirit Beads x5",m=1452,x=31.4,y=36.3,n=5}}},
  {t="Salfa", lv=59, g={{"t",8469,m=1452,x=27.7,y=34.5}}},
  {t="Meilosh", lv=59, n="With 30 Runecloth in your bags: follow the road north to Timbermaw Hold; Meilosh trades just inside the entrance.", w={{k="complete",q=6031}}, g={{"t",6031,n2="Below ground",m=1448,x=65.7,y=2.8}}},
  {t="Kernda", lv=59, n="The Deadwood totem from Felpaw Village, if Kernda didn't take it then: she waits at the tunnel mouth of Timbermaw Hold and speaks to you from Neutral with the Timbermaw, which the Deadwood furbolgs of Felwood brought you to.", w={{k="onquest",q={8470}}}, g={{"t",8470,n2="Kernda walks around here: look inside the circle on the map",m=1448,x=65.5,y=3.5}}},
  {t="Winterspring", lv=59, g={{"g",0,txt="Darkwhisper Gorge",m=1452,x=59.8,y=74.3}}},
  {t="Darkwhisper Gorge", lv=59, n="Ride east, then south down Frostwhisper Gorge. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of Darkwhisper Gorge, at the south end.", g={{"g",0,txt="Darkwhisper Gorge",m=1452,x=59.8,y=74.2},{"c",4842,txt="Discover Darkwhisper Gorge"}}},
  {t="Level 59.9", lv=59, n="Top up here to level 59.9 before the hand-ins at Winterspring: they take you to level 60. The Rabid Shardtooths (59) of Frostwhisper Gorge, just north of the strange source, give far more experience than the furbolgs by Timbermaw Hold. Or, with a group, run the Scholomance dungeon or the Stratholme dungeon instead.", w={{k="level",op="<",n=59,frac=0.9}}, g={{"g",0,txt="Rabid Shardtooth",m=1452,x=60.1,y=71.2},{"l",59,txt="Reach level 59 (90% in): grind Rabid Shardtooth",n2="grind on Rabid Shardtooth",m=1452,x=60.1,y=71.5,fr=0.9}}},
  {t="Donova Snowden", lv=59, n="Ride back west to Frostfire Hot Springs.", g={{"t",4842,m=1452,x=31.3,y=45.2},{"t",5087,m=1452,x=31.3,y=45.2},{"i",0,txt="Donova next sends you after High Chief Winterfall, an elite in his cave. Skip it."}}},
  {t="Are We There, Yeti?", lv=59, g={{"o",5163,i=1,txt="Scare Legacki with Umi's Mechanical Yeti",m=1452,x=61.5,y=38.6}}},
  {t="Everlook", lv=59, n="Ride east along the road to Everlook.", g={{"t",5163,m=1452,x=60.9,y=37.6}}},
  {t="Dungeon instead of grinding", lv=59, n="Optional. Running Stratholme, Scholomance, Lower Blackrock Spire or Blackrock Depths with a group instead of grinding gets you there faster.", g={{"i",0,txt="Optional: with a group, a 55-60 dungeon replaces the grind below."}}},
  {t="Grind to 60", lv=60, n="The quests run out here. Rabid Shardtooths prowl Frostwhisper Gorge in southern Winterspring, south of the road from Everlook.", g={{"g",0,txt="Frostwhisper Gorge",m=1452,x=60.1,y=71.2},{"l",60,txt="Reach level 60: grind Rabid Shardtooth",n2="grind on Rabid Shardtooth at Frostwhisper Gorge, Winterspring",m=1452,x=60.1,y=71.5},{"tr",0,txt="Visit your class trainer",n2="In Orgrimmar: fly from Everlook",opt=true,f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}},{"tr",0,txt="Visit your class trainer",n2="In Thunder Bluff: fly from Everlook",opt=true,f={c={"PALADIN","DRUID"}}}}},
} end)

R:Segment({id="horde/orc/01-durotar",title="Durotar",faction="Horde",races={"Orc"},min=1,max=12,zone=1411,zoneName="Durotar",next="horde/03-silverpine-forest"}, function() return {
  {t="Kaltunk", lv=1, n="Gornek waits inside the Den, the building just west of Kaltunk.", g={{"a",4641,n2="Kaltunk, where you start",m=1411,x=43.3,y=68.5,ml=1},{"t",4641,n2="Inside",m=1411,x=42.1,y=68.3},{"a",788,m=1411,x=42.1,y=68.3,ml=1},{"a",97279,m=1411,x=42.1,y=68.3,ml=1},{"a",1485,m=1411,x=42.6,y=69,f={c={"WARLOCK"}},ml=1}}},
  {t="Training weapons and boars", lv=1, n="The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor.", g={{"o",788,i=1,txt="Kill Mottled Boar x10",m=1411,x=42.7,y=71.6},{"o",97279,i=1,txt="Abandoned Training Weapon x6",m=1411,x=43.2,y=71.7},{"g",0,txt="The Den",m=1411,x=42.4,y=68.6}}},
  {t="The Den", lv=2, n="Gornek stands just inside the cave mouth; Kzan Thornslash at the back of the cave behind him.", g={{"a",792,m=1411,x=42.9,y=69.2,f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","DRUID"}},ml=2},{"tr",0,txt="Visit your class trainer"},{"t",788,n2="Gornek, inside",m=1411,x=42.1,y=68.3},{"a",2383,n2="Gornek: Simple Parchment",m=1411,x=42.1,y=68.3,f={c={"WARRIOR"},r={"Orc"}},ml=1},{"a",3087,n2="Gornek: Etched Parchment",m=1411,x=42.1,y=68.3,f={c={"HUNTER"},r={"Orc"}},ml=1},{"a",3088,n2="Gornek: Encrypted Parchment",m=1411,x=42.1,y=68.3,f={c={"ROGUE"},r={"Orc"}},ml=1},{"a",3089,n2="Gornek: Rune-Inscribed Parchment",m=1411,x=42.1,y=68.3,f={c={"SHAMAN"},r={"Orc"}},ml=1},{"a",98576,n2="Gornek: Glyphic Parchment",m=1411,x=42.1,y=68.3,f={c={"MAGE"},r={"Orc"}},ml=1},{"a",3090,n2="Gornek: Tainted Parchment",m=1411,x=42.1,y=68.3,f={c={"WARLOCK"},r={"Orc"}},ml=1},{"a",789,m=1411,x=42.1,y=68.3,ml=1},{"t",3090,n2="Nartok, the warlock trainer at the back of the cave",m=1411,x=40.6,y=68.5,f={c={"WARLOCK"},r={"Orc"}}},{"t",3088,n2="Rwag, the rogue trainer in the Den",m=1411,x=41.3,y=68,f={c={"ROGUE"},r={"Orc"}}},{"t",2383,n2="Frang, the warrior trainer beside the Den",m=1411,x=42.9,y=69.4,f={c={"WARRIOR"},r={"Orc"}}},{"t",3087,n2="Jen'shan, the hunter trainer beside the Den",m=1411,x=42.8,y=69.3,f={c={"HUNTER"},r={"Orc"}}},{"t",3089,n2="Shikrik, the shaman trainer beside the Den",m=1411,x=42.4,y=69,f={c={"SHAMAN"},r={"Orc"}}},{"t",98576,n2="Mai'ah, the mage trainer, at the entrance to the Den",m=1411,x=42.5,y=69,f={c={"MAGE"},r={"Orc"}}},{"t",97279,n2="Kzan Thornslash, at the back of the cave; below ground",m=1411,x=40.5,y=68},{"a",4402,n2="Galgar, by the cooking fire",m=1411,x=42.7,y=67.2,ml=1}}},
  {t="Hana'zua", lv=2, n="Hana'zua lies wounded at the foot of the hills north-west of the Den.", g={{"a",790,m=1411,x=40.6,y=62.6,ml=1}}},
  {t="Valley of Trials: kill these as you meet them", lv=2, n="Sarkoth, a large scorpid, prowls the slope south of Hana'zua among the Scorpid Workers; pick the Cactus Apples by the cactuses on the way.\nThe Vile Familiars swarm the slope below the Burning Blade Coven, the cave on the valley's north side.", g={{"o",789,i=1,txt="Scorpid Worker Tail x10",m=1411,x=40.2,y=62.1},{"o",4402,i=1,txt="Cactus Apple x10",m=1411,x=39.6,y=63},{"o",790,i=1,txt="Sarkoth's Mangled Claw",m=1411,x=40.5,y=66.8},{"t",790,m=1411,x=40.6,y=62.6},{"a",804,m=1411,x=40.6,y=62.6,ml=1},{"o",792,i=1,txt="Kill Vile Familiar x12",m=1411,x=43.8,y=58.3,f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","DRUID"}}},{"o",1485,i=1,txt="Vile Familiar Head x6",m=1411,x=43.8,y=58.3,f={c={"WARLOCK"}}}}},
  {t="Class trainer", lv=2, f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}}}},
  {t="Paladin trainer", lv=2, f={c={"PALADIN"}}, g={{"tr",0,txt="Visit your class trainer",n2="Alodan the Hopeful in Thunder Bluff; Valley of Trials has no paladin trainer",f={c={"PALADIN"}}}}},
  {t="Druid trainer", lv=2, f={c={"DRUID"}}, g={{"tr",0,txt="Visit your class trainer",n2="Sheal Runetotem in Mulgore; Valley of Trials has no druid trainer",f={c={"DRUID"}}}}},
  {t="Back to the Den", lv=4, g={{"t",789,n2="Gornek, inside",m=1411,x=42.1,y=68.3},{"t",804,n2="Gornek, inside",m=1411,x=42.1,y=68.3},{"t",1485,m=1411,x=42.6,y=69,f={c={"WARLOCK"}}},{"a",1516,m=1411,x=42.4,y=69.2,f={c={"SHAMAN"}},ml=4},{"t",792,m=1411,x=42.9,y=69.2,f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","DRUID"}}},{"a",1499,m=1411,x=42.6,y=69,f={c={"WARLOCK"}},ml=1},{"t",1499,m=1411,x=42.9,y=69.2,f={c={"WARLOCK"}}},{"a",794,m=1411,x=42.9,y=69.2,ml=1},{"a",5441,n2="Foreman Thazz'ril, at the lumber pile east of the Den",m=1411,x=44.6,y=68.7,ml=3},{"t",4402,m=1411,x=42.7,y=67.2}}},
  {t="Lazy Peons", lv=4, g={{"o",5441,i=1,txt="Wake Lazy Peons with the Foreman's Blackjack x5",m=1411,x=45,y=69.1}}},
  {t="Foreman Thazz'ril", lv=4, g={{"t",5441,m=1411,x=44.6,y=68.7},{"a",6394,m=1411,x=44.6,y=68.7,ml=3}}},
  {t="Burning Blade Coven", lv=4, g={{"g",0,txt="Burning Blade Coven",m=1411,x=45,y=56}}},
  {t="Thazz'ril's Pick", lv=4, n="Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock.", g={{"o",6394,i=1,txt="Thazz'ril's Pick",m=1411,x=43.7,y=53.8}}},
  {t="Yarrog Baneshadow", lv=4, n="Inside the cave, keep to the right wall all the way round, over the stream: Yarrog waits at the end.", g={{"o",794,i=1,txt="Burning Blade Medallion",n2="Below ground",m=1411,x=42.7,y=53}}},
  {t="Felstalker hooves", lv=4, n="Felstalkers roam the slope below the cave, on the valley's north side.", f={c={"SHAMAN"}}, g={{"o",1516,i=1,txt="Felstalker Hoof x2",m=1411,x=42.5,y=53.5}}},
  {t="Back to the Den", lv=4, g={{"g",0,txt="The Den",m=1411,x=42.4,y=68.6},{"t",1516,m=1411,x=42.4,y=69.2,f={c={"SHAMAN"}}},{"a",1517,m=1411,x=42.4,y=69.2,f={c={"SHAMAN"}},ml=4},{"t",794,m=1411,x=42.9,y=69.2},{"a",805,m=1411,x=42.9,y=69.2,ml=1},{"a",96652,n2="the Lost Journal on the ground beside her",m=1411,x=42.8,y=69.1,ml=4},{"tr",0,txt="Visit your class trainer"},{"t",6394,m=1411,x=44.6,y=68.7}}},
  {t="Call of Earth", lv=4, n="Canaga stands outside the Den. Spirit Rock is the hill just south of it: drink the Earth Sapta there to see the Minor Manifestation of Earth, then take the Rough Quartz back to Canaga.", f={c={"SHAMAN"}}, g={{"t",1517,n2="Minor Manifestation of Earth, on Spirit Rock",m=1411,x=44,y=76.2},{"a",1518,m=1411,x=44,y=76.2,ml=4},{"t",1518,n2="Canaga Earthcaller: Stoneskin Totem and your Earth Totem",m=1411,x=42.4,y=69.2}}},
  {t="Ukor", lv=4, n="Ukor stands on the road at the valley's eastern exit.", g={{"a",2161,m=1411,x=52.1,y=68.3,ml=1}}},
  {t="Sen'jin Village", lv=5, g={{"a",96873,n2="Pa'zula: enchanters only, the residue is disenchanted from Hexed Pendants",m=1411,x=56.7,y=73.7,opt=true,ml=5},{"a",817,m=1411,x=56,y=73.9,ml=5},{"a",96821,m=1411,x=56,y=73.9,ml=1},{"a",818,m=1411,x=55.9,y=74.4,ml=5},{"t",805,m=1411,x=56,y=74.7},{"a",97225,m=1411,x=55.9,y=74.4,ml=4},{"tr",0,txt="Visit your class trainer",n2="Un'Thuwa, the mage trainer in Sen'jin",f={c={"MAGE"}}},{"a",808,m=1411,x=56,y=74.7,ml=4},{"a",826,m=1411,x=56,y=74.7,ml=4},{"a",823,m=1411,x=56,y=74.7,ml=4},{"a",97223,m=1411,x=55.3,y=75.5,ml=5},{"a",786,m=1411,x=54.4,y=74.3,ml=5},{"o",96821,i=1,txt="Kill Ridgeshade Creeper x6",m=1411,x=52.4,y=67.2},{"o",96821,i=2,txt="Kill Ridgeshade Lurker x6",m=1411,x=52.2,y=66}}},
  {t="Brakk's campfire", lv=5, n="Brakk camps just south of Razor Hill. Sit by his campfire (/sit) until the Boosted Rest buff appears. With a profession learned, Brakk also offers its Camping 101, which its trainer takes: in Razor Hill or in Orgrimmar at the start of the next guide.", g={{"t",96652,m=1411,x=52,y=47.3},{"a",96604,m=1411,x=52,y=47.3,ml=4},{"c",96604,txt="Sit near the campfire (Optional); Gain the Boosted Rest buff",m=1411,x=52.1,y=47.4},{"t",96604,m=1411,x=52,y=47.3},{"a",96655,m=1411,x=52,y=47.3,ml=4}}},
  {t="Camping 101: Mining", lv=5, w={{k="skill",n=1,name="Mining",skillLine=186},{k="knows",neg=true,spell=1230161}}, g={{"a",97907,n2="Brakk: for Krunn",m=1411,x=52,y=47.3,ml=4}}},
  {t="Camping 101: Engineering", lv=5, w={{k="skill",n=1,name="Engineering",skillLine=202},{k="knows",neg=true,spell=1230656}}, g={{"a",97902,n2="Brakk: for Mukdrak",m=1411,x=52,y=47.3,ml=4}}},
  {t="Camping 101: First Aid", lv=5, w={{k="skill",n=1,name="First Aid",skillLine=129},{k="knows",neg=true,spell=1230117}}, g={{"a",97903,n2="Brakk: for Rawrk",m=1411,x=52,y=47.3,ml=4}}},
  {t="Camping 101: Skinning", lv=5, w={{k="skill",n=1,name="Skinning",skillLine=393},{k="knows",neg=true,spell=1229517}}, g={{"a",97908,n2="Brakk: for Thuwd",m=1411,x=52,y=47.3,ml=4}}},
  {t="Camping 101: Leatherworking", lv=5, w={{k="skill",n=1,name="Leatherworking",skillLine=165},{k="knows",neg=true,spell=1229432}}, g={{"a",97906,n2="Brakk: for Karolek",m=1411,x=52,y=47.3,ml=4}}},
  {t="Camping 101: Tailoring", lv=5, w={{k="skill",n=1,name="Tailoring",skillLine=197},{k="knows",neg=true,spell=1229504}}, g={{"a",96102,n2="Brakk: for Snang",m=1411,x=52,y=47.3,ml=4}}},
