  {t="Scuttle Coast: kill these as you meet them", lv=6, n="The gnomish toolboxes lie in the wreckage along the shore east and south-east of Razor Hill. Follow the shore south to Sen'jin.\nMakrura and surf crawlers line the beaches north-east of Sen'jin.", g={{"o",825,i=1,txt="Gnomish Tools x3",n2="Underwater",m=1411,x=61.9,y=42.4},{"o",818,i=2,txt="Crawler Mucus x8",m=1411,x=60.3,y=43.3},{"o",818,i=1,txt="Intact Makrura Eye x4",n2="Underwater",m=1411,x=61.1,y=42.5},{"o",815,i=1,txt="Taillasher Egg x3",m=1411,x=67.8,y=69.8}}},
  {t="Echo Isles: kill these as you meet them", lv=6, n="Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach.", g={{"o",97223,i=1,txt="Bloodtalon Matriarch Eggs",m=1411,x=68.8,y=71.8},{"o",817,i=1,txt="Durotar Tiger Fur x4",m=1411,x=69,y=72.4}}},
  {t="Echo Isles: kill these as you meet them", lv=6, n="Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. Zalazane and Minshina's cage are on the southernmost isle.", g={{"o",97225,i=1,txt="Forgotten Loa Idol x8",m=1411,x=67.8,y=81.4},{"c",96873,txt="Luminous Residue",opt=true},{"o",826,i=2,txt="Kill Voodoo Troll x8",m=1411,x=67.8,y=82.1},{"o",826,i=1,txt="Kill Hexed Troll x8",m=1411,x=68.3,y=83.2},{"o",826,i=3,txt="Zalazane's Head",m=1411,x=67.5,y=87.8},{"o",808,i=1,txt="Minshina's Skull",m=1411,x=67.4,y=87.8}}},
