  {t="Far Watch Post", lv=10, n="West from Razor Hill over the Southfury River bridge: Kargal Battlescar and Uzzek stand together at Far Watch Post above it. From there the road north through Durotar leads to Orgrimmar.", w={{k="onquest",q={840}}}, g={{"t",840,m=1413,x=62.3,y=19.4},{"t",1505,m=1413,x=61.4,y=21.1,f={c={"WARRIOR"}}},{"a",1498,m=1413,x=61.4,y=21.1,f={c={"WARRIOR"}},ml=10}}},
  {t="Thunder lizards on the way north", lv=10, n="Thunder Lizards and Lightning Hides graze on Thunder Ridge, beside the road north to Orgrimmar; any of them can drop a Singed Scale. Uzzek takes it when the next guide passes Far Watch Post.\nCareful: Halikor, a level 12 elite, roams Thunder Ridge among the lizards: watch for him before you pull.", f={c={"WARRIOR"}}, g={{"o",1498,i=1,txt="Singed Scale x5",m=1411,x=39.7,y=29.2}}},
  {t="Orgrimmar", lv=10, f={c={"HUNTER"}}, g={{"g",0,txt="Ormak Grimshot",m=1454,x=66,y=18.5}}},
  {t="Ormak Grimshot", lv=10, n="Follow the road north from Far Watch Post to Orgrimmar's main gate, just west of Skull Rock. Ormak Grimshot stands with the hunter trainers in the Valley of Honor.", f={c={"HUNTER"}}, g={{"t",6081,n2="Ormak Grimshot: Beast Training",m=1454,x=66,y=18.5}}},
  {t="Hanashi", lv=10, n="While you're here: learn Staves from Hanashi (Valley of Honor, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Staves",skillLine=136}}, f={c={"HUNTER"}}, g={{"tr",0,txt="Train with Hanashi",m=1454,x=81.5,y=19.6}}},
  {t="To Orgrimmar", lv=10, n="Follow the road north from Far Watch Post to Orgrimmar's main gate. The next guide starts in Orgrimmar: Neeru Fireblade takes the cultists' quest, the trainers teach your new ranks, and the zeppelin leaves from the towers outside the gate for Tirisfal Glades and Silverpine Forest. The Barrens come after Silverpine.", g={{"g",0,txt="Orgrimmar's Valley of Strength",m=1454,x=55.6,y=72.3}}},
  {t="The Binding", lv=10, n="Gan'rul Bloodeye stands in the Cleft of Shadow, the canyon under the Valley of Strength. Hand him the Tablet of Verga, then use the Glyphs of Summoning on the summoning circle beside him and defeat the voidwalker to bind it.", f={c={"WARLOCK"}}, g={{"t",1501,m=1454,x=48.2,y=45.3},{"a",1504,m=1454,x=48.2,y=45.3,ml=10},{"i",0,txt="Use Glyphs of Summoning",m=1454,x=49.3,y=50},{"o",1504,i=1,txt="Kill Summoned Voidwalker",m=1454,x=49.3,y=50},{"t",1504,n2="Gan'rul Bloodeye: Summon Voidwalker",m=1454,x=48.2,y=45.3}}},
} end)

R:Segment({id="horde/skyborne/01-zephras-isle",title="Zephras Isle",faction="Horde",races={"Skyborne"},min=1,max=14,zone=2521,zoneName="Zephras Isle",next="horde/03-silverpine-forest"}, function() return {
  {t="Thendal Village", lv=1, n="You wake in Thendal Village, in the north of the isle. Ailee stands by the path, Rorian at the village centre.", g={{"a",92460,m=2521,x=42.8,y=23.4,ml=1},{"t",92460,m=2521,x=42,y=23.5},{"a",92461,m=2521,x=42,y=23.5,ml=1},{"a",92462,m=2521,x=43.4,y=24.8,ml=1}}},
  {t="Thendal Grove: kill these as you meet them", lv=1, n="Pesky Cirrusflies and Juvenile Vuldren roam the grove just south-east of the village.", g={{"o",92461,i=1,txt="Kill Juvenile Vuldren x8",m=2521,x=43.5,y=25.4},{"o",92462,i=1,txt="Kill Pesky Cirrusfly x8",m=2521,x=43.6,y=26.9}}},
  {t="Back to Thendal Village", lv=2, n="Halaan Hawk-Eye and Myriaal Mistwake stand at the top of the watchtower, a few steps north-east of Elatrell.", g={{"t",92462,m=2521,x=43.4,y=24.8},{"a",92463,m=2521,x=43.4,y=24.8,ml=2},{"a",94414,m=2521,x=43.8,y=24.1,ml=2},{"c",94414,txt="Halaan Hawk-Eye",n2="talk to Halaan Hawk-Eye",m=2521,x=43.8,y=24.1},{"t",94414,m=2521,x=43.8,y=24.1},{"a",92474,m=2521,x=43.7,y=24.1,ml=2}}},
  {t="Rorian's errands", lv=2, n="Jump off the top of the watchtower and use Walk on Air to float down to Rorian, west of the tower.", g={{"a",92598,m=2521,x=42.6,y=24.4,ml=2},{"t",92461,m=2521,x=42,y=23.5},{"t",92474,m=2521,x=42,y=23.5},{"a",92464,m=2521,x=42,y=23.5,ml=2},{"a",92532,n2="Rorian the Dayseeker: the Crumpled Note",m=2521,x=42,y=23.5,f={c={"WARRIOR"}},ml=2},{"a",92482,n2="Rorian the Dayseeker: a note from your trainer",m=2521,x=42,y=23.5,f={c={"HUNTER"}},ml=2},{"a",92484,n2="Rorian: examine the Humming Recall Crystal",m=2521,x=42,y=23.5,f={c={"SHAMAN"}},ml=2},{"a",92485,n2="Rorian: A Student of Nature",m=2521,x=42,y=23.5,f={c={"DRUID"}},ml=2},{"a",92483,n2="Rorian the Dayseeker: read the Simple Note",m=2521,x=42,y=23.5,f={c={"ROGUE"}},ml=2},{"t",92484,n2="Windshaper Boro, beside Rorian",m=2521,x=42.8,y=23.6,f={c={"SHAMAN"}}},{"t",92485,n2="Xyton Silverwind, the druid trainer, on the ground floor of the tree behind Rorian",m=2521,x=41.7,y=23.3,f={c={"DRUID"}}},{"tr",0,txt="Visit your class trainer",n2="Boro and Xyton, while you stand beside them",f={c={"SHAMAN","DRUID"}}},{"a",93552,m=2521,x=43.4,y=24,ml=2}}},
  {t="Raw Windstones", lv=2, n="The Raw Windstones are blue crystals on the slopes around the village.", g={{"o",93552,i=1,txt="Windstone Cluster x15",m=2521,x=43.5,y=23.9}}},
  {t="Dalia the Collector", lv=2, g={{"t",93552,m=2521,x=43.4,y=24}}},
  {t="The standing stones", lv=3, n="Yala Windwatcher stands at the Thendal Standing Stones, east of the village. Roiling Winds and Al'Aketh Converts gather just north of her. The Elemental Convergence is just north-east of her: cast your Skysight racial ability next to it.", g={{"t",92464,m=2521,x=47.2,y=22},{"a",92465,m=2521,x=47.2,y=22,ml=2},{"o",92465,i=1,txt="Kill Al'Aketh Convert x7",m=2521,x=47.2,y=21.6},{"o",92465,i=2,txt="Kill Roiling Winds x6",m=2521,x=47,y=21.8},{"o",92598,i=1,txt="Cast Skysight near the Elemental Convergence",m=2521,x=48.3,y=20.6},{"t",92465,m=2521,x=47.2,y=22},{"a",92469,m=2521,x=47.2,y=22,ml=3}}},
  {t="The Cirrusfly Queen", lv=3, n="The queen hovers at the south-east end of the grove, on your way back from the stones.", g={{"o",92463,i=1,txt="Kill Cirrusfly Queen",m=2521,x=47.2,y=28.4}}},
  {t="Thendal Village turn-ins", lv=4, g={{"t",92463,m=2521,x=43.4,y=24.8},{"t",92598,m=2521,x=42.6,y=24.4},{"t",92469,m=2521,x=42,y=23.5},{"a",92471,m=2521,x=42,y=23.5,ml=4},{"t",92482,n2="Tai'ree Farsight, beside Rorian",m=2521,x=42.5,y=23.8,f={c={"HUNTER"}}},{"t",92483,n2="Akeri Duskblade, in the watchtower",m=2521,x=43.7,y=24.4,f={c={"ROGUE"}}},{"t",92532,n2="Blademaster Ren, in the watchtower",m=2521,x=43.6,y=24.1,f={c={"WARRIOR"}}},{"t",92471,m=2521,x=42.8,y=23.7},{"a",92470,m=2521,x=42.8,y=23.7,ml=2},{"tr",0,txt="Visit your class trainer"},{"a",92466,n2="Windshaper Boro: Call of Earth",m=2521,x=42.8,y=23.6,f={c={"SHAMAN"}},ml=3},{"a",92473,m=2521,x=42.4,y=25.2,ml=3}}},
  {t="Thendal Grove: kill these as you meet them", lv=4, n="Scrawny Ursera prowl the slopes south-west of the village, on the way to Hanaa.\nThe Ursera den is west of the village. Urs'anah, their matriarch, sits at its far end.", g={{"o",92473,i=1,txt="Scrawny Ursera Claw x6",m=2521,x=41.4,y=26.4},{"o",92470,i=1,txt="Kill Ursera Scavenger x8",n2="Below ground",m=2521,x=39.5,y=26.9},{"o",92470,i=2,txt="Head of Urs'anah",n2="Below ground",m=2521,x=35.6,y=26.1}}},
  {t="Back to Thendal Village", lv=4, n="Back up from the den to Valreaa and Aetheen in the village before heading south-west to Hanaa: the road from her camp leads on south to Shen'dar.", g={{"t",92473,m=2521,x=42.4,y=25.2},{"t",92470,m=2521,x=42.8,y=23.7},{"a",92472,m=2521,x=42.8,y=23.7,ml=3},{"a",96638,m=2521,x=42.8,y=23.7,ml=4},{"tr",0,txt="Visit your class trainer"}}},
  {t="Hanaa Nightwind", lv=4, n="Hanaa waits in Thendal Grove, south-west of the village. The Al'Aketh camp is just beyond her; Malduko Cloudcrush leads it.\nCareful: Malduko Cloudcrush casts shocks; drag him clear of the other cultists before fighting so they don't join in.", g={{"a",92544,m=2521,x=38.3,y=30.2,ml=2},{"o",92544,i=1,txt="Kill Al'Aketh Brute x6",m=2521,x=38.1,y=30.8},{"o",92466,i=1,txt="Signet of Akir",n2="Signet of Akir: the Al'Aketh in Hanaa's camp carry it",m=2521,x=38.2,y=30.8,f={c={"SHAMAN"}}},{"o",92544,i=2,txt="Kill Al'Aketh Neophyte x4",m=2521,x=38.1,y=30.7},{"o",92544,i=3,txt="Kill Malduko Cloudcrush",m=2521,x=36,y=33.5},{"t",92544,m=2521,x=38.3,y=30.2}}},
  {t="Windshaper Boro", lv=4, n="Back to Boro in Thendal Village with the Signet.", f={c={"SHAMAN"}}, g={{"t",92466,m=2521,x=42.8,y=23.6,f={c={"SHAMAN"}}},{"a",92467,m=2521,x=42.8,y=23.6,f={c={"SHAMAN"}},ml=3},{"t",92467,n2="drink the Earth Sapta at the Rise of Spirits, just east of the village, to see the Minor Manifestation of Earth",m=2521,x=49.7,y=23.8,f={c={"SHAMAN"}}},{"a",92468,m=2521,x=49.7,y=23.8,f={c={"SHAMAN"}},ml=3},{"t",92468,n2="Windshaper Boro: Stoneskin Totem and your Earth Totem",m=2521,x=42.8,y=23.6,f={c={"SHAMAN"}}}}},
  {t="Shen'dar Village", lv=4, n="Follow the road south to Shen'dar Village, in the middle of the isle. Constable Aonda stands on its east side, Illaya Amberwind in the middle, Coriella just north-west of her, Raan Wildwind by the campfire on the west side. With a profession learned, Raan also offers its Camping 101: its trainer stands in the village.", g={{"t",92472,m=2521,x=45.7,y=45.5},{"a",92514,m=2521,x=45.7,y=45.5,ml=4},{"a",92595,m=2521,x=43.5,y=44.8,ml=4},{"o",92595,i=1,txt="Talk to Illaya Amberwind",n2="talk to Illaya Amberwind",m=2521,x=43.5,y=44.8},{"t",92595,m=2521,x=43.5,y=44.8},{"a",94411,m=2521,x=43.5,y=44.8,ml=4},{"o",92514,i=1,txt="Talk to Illaya Amberwind",m=2521,x=43.5,y=44.8},{"o",92514,i=2,txt="Talk to Coriella Calmbreeze",m=2521,x=43,y=43.3},{"t",96638,m=2521,x=41.7,y=44.8},{"a",96101,m=2521,x=41.7,y=44.8,ml=4},{"c",96101,txt="Sit near the campfire (Optional); Gain the Boosted Rest buff",n2="/sit by Raan's campfire until you get Boosted Rest",m=2521,x=41.7,y=44.8},{"t",96101,m=2521,x=41.7,y=44.8},{"a",96646,m=2521,x=41.7,y=44.8,ml=4}}},
