  {t="Camping 101: Alchemy", lv=4, w={{k="skill",n=1,name="Alchemy",skillLine=171},{k="knows",neg=true,spell=1230564}}, g={{"a",97963,m=2521,x=41.7,y=44.8,ml=4}}},
  {t="Camping 101: Blacksmithing", lv=4, w={{k="skill",n=1,name="Blacksmithing",skillLine=164},{k="knows",neg=true,spell=1230171}}, g={{"a",97964,m=2521,x=41.7,y=44.8,ml=4}}},
  {t="Camping 101: Fishing", lv=4, w={{k="skill",n=1,name="Fishing",skillLine=356},{k="knows",neg=true,spell=1229745}}, g={{"a",97967,m=2521,x=41.7,y=44.8,ml=4}}},
  {t="Shen'dar Village", lv=4, g={{"t",92514,m=2521,x=45.7,y=45.5},{"a",92517,m=2521,x=45.7,y=45.5,ml=4},{"a",92516,m=2521,x=44.5,y=45,ml=4},{"a",93319,m=2521,x=44.5,y=45,ml=4},{"a",92515,m=2521,x=44.7,y=44.5,ml=4},{"a",93951,m=2521,x=44.9,y=44.2,ml=4},{"tr",0,txt="Learn Cooking from Zerril Softbreeze",n2="Zerril Softbreeze: Camping 101 asks you to learn it",m=2521,x=43.9,y=43.8},{"c",96646,txt="Zerril Softbreeze",m=2521,x=43.9,y=43.9},{"t",96646,m=2521,x=43.9,y=43.8},{"a",92553,m=2521,x=43.9,y=43.8,ml=4}}},
  {t="Mendalass Tattermend", lv=4, w={{k="onquest",q={97971}}}, g={{"c",97971,txt="Mendalass Tattermend",m=2521,x=43.3,y=43.4},{"t",97971,m=2521,x=43.3,y=43.4}}},
