  {t="Indari Sunseam", lv=4, w={{k="onquest",q={97969}}}, g={{"c",97969,txt="Indari Sunseam",m=2521,x=44.7,y=44.5},{"t",97969,m=2521,x=44.7,y=44.5}}},
  {t="Messana Crestwind", lv=4, w={{k="onquest",q={97970}}}, g={{"c",97970,txt="Messana Crestwind",m=2521,x=44.8,y=44.6},{"t",97970,m=2521,x=44.8,y=44.6}}},
  {t="Nyassa Swiftdraught", lv=4, w={{k="onquest",q={97963}}}, g={{"c",97963,txt="Nyassa Swiftdraught",m=2521,x=43.7,y=43.4},{"t",97963,m=2521,x=43.7,y=43.4}}},
  {t="Aedi Thriceforged", lv=4, w={{k="onquest",q={97964}}}, g={{"c",97964,txt="Aedi Thriceforged",m=2521,x=44.9,y=44.4},{"t",97964,m=2521,x=44.9,y=44.4}}},
  {t="Fenn Fairweather", lv=4, w={{k="onquest",q={97967}}}, g={{"c",97967,txt="Fenn Fairweather",m=2521,x=45,y=48.4},{"t",97967,m=2521,x=45,y=48.4}}},
  {t="Shen'dar Village: kill these as you meet them", lv=4, n="Prideclaws and Galestriders share the meadows around Shen'dar Village; the Galestriders graze thickest just west of it. They drop both the Small Eggs and the Strider Meat for Zerril.", g={{"o",92553,i=1,txt="Small Egg x3",m=2521,x=42.1,y=39.4},{"o",92553,i=2,txt="Strider Meat x8",m=2521,x=44.5,y=39.4}}},
  {t="Shen'dar Village hand-ins", lv=4, n="Zerril, Teeri, Taleen, Danarii and Constable Aonda all stand in Shen'dar Village. If you are still short of Strider Meat, the Galestriders graze just south of the village.", g={{"t",92553,m=2521,x=43.9,y=43.8}}},
  {t="Shen'dar Highlands: kill these as you meet them", lv=4, n="The apprentices practise north-east of the village.\nThe bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones.", g={{"o",92515,i=1,txt="Prideclaw Pelt x10",m=2521,x=45.2,y=45.2},{"o",94411,i=1,txt="Kill High Order Apprentice x6",m=2521,x=45.1,y=41.5},{"o",93319,i=1,txt="Pilfered Windstone x10",m=2521,x=47.6,y=39.4},{"o",92517,i=1,txt="Kill Highlands Bandit x10",m=2521,x=47.6,y=39.4},{"o",92517,i=2,txt="Kill \"Badwind\" Bennic",n2="Below ground",m=2521,x=50.6,y=34.3}}},
  {t="Shen'dar bounty board", lv=4, w={{k="group",q=93318}}, g={{"a",93318,n2="the bounty board",m=2521,x=43.4,y=45.8,ml=4}}},
  {t="Shen'dar Village turn-ins", lv=5, g={{"t",92517,m=2521,x=45.7,y=45.5},{"a",93036,m=2521,x=45.7,y=45.5,ml=5},{"t",93036,m=2521,x=44.9,y=45.5},{"a",92529,m=2521,x=44.9,y=45.5,ml=5},{"t",92515,m=2521,x=44.7,y=44.5},{"t",93319,m=2521,x=44.5,y=45},{"tr",0,txt="Visit your class trainer"},{"t",94411,m=2521,x=43.5,y=44.8}}},
  {t="Vulgara the Insatiable", lv=5, n="Vulgara lurks south of the village, among the Prideclaws. Vulgara is elite: grouping up is advised.", w={{k="group",q=93318}}, g={{"o",93318,i=1,txt="Vulgara's Head",m=2521,x=42.7,y=52.8,grp=true}}},
  {t="Falaath Village", lv=5, n="Falaath Village lies south of Shen'dar. Missionary Jasaan meets you at its edge; search the wardrobe in the house behind him.", g={{"t",92529,m=2521,x=46.9,y=56.2},{"a",92528,m=2521,x=46.9,y=56.2,ml=5},{"c",92528,txt="Wardrobe",n2="search the wardrobe",m=2521,x=48.8,y=53.9}}},
  {t="Constable Aonda", lv=5, n="Constable Aonda waits in Shen'dar Village for what you found in the wardrobe.", g={{"t",92528,m=2521,x=45.7,y=45.5},{"a",92550,m=2521,x=45.7,y=45.5,ml=5},{"a",93926,m=2521,x=45.7,y=45.5,ml=5},{"a",92551,m=2521,x=45.2,y=45.2,ml=5}}},
  {t="Shen'dar Highlands: kill these as you meet them", lv=5, n="Back at Falaath Village: Stormcallers and Living Lightning fill the village, the Supply Caches stand among the houses and Commander Cyclas waits at its south-east end.", g={{"o",92550,i=2,txt="Kill Living Lightning x4",m=2521,x=47.6,y=50.7},{"o",92551,i=1,txt="Stolen Shen'dar Supplies x10",m=2521,x=47.5,y=51.6},{"o",92550,i=1,txt="Kill Al'Aketh Stormcaller x6",m=2521,x=47.5,y=51.6},{"o",92550,i=3,txt="Commander Cyclas's Head",m=2521,x=50.4,y=57}}},
  {t="Danarii Bellowveil", lv=5, w={{k="group",q=93318}}, g={{"t",93318,m=2521,x=45.2,y=45.2}}},
  {t="The West Pylon Watchtower", lv=5, n="Head south-west to the West Pylon Watchtower. Peacekeeper Vaaniel is at the top; the Bloody Note lies beside him.", g={{"o",93926,i=1,txt="Talk to Peacekeeper Vaaniel",n2="talk to Peacekeeper Vaaniel",m=2521,x=42.3,y=62.1},{"t",93926,m=2521,x=42.4,y=62},{"a",93927,m=2521,x=42.4,y=62,ml=5},{"o",93927,i=1,txt="Bloody Note",m=2521,x=42.4,y=62.1}}},
  {t="Skypriest Aanders", lv=5, n="Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies.", g={{"o",93927,i=2,txt="Kill Skypriest Aanders",m=2521,x=41,y=64.1},{"o",93927,i=3,txt="Raani's Lucky Feather",m=2521,x=41.1,y=64.1},{"o",93927,i=4,txt="Shadowsong Family Signet",m=2521,x=41,y=64.1}}},
