  {t="Windsong Lake", lv=10, n="Zephyrseed cones grow south of the hermit; the Wind Hollows drift east of the lake and also drop the Wind Hollow Essences for Endaria's Unwelcome Spirits. The refugees' belongings lie along the north shore of Windsong Lake; Resaan Nimbuswalker is at its north-west end.", g={{"o",93160,i=1,txt="Zephyrseed x8",m=2521,x=55.7,y=39.2},{"o",93172,i=1,txt="Kill Wind Hollow x10",m=2521,x=56.7,y=35.3},{"o",93736,i=1,txt="Wind Hollow Essence x10",m=2521,x=56.9,y=35},{"o",94896,i=1,txt="Abandoned Belongings x8",m=2521,x=56.9,y=33.6},{"o",94897,i=1,txt="Resaan's Heirloom",m=2521,x=57,y=29.4}}},
  {t="The Strange Hermit", lv=10, g={{"t",93160,m=2521,x=54,y=38.9},{"t",93172,m=2521,x=54,y=38.9}}},
  {t="The Shrine of Akir", lv=10, n="The Shrine of Akir is north of Valanaar. Fight through the guards up to Hyusaa Quickbreeze at its east side.", g={{"o",92947,i=1,txt="Kill Al'Aketh Guardian x7",m=2521,x=64,y=52.1},{"o",92947,i=2,txt="Kill Al'Aketh Spiritcaller x7",m=2521,x=63,y=50.3},{"o",92947,i=3,txt="Kill Al'Aketh Blademaster x7",m=2521,x=62.9,y=50.3},{"o",92947,i=4,txt="Talk to Hyusaa Quickbreeze",m=2521,x=63.8,y=50.5},{"t",92947,m=2521,x=63.8,y=50.5},{"a",93958,m=2521,x=63.8,y=50.5,ml=7},{"t",93958,n2="Valennia Stormfist, upstairs",m=2521,x=65.2,y=50.4},{"a",92646,m=2521,x=65.2,y=50.4,ml=7}}},
  {t="Portal to Rohashi Spires", lv=10, g={{"g",0,txt="Portal to Rohashi Spires",m=2521,x=65.6,y=50.3}}},
  {t="Confront Lorthuna", lv=10, n="Take the Portal to Rohashi Spires in the shrine up to the heights. Fight east along the ledge to the Peacekeepers at its end, ride the wind current up to the upper terrace and tell Elaadrin you are ready. Leave the Portal to Valanaar up there alone until Rohash has withdrawn; then it takes you straight back to town.", g={{"g",0,txt="Go here",m=2521,x=74.9,y=53},{"c",92646,txt="Confront Lorthuna",m=2521,x=74.8,y=53.4}}},
  {t="The Fate of Zephras", lv=10, g={{"t",92646,m=2521,x=59.1,y=79.8},{"a",93836,m=2521,x=59.1,y=79.8,ml=7},{"t",93736,n2="Endaria Mistgaze, beside Ayessa",m=2521,x=58.1,y=78.3}}},
  {t="Seena Skybreaker", lv=10, n="Seena stands beside Riaani, just north-west of Valanaar.", f={c={"WARRIOR"}}, g={{"t",94003,n2="Seena Skybreaker: Defensive Stance",m=2521,x=59.9,y=72.9}}},
  {t="Valanaar", lv=10, n="Ayessa sends you on to Kalimdor. Once you have trained, board the skycutter at the dock on Valanaar's south-west edge: it flies to northern Mulgore, where Alaana Stormwalker waits.", g={{"o",93836,i=1,txt="Talk to Talaanis Shadowsong",n2="talk to Talaanis Shadowsong",m=2521,x=66.2,y=76.5},{"t",93836,n2="Talaanis Shadowsong, upstairs",m=2521,x=66.2,y=76.5},{"a",93090,m=2521,x=66.2,y=76.5,ml=7},{"t",94896,m=2521,x=66,y=74.4},{"t",94897,m=2521,x=66,y=74.4},{"t",94491,m=2521,x=64,y=75.1}}},
  {t="Valanaar", lv=10, g={{"tr",0,txt="Visit your class trainer"},{"t",93090,m=2521,x=59.1,y=79.8},{"a",95349,m=2521,x=59.1,y=79.8,ml=7}}},
  {t="Leave Zephras Isle to Mulgore", lv=10, g={{"g",0,txt="Leave Zephras Isle to Mulgore",m=2521,x=57.9,y=80.8}}},
  {t="Northern Mulgore", lv=10, n="You leave the isle for good. Alaana Stormwalker waits where the airship lands.", g={{"t",95349,m=1412,x=33.4,y=22.6},{"a",95350,n2="Alaana Stormwalker: keep it: Thrall in Orgrimmar, at the start of the next guide",m=1412,x=33.4,y=22.6,ml=7},{"a",94911,n2="Muln Earthfury, by the landing: for Turak Runetotem in Thunder Bluff",m=1412,x=33.4,y=22.6,f={c={"DRUID"}},ml=10}}},
  {t="Clarice Foster", lv=12, n="Clarice Foster stands in the Pools of Vision, the cave under Spirit Rise: go down inside, the arrow cannot tell the floors apart.", g={{"l",12,txt="Reach level 12"},{"a",264,m=1456,x=27.2,y=24.4,ml=12}}},
  {t="Class trainer", lv=12, f={c={"PALADIN","PRIEST","MAGE"}}, g={{"tr",0,txt="Visit your class trainer",f={c={"PALADIN","PRIEST","MAGE"}}}}},
  {t="Traditions of the Bluff", lv=12, n="Eylah Sunhorn wants tauren incense: buy its four parts from Nida the herbalist, Nata the enchanting supplier, Mahu the leatherworking supplier and Naal the cooking supplier, then combine them into Prepared Incense.", g={{"fp",22,txt="Get the Thunder Bluff flight path (Tal)",m=1456,x=47,y=49.8},{"a",97485,m=1456,x=38,y=55.9,ml=3},{"h",278079,txt="Buy Bundle of Herbs (Nida Winterhoof)",n2="Bundle of Herbs, from Nida Winterhoof",m=1456,x=49.6,y=39.6,n=1},{"h",278080,txt="Buy Bundle of Dried Cedar Twigs (Nata Dawnstrider)",n2="Bundle of Dried Cedar Twigs, from Nata Dawnstrider",m=1456,x=45,y=38.8,n=1},{"h",278081,txt="Buy Sinew Thread (Mahu)",n2="Sinew Thread, from Mahu",m=1456,x=43.8,y=45.1,n=1},{"h",278083,txt="Buy Ceremonial Flint and Tinder (Naal Mistrunner)",n2="Ceremonial Flint and Tinder, from Naal Mistrunner",m=1456,x=51,y=52.5,n=1}}},
  {t="Turak Runetotem", lv=12, n="Turak Runetotem trains druids on Elder Rise. He teaches you Teleport: Moonglade; Dendrite Starblaze's welcome waits for your Cat Form trip at about 21 (forever/horde/02-the-barrens).", f={c={"DRUID"}}, g={{"t",94911,m=1456,x=76.5,y=27.2},{"a",94913,m=1456,x=76.5,y=27.2,ml=10},{"tr",0,txt="Visit your class trainer"}}},
  {t="Hunter Rise", lv=12, n="Use the Prepared Incense at the ceremonial mat and burner on the south-facing cliff of Hunter Rise.", g={{"o",97485,i=2,txt="Spread the Prepared Incense off Hunter Rise",m=1456,x=53.3,y=87.9}}},
  {t="Eylah Sunhorn", lv=12, g={{"t",97485,m=1456,x=38,y=55.9}}},
  {t="Ansekhwa", lv=12, n="While you're here: learn Two-Handed Maces from Ansekhwa (10 silver); two-handers level a Warrior fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Maces",skillLine=160}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Ansekhwa",m=1456,x=40.9,y=62.7}}},
  {t="Ansekhwa", lv=12, n="While you're here: learn Staves from Ansekhwa (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Staves",skillLine=136}}, f={c={"HUNTER"}}, g={{"tr",0,txt="Train with Ansekhwa",m=1456,x=40.9,y=62.7}}},
  {t="Into Mulgore", lv=12, g={{"g",0,txt="Into Mulgore",m=1412,x=42.1,y=20.2}}},
  {t="Into The Barrens", lv=12, g={{"g",0,txt="Into The Barrens",m=1413,x=41.9,y=58.6}}},
  {t="The Crossroads", lv=12, g={{"g",0,txt="The Crossroads",m=1413,x=52.2,y=31}}},
  {t="The Crossroads", lv=12, n="Learn the flight path from Devrak on the tower platform. The Crossroads' own quests come after Silverpine Forest, in the Barrens guide.", g={{"fp",25,txt="Get the Crossroads flight path (Devrak)",m=1413,x=51.5,y=30.3}}},
  {t="To Orgrimmar", lv=12, n="From the Crossroads follow the road north-east to Far Watch Post, cross the Southfury River into Durotar and keep north to Orgrimmar's main gate. The next guide starts in Orgrimmar: Thrall takes Welcome to Azeroth, and the zeppelin leaves for Tirisfal Glades and Silverpine Forest.", g={{"g",0,txt="Orgrimmar's Valley of Strength",m=1454,x=55.6,y=72.3}}},
} end)

R:Segment({id="horde/tauren/01-mulgore",title="Mulgore",faction="Horde",races={"Tauren"},min=1,max=12,zone=1412,zoneName="Mulgore",next="horde/03-silverpine-forest"}, function() return {
  {t="Camp Narache", lv=1, n="You start on the mesa of Camp Narache. Grull and the chief stand by the big tent in the middle.", g={{"a",747,m=1412,x=44.5,y=77.5,ml=1},{"a",752,n2="Chief Hawkwind, inside",m=1412,x=43.9,y=76.7,ml=1}}},
  {t="Greatmother Hawkwind", lv=1, n="Greatmother Hawkwind sits by the tent on the camp's eastern edge; the Water Pitcher stands next to her.", g={{"t",752,m=1412,x=48.8,y=80.9},{"a",753,m=1412,x=48.8,y=80.9,ml=1},{"o",753,i=1,txt="Water Pitcher",m=1412,x=48.9,y=81.2}}},
  {t="Camp Narache: kill these as you meet them", lv=1, n="Plainstriders roam the mesa all around the camp: take their meat and feathers on the way back to Grull.", g={{"o",747,i=1,txt="Plainstrider Meat x7",m=1412,x=49.7,y=82.5},{"o",747,i=2,txt="Plainstrider Feather x7",m=1412,x=49.7,y=82.5}}},
  {t="Grull Hawkwind", lv=1, g={{"t",747,m=1412,x=44.5,y=77.5},{"a",750,m=1412,x=44.5,y=77.5,ml=1},{"a",3091,n2="Grull Hawkwind: Simple Note",m=1412,x=44.5,y=77.5,f={c={"WARRIOR"}},ml=1},{"a",3092,n2="Grull Hawkwind: Etched Note",m=1412,x=44.5,y=77.5,f={c={"HUNTER"}},ml=1},{"a",3093,n2="Grull Hawkwind: Rune-Inscribed Note",m=1412,x=44.5,y=77.5,f={c={"SHAMAN"}},ml=1},{"a",3094,n2="Grull Hawkwind: Verdant Note",m=1412,x=44.5,y=77.5,f={c={"DRUID"}},ml=1},{"t",3091,n2="Harutt Thunderhorn, the warrior trainer; inside",m=1412,x=43.8,y=76.7,f={c={"WARRIOR"}}},{"t",3092,n2="Lanka Farshot, the hunter trainer",m=1412,x=44,y=76.3,f={c={"HUNTER"}}},{"t",3093,n2="Meela Dawnstrider, the shaman trainer in camp",m=1412,x=44.6,y=76.6,f={c={"SHAMAN"}}},{"t",3094,n2="Gart Mistrunner, the druid trainer beside him",m=1412,x=44.6,y=76.5,f={c={"DRUID"}}},{"tr",0,txt="Visit your class trainer"},{"t",753,n2="Inside",m=1412,x=43.9,y=76.7},{"a",755,m=1412,x=43.9,y=76.7,ml=1}}},
  {t="The Hunt Continues", lv=1, n="Antur Fallow stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, then hunt the cougars south through the hills towards the Seer's tent at their foot.", g={{"a",1656,m=1412,x=39.2,y=81.2,ml=1},{"o",750,i=1,txt="Mountain Cougar Pelt x10",m=1412,x=41.1,y=81.7}}},
  {t="Seer Graytongue", lv=1, n="The Seer's tent stands at the foot of the cougars' hills.", g={{"t",755,m=1412,x=42.5,y=90.1},{"a",95805,m=1412,x=42.5,y=90.1,ml=1},{"a",757,m=1412,x=42.5,y=90.1,ml=1}}},
  {t="The shrine of An'she and Mu'sha", lv=1, n="The incense burns out in ten minutes: run straight east along the southern hills to the Ritual Fire.", g={{"t",95805,m=1412,x=56.6,y=88.7}}},
  {t="Grull Hawkwind", lv=3, n="Back north-west up to Camp Narache.", g={{"t",750,m=1412,x=44.5,y=77.5},{"a",780,m=1412,x=44.5,y=77.5,ml=1},{"a",3376,n2="Brave Windfeather, next to Grull; walks around Camp Narache: look inside the circle on the map",m=1412,x=44.2,y=77,ml=3},{"tr",0,txt="Visit your class trainer"}}},
  {t="Red Cloud Mesa: kill these as you meet them", lv=3, n="Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. Chief Sharptusk Thornmantle stands at its eastern end, and the Dirt-stained Map lies on the ground in the camp.", g={{"o",780,i=1,txt="Battleboar Snout x8",m=1412,x=50.3,y=77.6},{"o",780,i=2,txt="Battleboar Flank x8",m=1412,x=50.3,y=77.6},{"o",757,i=1,txt="Bristleback Belt x12",m=1412,x=55.8,y=78.6},{"o",3376,i=1,txt="Chief Sharptusk Thornmantle's Head",m=1412,x=61,y=78},{"h",4851,txt="Get Dirt-stained Map",n2="Below ground",m=1412,x=59.8,y=82.2,n=1},{"a",781,ml=1}}},
  {t="Deathskip to Red Cloud Mesa", lv=3, n="Die to the mobs at 63.7,78.4 (Bristleback Battleboar): a death there sends you to this graveyard. Release your spirit and take the Spirit Healer's resurrection.", g={{"z",0,txt="Die and resurrect at Red Cloud Mesa",m=1412,x=42.6,y=78.4,at="Red Cloud Mesa"}}},
  {t="Camp Narache", lv=4, n="Back west to the camp.", g={{"t",780,m=1412,x=44.5,y=77.5},{"t",3376,n2="Brave Windfeather walks around Camp Narache: look inside the circle on the map",m=1412,x=44.2,y=77},{"t",781,m=1412,x=43.9,y=76.7,opt=true},{"t",757,n2="Inside",m=1412,x=43.9,y=76.7},{"a",763,m=1412,x=43.9,y=76.7,ml=1},{"a",96659,m=1412,x=43.9,y=76.7,ml=4}}},
  {t="Seer Ravenfeather", lv=4, n="Seer Ravenfeather stands in Camp Narache. Call of Earth needs level 4, which you reach with the turn-ins here.", f={c={"SHAMAN"}}, g={{"a",1519,m=1412,x=44.4,y=76.8,ml=4}}},
  {t="Ritual Salve", lv=4, n="Back east to Brambleblade Ravine: the Bristleback Shamans stand among the quilboar there.", f={c={"SHAMAN"}}, g={{"o",1519,i=1,txt="Ritual Salve x2",m=1412,x=56.6,y=78.3}}},
  {t="Call of Earth", lv=4, n="Back to Seer Ravenfeather in the camp. The Minor Manifestation of Earth waits on the mesa east of the camp: drink the Earth Sapta there to see it, then take the Rough Quartz back to the Seer.", f={c={"SHAMAN"}}, g={{"t",1519,m=1412,x=44.4,y=76.8},{"a",1520,m=1412,x=44.4,y=76.8,ml=4},{"t",1520,m=1412,x=52,y=80.4},{"a",1521,m=1412,x=52,y=80.4,ml=4},{"t",1521,n2="Seer Ravenfeather: Stoneskin Totem and your Earth Totem",m=1412,x=44.4,y=76.8}}},
  {t="Kaga Wildhoof", lv=4, n="Follow the road north out of Red Cloud Mesa. Kaga Wildhoof waits on the road just south of Bloodhoof Village; /sit by her campfire until you get Boosted Rest. With a profession learned, Kaga also offers its Camping 101, which its trainer takes: in Bloodhoof or on the Thunder Bluff stop.", g={{"t",96659,m=1412,x=46.2,y=67.3},{"a",96605,m=1412,x=46.2,y=67.3,ml=4},{"c",96605,txt="Sit near the campfire (Optional); Gain the Boosted Rest buff",n2="/sit by Kaga's campfire until you get Boosted Rest",m=1412,x=46.2,y=67.3},{"t",96605,m=1412,x=46.2,y=67.3},{"a",96661,m=1412,x=46.2,y=67.3,ml=4}}},
