  {t="Camping 101: Enchanting", lv=4, w={{k="skill",n=1,name="Enchanting",skillLine=333},{k="knows",neg=true,spell=1230643}}, g={{"a",97929,n2="Kaga Wildhoof: for Mot Dawnstrider",m=1412,x=46.2,y=67.3,ml=4}}},
