  {t="Bloodhoof Village", lv=6, g={{"tr",0,txt="Learn Cooking from Pyall Silentstride",n2="Pyall Silentstride: Camping 101 asks you to learn it",m=1412,x=44.9,y=61.7},{"c",96661,txt="Pyall Silentstride",m=1412,x=44.9,y=61.7},{"t",96661,m=1412,x=44.9,y=61.7},{"a",746,m=1412,x=46.7,y=63.4,ml=6}}},
