  {t="Chaw Stronghide", lv=6, w={{k="onquest",q={97934}}}, g={{"c",97934,txt="Chaw Stronghide",m=1412,x=44.9,y=61.5},{"t",97934,n2="Chaw Stronghide, beside Pyall: Camping 101: Leatherworking",m=1412,x=44.9,y=61.5}}},
