  {t="Grunt Kor'ja", lv=6, n="Grunt Kor'ja kneels behind the rocks just off the road south of Razor Hill, on your way to the keep. Cast Lesser Heal (Rank 2) on her, then Power Word: Fortitude: Rank 1 of Lesser Heal does not count.", f={c={"PRIEST"},r={"Troll"}}, g={{"o",5648,i=1,txt="Heal and fortify Grunt Kor'ja",m=1411,x=53.1,y=46.5}}},
  {t="Tiragarde Keep", lv=6, n="The keep stands on the coast south-east of Razor Hill. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the Canvas Scraps. Lieutenant Benedict waits at the top of the keep; his key opens the chest beside him, which holds the Aged Envelope.", g={{"o",96822,i=3,txt="Raider's Shield",m=1411,x=56.6,y=53},{"o",791,i=1,txt="Canvas Scraps x8",m=1411,x=56.6,y=53},{"o",784,i=1,txt="Kill Kul Tiras Sailor x10",m=1411,x=56.6,y=53},{"o",784,i=2,txt="Kill Kul Tiras Marine x8",m=1411,x=57.8,y=53.8},{"o",784,i=3,txt="Kill Lieutenant Benedict",n2="Upstairs",m=1411,x=59.7,y=58.3},{"h",4881,txt="Get Aged Envelope",n2="Upstairs",m=1411,x=59.3,y=57.6,n=1},{"a",830,ml=1},{"o",96822,i=1,txt="Raider's Bow",m=1411,x=59.4,y=56.4},{"o",96822,i=2,txt="Raider's Battleaxe",m=1411,x=57.4,y=56.4}}},
