  {t="Brill", lv=6, n="Apothecary Johaan is in the apothecary's house on the west side of the square, Executor Zygand in front of the inn with the Wanted poster beside him, Magistrate Sevren in the town hall on the square's north side. The inn comes last, in one go.", g={{"t",365,n2="Apothecary Johaan, inside",m=1420,x=59.5,y=52.4},{"a",407,m=1420,x=59.5,y=52.4,ml=4},{"a",367,m=1420,x=59.5,y=52.4,ml=6},{"t",91209,n2="Shari Stilwell, the Paladin trainer",m=1420,x=60.2,y=52.7,f={c={"PALADIN"}}},{"t",383,n2="Executor Zygand, in front of the inn",m=1420,x=60.6,y=51.8},{"a",427,m=1420,x=60.6,y=51.8,ml=5},{"a",99134,m=1420,x=60.6,y=51.8,ml=4},{"a",99141,m=1420,x=60.6,y=51.8,ml=4},{"a",398,n2="The Wanted poster by the inn",m=1420,x=60.7,y=51.5,ml=6},{"a",358,n2="Magistrate Sevren, in the town hall",m=1420,x=61.3,y=50.8,ml=4}}},
  {t="Faruza", lv=6, w={{k="onquest",q={97957}}}, g={{"c",97957,txt="Faruza",m=1420,x=59.8,y=52.1},{"t",97957,n2="Faruza, beside Johaan: Camping 101: Herbalism",m=1420,x=59.8,y=52.1}}},
  {t="Carolai Anise", lv=6, w={{k="onquest",q={97951}}}, g={{"c",97951,txt="Carolai Anise",m=1420,x=59.4,y=52.2},{"t",97951,n2="Carolai Anise, beside Johaan: Camping 101: Alchemy",m=1420,x=59.4,y=52.2}}},
  {t="Carolai Anise", lv=7, n="From level 7 Carolai Anise, beside Johaan in the apothecary's house, offers her elixir quest; below 7 it waits for the next Brill visit.", w={{k="level",op=">=",n=7}}, g={{"a",95314,n2="Carolai Anise, beside Johaan; inside",m=1420,x=59.4,y=52.2,ml=7}}},
  {t="Discipline", lv=7, g={{"g",0,txt="Brill",n2="Use the Executor's Motivator on five idle Deathguards around town",m=1420,x=60.6,y=52},{"c",99134,txt="Motivate 5 Deathguards"}}},
  {t="Executor Zygand", lv=7, g={{"t",99134,m=1420,x=60.6,y=51.8}}},
  {t="Gallows' End Tavern", lv=7, n="Everything here is inside the inn, through its door on the south side: Innkeeper Renee at the bar, William Pickman at the north end of the ground floor, the Captured Scarlet Zealot in the cellar under that end, and Cain Firesong (mages), Dark Cleric Beryl (priests), Rupert Boch (warlocks) and Marion Call (rogues) upstairs: take the stairs inside, the arrow cannot tell the floors apart.", g={{"b",0,txt="Set your hearthstone at Gallows' End Tavern",m=1420,x=61.7,y=52,at="Gallows' End Tavern"},{"t",8,m=1420,x=61.7,y=52},{"tr",0,txt="Learn Cooking from William Pickman",n2="William Pickman, at the inn's north end: Camping 101 asks you to learn it",m=1420,x=61.8,y=51.4},{"c",96658,txt="William Pickman",m=1420,x=61.8,y=51.5},{"t",96658,m=1420,x=61.8,y=51.4},{"t",407,n2="The Captured Scarlet Zealot, in the inn's cellar",m=1420,x=62,y=51.3},{"tr",0,txt="Visit your class trainer",n2="The Brill trainers are in the inn (Austil de Mon downstairs, the rest upstairs); Shari Stilwell, the Paladin trainer, by the square"},{"t",5651,n2="Dark Cleric Beryl, upstairs",m=1420,x=61.6,y=52.2,f={c={"PRIEST"}}},{"a",5650,m=1420,x=61.6,y=52.2,f={c={"PRIEST"}},ml=5}}},
  {t="Nurse Neela", lv=7, w={{k="onquest",q={97955}}}, g={{"c",97955,txt="Nurse Neela",m=1420,x=61.8,y=52.8},{"t",97955,n2="Nurse Neela, by the bar: Camping 101: First Aid",m=1420,x=61.8,y=52.8}}},
  {t="Vance Undergloom", lv=7, w={{k="onquest",q={97953}}}, g={{"c",97953,txt="Vance Undergloom",m=1420,x=61.8,y=51.6},{"t",97953,n2="Vance Undergloom: Camping 101: Enchanting",m=1420,x=61.8,y=51.6}}},
  {t="Coleman Farthing and Gretchen Dedmar", lv=7, n="Still in the inn: from level 7 Coleman Farthing on the ground floor and Gretchen Dedmar upstairs offer their quests; below 7 they wait for the next Brill visit.", w={{k="level",op=">=",n=7}}, g={{"a",362,n2="Coleman Farthing, in the inn",m=1420,x=61.7,y=52.3,ml=7},{"a",354,m=1420,x=61.7,y=52.3,ml=7},{"a",375,n2="Gretchen Dedmar, upstairs",m=1420,x=61.9,y=52.7,ml=7}}},
  {t="Deathguard Linnea's camp", lv=7, n="Follow the road south-east from Brill past the zeppelin towers. Linnea, Kristof and Shelene Rhobart camp by the road.", g={{"o",99141,i=2,txt="Kristof's Report",n2="Ask Deathguard Kristof for his report",m=1420,x=65.2,y=60.3},{"a",97558,m=1420,x=65.4,y=60.1,ml=6},{"a",356,m=1420,x=65.5,y=60.2,ml=6}}},
  {t="Rand Rhobart", lv=7, w={{k="onquest",q={97960}}}, g={{"c",97960,txt="Rand Rhobart",m=1420,x=65.6,y=60},{"t",97960,n2="Rand Rhobart, beside Shelene: Camping 101: Skinning",m=1420,x=65.6,y=60}}},
  {t="Shelene Rhobart", lv=7, w={{k="onquest",q={97958}}}, g={{"c",97958,txt="Shelene Rhobart",m=1420,x=65.4,y=60.1},{"t",97958,n2="Shelene Rhobart: Camping 101: Leatherworking",m=1420,x=65.4,y=60.1}}},
  {t="Deathguard Dillinger", lv=7, n="Back up the road and through Brill to its west end.", g={{"o",99141,i=1,txt="Dillinger's Report",n2="Ask Deathguard Dillinger for his report",m=1420,x=58.2,y=51.5}}},
  {t="Cold Hearth Manor: kill these as you meet them", lv=7, n="Rotting Dead and Ravaged Corpses shamble through the fields just west of Brill; Decrepit Darkhounds roam there and on west along the road toward Gordo. Johaan wants their blood, Shelene their hides.", g={{"o",404,i=1,txt="Putrid Claw x7",m=1420,x=56.1,y=49.9},{"o",367,i=1,txt="Darkhound Blood x5",m=1420,x=57.8,y=52.7},{"o",97558,i=2,txt="Darkhound Hide x6",m=1420,x=57.8,y=52.7}}},
  {t="Bowen Brisboise", lv=7, w={{k="onquest",q={97961}}}, g={{"c",97961,txt="Bowen Brisboise",m=1420,x=52.6,y=55.5},{"t",97961,n2="Bowen Brisboise, by the road west of Brill: Camping 101: Tailoring",m=1420,x=52.6,y=55.5}}},
  {t="Gordo", lv=7, n="Gordo walks the long road west of Brill, past Cold Hearth Manor, and back: the arrow follows his road west until you meet him.", g={{"o",99141,i=3,txt="Gordo's Report",n2="Ask Gordo for his report",m=1420,x=53.8,y=53.1}}},
  {t="Calvin Montague", lv=7, n="Calvin Montague stands by the farmhouse at the Solliden Farmstead, on the way to the Crusader's Outpost.", g={{"a",590,n2="Calvin Montague, by the farmhouse: talk to him for the duel; he offers it once Innkeeper Renee has his letter",m=1420,x=38.2,y=56.8,ml=1},{"c",590,txt="Calvin Montague; Defeat Calvin Montague",n2="Beat Calvin in the duel",m=1420,x=38.2,y=56.8},{"t",590,m=1420,x=38.2,y=56.8}}},
  {t="Crusader's Outpost", lv=7, n="Scarlet Warriors guard the outpost north-west of the pumpkin fields. Bareth Dawnstone is held inside: talk to him and stay with him until he is out.\nCareful: Scarlet Warriors are level 6-7 and not elite. Once their health falls to 15% they run off to bring help, so more of them may join the fight.", g={{"o",427,i=1,txt="Kill Scarlet Warrior x10",m=1420,x=34.1,y=51.4},{"a",99144,n2="Bareth Dawnstone, on the top floor",m=1420,x=33.3,y=47.6,ml=5},{"g",0,txt="Crusader's Outpost",n2="Escort Bareth out of the outpost",m=1420,x=32,y=46.3},{"c",99144,txt="Escort Bareth Dawnstone out of Crusader's Outpost"}}},
  {t="Brill", lv=7, n="Back east along the road to Brill. Cain Firesong (mages), Dark Cleric Beryl (priests), Rupert Boch (warlocks) and Marion Call (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart.", g={{"t",404,m=1420,x=58.2,y=51.5},{"a",426,m=1420,x=58.2,y=51.5,ml=6},{"t",367,n2="Apothecary Johaan, inside",m=1420,x=59.5,y=52.4},{"a",368,m=1420,x=59.5,y=52.4,ml=6},{"a",95314,n2="Carolai Anise, beside Johaan; inside",m=1420,x=59.4,y=52.2,ml=7},{"t",99144,m=1420,x=60.2,y=52.7},{"t",427,m=1420,x=60.6,y=51.8},{"a",370,m=1420,x=60.6,y=51.8,ml=5},{"t",99141,m=1420,x=60.6,y=51.8},{"a",374,m=1420,x=60.9,y=52,ml=5},{"h",2320,txt="Buy Coarse Thread (Abigail Shiel)",n2="Coarse Thread from Abigail Shiel, for Gretchen",m=1420,x=61,y=52.4,n=1},{"a",362,n2="Coleman Farthing, in the inn",m=1420,x=61.7,y=52.3,ml=7},{"a",354,m=1420,x=61.7,y=52.3,ml=7},{"a",375,n2="Gretchen Dedmar, upstairs",m=1420,x=61.9,y=52.7,ml=7},{"tr",0,txt="Visit your class trainer"}}},
  {t="Deathguard Kel", lv=7, n="Deathguard Kel kneels by the north gate of Brill's graveyard, on your way north. Cast Lesser Heal (Rank 2) on him, then Power Word: Fortitude: Fortitude first does not count.", f={c={"PRIEST"}}, g={{"o",5650,i=1,txt="Heal and fortify Deathguard Kel",m=1420,x=59.2,y=46.5}}},
  {t="Tirisfal Glades: kill these as you meet them", lv=7, n="Greater Duskbats fly over the fields around Brill and along the road north: Gretchen wants their pelts, Shelene their wings.\nThe Doom Weed grows in the graveyard fields just north of Brill, where the Rot Hide Graverobbers dig; all the Rot Hides drop the ichor.\nThe Rot Hide Mongrels hold the hills further north. Maggot Eye (level 11) stands in their camp on the hill south of the shore: clear the gnolls around him first.\nCareful: Gnoll guards stand outside the hut and can join the fight. If you slip past them and fight him inside, he fights alone.\nThe Vile Fin murlocs line the north shore: they all drop the scales, and the Minor Oracles and Muckdwellers the skins for Shelene.", g={{"o",375,i=1,txt="Duskbat Pelt x5",m=1420,x=60.5,y=43.1},{"o",97558,i=1,txt="Duskbat Wing Membrane x8",m=1420,x=60.5,y=43.1},{"o",5482,i=1,txt="Doom Weed x10",m=1420,x=58.3,y=42.9},{"o",358,i=1,txt="Kill Rot Hide Graverobber x8",m=1420,x=58.3,y=42.9},{"o",358,i=3,txt="Embalming Ichor x8",m=1420,x=58.3,y=42.9},{"o",358,i=2,txt="Kill Rot Hide Mongrel x5",n2="Rot Hide Mongrel walks around Garren's Haunt: look inside the circle on the map",m=1420,x=60.5,y=38.8},{"o",398,i=1,txt="Maggot Eye's Paw",n2="Maggot Eye's Paw; inside",m=1420,x=58.7,y=30.8},{"o",368,i=1,txt="Vile Fin Scale x5",m=1420,x=58.5,y=28.8},{"o",97558,i=3,txt="Vile Fin Murloc Skin x3",m=1420,x=58.3,y=28.1}}},
  {t="Brill", lv=8, n="Cain Firesong (mages), Dark Cleric Beryl (priests), Rupert Boch (warlocks) and Marion Call (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart.", g={{"t",5482,n2="Junior Apothecary Holland walks around Brill: look inside the circle on the map",m=1420,x=57.4,y=48.9},{"a",99142,m=1420,x=57.4,y=48.9,ml=5},{"t",368,n2="Apothecary Johaan, inside",m=1420,x=59.5,y=52.4},{"a",369,m=1420,x=59.5,y=52.4,ml=6},{"a",91282,n2="Shari Stilwell, the Paladin trainer: A Second Home, to Bandarion Keep",m=1420,x=60.2,y=52.7,f={c={"PALADIN"}},ml=8},{"t",398,m=1420,x=60.6,y=51.8},{"t",358,n2="Magistrate Sevren, inside",m=1420,x=61.3,y=50.8},{"a",359,m=1420,x=61.3,y=50.8,ml=6},{"h",2320,txt="Buy Coarse Thread (Abigail Shiel)",n2="Coarse Thread from Abigail Shiel, for Gretchen",m=1420,x=61,y=52.4,n=1},{"t",375,n2="Gretchen Dedmar, upstairs",m=1420,x=61.9,y=52.7},{"t",5650,n2="Dark Cleric Beryl, upstairs: the Acolyte's Sacrificial Robes",m=1420,x=61.6,y=52.2,f={c={"PRIEST"}}},{"tr",0,txt="Visit your class trainer"}}},
  {t="Deathguard Terrence", lv=10, n="From level 10 Deathguard Terrence offers The Argent Emissary: Hadric waits at Linnea's camp, the next stop. Below 10 it waits for the Brill visit after Agamand Mills.", w={{k="level",op=">=",n=10}}, g={{"a",96895,m=1420,x=61.4,y=53.4,ml=10}}},
  {t="Deathguard Linnea's camp", lv=10, n="Follow the road south-east from Brill past the zeppelin towers.", g={{"t",359,m=1420,x=65.5,y=60.2},{"a",360,m=1420,x=65.5,y=60.2,ml=6},{"t",97558,m=1420,x=65.4,y=60.1}}},
  {t="Hadric Harlson", lv=10, n="Hadric stands at the camp beside Linnea.", w={{k="onquest",q={96895}}}, g={{"t",96895,m=1420,x=65.9,y=61.1},{"a",96897,m=1420,x=65.9,y=61.1,ml=10},{"a",96898,m=1420,x=65.9,y=61.1,ml=10}}},
  {t="Magistrate Sevren", lv=10, n="Back up the road to Brill, on the way north-west to Agamand Mills.", g={{"t",360,n2="Inside",m=1420,x=61.3,y=50.8}}},
  {t="Agamand Mills", lv=10, n="Follow the road north-west to Agamand Mills. Devlin Agamand walks the graveyard south of the mills; Nissa, Gregor and Thurman Agamand haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop A Letter to Yvette.\nCareful: Rotting undead and Darkeye Bonecasters near the Agamands can join a fight as adds.", g={{"o",362,i=1,txt="Devlin's Remains",m=1420,x=47.2,y=40},{"o",426,i=1,txt="Notched Rib x5",m=1420,x=45.8,y=40.4},{"o",426,i=2,txt="Blackened Skull x3",m=1420,x=46.8,y=39.9},{"o",354,i=2,txt="Nissa's Remains",n2="Nissa Agamand; upstairs",m=1420,x=49.7,y=36.3},{"o",354,i=3,txt="Thurman's Remains",m=1420,x=42.8,y=32.5},{"o",354,i=1,txt="Gregor's Remains",m=1420,x=45.8,y=29.4},{"h",2839,txt="Get A Letter to Yvette",n2="A Letter to Yvette, a rare drop",m=1420,x=46.2,y=29.4,n=1,opt=true},{"a",361,n2="Only if the letter dropped",opt=true,ml=4}}},
  {t="Brill", lv=10, n="Cain Firesong (mages), Dark Cleric Beryl (priests), Rupert Boch (warlocks) and Marion Call (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart.", g={{"t",426,m=1420,x=58.2,y=51.5},{"a",1819,m=1420,x=58.2,y=51.5,f={c={"WARRIOR"}},ml=10},{"t",362,n2="Coleman Farthing, in the inn",m=1420,x=61.7,y=52.3},{"t",354,m=1420,x=61.7,y=52.3},{"a",355,m=1420,x=61.7,y=52.3,ml=7},{"t",361,n2="Yvette Farthing, in the inn",m=1420,x=61.6,y=52.6,opt=true},{"a",1881,n2="Cain Firesong: Anastasia Hartwell in the Undercity takes it",m=1420,x=62,y=52.5,f={c={"MAGE"}},ml=10},{"a",1478,n2="Ageron Kargal: Carendin Halgar in the Undercity takes it",m=1420,x=61.6,y=52.7,f={c={"WARLOCK"}},ml=10},{"tr",0,txt="Visit your class trainer"},{"t",355,n2="Magistrate Sevren, in the town hall",m=1420,x=61.3,y=50.8},{"a",96895,n2="Deathguard Terrence, if you were below 10 on the last Brill visit",m=1420,x=61.4,y=53.4,ml=10}}},
  {t="Ulag the Cleaver", lv=10, n="Ulag waits in the mausoleum on the hill just north of town: open the gate and fight him.", f={c={"WARRIOR"}}, g={{"o",1819,i=1,txt="Kill Ulag the Cleaver",m=1420,x=59.5,y=48.3},{"t",1819,n2="Deathguard Dillinger: Defensive Stance",m=1420,x=58.2,y=51.5}}},
  {t="Carendin Halgar", lv=10, n="Walk south from Brill to the Ruins of Lordaeron and down into the Undercity. Carendin Halgar stands in the Magic Quarter. The Scarlet camp is just west of the ruins.", f={c={"WARLOCK"}}, g={{"t",1478,n2="Carendin Halgar: he offers Creature of the Void only once this is handed in",m=1458,x=85.1,y=26},{"a",1473,m=1458,x=85.1,y=26,ml=10}}},
