  {t="Tirisfal Glades: kill these as you meet them", lv=10, n="Follow the road south-west from Brill to the Scarlet Crusade camp. Captain Perrine stands at its south end; every Scarlet there can drop a ring.", g={{"o",374,i=1,txt="Scarlet Insignia Ring x10",m=1420,x=52,y=68.1},{"o",370,i=2,txt="Kill Scarlet Zealot x3",n2="Scarlet Zealot walks around here: look inside the circle on the map",m=1420,x=52,y=68.1},{"o",370,i=3,txt="Kill Scarlet Missionary x3",m=1420,x=52.8,y=67.4},{"o",370,i=1,txt="Kill Captain Perrine",m=1420,x=51.1,y=67.8}}},
  {t="Perrine's Chest", lv=10, n="Perrine's Chest stands beside Captain Perrine at the camp's south end.", f={c={"WARLOCK"}}, g={{"o",1473,i=1,txt="Egalin's Grimoire",m=1420,x=51.1,y=67.6}}},
