  {t="Hadric Harlson", lv=10, n="Hadric stands at Deathguard Linnea's camp, on the road to the cult's farm.", g={{"t",96895,m=1420,x=65.9,y=61.1},{"a",96897,m=1420,x=65.9,y=61.1,ml=10},{"a",96898,m=1420,x=65.9,y=61.1,ml=10}}},
  {t="Tirisfal Glades: kill these as you meet them", lv=10, n="Follow the road south-east past Deathguard Linnea's camp: the Cult of the Damned holds the farm just south-east of it. The Necrotic Crystal Fragments lie on the ground among the cultists, and the cultists carry some too.", g={{"o",96898,i=1,txt="Necrotic Crystal Fragment x12",m=1420,x=68.2,y=64.6},{"o",96897,i=2,txt="Kill Dark Enforcer x8",m=1420,x=68.2,y=64.6},{"o",96897,i=1,txt="Kill Dark Neophyte x8",m=1420,x=68.2,y=64.6}}},
  {t="Balnir Farmstead: kill these as you meet them", lv=10, n="Follow the road east. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the Tomb Weed grows: Linnea wants eight of each.\nThe Scarlet Friars camp just north-east of the graves; Captain Vachon stands among them.\nThe spiders lurk in the woods at the far east end of the glades.", g={{"o",356,i=1,txt="Kill Bleeding Horror x8",m=1420,x=74.2,y=62.8},{"o",356,i=2,txt="Kill Wandering Spirit x8",m=1420,x=74.2,y=61.5},{"o",99142,i=1,txt="Tomb Weed x5",m=1420,x=74.4,y=61.8},{"o",1882,i=1,txt="Balnir Snapdragons",n2="Balnir Snapdragons, in the farmstead's garden",m=1420,x=77.4,y=61.8,f={c={"MAGE"}}},{"o",371,i=2,txt="Kill Scarlet Friar x5",m=1420,x=76.1,y=57.2},{"o",371,i=1,txt="Kill Captain Vachon",m=1420,x=78.8,y=56.1},{"o",369,i=1,txt="Vicious Night Web Spider Venom x4",m=1420,x=82.4,y=54.8}}},
