  {t="Brill", lv=10, n="Back up the road to Brill. Cain Firesong (mages), Dark Cleric Beryl (priests), Rupert Boch (warlocks) and Marion Call (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart.", g={{"t",369,n2="Apothecary Johaan, inside",m=1420,x=59.5,y=52.4},{"a",492,m=1420,x=59.5,y=52.4,ml=6},{"a",445,n2="Apothecary Johaan: for Renferrel at the Sepulcher",m=1420,x=59.5,y=52.4,ml=9},{"t",371,m=1420,x=60.6,y=51.8},{"tr",0,txt="Visit your class trainer"},{"t",492,n2="The Captured Mountaineer, in the inn's cellar",m=1420,x=61.9,y=51.4},{"t",99142,n2="Junior Apothecary Holland walks around Brill: look inside the circle on the map",m=1420,x=57.4,y=48.9}}},
  {t="Leonid Barthalomew the Revered", lv=10, n="Follow the road west past Agamand Mills to the Whispering Forest. Leonid stands just north of Hilda's camp.\nHilda the Breaker and Ephram Barbaro camp at the forest's edge just south of Leonid. Every class can take both quests once A Righteous Cause is handed in (level 10). They send you into the cellar under Shadowvale, the next stop.", g={{"t",96899,m=1420,x=22,y=44.7},{"a",96896,m=1420,x=22,y=44.7,ml=10},{"t",96896,n2="Listen to Leonid and Danitha Morr, then talk to him again",m=1420,x=22,y=44.7},{"a",99152,m=1420,x=22,y=47.2,ml=10},{"a",99153,m=1420,x=20.2,y=46.5,ml=10}}},
  {t="Paladin: Bandarion Keep", lv=10, n="Breton Samuels waits at the keep's gate beside Leonid.", f={c={"PALADIN"}}, g={{"t",91282,m=1420,x=21.9,y=45.2},{"a",91285,m=1420,x=21.9,y=45.2,ml=7}}},
  {t="Paladin: Murlocs at the Gates", lv=10, n="The Vile Fin murlocs lurk on the bluffs just east of the keep and in the camps around the lake to the south-west, on the way down to Shadowvale.", f={c={"PALADIN"}}, g={{"o",91285,i=1,txt="Kill Vile Fin Attacker x8",n2="Vile Fin Attackers",m=1420,x=25.7,y=48.2},{"o",91285,i=2,txt="Kill Vile Fin Seer x8",n2="Vile Fin Seers",m=1420,x=25.6,y=48.1}}},
  {t="Shadowvale", lv=10, n="Shadowvale is the hollow at the west edge of the glades, south-west of the Whispering Forest. Go down into the big basement under the ruined house (only a floor and a few pillars left, not the two-storey house): the bottles lie on its floor among the Shadowvale Lurchers and Mystics.", g={{"g",0,txt="the basement under the ruined house",m=1420,x=12.9,y=65.7},{"o",95314,i=1,txt="Bottle of Whispering Elixir x8",n2="Below ground",m=1420,x=11.8,y=66.4},{"o",99153,i=1,txt="Glowing Crystal Fragment",n2="the Glowing Crystal Fragment, at the basement's south end",m=1420,x=9.7,y=69.4},{"o",99152,i=1,txt="Faintly Glowing Bone x6",n2="the Shadowvale Lurchers and Mystics drop the bones; below ground",m=1420,x=9.8,y=69}}},
  {t="Hilda and Ephram", lv=10, n="Back up to the forest's edge south of the keep's gate: Hilda and Ephram take the bones and the crystal.", g={{"t",99153,m=1420,x=20.2,y=46.5},{"t",99152,m=1420,x=22,y=47.2}}},
  {t="Paladin: Bandarion Keep", lv=10, n="Ephram and Hilda at the forest's edge, Breton Samuels at the gate, Jorin Croge and Ander Solliden nearby, Danitha Morr inside.", f={c={"PALADIN"}}, g={{"t",91285,m=1420,x=21.9,y=45.2},{"a",91294,m=1420,x=21.9,y=45.2,ml=8},{"tk",246389,txt="Talk to Hilda the Breaker",m=1420,x=22,y=47.2},{"tk",246393,txt="Talk to Jorin Croge",m=1420,x=22.7,y=44.7},{"tk",246394,txt="Talk to Ander Solliden",m=1420,x=22.3,y=49.6},{"t",91294,n2="Danitha Morr, inside the keep",m=1420,x=22.1,y=44.7}}},
  {t="The Undercity", lv=10, n="The Undercity is under the Ruins of Lordaeron, beside the zeppelin towers. Carendin Halgar is in the Magic Quarter: use the Runes of Summoning on the summoning circle beside him and defeat the voidwalker. Aelthalyste is in the War Quarter. Anastasia Hartwell is in the Magic Quarter too.", f={c={"PRIEST","MAGE","WARLOCK"}}, g={{"t",1473,m=1458,x=85.1,y=26,f={c={"WARLOCK"}}},{"a",1471,m=1458,x=85.1,y=26,f={c={"WARLOCK"}},ml=10},{"i",0,txt="Use Runes of Summoning",m=1458,x=86.6,y=27.1,f={c={"WARLOCK"}}},{"o",1471,i=1,txt="Kill Summoned Voidwalker",m=1458,x=86.6,y=27.1,f={c={"WARLOCK"}}},{"t",1471,n2="Carendin Halgar: Summon Voidwalker",m=1458,x=85.1,y=26,f={c={"WARLOCK"}}},{"t",5658,n2="Aelthalyste: Touch of Weakness",m=1458,x=49.3,y=17.1,f={c={"PRIEST"}}},{"t",1882,n2="Anastasia Hartwell: The Balnir Farmstead",m=1458,x=85.1,y=10,f={c={"MAGE"}}}}},
